INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'Im Anfang schuf Gott den Himmel und die Erde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'Es war aber die Erde wüste und leer und Finsternis lag auf dem Ozean und der Geist Gottes schwebte über dem Gewässer.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, 'Da sprach Gott: Es werde Licht! Und es ward Licht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'Und Gott sah, daß das Licht gut war, und Gott trennte das Licht von der Finsternis.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'Und Gott nannte das Licht Tag, die Finsternis aber nannte er Nacht. Und es wurde Abend und wurde Morgen, der erste Tag.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, 'Da sprach Gott: Es werde ein Veste inmitten der Gewässer und bilde eine Scheidewand zwischen den verschiedenen Gewässern. Und es geschah so.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'Da machte Gott die Veste als eine Scheidewand zwischen den Gewässern unterhalb der Veste und den Gewässern oberhalb der Veste.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'Und Gott nannte die Veste Himmel. Und es wurde Abend und wurde Morgen, der zweite Tag.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, 'Da sprach Gott: Es sammle sich das Wasser unterhalb des Himmels an einen Ort, so daß das Trockene sichtbar wird. Und es geschah so.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'Und Gott nannte das Trockene Erde, die Ansammlung der Gewässer aber nannte er Meer. Und Gott sah, daß es gut war.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'Da sprach Gott: Die Erde lasse junges Grün sprossen, samentragende Pflanzen und Fruchtbäume, welche je nach ihrer Art Früchte auf Erden erzeugen, in denen sich Same zu ihnen befindet. Und es geschah so.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, 'Da ließ die Erde junges Grün aufgehen, samentragende Pflanzen je nach ihrer Art und Bäume, welche Früchte trugen, in denen sich Same zu ihnen befand, je nach ihrer Art. Und Gott sah, daß es gut war.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'Und es wurde Abend und wurde Morgen, der dritte Tag.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, 'Da sprach Gott: Es sollen Leuchten entstehen an der Veste des Himmels, um den Tag und die Nacht von einander zu trennen, und sie sollen dienen zu Merkzeichen und zur Bestimmung von Zeiträumen und Tagen und Jahren.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'Und sie sollen dienen als Leuchten an der Veste des Himmels, um die Erde zu beleuchten. Und es geschah so.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'Da machte Gott die beiden großen Leuchten: die große Leuchte, damit sie bei Tage die Herrschaft führe, und die kleine Leuchte, damit sie bei Nacht die Herrschaft führe, dazu die Sterne.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'Und Gott setzte sie an die Veste des Himmels, damit sie die Erde beleuchteten');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'und über den Tag und über die Nacht herrschten und das Licht und die Finsternis von einander trennten. Und Gott sah, daß es gut war.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'Und es wurde Abend und wurde Morgen, der vierte Tag.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, 'Da sprach Gott: Es wimmle das Wasser von Gewimmel lebendiger Wesen, und Vögel sollen über der Erde hinfliegen an der Veste des Himmels.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'Da schuf Gott die großen Seetiere und alle die lebenden Wesen, die sich herumtummeln, von denen das Wasser wimmelt, je nach ihrer Art, dazu alle geflügelten Tiere je nach ihrer Art. Und Gott sah, daß es gut war.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'Da segnete sie Gott und sprach: Seid fruchtbar und mehrt euch und bevölkert das Wasser im Meer, und auch die Vögel sollen sich mehren auf Erden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'Und es wurde Abend und wurde Morgen, der fünfte Tag.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, 'Da sprach Gott: Die Erde bringe hervor lebendige Wesen je nach ihrer Art, Vieh und kriechende Tiere und wilde Tiere je nach ihrer Art. Und es geschah so.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'Da machte Gott die wilden Tiere je nach ihrer Art und das Vieh nach seiner Art und alle Tiere, die auf dem Boden kriechen, je nach ihrer Art. Und Gott sah, daß es gut war.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, 'Da sprach Gott: Laßt uns Menschen machen nach unserem Bilde, uns ähnlich, und sie sollen herrschen über die Fische im Meer und über die Vögel am Himmel und über das Vieh und über alle wilden Tiere und über alles Gewürm, das auf der Erde umherkriecht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'Und Gott schuf den Menschen nach seinem Bilde - nach dem Bilde Gottes schuf er ihn; als Mann und Weib schuf er sie.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'Da segnete sie Gott, und Gott sprach zu ihnen: Seid fruchtbar und mehrt euch und bevölkert die Erde und macht sie euch unterthan und herrscht über die Fische im Meer und die Vögel am Himmel und über alles Getier, das sich auf Erden tummelt!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'Und Gott sprach: Hiermit weise ich euch alle samentragenden Pflanzen an, die allenthalben auf Erden wachsen, dazu alle Bäume mit samenhaltigen Früchten - das sei eure Nahrung!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'Dagegen allen Tieren auf der Erde und allen Vögeln am Himmel und allem, was auf Erden kriecht, was da beseelt ist, bestimme ich alles Gras und Kraut zur Nahrung. Und es geschah so.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'Und Gott sah, daß alles, was er gemacht, sehr gut sei. Und es wurde Abend und wurde Morgen, der sechste Tag.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'So wurden vollendet der Himmel und die Erde mit ihrem ganzen Heer.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, 'Und Gott vollendete am siebenten Tage sein Werk, das er gemacht hatte, und ruhte am siebenten Tage von all seinem Werk, das er gemacht hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'Und Gott segnete den siebenten Tag und erklärte ihn für heilig, weil er an ihm geruht hat von all seinem Werk, das er geschaffen und gemacht hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'Das ist die Geschichte der Entstehung des Himmels und der Erde, als sie geschaffen wurden. Zur Zeit, als Jahwe Gott Erde und Himmel machte -');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'es gab aber auf Erden noch gar kein Gesträuch auf den Fluren und noch sproßten keine Pflanzen auf den Fluren; denn Jahwe Gott hatte noch nicht regnen lassen auf die Erde, und Menschen waren noch nicht da, um den Boden zu bebauen;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'es stieg aber ein Nebel von der Erde auf und tränkte die ganze Oberfläche des Erdbodens -');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'da bildete Jahwe Gott den Menschen aus Erde vom Ackerboden und blies in seine Nase Lebensodem; so wurde der Mensch ein lebendiges Wesen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'Hierauf pflanzte Jahwe Gott einen Garten in Eden im fernen Osten und setzte dorthin den Menschen, den er gebildet hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'Und Jahwe Gott ließ allerlei Bäume aus dem Boden emporwachsen, die lieblich anzusehen und deren Früchte wohlschmeckend waren, und den Baum des Lebens mitten im Garten und den Baum der Erkenntnis des Guten und Bösen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, 'Und ein Strom ging aus von Eden, den Garten zu bewässern; alsdann teilte er sich und zwar in vier Arme.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'Der erste heißt Pison; das ist der, welcher das ganze Land Havila umfließt, woselbst sich das Gold findet.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'Und das Gold dieses Landes ist vortrefflich; dort finden sich auch Bedolachharz und Schohamsteine.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, 'Und der zweite Strom heißt Gihon; das ist der, welcher das ganze Land Kusch umfließt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, 'Und der dritte Strom heißt Hiddekel; das ist der, welcher auf der Vorderseite von Assur fließt; und der vierte Strom, das ist der Euphrat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'Da nahm Jahwe Gott den Menschen und setzte ihn in den Garten Eden, ihn zu bebauen und zu bewachen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'Und Jahwe Gott gebot dem Menschen und sprach: Von allen Bäumen des Gartens kannst du nach Belieben essen;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'aber von dem Baum der Erkenntnis des Guten und Bösen - von dem darfst du nicht essen; denn sobald du von ihm issest, muß du sterben!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'Und Jahwe Gott sprach: Es ist nicht gut für den Menschen, daß er allein sei; ich will ihm einen Beistand schaffen, wie er für ihn paßt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, 'Da bildete Jahwe Gott aus der Erde alle Tiere des Feldes und alle Vögel des Himmels und brachte sie zum Menschen, um zu sehen, wie er sie benennen würde; und ganz, wie der Mensch sie, die lebendigen Wesen, benennen würde, so sollten sie heißen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'Da gab der Mensch allem Vieh und allen Vögeln des Himmels und allen Tieren des Feldes Namen; aber für einen Menschen fand er keinen Beistand, der für ihn gepaßt hätte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, 'Da ließ Jahwe Gott einen tiefen Schlaf auf den Menschen fallen; und als er entschlafen war, nahm er eine von seinen Rippen und füllte ihre Stelle mit Fleisch aus.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'Alsdann gestaltete Jahwe Gott die Rippe, die er von dem Menschen genommen hatte, zu einem Weibe und brachte sie zu dem Menschen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'Da sprach der Mensch: Diese endlich ist Gebein von meinem Gebein und Fleisch von meinem Fleisch; die soll Männin heißen, denn einem Mann ist sie entnommen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'Darum verläßt einer seinen Vater und seine Mutter, um seinem Weibe anzuhangen, so daß sie zu einem Leibe werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'Und sie waren beide nackt, der Mensch und sein Weib, und schämten sich nicht vor einander.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'Die Schlange jedoch war listig, wie kein anderes unter den Tieren des Feldes, welche Jahwe Gott gemacht hatte, und sie sprach zu dem Weibe: Hat Gott wirklich gesagt: Ihr dürft von keinem der Bäume des Gartens essen?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'Da sprach das Weib zu der Schlange: Von den Früchten der Bäume des Gartens dürfen wir essen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'Aber von den Früchten des Baums, der mitten im Garten steht, - von denen hat Gott gesagt, dürft ihr nicht essen und dürft sie nicht anrühren, sonst müßt ihr sterben!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'Da sprach die Schlange zum Weibe: Ihr werdet ganz gewiß nicht sterben;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, 'sondern Gott weiß gar wohl: sobald ihr davon eßt, da werden euch die Augen aufgethan, daß ihr werdet, wie Gott, erkennend Gutes und Böses.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, 'Da nun das Weib sah, daß der Baum gut zum Essen und eine Lust für die Augen und daß der Baum begehrenswert sei, um durch ihn klug zu werden, da nahm sie von seinen Früchten und aß und gab auch ihrem Manne, der bei ihr war, und er aß.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'Da wurden ihrer beiden Augen aufgethan und sie wurden gewahr, daß sie nackt seien; da nähten sie Feigenblätter zusammen und machten sich Schürze.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, 'Als sie nun die Tritte Jahwes Gottes hörten, der in der Abendkühle im Garten wandelte, da suchte sich der Mensch mit seinem Weibe vor Jahwe Gott zu verstecken unter den Bäumen des Gartens.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'Da rief Jahwe Gott den Menschen an und sprach zu ihm: Wo bist du?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'Da sprach er: Ich hörte deine Tritte im Garten; da fürchtete ich mich, weil ich nackt bin, und versteckte mich.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'Da sprach er: Wer hat dir verraten, daß du nackt bist? Hast du von dem Baume, von dem zu essen ich dir verboten habe, doch gegessen?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'Da sprach der Mensch: Das Weib, das du mir beigesellt hast, die gab mir von dem Baume und ich aß.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'Da sprach Jahwe Gott zu dem Weibe: Was hast du gethan! Das Weib sprach: Die Schlange verführte mich, daß ich aß.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'Da sprach Jahwe Gott zur Schlange: Weil du solches gethan hast, sollst du verflucht sein unter allem Vieh und unter allen Tieren des Feldes: auf deinem Bauche sollst du kriechen und Erde fressen dein Leben lang!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, 'Und ich will Feindschaft setzen zwischen dir und dem Weibe und zwischen deinem Samen und ihrem Samen; er wird dir den Kopf zermalmen und du wirst ihm die Ferse zermalmen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'Zum Weibe aber sprach er: Ich will dir viel Mühsal bereiten mit Schwangerschaften; mit Schmerzen sollst du Kinder gebären. Und nach deinem Manne wirst du verlangen, er aber soll Herr sein über dich!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'Und zum Menschen sprach er: Weil du der Stimme deines Weibes gehorcht und von dem Baume gegessen hast, von dem ich dir gebot und sprach: Du sollst nicht von ihm essen! so soll nun der Acker verflucht sein um deinetwillen; unter Mühsal sollst du dich von ihm nähren dein Leben lang.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'Dornen und Gestrüpp soll er dir tragen; und du sollst das Kraut des Feldes essen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'Im Schweiße deines Angesichts sollst du dein Brod essen, bis du zum Erdboden zurückkehrst, denn ihm bist du entnommen. Denn Erde bist du und zu Erde mußt du wieder werden!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'Und der Mensch gab seinem Weibe den Namen Eva, denn sie wurde die Stammutter aller Lebendigen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'Und Jahwe Gott machte dem Menschen und seinem Weibe Röcke von Fell und zog sie ihnen an.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'Und Jahwe Gott sprach: Fürwahr, der Mensch ist geworden wie unsereiner, indem er Gutes und Böses erkennt; daß er nunmehr nur nicht etwa seine Hand ausstreckt und auch von dem Baume des Lebens nimmt und ißt und ewiglich lebt!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'Da entfernte ihn Jahwe Gott aus dem Garten Eden, damit er den Boden bebaue, dem er entnommen war.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, 'Da trieb er den Menschen aus und ließ östlich vom Garten Eden die Kerube sich lagern und die Flamme des zuckenden Schwerts, um den Weg zum Baume des Lebens zu bewachen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'Der Mensch aber wohnte seinem Weibe Eva bei; da wurde sie schwanger und gebar den Kain und sprach: Einen Menschen habe ich erhalten mit Hilfe Jahwes.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'Hierauf gebar sie abermals, den Abel, seinen Bruder; und Abel wurde ein Schafhirt, Kain aber ein Ackerbauer.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, 'Und nach Verlauf einiger Zeit brachte Kain Jahwe ein Opfer von den Früchten des Ackers;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'Abel aber brachte gleichfalls Opfer von den Erstlingen seiner Herde und zwar von ihrem Fett. Und Jahwe schaute mit Wohlgefallen auf Abel und sein Opfer;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'auf Kain aber und sein Opfer schaute er nicht. Da wurde Kain sehr ergrimmt und es senkte sich sein Antlitz.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'Da sprach Jahwe zu Kain: Warum bist du ergrimmt und warum senkt sich dein Antlitz?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, 'Ist\'s nicht also: wenn du recht handelst, so kannst du dein Antlitz frei erheben; wenn du aber nicht recht handelst, so lauert die Sünde vor der Thür und nach dir geht ihr Verlangen, du aber sollst Herr werden über sie!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'Da sagte Kain zu seinem Bruder Abel: Laß uns aufs Feld gehen! und als sie auf dem Felde waren, da griff Kain seinen Bruder Abel an und schlug ihn tot.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'Da sprach Jahwe zu Kain: Wo ist dein Bruder Abel? Er aber sprach: ich weiß nicht; bin ich etwa der Hüter meines Bruders?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'Da sprach er: Was hast du gethan! Horch, das Blut deines Bruders schreit zu mir vom Erdboden her!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'Und nun - verflucht sollst du sein, fortgetrieben von dem Boden, der seinen Mund aufgethan hat, um das Blut deines Bruders von deiner Hand in Empfang zu nehmen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'Wenn du den Boden bebaust, soll er dir keinen Ertrag mehr geben; unstät und flüchtig sollst du sein auf Erden!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'Da sprach Kain zu Jahwe: Unerträglich sind die Folgen meiner Verschuldung.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'Du treibst mich jetzt hinweg vom Ackerland, und vor deinem Angesicht muß ich mich verbergen und muß unstät und flüchtig sein auf Erden, und wer mich irgend antrifft, wird mich totschlagen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'Da sprach Jahwe zu ihm: Ebendarum soll, wer Kain erschlägt, siebenfältiger Rache verfallen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'Und Jahwe bestimmte ein Zeichen für Kain, damit ihn nicht erschlüge, wer ihn irgend träfe. Da zog Kain hinweg vom Angesicht Jahwes und nahm seinen Aufenthalt im Lande Nod östlich von Eden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'Und Kain wohnte seinem Weibe bei; da wurde sie schwanger und gebar den Henoch. Er erbaute aber eine Stadt und benannte die Stadt nach dem Namen seines Sohnes Henoch.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'Dem Henoch aber wurde Irad geboren und Irad erzeugte den Mehujael und Mehujael erzeugte den Methusael und Methusael erzeugte den Lamech.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'Lamech aber nahm sich zwei Weiber; die eine hieß Ada, die andere Zilla.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'Und Ada gebar den Jabal; der wurde der Stammvater der Zeltbewohner und Viehzüchter.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'Sein Bruder aber hieß Jubal; dieser wurde der Stammvater aller derer, die sich mit Zither und Schalmei befassen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'Und Zilla gebar ebenfalls, nämlich den Thubalkain, den Stammvater aller derer, die Erz und Eisen bearbeiten; die Schwester des Thubalkain aber war Naama.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'Da sprach Lamech zu seinen Weibern: Ada und Zilla, hört meine Rede; ihr Weiber Lamechs, vernehmt meinen Spruch! Einen Mann erschlage ich für meine Wunde und einen Jüngling für meine Strieme.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'Wird siebenfältig Kain gerächt, so Lamech siebenundsiebzigmal!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'Und Adam wohnte abermals seinem Weibe bei; da gebar sie einen Sohn und nannte ihn Seth. Denn Gott hat mir, sprach sie, andere Nachkommenschaft gesetzt an Stelle Abels, weil ihn Kain erschlagen hat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'Und auch dem Seth wurde ein Sohn geboren, den nannte er Enos. Damals fing man an, den Namen Jahwes anzurufen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'Dies ist das Buch über die Nachkommen Adams. Als Gott den Adam erschuf, da erschuf er ihn Gott ähnlich;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'als Mann und Weib erschuf er sie und er segnete sie und gab ihnen den Namen “Mensch” damals, als sie geschaffen wurden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'Als nun Adam 130 Jahre alt war, erzeugte er einen Sohn, der ihm glich als sein Abbild, und gab ihm den Namen Seth.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'Nach der Erzeugung des Seth aber lebte Adam noch 800 Jahre und erzeugte Söhne und Töchter.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'Und die ganze Lebensdauer Adams, die er durchlebte, betrug 930 Jahre; sodann starb er.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'Als nun Seth 105 Jahre alt war, erzeugte er den Enos.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'Nach der Erzeugung des Enos aber lebte Seth noch 807 Jahre und erzeugte Söhne und Töchter.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'Und die ganze Lebensdauer Seths betrug 912 Jahre; sodann starb er.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'Als nun Enos 90 Jahre alt war, erzeugte er den Kenan.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'Nach der Erzeugung Kenans aber lebte Enos noch 815 Jahre und erzeugte Söhne und Töchter.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'Und die ganze Lebensdauer des Enos betrug 905 Jahre; sodann starb er.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'Als nun Kenan 70 Jahre alt war, erzeugte er den Mahalalel.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'Nach der Erzeugung Mahalalels aber lebte Kenan noch 840 Jahre und erzeugte Söhne und Töchter.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'Und die ganze Lebensdauer Kenans betrug 910 Jahre; sodann starb er.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'Als nun Mahalalel 65 Jahre alt war, erzeugte er den Jared.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'Nach der Erzeugung Jareds aber lebte Mahalalel noch 830 Jahre und erzeugte Söhne und Töchter.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'Und die ganze Lebensdauer Mahalalels betrug 895 Jahre; sodann starb er.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'Als nun Jared 162 Jahre alt war, erzeugte er den Henoch.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'Nach der Erzeugung Henochs aber lebte Jared noch 800 Jahre und erzeugte Söhne und Töchter.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'Und die ganze Lebensdauer Jareds betrug 962 Jahre; sodann starb er.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'Als nun Henoch 65 Jahre alt war, erzeugte er den Methusalah.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'Nach der Erzeugung Methusalahs aber wandelte Henoch in Gemeinschaft mit Gott 300 Jahre und erzeugte Söhne und Töchter.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'Und die ganze Lebensdauer Henochs betrug 365 Jahre.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'Und weil Henoch in Gemeinschaft mit Gott gewandelt hatte, so verschwand er einst, denn Gott hatte ihn hinweggenommen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'Als nun Methusalah 187 Jahre alt war, erzeugte er den Lamech.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'Nach der Erzeugung des Lamech aber lebte Methusalah noch 782 Jahre und erzeugte Söhne und Töchter.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'Und die ganze Lebensdauer Methusalahs betrug 969 Jahre; sodann starb er.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'Als nun Lamech 182 Jahre alt war, erzeugte er einen Sohn;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'den hieß er Noah, indem er sprach: Dieser wird uns aufatmen lassen von unserer Arbeit und der Mühsal unserer Hände, die uns verursacht wird von dem Boden, den Jahwe verflucht hat!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'Nach der Erzeugung Noahs aber lebte Lamech noch 595 Jahre und erzeugte Söhne und Töchter.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'Und die ganze Lebensdauer Lamechs betrug 777 Jahre; sodann starb er.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, 'Als nun Noah 500 Jahre alt war, erzeugte er den Sem, den Ham und den Japhet.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'Als nun die Menschen anfingen, sich zu vermehren auf der Erde, und ihnen Töchter geboren wurden,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, 'da sahen die Gottessöhne, daß die Töchter der Menschen gar schön waren, und nahmen sich zu Weibern, welche ihnen irgend gefielen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'Da sprach Jahwe: Mein Geist soll nicht ewig im Menschen walten, denn auch er ist Fleisch, und seine Lebensdauer betrage 120 Jahre!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, 'Zu jener Zeit waren die Riesen auf Erden; und auch nach der Zeit, wo sich die Gottessöhne zu den Töchtern der Menschen gesellten, und diese ihnen gebaren - das sind die Recken, die in grauer Vorzeit waren, die Hochgefeierten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'Als nun Jahwe sah, daß die Bosheit der Menschen groß ward auf Erden und alles Dichten und Trachten ihres Herzens allezeit nur böse war,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'da bereute Jahwe, daß er die Menschen geschaffen hatte auf Erden, und war tief bekümmert.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'Da sprach Jahwe: Ich will die Menschen, die ich geschaffen habe, hinwegtilgen von der Erde, sowohl die Menschen, als das Vieh, das Gewürm und die Vögel des Himmels; denn es reut mich, daß ich sie geschaffen habe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'Noah aber hatte Gnade bei Jahwe gefunden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'Dies ist die Geschichte Noahs. Noah war ein frommer, unsträflicher Mann unter seinen Zeitgenossen; in Gemeinschaft mit Gott wandelte Noah.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'Und Noah erzeugte drei Söhne: Sem, Ham und Japhet.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'Die Erde aber war verderbt vor dem Angesichte Gottes, und die Erde wurde voll von Frevel.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'Da sah Gott, daß die Erde arg verderbt war; denn alles Fleisch hatte seinen Wandel verderbt auf Erden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, 'Da sprach Gott zu Noah: Das Ende alles Fleisches ist bei mir beschlossen, denn voll ist die Erde von Frevel, den sie verüben; so will ich sie nun von der Erde vertilgen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, 'Baue dir einen Kasten aus Gopherholz; mit lauter Zellen mußt du den Kasten erbauen und ihn inwendig und auswendig mit Harz verpichen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'Und also sollst du ihn bauen: 300 Ellen betrage die Länge des Kastens, 50 Ellen seine Breite und 30 Ellen seine Höhe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, 'Ein Fenster sollst du oben an dem Kasten machen; eine Elle weit sollst du es herstellen. Und den Eingang zu dem Kasten sollst du an seiner Seite anbringen; in drei Stockwerken mit lauter Zellen sollst du ihn erbauen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'Denn ich werde alsbald die Flut über die Erde kommen lassen, um alles Fleisch unter dem Himmel, das lebendigen Odem in sich hat, zu vertilgen; alles, was auf Erden ist, soll umkommen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'Aber mit dir will ich einen Bund aufrichten, und du sollst in den Kasten eingehen - du und deine Söhne und dein Weib und die Weiber deiner Söhne mit dir.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'Und von allem Lebendigen, von allem Fleische, sollst du je zwei von allen mit hineinnehmen in den Kasten, um sie samt dir am Leben zu erhalten; je ein Männchen und ein Weibchen soll es sein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'Von den Vögeln je nach ihrer Art, von dem Vieh je nach seiner Art, und von allem, was auf der Erde kriecht, je nach seiner Art sollen immer je zwei zu dir in den Kasten eingehen, damit sie am Leben bleiben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'Du aber beschaffe dir von jeder Art Speise, die genossen zu werden pflegt, und speichere sie bei dir auf, damit sie dir und ihnen zur Nahrung diene.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'Da that Noah ganz, wie ihm Gott geheißen hatte - so that er.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'Da sprach Jahwe zu Noah: Gehe du und dein ganzes Haus hinein in den Kasten; denn dich habe ich rechtschaffen vor mir erfunden in diesem Geschlecht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'Von allen reinen Tieren nimm dir je sieben, je ein Männchen und sein Weibchen; aber von den Tieren, die nicht rein sind, je zwei, ein Männchen und sein Weibchen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, 'Auch von den Vögeln unter dem Himmel je sieben, ein Männchen und ein Weibchen, um auf der ganzen Erde Samen am Leben zu erhalten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'Denn in noch sieben Tagen will ich regnen lassen auf die Erde vierzig Tage und vierzig Nächte lang und will alles Bestehende, das ich gemacht habe, wegtilgen von der Erde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'Da that Noah ganz, wie ihm Jahwe geheißen hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, 'Und Noah war 600 Jahre alt, als die Flut über die Erde kam.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'Da ging Noah und seine Söhne und sein Weib und die Weiber seiner Söhne mit ihm hinein in den Kasten vor den Gewässern der Flut.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'Von den reinen Tieren und von den Tieren, die nicht rein sind, und von den Vögeln und von allem, was auf dem Boden kriecht,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'gingen je zwei zu Noah in den Kasten, ein Männchen und ein Weibchen, wie Gott Noah geboten hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'Und nach Ablauf der sieben Tage, da kamen die Gewässer der Flut über die Erde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'Im sechshundertsten Lebensjahre Noahs, im zweiten Monat, am siebzehnten Tage des Monats, an diesem Tage brachen auf alle Sprudel der großen Meerestiefe, und die Gitter des Himmels thaten sich auf.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'Da strömte der Regen auf die Erde, vierzig Tage und vierzig Nächte lang.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'An eben diesem Tage gingen Noah und Sem und Ham und Japhet, die Söhne Noahs, und das Weib Noahs und die drei Weiber seiner Söhne mit ihnen hinein in den Kasten,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'sie und alle wilden Tiere nach ihrer Art und alles Vieh nach seiner Art und alles Gewürm, das auf der Erde kriecht, nach seiner Art und alle Vögel nach ihrer Art, was irgend Flügel hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'Die gingen hinein zu Noah in den Kasten, je zwei und zwei von allem Fleisch, das lebendigen Odem in sich hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'Und die hineingingen, waren je ein Männchen und ein Weibchen von allem Fleisch, wie ihm Gott geheißen hatte. Und Jahwe schloß hinter ihm zu.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'Da kam die Flut vierzig Tage über die Erde, und das Wasser wuchs und hob den Kasten empor, so daß er über der Erde schwebte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'Und die Gewässer nahmen überhand und wuchsen gewaltig auf der Erde; da fuhr der Kasten dahin auf dem Wasser.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'Und die Gewässer nahmen über alle Maßen überhand auf der Erde, so daß alle die hohen Berge, die irgend unter dem Himmel sind, überschwemmt wurden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'Fünfzehn Ellen hoch stiegen die Gewässer, so daß die Berge überschwemmt wurden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'Da kam um alles Fleisch, das sich auf der Erde regte, an Vögeln und an Vieh und an wilden Tieren, und alles Gewürm, das auf Erden kroch, und alle Menschen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'Alles, was Lebensodem in seiner Nase trug, soweit es auf dem Trockenen war, das starb.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'So vertilgte er alles Bestehende, was auf dem Erdboden war, sowohl Menschen als Vieh und Gewürm und die Vögel unter dem Himmel; und sie wurden vertilgt von der Erde, so daß nur Noah übrig blieb und was bei ihm im Kasten war.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'Und die Gewässer nahmen überhand auf Erden hundertundfünfzig Tage lang.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'Da gedachte Gott an Noah und an alle die wilden Tiere und an all das Vieh, welches bei ihm im Kasten war, und Gott ließ Wind über die Erde wehen, so daß die Gewässer fielen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'Da schlossen sich die Sprudel der Meerestiefe und die Gitter des Himmels, und dem Regen vom Himmel wurde Einhalt gethan.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'Da verliefen sich die Gewässer immer mehr von der Erde und die Gewässer nahmen ab nach Verlauf der hundertundfünfzig Tage.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, 'Und im siebenten Monat, am siebzehnten Tage des Monats, ließ sich der Kasten nieder auf einem der Berge Ararats.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'Und die Gewässer nahmen immer weiter ab bis zum zehnten Monat; im zehnten Monat, am ersten des Monats, wurden die Gipfel der Berge sichtbar.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'Nach Verlauf von vierzig Tagen aber öffnete Noah das Fenster des Kastens, das er gemacht hatte,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'und schickte den Raben aus; der flog hin und wieder, bis das Wasser auf Erden vertrocknete.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'Hierauf ließ er die Taube von sich ausfliegen, um zu erfahren, ob sich die Gewässer von der Erde verlaufen hätten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'Aber die Taube fand keinen Ort, wo ihr Fuß ruhen konnte; da kehrte sie zu ihm in den Kasten zurück, denn noch war Gewässer auf dem ganzen Erdboden; und er streckte seine Hand aus und holte sie zu sich herein in den Kasten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, 'Hierauf wartete er noch weitere sieben Tage, dann ließ er abermals die Taube aus dem Kasten ausfliegen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'Da kam die Taube zur Abendzeit zu ihm und zwar mit einem frischen Ölblatt im Schnabel. Da erkannte Noah, daß sich die Gewässer von der Erde verlaufen hatten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'Hierauf wartete er noch weitere sieben Tage und ließ die Taube ausfliegen; diesmal aber kehrte sie nicht wieder zu ihm zurück.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'Und im sechshundertersten Jahre, am ersten Tage des ersten Monats, waren die Gewässer auf Erden versiegt. Da entfernte Noah das Dach des Kastens und schaute aus: da war der Erdboden trocken geworden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, 'Und im zweiten Monat, am siebenundzwanzigsten Tage des Monats, war die Erde ganz trocken.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, 'Da redete Gott zu Noah und sprach:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, 'Gehe heraus aus dem Kasten, du und dein Weib und deine Söhne und die Weiber deiner Söhne mit dir.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'Alle Tiere, welche bei dir sind, von allem Fleisch, an Vögeln und Vieh und an allem Gewürm, das auf der Erde kriecht, laß mit dir herausgehn, damit sie sich auf der Erde tummeln und fruchtbar seien und sich vermehren auf der Erde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'Da ging Noah heraus und seine Söhne und sein Weib und die Weiber seiner Söhne mit ihm.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'Alle vierfüßigen Tiere, alles Gewürm und alle Vögel, alles was sich auf Erden regt, nach ihren verschiedenen Arten, gingen heraus aus dem Kasten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, 'Da erbaute Noah Jahwe einen Altar und nahm von allen reinen Tieren und von allen reinen Vögeln und brachte Brandopfer dar auf dem Altar.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'Als nun Jahwe den lieblichen Duft roch, da sprach er bei sich selbst: Ich will hinfort die Erde nicht mehr verfluchen um der Menschen willen. Denn das Dichten des menschlichen Herzens ist böse von Jugend auf; und ich will hinfort nicht mehr alles Lebendige schlagen, wie ich gethan habe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'Fortan sollen, so lange die Erde steht, nicht aufhören Säen und Ernten, Frost und Hitze, Sommer und Winter und Tag und Nacht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'Da segnete Gott Noah und seine Söhne und sprach zu ihnen: Seid fruchtbar und mehrt euch und bevölkert die Erde!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'Und Furcht und Schrecken vor euch soll kommen über alle Tiere auf Erden und über alle Vögel unter dem Himmel, über alles, was sich auf Erden regt, und über alle Fische des Meeres: in eure Gewalt sind sie gegeben!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'Alles, was sich regt und lebt, soll euch zur Nahrung dienen: wie das grüne Kraut gebe ich es euch alles.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, 'Nur Fleisch, das noch sein Leben, sein Blut in sich hat, dürft ihr nicht essen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'Euer eignes Blut aber will ich rächen; an jedem Tiere will ich es rächen und an einem jeden Menschen, als der sein Bruder ist, will ich das Leben des Menschen rächen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'Wer Menschenblut vergießt, des Blut soll auch durch Menschen vergossen werden; denn nach seinem Bilde hat Gott den Menschen gemacht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'Ihr aber seid fruchtbar und mehrt euch; regt euch auf der Erde und mehr euch auf ihr!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, 'Da sprach Gott zu Noah und zu seinen Söhnen, die bei ihm waren, also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, 'Siehe, ich errichte einen Bund mit euch und mit euren Nachkommen');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'und mit allen lebendigen Wesen, die bei euch sind, an Vögeln, an Vieh und an allen wilden Tieren, die bei euch sind, was irgend von den Tieren auf Erden aus dem Kasten herausgegangen ist.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'Und zwar will ich meinen Bund mit euch aufrichten, daß hinfort kein Geschöpf mehr hinweggetilgt werden soll durch die Wasser der Flut, und daß hinfort keine Flut mehr kommen soll, die Erde zu verheeren.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'Und Gott sprach: Dies sei das Zeichen des Bundes, den ich stifte zwischen mir und euch und allen lebendigen Wesen, die bei euch sind, auf alle kommenden Geschlechter:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'Meinen Bogen stelle ich in die Wolken, damit er als ein Zeichen des Bundes zwischen mir und der Erde diene.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'Und wenn ich je Wolken über der Erde anhäufe, und der Bogen in den Wolken erscheint,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'so will ich an den Bund denken, der zwischen mir und euch und allen lebendigen Wesen unter allem Fleische besteht, daß die Gewässer nicht wieder zu einer Flut werden sollen, alles Fleisch zu verderben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'Und wenn der Bogen in den Wolken steht, will ich ihn ansehen, um eingedenk zu werden des ewigen Bundes zwischen Gott und allen lebendigen Wesen unter allem Fleisch, das auf Erden ist.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'Und Gott sprach zu Noah: Dies sei das Zeichen des Bundes, den ich aufgerichtet habe zwischen mir und allem Fleisch, das auf Erden ist.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'Es waren aber die Söhne Noahs, die aus dem Kasten gingen, Sem und Ham und Japhet; Ham aber ist der Vater Kanaans.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'Das sind die drei Söhne Noahs, und von ihnen aus verzweigte sich die gesamte Bevölkerung der Erde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, 'Und Noah, der Landmann, fing an, einen Weinberg zu pflanzen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'Als er aber von dem Weine trank, wurde er trunken und lag entblößt in seinem Zelte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'Als nun Ham, der Vater Kanaans, seinen Vater so entblößt sah, sagte er es seinen beiden Brüdern draußen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'Da nahmen Sem und Japhet das Obergewand, legten es auf ihre Schulter und deckten rückwärts gehend die Blöße ihres Vaters zu; ihr Gesicht aber war abgewandt, so daß sie die Blöße ihres Vater nicht sahen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'Als aber Noah von seinem Rausche erwachte und erfuhr, was ihm sein jüngster Sohn angethan hatte,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, 'da sprach er: Verflucht sei Kanaan! als niedrigster Sklave soll er seinen Brüdern dienen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'Dann sprach er Gepriesen sei Jahwe der Gott Sems; aber Kanaan soll ihr Sklave sein!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'Weiten Raum schaffe Gott für Japhet, und er wohne in den Zelten Sems; aber Kanaan soll ihr Sklave sein!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'Und Noah lebte nach der Flut 350 Jahre;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'und die ganze Lebensdauer Noahs betrug 950 Jahre; sodann starb er.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'Und dies ist die Geschichte der Söhne Noahs, Sem, Ham und Japhet; und es wurden ihnen Söhne geboren nach der Flut.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'Die Söhne Japhets waren: Gomer, Magog, Madai, Javan, Tubal, Mesech und Tiras.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'Und die Söhne Gomers: Askenas, Riphath und Togarma.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'Und die Söhne Javans: Elisa, Tarsis, die Kittiter und die Rodaniter.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, 'Von diesen zweigten sich ab die Bewohner der Inseln der Heiden. Dies sind die Söhne Japhets nach ihren Ländern, ihren verschiedenen Sprachen, ihren Stämmen, ihren Völkerschaften.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, 'Und die Söhne Hams waren Kusch, Mizraim, Put und Kanaan.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'Und die Söhne Kuschs: Seba, Havila, Sabta, Raema und Sabtecha; und die Söhne Raemas waren Saba und Dedan.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'Und Kusch erzeugte den Nimrod; dieser fing an, ein Gewaltiger zu werden auf der Erde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'Dieser war ein gewaltiger Jäger vor Jahwe; daher pflegt man zu sagen: ein gewaltiger Jäger vor Jahwe, wie Nimrod!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'Es erstreckte sich aber seine Herrschaft anfänglich auf Babel und Erech und Akkad und Kalne im Lande Sinear.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, 'Von diesem Lande zog er aus nach Assur und erbaute Nineve und Rehoboth-Ir und Kalah');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'und Resen zwischen Nineve und Kalah - das ist die große Stadt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'Und Mizraim erzeugte die Luditer, die Anamiter, die Lehabiter, die Naphtuhiter,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'die Patrusiter, die Kasluhiter (von denen die Philister ausgegangen sind) und die Kaphtoriter.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, 'Kanaan aber erzeugte Sidon, seinen Erstgebornen, und Heth');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'und die Jebusiter, Amoriter, Girgasiter,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'Heviter, Arkiter, Siniter,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'Arvaditer, Zemariter und Hamathiter; und darnach breiteten sich die Stämme der Kanaaniter aus.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'Und das Gebiet der Kanaaniter erstreckte sich von Zidon bis hin nach Gerar bis Gaza, bis hin nach Sodom, Gomorra, Adma und Zeboim bis Lasa.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, 'Dies sind die Söhne Hams nach ihren Stämmen und Sprachen, ihren Ländern und Völkerschaften.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'Aber auch Sem, dem Stammvater aller Söhne Ebers, dem älteren Bruder Japhets, wurden Söhne geboren.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'Die Söhne Sems sind Elam, Assur, Arpachsad, Lud und Aram.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'Und die Söhne Arams sind Uz, Hul, Gether und Mas.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'Arpachsad aber erzeugte Selah und Selah erzeugte Eber.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'Und dem Eber wurden zwei Söhne geboren; der eine hieß Peleg, weil sich zu seiner Zeit die Bevölkerung der Erde zerteilte, und sein Bruder hieß Joktan.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'Und Joktan erzeugte Almodad, Saleph, Hazarmaveth, Jarah,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'Hadoram, Usal, Dikla,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'Obal, Abimael, Saba,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'Ophir, Havila und Jobab: diese alle sind Söhne Joktans.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'Und ihre Wohnsitze erstreckten sich von Mesa bis gen Sephar, bis zum Ostgebirge.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, 'Das sind die Söhne Sems nach ihren Stämmen und Sprachen, ihren Ländern und Völkerschaften.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'Das sind die Stämme der Söhne Noahs nach ihren Sippschaften, ihren Völkern; und von ihnen zweigten sich ab die Völker auf Erden nach der Flut.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'Es hatte aber die ganze Menschheit eine Sprache und einerlei Worte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'Als sie nun im Osten umherzogen, fanden sie eine Ebene im Lande Sinear und ließen sich daselbst nieder.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, 'Und sie sprachen zu einander: Wohlan, laßt uns Ziegel streichen und hart brennen! So diente ihnen der Ziegel als Baustein, und das Erdharz diente ihnen als Mörtel.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'Da sprachen sie: Wohlan, wir wollen uns eine Stadt bauen und einen Turm, dessen Spitze bis an den Himmel reicht, und wollen uns ein Denkmal machen, damit wir uns nicht über die ganze Erde hin zerstreuen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'Da stieg Jahwe herab, um die Stadt und den Turm, den die Menschenkinder erbaut hatten, zu besehen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'Und Jahwe sprach: Ein Volk sind sie und haben alle dieselbe Sprache, und das ist nur der Anfang ihres Thuns, und fortan wird ihnen nichts unerreichbar sein, was sie sich vornehmen werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'Wohlan, wir wollen hinabfahren und daselbst ihre Sprache verwirren, so daß keiner mehr die Sprache des andern verstehen soll!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'So zerstreute sie Jahwe von dort über die ganze Erde, so daß sie davon abstehen mußten, die Stadt zu erbauen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'Darum nennt man sie Babel, weil Jahwe dort die Sprache der ganzen Menschheit verwirrte und Jahwe sie von dort über die ganze Erde zerstreute.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, 'Dies ist die Geschichte Sems. Als Sem hundert Jahre alt war, erzeugte er Arpachsad, zwei Jahre nach der Flut.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'Nach der Erzeugung Arpachsads aber lebte Sem noch 500 Jahre und erzeugte Söhne und Töchter.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'Als nun Arpachsad 35 Jahre alt war, erzeugte er Selah.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'Nach der Erzeugung Selahs aber lebte Arpachsad noch 403 Jahre und erzeugte Söhne und Töchter.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'Als nun Selah 30 Jahre alt war, erzeugte er Eber.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'Nach der Erzeugung Ebers aber lebte Selah noch 403 Jahre und erzeugte Söhne und Töchter.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'Als nun Eber 34 Jahre alt war, erzeugte er Peleg.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'Nach der Erzeugung Pelegs aber lebte Eber noch 430 Jahre und erzeugte Söhne und Töchter.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'Als nun Peleg 30 Jahre alt war, erzeugte er Reu.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'Nach der Erzeugung Reus aber lebte Peleg noch 209 Jahre und erzeugte Söhne und Töchter.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'Als nun Reu 32 Jahre alt war, erzeugte er Serug.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'Nach der Erzeugung Serugs aber lebte Reu noch 207 Jahre und erzeugte Söhne und Töchter.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'Als nun Serug 30 Jahre alt war, erzeugte er Nahor.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'Nach der Erzeugung Nahors aber lebte Serug noch 200 Jahre und erzeugte Söhne und Töchter.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'Als nun Nahor 29 Jahre alt war, erzeugte er Tharah.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'Nach der Erzeugung Tharahs aber lebte Nahor noch 119 Jahre und erzeugte Söhne und Töchter.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'Als nun Tharah 70 Jahre alt war, erzeugte er Abram, Nahor und Haran.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'Und dies ist die Geschichte Tharahs: Tharah erzeugte Abram, Nahor und Haran; Haran aber erzeugte Lot.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'Es starb jedoch Haran vor seinem Vater Tharah in seinem Geburtslande, zu Ur in Chaldäa.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'Da nahmen sich Abram und Nahor Weiber; das Weib Abrams hieß Sarai und das Weib Nahors Milka, die Tochter Harans, des Vaters der Milka und der Jiska.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'Sarai aber war unfruchtbar; sie hatte kein Kind.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'Da nahm Tharah seinen Sohn Abram und Lot, den Sohn seines Sohnes Haran, und seine Schwiegertochter Sarai, das Weib seines Sohnes Abram, und führte sie aus Ur in Chaldäa hinweg, um in das Land Kanaan zu ziehen; und sie gelangten bis Haran und ließen sich daselbst nieder.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'Es betrug aber die Lebensdauer Tharahs 205 Jahre; sodann starb Tharah in Haran.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'Da sprach Jahwe zu Abram: Ziehe hinweg aus deinem Lande, von deiner Verwandtschaft und aus deines Vaters Hause in das Land, das ich dir zeigen werde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'Und ich will dich zu einem großen Volke machen und will dich segnen und dir einen großen Namen machen, und sollst ein Segen sein!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'Und ich will segnen, die dich segnen, und den, der dich verwünscht, will ich verfluchen, und durch dich sollen gesegnet werden alle Völkerstämme auf Erden!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'Da zog Abram hinweg, wie Jahwe zu ihm gesagt hatte, und Lot zog mit ihm. Abram aber war 75 Jahre alt, als er von Haran auszog.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'Da nahm Abram sein Weib Sarai und Lot, seines Bruders Sohn, und alle ihre Habe, die sie besaßen, und die Seelen, die sie in Haran erworben hatten, und sie zogen aus, um sich ins Land Kanaan zu begeben, und gelangten ins Land Kanaan.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'Und Abram durchzog das Land bis zu der Stätte von Sichem, bis zur Orakel-Terebinthe; es waren aber damals die Kanaaniter im Lande.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'Da erschien Jahwe dem Abram und sprach zu ihm: Deinen Nachkommen will ich dieses Land verleihen! Da erbaute er dort Jahwe, der ihm erschienen war, einen Altar.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'Von da rückte er weiter vor aufs Gebirge, östlich von Bethel, und schlug sein Zelt auf, so daß er Bethel westlich und Ai östlich hatte; und er erbaute daselbst Jahwe einen Altar und rief den Namen Jahwes an.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'Hierauf zog Abram immer weiter und weiter nach dem Südland zu.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, 'Es kam aber eine Hungersnot ins Land. Da zog Abram hinab nach Ägypten, um sich eine Zeit lang dort aufzuhalten, denn die Hungersnot lag schwer auf dem Lande.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'Als er nun nahe daran war, nach Ägypten zu gelangen, sprach er zu seinem Weibe Sarai: Ich weiß gar wohl, daß du ein schönes Weib bist.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'Wenn dich nun die Ägypter erblicken werden, werden sie sagen: Sie ist sein Weib! und werden mich totschlagen, dich aber werden sie am Leben lassen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'Bitte, sage doch, du seist meine Schwester, damit es mir wohl gehe um deinetwillen, und ich deinetwegen ungefährdet bleibe!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'Als nun Abram nach Ägypten gelangt war, da sahen die Ägypter, daß das Weib überaus schön war.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'Und als die obersten Beamten des Pharao sie zu Gesicht bekommen hatten, rühmten sie sie gegen den Pharao; da wurde das Weib in den Palast des Pharao geholt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'Gegen Abram aber erzeigte er sich freigebig um ihretwillen, und es wurden ihm Schafe und Rinder und Esel, Sklaven und Sklavinnen, Eselinnen und Kamele zu teil.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, 'Jahwe aber schlug den Pharao mit schweren Plagen und sein Haus wegen Sarai, des Weibes Abrams.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'Da ließ der Pharao Abram rufen und sprach: Was hast du mir da angethan! Warum sagtest du mir nicht, daß sie dein Weib ist?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, 'Warum hast du behauptet: sie ist meine Schwester, so daß ich sie mir zum Weibe nahm? nun aber - hier hast du dein Weib; nimm sie und geh!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'Und der Pharao entbot seinetwegen Leute, daß sie ihn und sein Weib und alles, was ihm gehörte, geleiteten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'Und Abram zog herauf aus Ägypten mit seinem Weibe und allem, was ihm gehörte, und Lot mit ihm, in das Südland.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'Abram aber war sehr reich an Vieh, an Silber und an Gold.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, 'Und er zog immer weiter und weiter aus dem Südland bis nach Bethel, bis zu der Stelle, wo vordem sein Zelt gestanden hatte, zwischen Bethel und Ai,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'zu der Stätte des Altars, den er früher dort erbaut hatte. Und Abram rief daselbst den Namen Jahwes an.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'Aber auch Lot, der mit Abram zog, hatte Schafe und Rinder und Zelte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'Und das Land ertrug sie nicht, daß sie hätten bei einander bleiben können; denn ihre Habe war groß, und es war unmöglich, daß sie bei einander blieben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'Und es entstand Zwietracht zwischen den Hirten von Abrams Vieh und den Hirten von Lots Vieh; überdies waren die Kanaaniter und Pheresiter damals im Lande ansässig.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'Da sprach Abram zu Lot: Laß doch nicht Zwietracht sein zwischen mir und dir und zwischen meinen und deinen Hirten; sind wir doch Brüder!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, 'Steht dir nicht das ganze Land offen? Trenne dich lieber von mir; willst du zur Linken, so will ich rechts gehen, und willst du zur Rechten, so will ich links gehen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, 'Da erhob Lot seine Augen und gewahrte, daß die ganze Jordansaue durchaus wohlbewässertes Land war, bevor Jahwe Sodom und Gomorra zerstörte, gleich dem Garten Jahwes, wie Ägyptenland, bis nach Zoar hin.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'Da wählte sich Lot die ganze Jordansaue, und Lot brach auf nach Osten, und so trennten sie sich von einander;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'Abram wohnte im Lande Kanaan, während Lot in den Städten der Aue wohnte. Und er rückte mit seinen Zelten weiter bis nach Sodom.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'Die Leute von Sodom aber waren böse und sündigten sehr gegen Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'Jahwe aber sprach zu Abram, nachdem sich Lot von ihm getrennt hatte: Erhebe deine Augen und schaue von dem Ort, an welchem du dich befindest, nach Norden, Süden, Osten und Westen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'Denn all das Land, welches du siehst, will ich dir zu eigen geben und deinen Nachkommen für immer.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'Und ich will deine Nachkommen so zahlreich machen, wie die Krümchen der Erde, daß deine Nachkommen so wenig zu zählen sein werden, als jemand die Erdkrümchen zu zählen vermag.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'Mache dich auf und durchziehe das Land nach seiner Länge und Breite, denn dir will ich es zu eigen geben!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'Abram aber rückte weiter mit seinen Zelten und kam und ließ sich nieder bei den Terebinthen Mamres, die sich zu Hebron befinden, und erbaute daselbst Jahwe einen Altar.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, 'Es begab sich aber zur Zeit Amraphels, des Königs von Sinear, da fingen Arioch, der König von Ellasar, Kedorlaomer, der König von Elam, und Tideal, der König der Heiden,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'Krieg an mit Bera, dem König von Sodom, und mit Birsa, dem König von Gomorra, Sineab, dem König von Adma, und Semeber, dem König von Zeboim, und mit dem König von Bela, das ist Zoar.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'Alle diese zogen vereint ins Gefilde von Siddim, das ist das heutige Salzmeer.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'Zwölf Jahre hindurch waren sie Kedorlaomer unterthan gewesen und im dreizehnten waren sie abgefallen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'Im vierzehnten Jahre aber kam Kedorlaomer und die Könige, die mit ihm waren, und sie schlugen die Rephaiter zu Astaroth Karnaim und die Susiter zu Ham und die Emiter in der Ebene von Kirjathaim');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'und die Horiter auf ihrem Gebirge Seir bis nach El Paran, welches östlich von der Wüste liegt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, 'Hierauf wandten sie um und gelangten nach En Mispat, das ist Kades; und sie schlugen das ganze Land der Amalekiter, dazu auch die Amoriter, die in Hazazon Thamar wohnten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'Da zogen der König von Sodom und der König von Gomorra und der König von Adma und der König von Zeboim und der König von Bela, das ist Zoar, aus und stellten sich gegen sie in Schlachtordnung im Gefilde von Siddim,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, 'gegen Kedorlaomer, den König von Elam, Tideal, den König der Heiden, Amraphel, den König von Sinear, und Arioch, den König von Ellasar - vier Könige gegen fünf!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, 'Im Gefilde von Siddim aber war eine Erdharzgrube an der andern. Als nun die Könige von Sodom und Gomorra fliehen mußten, versanken sie darein, und was übrig blieb, foh auf das Gebirge.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, 'Da nahmen sie die gesamte Habe von Sodom und Gomorra und ihren gesamten Mundvorrat und zogen davon.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'Sie nahmen aber auch Lot, den Sohn des Bruders Abrams, der in Sodom wohnte, samt seiner Habe und zogen davon.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, 'Da kam einer, der entronnen war, und berichtete es Abram, dem Hebräer; derselbe wohnte bei den Terebinthen des Amoriters Mamre, des Bruders Eskols und Aners. Diese waren im Bunde mit Abram.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'Als nun Abram hörte, daß sein Verwandter weggeführt worden sei als Gefangener, da ließ er seine erprobten Leute, die in seinem Hause geborenen Sklaven, dreihundert und achtzehn, ausrücken und jagte nach bis Dan.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, 'Da teilte er seine Leute in mehrere Haufen und überfiel sie des Nachts, schlug sie und verfolgte sie bis Hoba, welches nördlich von Damaskus liegt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'Hierauf brachte er die gesamte Habe zurück und auch Lot, seinen Verwandten, brachte er zurück samt seiner Habe, ebenso auch die Weiber und das Volk.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'Als er nun Kedorlaomer und die Könige, die mit ihm waren, besiegt hatte und wieder heimkehrte, da zog ihm der König von Sodom entgegen ins Thal Save, das ist das Königsthal.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, 'Und Melchisedek, der König von Salem, brachte Brot und Wein heraus; derselbe war ein Priester des höchsten Gottes.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, 'Und er segnete ihn und sprach: Gesegnet werde Abram vom höchsten Gott, dem Schöpfer des Himmels und der Erde!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, 'Und gepriesen sei der höchste Gott, der deine Feinde in deine Hand gegeben hat! Da gab ihm Abram den Zehnten von allem.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, 'Und der König von Sodom sprach zu Abram: Gieb mir die Leute; dagegen die Habe behalte für dich.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'Da sprach Abram zum König von Sodom: Ich erhebe meine Hand zu Jahwe, dem höchsten Gott, dem Schöpfer des Himmels und der Erde:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'Nicht ein Faden, noch einen Schuhriemen, überhaupt nichts von dem, was dir gehört, nehme ich an, damit du nicht sagest, du habest Abram bereichert!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'Ich mag nichts! Nur was die Knechte verzehrt haben, und der Anteil der Männer, die mit mir gezogen sind, Aner, Eskol und Mamre - die mögen ihr Teil nehmen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, 'Nach diesen Begebenheiten erging das Wort Jahwes an Abram in einem Gesicht; und er sprach: Fürchte dich nicht, Abram; ich bin dein Schild - es wartet deiner reicher Lohn!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'Da sprach Abram: O Herr Jahwe! Was willst du mir geben, während ich doch kinderlos dahingehe, und der Erbe meines Besitzes wird Elieser sein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'Und Abram sprach: Mir hast du ja keine Nachkommenschaft gegeben; so wird denn ein Leibeigener meines Hauses mich beerben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'Aber das Wort Jahwes erging an ihn also: Er soll nicht dein Erbe sein, sondern einer, der von deinem Leibe kommen wird, der soll dich beerben!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'Und er führte ihn hinaus ins Freie und sprach: Blicke auf zum Himmel und zähle die Sterne, ob du sie zu zählen vermagst! Und er sprach zu ihm: So zahlreich sollen deine Nachkommen sein!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'Und er glaubte Jahwe, und das rechnete er ihm zu als Gerechtigkeit.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, 'Da sprach er zu ihm: Ich bin Jahwe, der dich ausgeführt hat aus Ur in Chaldäa, um dir dieses Land zu eigen zu geben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'Und er sprach: O Herr Jahwe! Woran soll ich erkennen, daß ich es besitzen werde?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'Da sprach er zu ihm: Hole mir eine dreijährige Kuh, eine dreijährige Ziege, einen dreijährigen Widder, eine Turteltaube und eine junge Taube.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'Da holte er ihm alle diese, zerteilte sie in je zwei gleiche Teile und legte je die eine Hälfte der andern gegenüber; die Vögel aber zerteilte er nicht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'Da stießen die Raubvögel herab auf die Stücke; Abram aber scheuchte sie hinweg.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'Als nun die Sonne untergehen wollte, da fiel ein tiefer Schlaf auf Abram, und Beängstigung, dichte Finsternis überfiel ihn.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'Da sprach er zu Abram: Du mußt wissen, daß deine Nachkommen Fremdlinge sein werden in einem Lande, das ihnen nicht gehört; und sie werden ihnen leibeigen sein, und jene werden sie hart bedrücken vierhundert Jahre lang.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'Aber auch das Volk, dem sie leibeigen sein werden, will ich richten, und darnach sollen sie ausziehen mit reicher Habe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'Du aber wirst in Frieden zu deinen Vätern eingehen; du wirst begraben werden in einem schönen Alter.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'Und das vierte Geschlecht von ihnen wird hierher zurückkehren; denn noch ist das Maß der Schuld der Amoriter nicht voll.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'Als aber die Sonne untergegangen und dichte Finsternis eingetreten war, da kam ein Rauch, wie aus einem Ofen, und eine Feuerfackel, die zwischen jenen Stücken hindurchging.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'An jenem Tage schloß Jahwe einen Bund mit Abram und sprach: Deinen Nachkommen will ich dieses Land geben vom Strome Ägyptens an bis zum großen Strom, dem Euphratstrom,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'das Land der Keniter, der Kenissiter, der Kadmoniter,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'der Hethiter, der Pheresiter, der Rephaiter,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'der Amoriter, der Kanaaniter, der Girgasiter und der Jebusiter.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'Und Sarai, das Weib Abrams, hatte ihm keine Kinder geboren; sie hatte aber eine ägyptische Sklavin Namens Hagar.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'Da sprach Sarai zu Abram: Da mir Jahwe nun einmal Kinder versagt hat, so gehe doch ein zu meiner Leibmagd: vielleicht werde ich durch sie zu Kindern kommen! Und Abram gehorchte den Worten Sarais.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'Da nahm Sarai, das Weib Abrams, die Ägypterin Hagar, ihre Leibmagd, nachdem Abram zehn Jahre im Lande Kanaan gewohnt hatte, und gab sie Abram, ihrem Manne, zum Weibe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, 'Und er wohnte Hagar bei, und sie wurde schwanger. Als sie aber merkte, daß sie schwanger sei, sah sie ihre Herrin geringschätzig an.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'Sarai aber sprach zu Abram: Die Kränkung, die mir widerfährt, komme über dich! Ich selbst habe dir meine Leibmagd abgetreten; nun sie aber merkt, daß sie schwanger ist, sieht sie mich geringschätzig an. Jahwe richte zwischen mir und dir!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'Da sprach Abram zu Sarai: Deine Leibmagd ist ja in deiner Gewalt; verfahre mit ihr, wie es dir gut dünkt!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'Da behandelte Sarai sie hart, so daß sie ihr entfloh. Da traf sie der Engel Jahwes an der Quelle in der Wüste, an der Quelle auf dem Wege nach Sur.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'Und er sprach: Hagar, Leibmagd Sarais, woher kommst du und wohin willst du? Sie antwortete: Ich bin auf der Flucht vor Sarai, meiner Herrin.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'Und der Engel Jahwes sprach zu ihr: Kehre zurück zu deiner Herrin und unterwirf dich ihrer Gewalt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'Und der Engel Jahwes sprach zu ihr: Ich will deine Nachkommenschaft überaus zahlreich machen, so daß sie unzählbar sein soll vor Menge.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'Und der Engel Jahwes sprach zu ihr: Du bist jetzt schwanger und wirst einen Sohn gebären; den sollst du Ismael nennen, weil Jahwe die Klage über dein Elend erhört hat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'Der aber wird ein Mensch wie ein Wildesel sein - seine Hand gegen jedermann und jedermanns Hand gegen ihn - und er wird allen seinen Verwandten auf dem Nacken sitzen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'Da nannte sie Jahwe, der zu ihr geredet hatte: Du bist der Gott des Schauens! Denn sie sprach: Habe ich auch wirklich hier dem nachgeschaut, der mich erschaut hat?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'Daher nennt man jenen Brunnen “Brunnen des Lebendigen, der mich schaut”; er liegt aber zwischen Kades und Bared.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'Und Hagar gebar Abram einen Sohn, und Abram nannte den Sohn, den ihm Hagar geboren hatte, Ismael.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'Abram aber war sechsundachtzig Jahre alt, als Hagar dem Abram den Ismael gebar.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'Und als Abram neunundneunzig Jahre alt war, erschien Jahwe dem Abram und sprach zu ihm: Ich bin Gott, der Allmächtige, wandle vor mir und sei fromm,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'so will ich einen Bund stiften zwischen mir und dir und will dir überaus zahlreiche Nachkommen verleihen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'Da warf sich Abram nieder auf sein Angesicht und Gott redete mit ihm also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, 'Ich bin\'s, der ich den Bund mit dir habe, daß du Stammvater eines Haufens von Völkern werden sollst.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'Darum sollst du fortan nicht mehr Abram heißen, sondern Abraham soll dein Name sein. Denn zum Stammvater eines Haufens von Völkern mache ich dich.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'Und ich will machen, daß deine Nachkommen überaus zahlreich werden und zu ganzen Völkern anwachsen und sogar Könige sollen von dir abstammen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'Und ich will meinen Bund aufrichten zwischen mir und dir und deinen Nachkommen nach dir, nach ihren Geschlechtern, als einen ewigen Bund, daß ich dir Gott sein will und deinen Nachkommen nach dir.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'Und ich will dir und deinen Nachkommen nach dir das Land verleihen, in welchem du jetzt als Fremdling weilst, das ganze Land Kanaan, zum Eigentum für immer, und will ihr Gott sein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'Und Gott sprach zu Abraham. Du aber sollst meinen Bund halten, du und deine Nachkommen nach dir, nach ihren Geschlechtern.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'Das ist der Bund, den ihr halten sollt zwischen mir und euch und deinen Nachkommen nach dir: alles, was männlich ist unter euch, soll beschnitten werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'Und zwar sollt ihr beschnitten werden am Fleisch eurer Vorhaut, und dies sei das Zeichen des Bundes zwischen mir und euch.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, 'Im Alter von acht Tagen soll alles, was männlich ist unter euch, beschnitten werden, Geschlecht für Geschlecht, sowohl der im Hause geborene, als der von irgend einem Fremden mit Geld erkaufte Sklave, der nicht deines Stammes ist.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'Beschnitten soll werden sowohl der in deinem Hause geborene, als der von dir mit Geld erkaufte, und so soll mein Bund an eurem Leibe bezeugt sein als ein ewiger Bund.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'Ein unbeschnittener Mann aber, der nicht beschnitten ist am Fleische seiner Vorhaut, - ein solcher soll weggetilgt werden aus seinen Volksgenossen; meinen Bund hat er gebrochen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'Und weiter sprach Gott zu Abraham: Dein Weib Sarai sollst du nicht mehr Sarai nennen, sondern Sara soll ihr Name sein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'Und ich will sie segnen und will dir auch durch sie einen Sohn schenken und will sie segnen, und sie soll die Stammmutter ganzer Völker werden; Völkerbeherrscher sollen von ihr abstammen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'Da warf sich Abraham nieder auf sein Angesicht und lachte, denn er dachte bei sich: Sollte wohl einem Hundertjährigen noch ein Sohn geboren werden, und sollte Sara, die neunzigjährige, noch gebären?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'Und Abraham sprach zu Gott: Möchte nur Ismael am Leben bleiben vor dir!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'Da sprach Gott: Nein! Dein Weib Sara wird dir einen Sohn gebären, den sollst du Isaak nennen, und ich werde meinen Bund mit ihm aufrichten als einen ewigen Bund für seine Nachkommen nach ihm.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, 'Aber auch in betreff Ismaels will ich dich erhören; ich will ihn segnen und ihn fruchtbar sein lassen und will machen, daß seine Nachkommen ganz überaus zahlreich werden. Zwölf Fürsten wird er zeugen, und ich will machen, daß er zu einem großen Volke wird.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'Aber meinen Bund werde ich aufrichten mit Isaak, den dir Sara gebären wird um diese Zeit im künftigen Jahre.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'Und als er seine Unterredung mit ihm geendigt hatte, fuhr Gott auf von Abraham.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, 'Da nahm Abraham seinen Sohn Ismael und alle in seinem Hause geborenen, sowie alle mit Geld von ihm erkauften Sklaven, alles, was männlich war unter den Hausgenossen Abrahams, und beschnitt an eben diesem Tage das Fleisch ihrer Vorhaut, wie Gott ihm geboten hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'Abraham aber war neunundneunzig Jahre alt, als er beschnitten wurde am Fleische seiner Vorhaut.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'Und sein Sohn Ismael war dreizehn Jahre alt, als er beschnitten wurde am Fleische seiner Vorhaut.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'An eben diesem Tage wurden beschnitten Abraham und sein Sohn Ismael;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'und alle seine Hausgenossen, sowohl die im Hause geborenen, als die mit Geld von Fremden erkauften Sklaven, wurden mit ihm beschnitten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'Da erschien ihm Jahwe bei den Terebinthen Mamres, während er um die heißeste Tageszeit am Eingang des Zeltes saß.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'Als er nun aufblickte, da gewahrte er, daß drei Männer vor ihm dastanden; und als er sie sah, lief er vom Eingang des Zeltes weg ihnen entgegen und verneigte sich bis auf den Boden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, 'Sodann sprach er: O Herr, wenn ich irgend Gnade gefunden habe vor deinen Augen, so gehe doch ja nicht an deinem Sklaven vorüber!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'Man soll etwas Wasser bringen, daß ihr euch die Füße wascht. Dann legt euch hin unter den Baum,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'und ich will einen Bissen Brot holen, daß ihr euch stärkt; darnach mögt ihr weiter ziehn. Denn dazu seid ihr vorübergekommen bei eurem Sklaven. Da sprachen sie: Thue, wie du gesagt hast!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'Da eilte Abraham ins Zelt zu Sara und sagte: Hole schnell drei Maß Feinmehl, knete und backe Kuchen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'Weiter aber lief Abraham zu den Rindern, holte ein zartes und schönes junges Rind und übergab es dem Diener, und dieser beeilte sich, es zuzubereiten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'Sodann holte er Dickmilch und süße Milch und das junge Rind, das er zubereitet hatte, und setzte es ihnen vor; er selbst aber bediente sie unter dem Baume, während sie aßen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, 'Da sprachen sie zu ihm: Wo ist dein Weib Sara? Er antwortete: Drinnen im Zelte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, 'Da sagte er: ich werde übers Jahr um diese Zeit wieder zu dir kommen; dann wird dein Weib Sara einen Sohn haben. Sara aber horchte am Eingang des Zeltes, und dieses war hinter ihm.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'Abraham und Sara waren jedoch alt und hochbetagt, so daß es Sara nicht mehr erging, wie es den Frauen ergeht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'Da lachte Sara in sich hinein, indem sie dachte: Nachdem ich welk geworden bin, sollte ich noch der Liebe pflegen? und mein Gemahl ist ja auch alt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'Da sprach Jahwe zu Abraham: Warum lacht doch Sara und denkt: Sollte ich wirklich noch gebären können, nachdem ich alt geworden bin?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, 'Ist für Jahwe irgend etwas unmöglich? Um diese Zeit werde ich übers Jahr wieder zu dir kommen, da soll Sara einen Sohn haben!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'Da leugnete Sara und sprach: Ich habe nicht gelacht! Denn sie fürchtete sich. Er aber sprach: Nicht doch, du hast gelacht!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, 'Hierauf brachen die Männer von dannen auf und schauten schon hinab auf Sodom - Abraham aber ging mit ihnen, sie zu geleiten -');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'da sprach Jahwe: Soll ich vor Abraham geheim halten, was ich alsbald thun will,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'während doch von Abraham ein großes und zahlreiches Volk ausgehen und durch ihn alle Völker auf Erden gesegnet werden sollen?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'Denn ich habe ihn erkoren, damit er seinen Kindern und seinem Hause nach ihm gebiete, den Weg Jahwes einzuhalten, indem sie Recht und Gerechtigkeit üben, damit Jahwe über Abraham kommen lasse, was er ihm verheißen hat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'Da sprach Jahwe: Das Geschrei über Sodom und Gomorra, das ist groß, und ihre Verschuldung - wahrlich sie ist sehr schwer!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'Darum will ich hinab, um zu sehen, ob sie wirklich alle so gehandelt haben, wie die Gerüchte über sie melden, die vor mich gekommen sind, oder nicht; ich will es erfahren!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'Da wandten sich die Männer von dannen und gingen nach Sodom zu, während Abraham noch vor Jahwe stehen blieb.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'Und Abraham trat herzu und sprach: Willst du denn auch die Unschuldigen umbringen mit den Schuldigen?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'Vielleicht giebt es fünfzig Unschuldige in der Stadt. Willst du die auch umbringen und nicht vielmehr den Ort begnadigen um der fünfzig Unschuldigen willen, die darin sind?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'Ferne sei es von dir, so etwas zu thun, daß du Unschuldige und Schuldige zugleich tötetest, und es dem Unschuldigen erginge, wie dem Schuldigen. Das sei ferne von dir! Sollte der Richter der ganzen Erde nicht Gerechtigkeit üben?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'Da sprach Jahwe: Wenn ich zu Sodom fünfzig Unschuldige in der Stadt finden sollte, so will ich um ihretwillen den ganzen Ort begnadigen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'Da hob Abraham wieder an und sprach: Ach, Herr! Ich habe mich unterfangen, zu dir zu reden, obschon ich Erd\' und Asche bin.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'Vielleicht werden an den fünfzig Unschuldigen fünf fehlen; willst du wegen fünfen die ganze Stadt zu Grunde richten? Da sprach er: Ich werde sie nicht zu Grunde richten, wenn ich fünfundvierzig darin finde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'Da fuhr er abermals fort, zu ihm zu reden, und sprach: Vielleicht finden sich nur vierzig darin. Er antwortete: Ich will\'s nicht thun um der vierzig willen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'Da sprach er: Ach, zürne nicht, Herr, daß ich noch weiter rede. Vielleicht finden sich nur dreißig darin. Er antwortete: Ich will\'s nicht thun, wenn ich dreißig darin finde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'Da sprach er: Ach, Herr, ich habe mich unterfangen, zu dir zu reden; vielleicht finden sich nur zwanzig darin. Er antwortete: Ich werde sie nicht zu Grunde richten um der zwanzig willen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'Da sprach er: Ach, zürne nicht, Herr, wenn ich nur das eine Mal noch rede; vielleicht finden sich nur zehn darin! Er antwortete: Ich werde sie nicht zu Grunde richten um der zehn willen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'Und Jahwe ging, nachdem er das Gespräch mit Abraham geendigt hatte, von dannen; Abraham aber kehrte zurück an seinen Ort.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'Die beiden Engel aber gelangten nach Sodom des Abends, als Lot gerade im Thore von Sodom saß. Und als Lot sie erblickte, erhob er sich, ging ihnen entgegen und verneigte sich bis auf den Boden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, 'Hierauf sprach er: Ach, meine Herren! Kehrt doch ein in das Haus eures Knechtes zum Übernachten und wascht euch die Füße; morgen früh mögt ihr dann eures Weges ziehen. Sie aber sprachen: Nein! wir wollen auf freier Straße übernachten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'Da drang er inständig in sie, bis sie bei ihm einkehrten und in sein Haus eintraten. Hierauf bereitete er ihnen eine Mahlzeit und buk ungesäuerte Kuchen, und sie aßen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'Noch hatten sie sich nicht schlafen gelegt, da umringte die männliche Bevölkerung der Stadt, die Männer von Sodom, das Haus, jung und alt, die ganze Bevölkerung von allen Enden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'Die riefen Lot und sprachen zu ihm: Wo sind die Männer, die heute Abend zu dir gekommen sind? Bringe sie heraus zu uns, damit wir ihnen beiwohnen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'Da ging Lot zu ihnen hinaus vor die Thür - die Thüre aber schloß er hinter sich ab -');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, 'und sprach: Liebe Brüder! Begeht doch nicht eine solche Schlechtigkeit!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'Hört an! Ich habe zwei Töchter, die noch mit keinem Manne zu thun gehabt haben: die will ich zu euch hinausbringen, damit ihr ihnen thut, was euch beliebt. Diesen Männern aber dürft ihr nichts thun, nachdem sie sich nun einmal in den Schatten meines Dachs begeben haben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, 'Da schrieen sie: Pack dich weg! und sprachen: als ein einzelner ist er hergekommen, um hier als Beisasse zu wohnen, und will nun immerfort befehlen! Jetzt wollen wir dir noch übler mitspielen, als ihnen! Und sie drangen hart auf den Mann, auf Lot, ein und nahten herzu, die Thüre zu erbrechen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'Da griffen die Männer hinaus und zogen Lot zu sich hinein ins Haus und verschlossen die Thüre.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'Die Leute aber, die vor der Thüre des Hauses waren, schlugen sie mit Blindheit, klein und groß, so daß sie sich vergeblich mühten, die Thüre zu finden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, 'Und die Männer sprachen zu Lot: Hast du noch jemanden hier?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'Denn wir werden diese Stätte verderben, weil schwere Klage über sie laut geworden ist vor Jahwe; daher sandte uns Jahwe, sie zu verderben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'Da ging Lot hinaus und redete mit seinen Schwiegersöhnen, die seine Töchter nehmen sollten, und sprach: Auf! verlaßt diese Stätte! Denn Jahwe will die Stadt verderben! Seine Schwiegersöhne aber dachten, er treibe nur Scherz mit ihnen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'Als aber die Morgenröte anbrach, da drängten die Engel Lot zur Eile und sprachen: Auf, nimm dein Weib und deine beiden Töchter, die hier gegenwärtig sind, damit du nicht mit weggerafft wirst wegen der Sündenschuld der Stadt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'Als er aber noch zögerte, da ergriffen die Männer ihn und sein Weib und seine beiden Töchter bei der Hand, weil Jahwe ihn verschonen wollte, und brachten ihn hinaus und ließen ihn draußen vor der Stadt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'Und während sie sie hinausbrachten, sprachen sie: Rette dich, es gilt dein Leben! Sieh\' dich nicht um und bleibe nirgends stehen in der Niederung. Auf das Gebirge rette dich, damit du nicht mit weggerafft wirst!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'Lot aber sprach zu ihnen: Ach nein, Herr!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'Dein Knecht hat nun einmal Gnade gefunden in deinen Augen, so daß du mir große Barmherzigkeit bewiesest und mich am Leben erhieltest. Aber ich bin nicht imstande, mich auf das Gebirge zu flüchten; wie leicht könnte mich das Verderben ereilen, daß ich sterben müßte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'Siehe, es ist da eine Stadt in der Nähe, dahin könnte ich fliehen, und sie ist nur etwas Geringfügiges; dorthin möchte ich mich flüchten - sie ist ja doch nur etwas Geringfügiges! - damit ich am Leben bleibe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'Da sprach er zu ihm: Auch in diesem Stücke will ich Rücksicht auf dich nehmen und die Stadt, von der du sprichst, nicht zerstören.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'Flüchte dich eilends dorthin, denn ich kann nichts unternehmen, bis du hingelangt bist! Darum nennt man die Stadt Zoar.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'Die Sonne war bereits aufgegangen, als Lot nach Zoar gelangte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'Jahwe aber ließ auf Sodom und Gomorra Schwefel und Feuer regnen von Jahwe, vom Himmel, her');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'und zerstörte jene Städte von Grund aus samt der ganzen Niederung und allen Bewohnern der Städte und dem, was auf den Fluren gewachsen war.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'Und sein Weib schaute sich hinter ihm um; da wurde sie zu einer Salzsäule.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'Abraham aber begab sich am andern Morgen früh an die Stätte, wo er vor Jahwe gestanden hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'Und als er hinabschaute auf Sodom und Gomorra und den ganzen Bereich der Niederung, da sah er, wie ein Qualm vom Lande aufstieg gleich dem Qualm eines Schmelzofens.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'Als aber Gott die Städte der Niederung zerstörte, da gedachte Gott an Abraham und geleitete Lot hinweg aus der Zerstörung, als er die Städte von Grund aus zerstörte, in denen Lot gewohnt hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, 'Lot aber zog von Zoar hinauf und blieb auf dem Gebirge mit seinen beiden Töchtern, denn er fürchtete sich, in Zoar zu bleiben; und er wohnte in einer Höhle mit seinen beiden Töchtern.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'Da sprach die ältere zu der jüngeren: Unser Vater ist alt, und es giebt niemand mehr auf Erden, der Umgang mit uns haben könnte, wie es aller Welt Brauch ist.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'Komm, wir wollen unserem Vater Wein zu trinken geben und uns zu ihm legen, damit wir durch unsern Vater unsern Stamm erhalten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'Da gaben sie ihrem Vater in jener Nacht Wein zu trinken; sodann ging die ältere hinein und legte sich zu ihrem Vater. Er aber merkte weder, wie sie sich hinlegte, noch wie sie aufstand.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'Am andern Morgen aber sprach die ältere zur jüngeren: Ich habe also heute Nacht bei meinem Vater gelegen. Wir wollen ihm auch diese Nacht Wein zu trinken geben; dann geh hinein und lege dich zu ihm, damit wir durch unsern Vater unsern Stamm erhalten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'Da gaben sie ihrem Vater auch in dieser Nacht Wein zu trinken, dann begab sich die jüngere hin und legte sich zu ihm. Er aber merkte weder wie sie sich hinlegte, noch wie sie aufstand.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'Also wurden die beiden Töchter Lots schwanger von ihrem Vater.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'Und die ältere gebar einen Sohn und nannte ihn Moab; das ist der Stammvater der heutigen Moabiter.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'Aber auch die jüngere gebar einen Sohn und nannte ihn Ben Ammi; das ist der Stammvater der heutigen Ammoniter.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'Und Abraham zog von dort hinweg in das Gebiet des Südlands und nahm seinen Aufenthalt zwischen Kades und Sur und verweilte auch in Gerar.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'Von seinem Weibe Sara aber behauptete Abraham: sie ist meine Schwester! Da sandte Abimelech, der König von Gerar, hin und ließ Sara holen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'Aber Gott kam des Nachts im Traume zu Abimelech und sprach zu ihm: Du muß sterben wegen des Weibes, das du weggenommen hast, denn sie ist eine Ehefrau.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'Abimelech aber war ihr nicht zu nahe gekommen; und er sprach: Herr! du wirst doch nicht Unschuldige umbringen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, 'Hat er doch selbst zu mir gesagt: sie ist meine Schwester! Und ebenso hat auch sie behauptet: er ist mein Bruder! In der Einfalt meines Herzens und mit reinen Händen habe ich so gehandelt!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'Da sprach Gott zu ihm im Traum: Auch ich weiß wohl, daß du in der Einfalt deines Herzens so gehandelt hast, und ich habe dich davor bewahrt, daß du dich gegen mich versündigtest; darum habe ich nicht zugelassen, daß du sie berührtest.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'So gieb nun dem Manne sein Weib zurück, denn er ist ein Prophet, und er soll Fürbitte für dich einlegen, daß du am Leben bleibst. Wenn du sie aber nicht zurückgiebst, so wisse, daß du sterben muß samt allen, die dir angehören.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'Am andern Morgen früh rief Abimelech alle seine Knechte und erzählte ihnen alles, was vorgegangen war; da gerieten die Männer in große Furcht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'Und Abimelech ließ Abraham rufen und sprach zu ihm: Was hast du uns angethan! Was habe ich gegen dich verschuldet, daß du über mich und mein Königreich so schwere Verschuldung gebracht hast! Was nimmermehr geschehen sollte, das hast du mir angethan!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'Und Abimelech sprach zu Abraham: Was hast du damit beabsichtigt, daß du so gehandelt hast?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'Da sprach Abraham: Ja, ich dachte, schwerlich ist irgend welche Gottesfurcht an diesem Ort zu finden; so werden sie mich denn umbringen um meines Weibes willen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'Übrigens ist sie wirklich meine Schwester, die Tochter meines Vaters - nur nicht die Tochter meiner Mutter -, und sie wurde mein Weib.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'Als mich Gott aus meiner Heimat in die Fremde wandern ließ, da sprach ich zu ihr: Das mußt du mir zu Liebe thun: wohin wir auch kommen mögen, da gieb mich für deinen Bruder aus!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'Da nahm Abimelech Schafe und Rinder und Sklaven und Sklavinnen und gab sie Abraham; dazu gab er ihm sein Weib Sara zurück.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, 'Und Abimelech sprach: Mein Land steht dir offen; laß dich nieder, wo es dir gefällt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'Und zu Sara sprach er: hier übergebe ich deinem Bruder tausend Silberstücke; das soll eine Ehrenerklärung für dich sein gegenüber allen, die bei dir sind, so daß du vor jedermann gerechtfertigt bist.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'Da legte Abraham bei Gott Fürbitte ein, und Gott heilte den Abimelech und sein Weib und seine Sklavinnen, so daß sie Kinder gebaren.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'Denn Jahwe hatte um Saras, des Weibes Abrahams, willen die Leiber aller Frauen im Hause Abimelechs gänzlich verschlossen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'Jahwe aber hatte an Sara erfüllt, was er verheißen hatte, und Jahwe that mit Sara, wie er geredet hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'Und Sara wurde schwanger und gebar dem Abraham einen Sohn in seinem hohen Alter um die Zeit, die Gott vorausgesagt hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'Und Abraham nannte seinen neugebornen Sohn, den ihm Sara geboren hatte, Isaak.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'Und Abraham beschnitt seinen Sohn Isaak, als er acht Tage alt war, wie ihm Gott geboten hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'Abraham aber war hundert Jahre alt, als ihm sein Sohn Isaak geboren wurde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'Und Sara sprach: Ein Lachen hat mir Gott bereitet; jedermann, der davon hört, wird über mich lachen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'Und sie sprach: Wer hätte je von Abraham gedacht, daß Sara Kinder säugen werde! und doch habe ich ihm einen Sohn geboren in seinem Alter.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'Und der Knabe wuchs heran und wurde entwöhnt; Abraham aber veranstaltete ein großes Mahl an dem Tage, wo Isaak entwöhnt wurde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, 'Als nun Sara den Sohn der Ägypterin Hagar, den sie Abraham geboren hatte, lachen sah,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'da sprach sie zu Abraham: Jage diese Sklavin und ihren Sohn hinweg; denn der Sohn dieser Sklavin soll nicht erben mit meinem Sohn, mit Isaak!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'Abraham aber mißfiel die Sache sehr um seines Sohnes willen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'Da sprach Gott zu Abraham: Laß es dir nicht leid sein wegen des Knaben und wegen deiner Sklavin; gehorche Sara in allem, was sie von dir verlangt; denn nur die, die von Isaak stammen, werden als deine wahrhaften Nachkommen gelten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'Aber auch den Sohn der Magd will ich zu einem Volke werden lassen, weil er dein Sohn ist.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'Am andern Morgen früh nahm Abraham Brot und einen Schlauch mit Wasser und gab es Hagar; das Kind aber setzte er ihr auf die Schulter und schickte sie fort. Da ging sie hinweg und irrte umher in der Steppe von Beerseba.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, 'Als nun das Wasser im Schlauche zu Ende gegangen war, da warf sie den Knaben unter einen Strauch,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'ging hin und setzte sich abseits einen Bogenschuß weit; denn sie sprach: Ich kann das Sterben des Kindes nicht ansehen! Daher setzte sie sich abseits; das Kind aber begann laut zu weinen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'Als nun Gott das Schreien des Knaben hörte, da rief der Engel Gottes der Hagar vom Himmel her zu und sprach zu ihr: Was ist dir, Hagar? Sei getrost! Gott hat das Schreien des Knaben gehört da, wo er liegt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'Geh, hebe den Knaben auf und fasse ihn bei der Hand, denn ich will ihn zu einem großen Volke werden lassen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'Und Gott that ihr die Augen auf, daß sie einen Wasserquell erblickte. Da ging sie hin, füllte den Schlauch mit Wasser und gab dem Knaben zu trinken.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'Und Gott war mit dem Knaben; der wuchs heran und nahm seinen Aufenthalt in der Steppe und wurde ein Bogenschütz.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'Er nahm aber seinen Aufenthalt in der Steppe Paran, und seine Mutter nahm ihm ein Weib aus dem Lande Ägypten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, 'Um dieselbe Zeit sprachen Abimelech und sein Heerführer Pichol zu Abraham also: Gott ist mir dir in allem, was du thust.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'Darum schwöre mir jetzt bei Gott allhier, daß du an mir und meiner gesamten Verwandtschaft nimmermehr treulos handeln willst. Gleichwie ich mich freundschaftlich gegen dich erzeigt habe, sollst du dich gegen mich erzeigen und gegen das Land, in welchem du dich als Fremdling aufhältst.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'Da sprach Abraham: Ich will schwören.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'Abraham aber setzte den Abimelech zur Rede wegen des Wasserbrunnens, den die Sklaven Abimelechs mit Gewalt genommen hatten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'Abimelech antwortete: Ich weiß nicht, wer das gethan hat; weder hast du mir etwas davon gesagt, noch habe ich bis heute davon gehört.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'Da nahm Abraham Schafe und Rinder und gab sie dem Abimelech, und sie schlossen einen Vertrag miteinander.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'Abraham aber stellte die sieben Lämmer besonders.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'Da sprach Abimelech zu Abraham: Was sollen diese sieben Lämmer, die du besonders gestellt hast?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'Abraham antwortete: Die sieben Lämmer mußt du von mir annehmen; das soll mir zum Zeugnis dienen, daß ich diesen Brunnen gegraben habe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'Daher heißt jene Stätte Beerseba, weil sie dort einander geschworen haben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, 'So schlossen sie einen Vertrag zu Beerseba. Alsdann brachen Abimelech und sein Heerführer Pichol auf und kehrten zurück ins Philisterland.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'Abraham aber pflanzte eine Tamariske zu Beerseba und rief daselbst den Namen Jahwes an, des ewigen Gottes.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, 'Abraham aber verweilte lange Zeit im Philisterland.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, 'Nach diesen Begebenheiten versuchte Gott Abraham und sprach zu ihm: Abraham! Er antwortete: Hier bin ich!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'Da sprach er: Nimm deinen Sohn, deinen einzigen, den du lieb hast, Isaak, ziehe hin in das Land Morija und bringe ihn dort als Brandopfer dar auf einem der Berge, den ich dir sagen werde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'Da gürtete Abraham am andern Morgen früh seinen Esel, nahm seine beiden Diener mit sich samt seinem Sohne Isaak, spaltete Holz zum Brandopfer, brach auf und zog nach der Stätte, von der ihm Gott gesagt hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'Am dritten Tage aber hob Abraham seine Augen auf und erblickte die Stätte von weitem.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'Da sprach Abraham zu seinen Dienern: Bleibt hier mit dem Esel; ich aber und der Knabe wollen dorthin gehen und anbeten und dann wieder zu euch kommen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'Hierauf nahm Abraham das Holz zum Brandopfer und legte es auf seinen Sohn Isaak, nahm in seine Hand das Feuer und das Schlachtmesser, und so gingen die beiden miteinander.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'Da sprach Isaak zu seinem Vater Abraham und sagte: Mein Vater! Er antwortete: Hier bin ich, mein Sohn! Da sagte er: Das Feuer und das Holz ist da; wo aber ist das Schaf zum Brandopfer?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'Abraham antwortete: Mein Sohn, Gott wird schon für ein Schaf zum Brandopfer sorgen! So gingen die beiden miteinander.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'Als sie nun an die Stätte gelangt waren, von der ihm Gott gesagt hatte, da errichtete Abraham den Altar und legte die Holzscheite zurecht; alsdann band er seinen Sohn Isaak und legte ihn auf den Altar oben über die Scheite.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'Sodann reckte Abraham seine Hand aus und ergriff das Messer, um seinen Sohn zu schlachten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, 'Da rief ihm der Engel Jahwes vom Himmel her zu und sprach: Abraham! Abraham! Er antwortete: Hier bin ich!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, 'Da sprach er: lege nicht Hand an den Knaben und thue ihm nichts zu leide! Denn nun weiß ich, daß du Gott fürchtest, da du mir deinen einzigen Sohn nicht verweigert hast.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'Da hob Abraham seine Augen auf und gewahrte einen Widder, der sich mit seinen Hörnern im Dickicht verfangen hatte; da ging Abraham hin, holte den Widder und brachte ihn als Brandopfer dar an Stelle seines Sohnes.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'Und Abraham nannte die Stätte: Jahwe sieht! Daher man noch heutiges Tages sagt: auf dem Berge, wo Jahwe erscheint.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'Der Engel Jahwes aber rief dem Abraham ein zweites Mal vom Himmel her zu');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, 'und sprach: Ich schwöre bei mir selbst, ist der Spruch Jahwes: dafür, daß du das gethan und mir deinen einzigen Sohn nicht verweigert hast,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'will ich dich reichlich segnen und deine Nachkommen so überaus zahlreich werden lassen, wie die Sterne am Himmel und wie der Sand am Ufer des Meeres, und deine Nachkommen sollen die Thore ihrer Feinde besitzen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'und durch deine Nachkommen sollen alle Völker der Erde gesegnet werden, zum Lohne dafür, daß du meinem Befehle gehorcht hast!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'Hierauf kehrte Abraham wieder zu seinen Dienern zurück, und sie brachen auf und zogen miteinander nach Beerseba, und Abraham blieb in Beerseba wohnen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, 'Nach diesen Begebenheiten wurde dem Abraham berichtet: Auch Milka hat deinem Bruder Nahor Söhne geboren,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'nämlich Uz, seinen Erstgebornen, und dessen Bruder Bus und Kemuel, von dem die Aramäer stammen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'und Chesed, Haso, Pildas, Jidlaph und Bethuel;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, 'Bethuel aber erzeugte Rebeka. Diese acht gebar Milka dem Nahor, dem Bruder Abrahams.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'Er hatte aber auch ein Kebsweib mit Namen Reuma; auch diese gebar: nämlich den Tebah, Gaham, Tahas und Maacha.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, 'Es betrug aber die Lebensdauer Saras 127 Jahre; das waren die Lebensjahre Saras.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'Und Sara starb zu Kirjath-Arba, das ist Hebron, im Lande Kanaan. Abraham aber ging hin, um wegen Sara zu klagen und sie zu beweinen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'Sodann verließ Abraham den Leichnam und redete also zu den Hethitern:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, 'Als Fremdling und Beisaß bin ich bei euch; gebt mir ein Erbbegräbnis bei euch, damit ich meine Tote aus dem Hause bringe und begrabe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'Da antworteten die Hethiter dem Abraham also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, 'Höre uns doch an, o Herr! Als ein Fürst Gottes weilst du unter uns; in dem besten unserer Gräber begrabe deine Tote! Keiner von uns wird dir verweigern, daß du deine Tote in seinem Grabe bestattest.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'Da erhob sich Abraham und verneigte sich vor den Landeskindern, den Hethitern,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'und redete mit ihnen also: Wenn es euch genehm ist, daß ich meine Tote aus dem Hause bringe und begrabe, so thut mir den Gefallen und legt Fürsprache für mich ein bei Ephron, dem Sohne Zohars,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'daß er mir die Höhle Machpela abtrete, die ihm gehört und die ganz am Ende seines Grundstücks liegt; für den vollen Betrag soll er sie mir abtreten zum Erbbegräbnis unter euch.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, 'Ephron aber saß mit da unter den Hethitern. Da antwortete Ephron, der Hethiter, dem Abraham, so daß es die Hethiter hörten, so viele ihrer durch das Thor seiner Stadt aus- und eingingen, folgendermaßen:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, 'Nicht doch, Herr! höre mich an! Ich schenke dir das Grundstück, und auch die Höhle, die darauf ist, die schenke ich dir; vor den Augen meiner Stammesgenossen schenke ich sie dir. Begrabe du nur deine Tote!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'Da verneigte sich Abraham vor den Landeskindern;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'sodann sprach er zu Ephron, so daß es seine Landsleute hörten, also: Wenn du - höre mich einmal an! Ich zahle das Geld für das Grundstück; nimm es von mir an, damit ich meine Tote begrabe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'Ephron aber antwortete dem Abraham also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, 'Höre mich doch nur an, Herr! Ein Stück Land von vierhundert Silbersekeln Wert, was hat das unter uns zu sagen? Begrabe du nur deine Tote!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'Und Abraham hörte auf Ephron, und Abraham wog dem Ephron den Kaufpreis dar, von dem er im Beisein der Hethiter gesprochen hatte: vierhundert Sekel Silber, wie es im Handel gäng und gäbe war.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'So wurde das Grundstück Ephrons bei Machpela, gegenüber Mamre, das Grundstück mit der Höhle darauf und mit allen Bäumen, die sich auf dem Grundstück befanden in seinem ganzen Bereich ringsum,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'dem Abraham zum Eigentum bestätigt im Beisein der Hethiter, so viele durch das Thor seiner Stadt aus- und eingingen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'Danach begrub Abraham sein Weib Sara in der Höhle des Grundstücks Machpela, gegenüber Mamre, das ist Hebron, in Kanaan.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'So wurde das Grundstück und die Höhle darauf dem Abraham zum Erbbegräbnis bestätigt von den Hethitern.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'Abraham aber war alt und wohlbetagt, und Jahwe hatte Abraham gesegnet in allem.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'Da sprach Abraham zu seinem Sklaven, dem Hausältesten, der alles das Seinige zu verwalten hatte: Lege doch deine Hand unter meine Lende!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'Denn du muß mir schwören bei Jahwe, dem Gott des Himmels und dem Gott der Erde, daß du für meinen Sohn nicht ein Weib freien willst von den Töchtern der Kanaaniter, unter denen ich wohne,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'sondern daß du in mein Vaterland und zu meiner Verwandtschaft ziehen willst, um für meinen Sohn Isaak ein Weib zu freien.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'Da antwortete ihm der Sklave: Wenn nun aber das Weib mir nicht folgen will in dieses Land, soll ich dann deinen Sohn wieder in das Land zurückbringen, aus dem du ausgewandert bist?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'Abraham sprach zu ihm: Hüte dich, meinen Sohn dorthin zurückzubringen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, 'Jahwe, der Gott des Himmels, der mich hinweggeführt hat aus dem Hause meines Vaters und aus meinem Heimatlande, der zu mir geredet und mir zugeschworen hat: Deinen Nachkkommen will ich dieses Land verleihen! - der wird seinen Engel vor dir hersenden, daß du meinem Sohn ein Weib von dort freiest.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'Und wenn das Weib nicht willens sein sollte, dir zu folgen, so bist du dieses Eides quitt; keinesfalls aber darfst du meinen Sohn dorthin zurückbringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'Da legte der Sklave seine Hand unter die Lende Abrahams, seines Herrn, und schwur ihm, wie er verlangt hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, 'Hierauf nahm der Sklave zehn Kamele von den Kamelen seines Herrn, sowie allerlei Kleinodien seines Herrn mit sich, brach auf und zog nach Mesopotamien, nach der Stadt Nahors.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'Da ließ er die Kamele draußen vor der Stadt bei einem Brunnen sich lagern, um die Abendzeit, wo die Weiber herauszukommen pflegen, um Wasser zu schöpfen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'Und er sprach: Jahwe, Gott meines Herrn Abraham! Laß es mir heute glücken und zeige dich gnädig gegen meinen Herrn Abraham.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'Wenn ich jetzt dastehe bei der Quelle, und die Töchter der Stadtbewohner herauskommen, um Wasser zu schöpfen -');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'wenn dann das Mädchen, zu der ich sagen werde: Neige doch deinen Krug, damit ich trinke, antworten wird: Trinke, und auch deine Kamele will ich tränken! die hast du bestimmt für deinen Diener Isaak, und daran will ich erkennen, daß du dich gegen meinen Herrn gnädig erzeigst.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'Noch hatte er nicht ausgeredet, da kam, den Krug auf der Schulter, Rebeka heraus, die Tochter Bethuels, des Sohnes der Milka, des Weibes Nahors, des Bruders Abrahams.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'Das Mädchen aber war überaus schön, eine Jungfrau, mit der noch keiner Umgang gehabt hatte; und sie stieg hinab zur Quelle, füllte ihren Krug und kam wieder herauf.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'Da lief ihr der Sklave entgegen und sprach: Laß mich doch ein wenig Wasser aus deinem Kruge trinken!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, 'Da sprach sie: Trinke, Herr! und eilend ließ sie den Krug hernieder auf ihre Hand und gab ihm zu trinken.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'Und als sie ihm genug zu trinken gegeben hatte, sprach sie: Auch für deine Kamele will ich schöpfen, bis sie sich satt getrunken haben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'Und eilend goß sie ihren Krug aus in die Tränkrinne, lief wieder zur Quelle, um Wasser zu schöpfen, und schöpfte für alle seine Kamele.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'Der Mann aber sah ihr voll Erstaunen schweigend zu, begierig, zu erfahren, ob Jahwe Glück zu seiner Reise gegeben habe oder nicht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'Als nun die Kamele sich satt getrunken hatten, da nahm der Mann einen goldenen Nasenring, einen halben Sekel schwer, und zwei Armbänder für ihre Arme, zehn Sekel Goldes schwer,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'und sprach: Wessen Tochter bist du? sage es mir! Ist im Hause deines Vaters Raum für uns zum Übernachten?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'Sie sprach zu ihm: Ich bin die Tochter Bethuels, des Sohnes der Milka, den sie dem Nahor geboren hat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'Und weiter sagte sie zu ihm: Wir haben Stroh und Futter in Fülle, sowie auch Raum zum Übernachten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'Da verneigte sich der Mann und beugte sich vor Jahwe');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, 'und sprach: Gepriesen sei Jahwe, der Gott meines Herrn Abraham, der es nicht hat fehlen lassen an Huld und Treue gegenüber meinem Herrn. Den Weg hat mich Jahwe geführt zum Hause der Verwandten meines Herrn!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'Das Mädchen aber lief und berichtete bei ihrer Mutter, was sich zugetragen hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'Nun hatte Rebeka einen Bruder, der hieß Laban, da lief Laban zu dem Manne hinaus an die Quelle.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'Als dieser den Ring und die Spangen an den Armen seiner Schwester erblickte und seine Schwester erzählen hörte: so und so hat der Mann zu mir gesagt, und kam zu dem Manne; der aber stand noch bei den Kamelen an der Quelle.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'Da sprach er: Komm herein, du Gesegneter Jahwes! warum stehst du draußen?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, 'Als er nun den Mann ins Haus geführt hatte, zäumte er die Kamele ab; alsdann gab er den Kamelen Stroh und Futter und brachte Wasser zum Waschen der Füße für ihn und die Männer, die bei ihm waren.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'Als ihm aber zu essen vorgesetzt wurde, da sprach er: Ich esse nicht eher, als bis ich meine Sache vorgebracht habe! Er antwortete: So rede!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, 'Da sprach er: Ich bin der Sklave Abrahams.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'Jahwe hat meinen Herrn reichlich gesegnet, so daß er zu großem Wohlstand gelangt ist, und hat ihm Schafe und Rinder, Silber und Gold, Sklaven und Sklavinnen und Kamele und Esel geschenkt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'Und Sara, das Weib meines Herrn, gebar meinem Herrn einen Sohn, als sie schon hochbetagt war; dem hat er alle seine Habe übergeben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'Mein Herr aber gebot mir und ließ mich darauf schwören: Du darfst meinem Sohne kein Weib freien aus den Töchtern der Kanaaniter, in deren Land ich wohne,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'sondern sollst hinziehen zu meines Vaters Haus und zu meiner Verwandtschaft um meinem Sohn ein Weib zu freien.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'Da sprach ich zu meinem Herrn: Wenn nun aber das Weib mir nicht folgen will?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'Da sprach er zu mir: Jahwe, vor dessen Angesicht ich gewandelt habe, wird seinen Engel mit dir senden und dir Glück zu deiner Reise geben, daß du meinem Sohn ein Weib freiest von meiner Verwandtschaft, aus dem Hause meines Vaters.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'Dann sollst du meines Eides quitt sein, wenn du dich zu meiner Verwandtschaft begeben wirst; geben sie dir sie nicht, so bist du meines Eides quitt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'Als ich nun heute zu der Quelle kam, da sprach ich: Jahwe, du Gott meines Herrn Abraham! Wenn du Glück geben willst zu dem Weg, auf dem ich mich befinde, so soll - wenn ich jetzt dastehe bei der Quelle -');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'das Mädchen, das herauskommt, um Wasser zu schöpfen, und zu dem ich sagen werde: Gieb mir doch ein wenig Wasser zu trinken aus deinem Kruge!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'und das dann antwortet: Trinke und auch deine Kamele will ich tränken - die soll das Weib sein, welches Jahwe dem Sohne meines Herrn bestimmt hat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'Kaum hatte ich so bei mir beschlossen, da kam Rebeka heraus, den Krug auf der Schulter, stieg zur Quelle hinab und schöpfte Wasser. Da sprach ich zu ihr: Gieb mir zu trinken!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'Sie aber ließ rasch ihren Krug herab und sprach: Trinke! und auch deine Kamele will ich tränken. Da trank ich und sie tränkte dann auch die Kamele.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'Hierauf fragte ich sie und sprach: Wessen Tochter bist du? Sie antwortete: Ich bin die Tochter Bethuels, des Sohnes Nahors, den ihm Milka geboren hat. Da legte ich den Ring an ihre Nase und die Spangen an ihre Arme.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'Dann verneigte ich mich und beugte mich vor Jahwe und pries Jahwe, den Gott meines Herrn Abraham, dafür, daß er mich den rechten Weg geführt hat, die Tochter des Bruders meines Herrn für seinen Sohn zu freien.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'Wenn ihr nun also meinem Herrn Liebe und Treue erweisen wollt, so sagt es mir; wenn aber nicht, so sagt es mir auch, damit ich mich wende zur Rechten oder zur Linken.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'Da antworteten Laban und Bethuel und sprachen: Das kommt von Jahwe! Wir können nichts dazu sagen, weder Schlimmes noch Gutes.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'Rebeka steht dir zur Verfügung; nimm sie und ziehe hin, damit sie das Weib des Sohnes deines Herrn werde, wie Jahwe geredet hat!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'Als nun der Sklave Abrahams diese ihre Worte hörte, verneigte er sich vor Jahwe bis auf die Erde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'Dann zog der Sklave Gold- und Silbersachen und Gewänder hervor und schenkte sie Rebeka; ihrem Bruder aber und ihrer Mutter schenkte er Kleinodien.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'Und sie aßen und tranken, er und die Männer, die mit ihm waren, und blieben über Nacht. Am andern Morgen aber, als sie aufgestanden waren, da sprach er: Laßt mich ziehen zu meinen Herrn!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'Da sprachen ihr Bruder und ihre Mutter: Laß doch das Mädchen noch einige Tage oder zehn bei uns bleiben, dann mag sie ziehen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'Er aber sprach zu ihnen: Haltet mich nicht auf! Jahwe hat Glück gegeben zu meiner Reise, so entlaßt mich nun, damit ich zu meinem Herrn ziehe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'Da sprachen sie: Wir wollen das Mädchen rufen und sie selbst befragen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'Hierauf riefen sie Rebeka und sprachen zu ihr: Willst du mit diesem Manne ziehen? Sie antwortete: Ja, ich will!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'Da ließen sie ihre Schwester Rebeka ziehen mit ihrer Amme und dem Sklaven Abrahams samt seinen Leuten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'Und sie segneten Rebeka und sprachen zu ihr: O Schwester! Werde du zu unzähligen Tausenden, und mögen deine Nachkommen die Thore ihrer Feinde in Besitz nehmen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'Hierauf brachen Rebeka und ihre Dienerinnen auf und setzten sich auf die Kamele und folgten dem Manne; und der Sklave nahm Rebeka und zog von dannen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, 'Isaak aber war vom “Brunnen des Lebendigen, der mich schaut” gekommen; denn er wohnte im Südland.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'Einst war Isaak ausgegangen, um auf dem Felde zu beten, als der Abend anbrach. Als er nun aufblickte, sah er Kamele daherkommen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'Als aber Rebeka aufschaute, erblickte sie den Isaak. Da sprang sie herab vom Kamel');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, 'und sprach zu dem Sklaven: Wer ist der Mann, der uns da auf dem Feld entgegenkommt? Der Sklave antwortete: Es ist mein Herr! Da nahm sie den Schleier und verhüllte sich.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'Hierauf erzählte der Sklave dem Isaak alles, was er verrichtet hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'Isaak aber führte sie hinein ins Zelt seiner Mutter Sara und er nahm Rebeka und sie wurde sein Weib und er gewann sie lieb; so tröstete sich Isaak über den Verlust seiner Mutter.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'Abraham aber nahm nochmals ein Weib, Namens Ketura,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'die gebar ihm Simran, Joksan, Medan, Midian, Jisbak und Suah.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'Joksan aber erzeugte Saba und Dedan; und die Söhne Dedans waren die Assuriter, die Letusiter und die Leummiter.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'Und die Söhne Midians waren Epha, Epher, Hanoch, Abida und Eldaa; diese alle stammen von Ketura.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'Abraham aber übergab alle seine Habe dem Isaak.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'Aber den Söhnen der Kebsweiber, die Abraham hatte, gab Abraham Geschenke und ließ sie noch bei seinen Lebzeiten von seinem Sohne Isaak hinweg östlich, in das Ostland ziehen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'Das aber ist die Dauer der Lebensjahre Abrahams, die er durchlebt hat: 175 Jahre.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'Und Abraham verschied und starb in schönem Alter, alt und lebenssatt, und wurde versammelt zu seinen Stammesgenossen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'Und es begruben ihn seine Söhne Isaak und Ismael in der Höhle Machpela, auf dem Grundstück des Hethiters Ephron, des Sohnes Zohars, welches Mamre gegenüberliegt,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'auf dem Grundstück, welches Abraham von den Hethitern gekauft hatte: dort wurden Abraham und sein Weib Sara begraben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'Nach dem Tode Abrahams aber segnete Gott seinen Sohn Isaak; Isaak aber wohnte bei dem “Brunnen des Lebendigen, der mich schaut”.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, 'Dies ist die Geschichte Ismaels, des Sohnes Abrahams, den die Ägypterin Hagar, die Leibmagd Saras, dem Abraham geboren hat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'Und dies sind die Namen der Söhne Ismaels nach ihren Namen, nach ihrem Stammbaum: der Erstgeborene Ismaels Nebajoth; Kedar, Adbeel, Mibsam,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'Misma, Duma, Massa,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'Hadad, Thema, Jetur, Naphis und Kedma.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'Das sind die Söhne Ismaels, und dies ihre Namen nach ihren Gehöften und Zeltlagern, zwölf Fürsten nach ihren Stammverbänden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'Und dies war die Lebensdauer Ismaels: 137 Jahre. Und er verschied und starb und wurde versammelt zu seinen Stammesgenossen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'Und sie wohnten von Havila an bis nach Sur, welches östlich von Ägypten liegt, bis nach Assur hin; allen seinen Verwandten setzte er sich auf den Nacken.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'Das ist die Geschichte Isaaks, des Sohnes Abrahams: Abraham erzeugte den Isaak.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'Isaak aber war vierzig Jahre alt, als er sich Rebeka, die Tochter des Aramäers Bethuel aus Mesopotamien, die Schwester des Aramäers Laban, zum Weibe nahm.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'Isaak aber bat Jahwe für sein Weib, denn sie war unfruchtbar. Da ließ sich Jahwe von ihm erbitten, und sein Weib Rebeka wurde schwanger.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'Es stießen sich aber die Kinder in ihrem Leibe; da sprach sie: Wenn es so steht, warum lebe ich dann? Und sie ging hin, Jahwe zu befragen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'Jahwe aber sprach zu ihr: Zwei Völker sind in deinem Leibe, und zwei Stämme werden aus deinem Schoße hervorgehen, sich zu befehden. Ein Stamm wird dem andern überlegen sein, und der ältere wird dem jüngeren dienstbar werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'Als nun ihre Zeit da war, daß sie gebären sollte, da fand sich, daß Zwillinge in ihrem Leibe waren.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'Da kam der erste heraus, rötlich, ganz und gar wie ein haariger Mantel; darum nannten sie ihn Esau.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'Darnach kam sein Bruder heraus, der hielt mit seiner Hand die Ferse Esaus; darum nannte man ihn Jakob. Isaak aber war sechzig Jahre alt, als sie geboren wurden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'Als nun die Knaben heranwuchsen, wurde Esau ein tüchtiger Jäger, ein Mann der Steppe; Jakob dagegen war ein sanfter Mann, der bei den Zelten blieb.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'Isaak aber liebte den Esau, denn Wildbret war nach seinem Geschmack; Rebeka dagegen liebte mehr den Jakob.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, 'Einst kochte Jakob ein Gericht; da kam Esau ganz verschmachtet aus der Steppe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'Und Esau sprach zu Jakob: Laß mich schnell essen von dem roten, dem roten da! denn ich bin ganz verschmachtet. Deshalb nannte man ihn Edom.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'Jakob aber sprach: Verkaufe mir zuvor dein Erstgeburtsrecht!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'Da sprach Esau: Ach, ich muß schließlich doch sterben; was soll mir da das Erstgeburtsrecht!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'Jakob sprach: Schwöre es mir zuvor zu! Da schwur er ihm und verkaufte so an Jakob sein Erstgeburtsrecht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'Jakob aber gab dem Esau Brot und ein Gericht Linsen. Da aß er und trank, stand auf und ging davon; so verscherzte Esau leichtfertig sein Erstgeburtsrecht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'Es kam aber eine Hungersnot über das Land - eine andere, als jene frühere Hungersnot, die zu Abrahams Zeit gewesen war -, da zog Isaak zu Abimelech, dem Könige der Philister, nach Gerar.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'Da erschien ihm Jahwe und sprach: ziehe nicht hinab nach Ägypten! Bleibe in dem Lande, das ich dir sagen werde!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'Weile als Fremdling in diesem Lande, so will ich mit dir sein und dich segnen. Denn dir und deinen Nachkommen will ich alle diese Länder geben und werde den Schwur aufrecht erhalten, den ich deinem Vater Abraham geschworen habe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'Und ich werde deine Nachkommen so zahlreich werden lassen, wie die Sterne am Himmel, und werde deinen Nachkommen alle diese Länder geben, und durch deine Nachkommen sollen alle Völker auf Erden gesegnet werden,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'zum Lohne dafür, daß Abraham meinem Befehl gehorcht und alles beobachtet hat, was ich von ihm forderte, meine Gebote, meine Satzungen und meine Weisungen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'So blieb Isaak in Gerar.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'Als sich aber die Bewohner des Orts nach seinem Weibe erkundigen, da sprach er: Sie ist meine Schwester! Denn er fürchtete sich zu sagen: Sie ist mein Weib; denn, dachte er, die Bewohner des Orts könnten mich sonst umbringen wegen Rebeka, weil sie so schön ist.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'Als er nun längere Zeit dort gewohnt hatte, da schaute einst Abimelech, der König der Philister, zum Fenster hinaus und sah, wie Isaak mit seinem Weibe Rebeka scherzte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'Da ließ Abimelech den Isaak rufen und sprach: Also dein Weib ist sie! Wie konntest du da sagen: Sie ist meine Schwester? Isaak antwortete ihm: Ja, ich dachte, ich könnte ihretwegen etwa gar sterben müssen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'Da sprach Abimelech: Was hast du uns da angethan! Wie leicht konnte irgend einer deinem Weibe beiwohnen, und du hättest damit schwere Schuld auf uns geladen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'Hierauf gebot Abimelech allem Volke: Wer diesen Mann und sein Weib antastet, soll mit dem Tode bestraft werden!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'Isaak aber säete in jenem Land und erntete in jenem Jahre hundertfältig, denn Jahwe segnete ihn.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'So wurde der Mann reich und wurde immer reicher, bis er sehr reich war;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'und er besaß Schafherden und Rinderherden und viele Leibeigene, so daß die Philister ihn beneideten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'Es hatten aber die Philister alle die Brunnen, welche die Sklaven seines Vaters bei Lebzeiten seines Vaters Abraham gegraben hatten, verschüttet und mit Erde angefüllt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'Da sprach Abimelech zu Isaak: Ziehe hinweg von uns, denn du bist uns zu mächtig geworden!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'Da zog Isaak von dort hinweg, schlug sein Lager im Thale von Gerar auf und blieb daselbst.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'Hierauf ließ Isaak die Brunnen wieder aufgraben, die die Sklaven seines Vaters Abraham gegraben und welche die Philister nach Abrahams Tode verschüttet hatten, und benannte sie wieder mit den Namen, die ihnen sein Vater gegeben hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'Da gruben die Sklaven Isaaks im Thalgrunde nach und fanden daselbst eine Quelle mit fließendem Wasser.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'Die Hirten von Gerar aber gerieten in Streit mit den Hirten Isaaks und sprachen: Uns gehört das Wasser! Da nannte er die Quelle “Esek”, weil sie mit ihm gezankt hatten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'Hierauf gruben sie einen anderen Brunnen, aber sie gerieten auch seinetwegen in Streit; daher nannte er ihn “Sitna”.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'Dann zog er weiter von dort hinweg und grub einen anderen Brunnen. Über den gerieten sie nicht in Streit; daher nannte er ihn “Rehoboth” und sprach: Nun hat uns Jahwe freien Raum geschafft, daß wir uns ausbreiten können im Lande!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'Alsdann zog er von dort hinauf nach Beerseba.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, 'Da erschien ihm Jahwe in selbiger Nacht und sprach: Ich bin der Gott deines Vaters Abraham! Sei getrost, denn ich bin mit dir; und ich will dich segnen und deine Nachkommen zahlreich werden lassen um meines Dieners Abraham willen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'Da erbaute er daselbst einen Altar, rief den Namen Jahwes an und schlug daselbst sein Zelt auf. Hierauf gruben die Sklaven Isaaks dort einen Brunnen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, 'Es war aber Abimelech mit Ahusat, seinem vertrauten Rat, und mit Pichol, seinem Heerführer, von Gerar zu ihm gekommen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'Da sprach Isaak zu ihnen: Warum kommt ihr zu mir, da ihr doch feindlich gegen mich gesinnt seid und mich von euch getrieben habt?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'Sie sprachen: Wir haben wohl gesehen, daß Jahwe mit dir war; da beschlossen wir, es müsse eine gegenseitige Verpflichtung von uns und dir beschworen werden, und wollen einen Vertrag mit dir schließen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, 'daß du uns nicht Böses zufügen willst, wie auch wir dich nicht angetastet und dir nur Gutes erwiesen haben, indem wir dich in Frieden ziehen ließen. Du bist nun einmal der Gesegnete Jahwes!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'Da bereitete er ihnen ein Mahl, und sie aßen und tranken.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'Am andern Morgen früh aber schwuren sie sich gegenseitig; hierauf verabschiedete sie Isaak, und sie gingen in Frieden von ihm.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'An demselben Tage kamen die Sklaven Isaaks und berichteten ihm in betreff des Brunnens, den sie gegraben hatten, und sprachen zu ihm: Wir haben Wasser gefunden!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, 'Da nannte er ihn Siba; daher hießt die Stadt Beerseba bis auf den heutigen Tag.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'Als nun Esau vierzig Jahre alt war, heiratete er Judith, die Tochter des Hethiters Beeri, und Basmath, die Tochter des Hethiters Elon.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'Die waren ein schwerer Kummer für Isaak und Rebeka.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'Als aber Isaak alt geworden war, und seine Augen stumpf waren, daß er nicht mehr sehen konnte, da rief er seinen älteren Sohn Esau und sprach zu ihm: Mein Sohn! Er antwortete ihm: Hier bin ich!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'Da sprach er: Ich bin nun alt geworden und weiß nicht, wann ich sterben werde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'So nimm nun dein Jagdgeräte, deinen Köcher und deinen Bogen, gehe aus in die Steppe und erjage für mich ein Stück Wild.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'Dann bereite mir ein Essen, wie ich es gern habe, und bringe es mir herein, daß ich esse; so will ich dir dann meinen Segen geben, bevor ich sterbe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'Rebeka aber hatte zugehört, als Isaak so zu seinem Sohn Esau redete. Während nun Esau in die Steppe ging, um ein Wild zu erjagen und heimzubringen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'sprach Rebeka zu ihrem Sohne Jakob: Eben habe ich zugehört, wie dein Vater zu deinem Bruder Esau redete und ihm gebot:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, 'Hole mir ein Wildbret und bereite mir ein Essen, daß ich esse; so will ich dir dann vor dem Angesicht Jahwes meinen Segen geben, bevor ich sterbe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'Nun aber, mein Sohn, folge meinem Rat und thue, was ich dich heißen werde!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'Gehe zur Herde und hole mir von dort zwei schöne Ziegenböckchen, daß ich sie herrichte zu einem Essen für deinen Vater, wie er es gern hat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'Dann muß du es deinem Vater hineinbringen, damit er davon ißt; so soll er dir dann seinen Segen geben, bevor er stirbt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'Jakob aber sprach zu seiner Mutter Rebeka: Ja, aber mein Bruder Esau ist stark behaart, während ich unbehaart bin.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'Vielleicht wird mich mein Vater betasten; dann würde ich vor ihm dastehn wie einer, der seinen Spott mit ihm treibt, und würde Fluch über mich bringen und nicht Segen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, 'Da sprach seine Mutter zu ihm: Auf mich falle der Fluch, der dich treffen könnte, mein Sohn; folge du nur meinem Rat, geh und hole mir!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'Da ging er, es zu holen, und brachte es seiner Mutter; seine Mutter aber bereitete ein Essen, wie es sein Vater gern hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'Hierauf holte Rebeka die guten Kleider ihres älteren Sohnes Esau, die sie drinnen bei sich hatte, und zog sie ihrem jüngeren Sohne Jakob an.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'Die Felle der Ziegenböckchen aber legte sie ihm um seine Hände und um seinen glatten Hals;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'dann gab sie ihrem Sohne Jakob das Essen nebst dem Brot, das sie gebacken hatte, in die Hand.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'Da ging er hinein zu seinem Vater und sprach: Mein Vater! Er antwortete: Hier bin ich! Wer bist du, mein Sohn?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'Da sprach Jakob zu seinem Vater: Ich bin Esau, dein Erstgeborener; ich habe gethan, wie du mir geboten hast. So setze dich nun auf und iß von meinem Wildbret, damit du mir dann deinen Segen gebest!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'Da sprach Isaak zu seinem Sohne: Ei wie schnell hast du etwas gefunden, mein Sohn! Er antwortete: Ja, dein Gott Jahwe ließ es mir in den Weg laufen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'Da sprach Isaak zu Jakob: Tritt einmal näher, daß ich dich bestasten kann, mein Sohn, ob du wirklich mein Sohn Esau bist oder nicht!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'Da trat Jakob zu seinem Vater Isaak heran, und als er ihn nun betastet hatte, sprach er: Die Stimme ist Jakobs Stimme, aber die Arme sind Esaus Arme.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'Und er erkannte ihn nicht, weil seine Arme behaart waren, wie die seines Bruders Esau, und so segnete er ihn denn.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, 'Da sprach er: Du also bist mein Sohn Esau? Er antwortete: Ja, ich bins!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'Da sprach er: So bringe mir es her, damit ich esse von dem Wildbret meines Sohnes; so will ich dir dann meinen Segen geben! Da brachte er es ihm, und er aß; dann brachte er ihm Wein, und er trank.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'Hierauf sprach sein Vater Isaak zu ihm: Tritt herzu und küsse mich, mein Sohn!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'Als er nun herzutrat und ihn küßte, da roch er den Duft seiner Kleider; und er segnete ihn und sprach: Fürwahr, der Duft meines Sohns ist wie der Duft des Gefildes, das Jahwe gesegnet hat!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'Es gebe dir Gott Tau vom Himmel und fetten Boden und Überfluß an Korn und Wein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, 'Es sollen Völker dir dienstbar werden und Nationen vor dir sich beugen. Du sollst ein Herr sein über deine Brüder, und vor dir sollen sich beugen die Söhne deiner Mutter. Wer irgend dir flucht, der sei verflucht, wer aber dich segnet, soll gesegnet sein!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'Als nun Isaak den Segen über Jakob vollendet hatte, und Jakob kaum eben hinweggegangen war von seinem Vater Isaak, da kam sein Bruder Esau heim von der Jagd.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'Und er bereitete gleichfalls ein Essen, brachte es seinem Vater hinein und sprach zu seinem Vater: Steh auf, mein Vater, und iß von dem Wildbret deines Sohns, damit du mir alsdann deinen Segen gebest!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'Da antwortete ihm sein Vater Isaak: Wer bist du? Er sprach: Ich bin dein erstgeborner Sohn Esau!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'Da erschrak Isaak über alle Maßen und sprach: Wer in aller Welt war denn der, der ein Wild erjagt und mir hereingebracht hat, so daß ich von allem aß, ehe du herkamst, und ihm meinen Segen gab? Nun wird er gesegnet bleiben!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'Als Esau diese Worte seines Vaters vernahm, da erhob er ein gar lautes und klägliches Geschrei und sprach zu seinem Vater: Segne auch mich, mein Vater!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'Er aber sprach: Dein Bruder kam hinterlistigerweise und nahm dir den Segen weg!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, 'Da sprach er: Ja, mit Recht nennt man ihn Jakob! Denn zweimal hat er mich nun überlistet: mein Erstgeburtsrecht hat er genommen und nun hat er mir auch den Segen weggenommen! Dann sprach er: Hast du denn keinen Segen für mich aufbehalten?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'Da antwortete Isaak und sprach zu Esau: Ich habe ihn nun einmal zum Herrn über dich gesetzt und alle seine Brüder habe ich ihm als Knechte untergeben und habe ihn reichlich ausgestattet mit Korn und Wein; was in aller Welt könnte ich nun für dich noch thun, mein Sohn?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'Da sprach Esau zu seinem Vater: Ist denn das dein einziger Segen, mein Vater? Segne auch mich, mein Vater! und Esau fing laut zu weinen an.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, 'Da antwortete sein Vater Isaak und sprach zu ihm: Fürwahr, fern von fettem Boden wird dein Wohnsitz sein und ohne Anteil am Tau des Himmels droben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'Von deinem Schwerte sollst du leben und deinem Bruder sollst du dienstbar sein. Es wird aber geschehn, wenn du dich anstrengst, wirst du sein Joch abschütteln von deinem Halse.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, 'Esau aber war Jakob feind wegen des Segens, den ihm sein Vater gegeben hatte; und Esau dachte bei sich: Wenn erst die Zeit der Trauer um meinen Vater herangekommen ist, werde ich meinen Bruder Jakob erschlagen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'Als nun der Rebeka solche Reden ihres älteren Sohnes Esau hinterbracht wurden, ließ sie ihren jüngeren Sohn Jakob rufen und sprach zu ihm: Höre, dein Bruder Esau sinnt auf Rache gegen dich und will dich erschlagen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'Folge daher meinem Rate, mein Sohn! Brich auf, flieh zu meinem Bruder Laban nach Haran');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'und bleibe einige Zeit bei ihm, bis sich der Groll deines Bruders legt,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'bis der Zorn deines Bruders von dir abläßt, und er vergißt, was du ihm angethan hast. Dann will ich hinsenden und dich von dort holen lassen. Warum sollte ich euch beide an einem Tage verlieren!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'Da sprach Rebeka zu Isaak: Ich bin des Lebens überdrüssig wegen der Hethiterinnen. Wenn Jakob auch so eine Hethiterin, eine Landeseingeborene, zum Weibe nehmen sollte, wozu lebe ich dann noch?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'Da rief Isaak Jakob herbei und segnete ihn; und er gebot ihm und sprach zu ihm: Nimm nicht ein Weib von den Töchtern Kanaans.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, 'Mache dich auf und ziehe nach Mesopotamien, zu dem Hause Bethuels, des Vaters deiner Mutter, und hole dir von dort ein Weib, eine der Töchter Labans, des Bruders deiner Mutter.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'Und der allmächtige Gott segne dich und mache dich fruchtbar und mehre dich, daß du zu einem Haufen von Völkern werdest.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, 'Und er verleihe dir den Segen Abrahams, dir und deinen Nachkommen mit dir, daß du das Land, in welchem du als Fremdling weilst, welches Gott dem Abraham verliehen hat, zu eigen bekommest.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, 'So entließ Isaak den Jakob, und er zog nach Mesopotamien zu Laban, dem Sohne Bethuels, des Aramäers, dem Bruder Rebekas, der Mutter Jakobs und Esaus.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'Als nun Esau sah, daß Isaak den Jakob gesegnet und ihn nach Mesopotamien geschickt hatte, damit er sich von dort ein Weib hole, indem er ihn segnete und ihm gebot und sprach: Nimm nicht ein Weib von den Töchtern Kanaans!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, 'und daß Jakob auf seinen Vater und auf seine Mutter hörte und nach Mesopotamien ging,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'da merkte Esau, daß die Töchter Kanaans seinem Vater Isaak mißfielen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 'Daher ging Esau zu Ismael und nahm sich Mahalath, die Tochter Ismaels, des Sohnes Abrahams, die Schwester Nebajoths, zu seinen anderen Weibern hinzu zum Weibe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, 'Da zog Jakob aus von Beerseba und machte sich auf den Weg nach Haran.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'Da gelangte er an eine Stätte und blieb daselbst über Nacht, denn die Sonne war untergegangen. Und er nahm einen von den Steinen dieser Stätte, lege ihn zu seinen Häupten und legte sich schlafen an selbiger Stätte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'Da träumte ihm, eine Leiter sei auf die Erde gestellt, deren oberes Ende bis zum Himmel reichte, und die Engel Gottes stiegen auf ihr hinauf und herab.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'Und Jahwe stand vor ihm und sprach: Ich bin Jahwe, der Gott deines Vaters Abraham und der Gott Isaaks: das Land, auf dem du liegst, das werde ich dir und deinen Nachkommen verleihen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'Und deine Nachkommen sollen so zahlreich werden, wie die Krümchen der Erde, und du sollst dich ausbreiten nach West und Ost und Nord und Süd, und durch dich sollen alle Völkerstämme auf Erden gesegnet werden und durch deine Nachkommen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'Und ich werde mit dir sein und dich behüten überall, wohin du gehst, und werde dich zurückbringen in dieses Land. Denn ich werde dich nicht verlassen, bis ich ausgeführt, was ich dir verheißen habe!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'Da erwachte Jakob aus seinem Schlaf und sprach: Wahrlich, Jahwe ist an dieser Stätte, und ich wußte es nicht!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, 'Da fürchtete er sich und sprach: Wie schauerlich ist diese Stätte! Ja, das ist der Wohnsitz Gottes und die Pforte des Himmels!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'Frühmorgens aber nahm Jakob den Stein, den er zu seinen Häupten gelegt hatte, stellte ihn auf als Malstein und goß Öl oben darauf.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'Und er gab jener Stätte den Namen Bethel; vorher aber hieß die Stadt Lus.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'Und Jakob that ein Gelübde und sprach: Wenn Gott mit mir sein und mich behüten wird auf dem Wege, den ich jetzt gehe, und mir Brot zu essen und Kleider anzuziehen giebt,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'und ich wohlbehalten zum Hause meines Vaters zurückkehren werde, so soll Jahwe mein Gott sein,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'und dieser Stein, den ich als Malstein aufgestellt habe, soll ein Gotteshaus werden, und alles, was du mir geben wirst, werde ich dir getreulich verzehnten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, 'Da machte sich Jakob auf den Weg und wanderte in das Gebiet der gegen Morgen wohnenden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'Da erblickte er dort in der Steppe einen Brunnen; an dem lagerten gerade drei Herden, denn aus diesem Brunnen pflegten sie die Herden zu tränken. Über dem Brunnenloch aber lag ein schwerer Stein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'Und wenn alle Herden dorthin zusammengetrieben waren, dann wälzten sie den Stein vom Brunnenloch ab und tränkten die Schafe; sodann schafften sie den Stein wieder zurück auf das Brunnenloch an seinen Ort.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'Da sprach Jakob zu ihnen: Liebe Brüder! woher seid ihr? Sie antworteten: Von Haran sind wir!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'Da sprach er zu ihnen: Kennt ihr Laban, den Sohn Nahors? Sie antworteten: Jawohl!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'Da sprach er zu ihnen: Geht es ihm wohl? Sie antworteten: Es geht ihm wohl! Da kommt eben seine Tochter Rahel mit den Schafen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'Da sagte er: Es ist ja noch hoch am Tage und noch zu früh, das Vieh einzutreiben. Tränkt die Schafe und laßt sie dann wieder weiden!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, 'Sie sprachen: Wir können nicht, bis alle Herden zusammengetrieben sind; dann wälzt man den Stein vom Brunnenloch ab, und wir tränken die Schafe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'Während er noch mit ihnen redete, war Rahel mit den Schafen ihres Vaters herangekommen, denn sie hütete die Schafe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'Als nun Jakob die Rahel, die Tochter Labans, des Bruders seiner Mutter, erblickte, dazu die Schafe Labans, des Bruders seiner Mutter, da trat Jakob herzu, wälzte den Stein vom Brunnenloch ab und tränkte die Schafe Labans, des Bruders seiner Mutter.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'Hierauf küßte Jakob die Rahel und fing laut zu weinen an.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'Und Jakob berichtete der Rahel, daß er ein Vetter ihres Vaters und daß er ein Sohn Rebekas sei; da lief sie hin und berichtete es ihrem Vater.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'Als nun Laban solche Kunde über Jakob, den Sohn seiner Schwester, vernahm, da eilte er ihm entgegen, herzte und küßte ihn und führte ihn hinein in sein Haus; er aber erzählte dem Laban alles, was vorangegangen war.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'Da sprach Laban zu ihm: Ja, du bist von meinem Bein und Fleisch! Als er nun einen Monat lang bei ihm gewesen war,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, 'da sprach Laban zu Jakob: Du bist ja doch mein Vetter! Solltest du da umsonst für mich arbeiten? Sage mir, worin soll dein Lohn bestehen?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'Nun hatte Laban zwei Töchter; die ältere hieß Lea, die jüngere hieß Rahel.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'Lea aber hatte glanzlose Augen, während Rahel schön von Gestalt und schön von Antlitz war.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'Und Jakob liebte die Rahel; darum sprach er: Ich will dir sieben Jahre um Rahel, deine jüngere Tochter, dienen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'Laban antwortete: Besser, ich gebe sie dir, als daß ich sie einem fremden Manne gebe; bleibe bei mir!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'So diente Jakob um Rahel sieben Jahre, und sie dünkten ihm wie wenige Tage, so lieb hatte er sie.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'Darnach sprach Jakob zu Laban: Gieb mir mein Weib - denn meine Zeit ist um -, daß ich ihr beiwohne.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'Da lud Laban alle Bewohner des Ortes ein und veranstaltete ein Gastmahl.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'Am Abend aber nahm er seine Tochter Lea und brachte sie zu ihm hinein, und er wohnte ihr bei.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'Und Laban gab ihr seine Sklavin Silpa, der Lea, seiner Tochter, zur Leibmagd.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, 'Am Morgen aber befand sich, daß es Lea war. Da sprach er zu Laban: Was hast du mir angethan? Habe ich nicht um Rahel bei dir gedient? Warum hast du mich denn betrogen?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'Laban antwortete: Es ist hier zu Lande nicht der Brauch, daß man die Jüngere vor der Älteren weggiebt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'Führe mit dieser die Woche zu Ende, so soll dir auch die andere zu teil werden, um den Dienst, den du noch weitere sieben Jahre bei mir thun wirst!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'Jakob aber that also und führte die Woche mit ihr zu Ende; alsdann gab er ihm auch seine Tochter Rahel zum Weibe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'Und Laban gab seiner Tochter Rahel seine Sklavin Bilha zur Leibmagd.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'Da wohnte er auch der Rahel bei und hatte Rahel lieber, als Lea. Und er diente bei ihm noch weitere sieben Jahre.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'Als nun Jahwe sah, daß Lea zurückgesetzt ward, machte er sie fruchtbar, während Rahel unfruchtbar war.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'Da wurde Lea schwanger und gebar einen Sohn, den nannte sie Ruben, denn, sprach sie, Jahwe hat mein Elend angesehen. Nun wird mein Mann mich sicherlich lieb haben!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'Hierauf wurde sie abermals schwanger und gebar einen Sohn. Da sprach sie: Jahwe hat gehört, daß ich zurückgesetzt bin; darum gab er mir auch diesen. Und sie nannte ihn Simeon.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'Hierauf wurde sie abermals schwanger und gebar einen Sohn. Da sprach sie: Nun endlich wird mein Mann mir anhängen, da ich ihm drei Söhne geboren habe; darum nannte sie ihn Levi.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'Sodann wurde sie nochmals schwanger und gebar einen Sohn. Da sprach sie: Nunmehr will ich Jahwe preisen! Darum nannte sie ihn Juda. Darnach aber gebar sie weiter kein Kind.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'Als nun Rahel sah, daß sie dem Jakob kein Kind gebar, da wurde Rahel eifersüchtig auf ihre Schwester und sprach zu Jakob: Schaffe mir Kinder - wo nicht, so sterbe ich!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'Da wurde Jakob zornig über Rahel und sprach: Bin ich denn an Gottes statt, der dir Leibesfrucht versagt hat?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'Da sprach sie: Hier ist meine Leibmagd Bilha: wohne ihr bei, damit sie auf meinem Schoß gebäre, und auch ich durch sie zu Kindern komme!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'Da gab sie ihm ihre Leibmagd Bilha zum Weibe und Jakob wohnte ihr bei.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'Da wurde Bilha schwanger und gebar dem Jakob einen Sohn.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'Rahel aber sprach: Gott hat mir Recht geschafft und hat mich erhört und mir einen Sohn geschenkt! Darum nannte sie ihn Dan.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'Hierauf wurde Bilha, die Leibmagd Rahels, abermals schwanger und gebar dem Jakob einen zweiten Sohn.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'Da sprach Rahel: Einen Kampf um Gott habe ich gekämpft mit meiner Schwester und habe gesiegt! Darum nannte sie ihn Naphtali.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'Als nun Lea sah, daß sie kein Kind weiter gebar, nahm sie ihre Leibmagd Silpa und gab sie dem Jakob zum Weibe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'Da gebar Silpa, die Leibmagd Leas, dem Jakob einen Sohn.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'Da sprach Lea: Glück auf! und nannte ihn Gad.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'Hierauf gebar Silpa, die Leibmagd Leas, dem Jakob einen zweiten Sohn.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'Da sprach Lea: Ich Glückliche! Ja, glücklich werden mich die Weiber preisen! Daher nannte sie ihn Asser.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, 'Ruben aber ging einst aus um die Zeit der Weizenernte und fand Liebesäpfel auf dem Felde; die brachte er seiner Mutter Lea. Da sprach Rahel zu Lea: Gieb mir doch ein paar von den Liebesäpfeln deines Sohnes!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'Sie antwortete: ist es nicht genug, daß du mir meinen Mann wegnimmst, daß du nun auch die Liebesäpfel meines Sohnes wegnehmen willst? Da sprach Rahel: Meinetwegen mag er diese Nacht bei dir schlafen zum Entgelt für die Liebesäpfel deines Sohnes.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'Als nun Jakob des Abends vom Felde kam, ging ihm Lea entgegen und sprach: Herein zu mir mußt du kommen, denn ich habe vollen Lohn für dich gezahlt mit den Liebesäpfeln meines Sohnes! Und er schlief in jener Nacht bei ihr.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'Gott aber erhörte Lea, so daß sie schwanger wurde und Jakob einen fünften Sohn gebar.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'Da sprach Lea: Gott hat mir meinen Lohn dafür gegeben, daß ich meinem Manne meine Leibmagd abgetreten habe. Daher nannte sie ihn Issachar.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'Hierauf wurde Lea abermals schwanger und gebar dem Jakob einen sechsten Sohn.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'Da sprach Lea: Gott hat mich beschenkt mit einem schönen Geschenk; nunmehr wird mein Mann mich hochhalten, weil ich ihm sechs Söhne geboren habe! Darum nannte sie ihn Sebulon.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'Darnach aber gebar sie eine Tochter, die nannte sie Dina.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, 'Da gedachte Gott an Rahel und Gott erhörte sie und machte sie fruchtbar.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'Da wurde sie schwanger und gebar einen Sohn. Da sprach sie: Gott hat meine Schmach hinweggenommen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'Darum nannte sie ihn Joseph, indem sie sprach: Möge mir Jahwe noch einen Sohn schenken!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'Als nun Rahel den Joseph geboren hatte, sprach Jakob zu Laban: Laß mich heimziehen in mein Vaterland!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'Gieb mir meine Weiber und meine Kinder, um die ich dir gedient habe, daß ich abziehe; denn du weißt ja selbst, wie ich dir gedient habe!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'Da antwortete ihm Laban: Wenn ich dir irgend etwas gelte - ich spüre, daß mich Jahwe gesegnet hat um deinetwillen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'Da erwiderte er: Nenne den Lohn, den du von mir forderst, so will ich dir ihn geben!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'Da erwiderte er ihm: Du weißt, wie ich dir gedient habe, und was aus deinem Viehstand bei mir geworden ist.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'Denn wenig war, was du besaßest, ehe ich herkam; aber es wuchs mit Macht, und Jahwe ließ jedem meiner Tritte Segen für dich nachfolgen - nun aber, wann soll denn ich für meine Familie sorgen?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, 'Da erwiderte er: Was soll ich dir geben? Jakob sprach: Du sollst mir gar nichts geben. Wenn du mir Folgendes zugestehst, so will ich aufs neue deine Schafe weiden und hüten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, 'Ich werde heute alle deine Schafe durchgehn und aus ihnen jedes gesprenkelte und scheckige Stück entfernen - alles, was schwarz ist unter den Lämmern und was scheckig und gesprenkelt ist unter den Ziegen. Und das soll mein Lohn sein,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'und darin wird sich meine Redlichkeit erweisen: wenn du künftig meinen Lohn in Augenschein nimmst, dann soll alles, was nicht gesprenkelt und scheckig ist unter meinen Ziegen und was nicht schwarz ist unter meinen Lämmern, als gestohlen gelten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'Da erwiderte Laban: Gut! Es sei, wie du gesagt hast!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'Und er entfernte an selbigem Tage die gestreiften und scheckigen Böcke und alle gesprenkelten und scheckigen Ziegen - alles, woran irgend etwas Weißes war - und alles, was schwarz war unter den Lämmern, und übergab es seinen Söhnen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, 'Und er machte einen Zwischenraum von drei Tagereisen zwischen sich und Jakob; Jakob aber weidete die übrigen Schafe Labans.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, 'Da holte sich Jakob frische Stäbe von Storaxstauden, Mandelbäumen und Platanen und schälte an ihnen weiße Streifen heraus, indem er das Weiße an den Stäben bloßlegte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'Dann stellte er die Stäbe, die er geschält hatte, in die Tränkrinnen, in die Wasserrinnen, wohin die Schafe zur Tränke kamen, gerade vor die Schafe hin. Und sie begatteten sich, wenn sie zur Tränke kamen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'So begatteten sich die Schafe angesichts der Stäbe; dann warfen die Schafe gestreifte, gesprenkelte und scheckige.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'Die Lämmer aber sonderte Jakob ab und kehrte die Gesichter der Schafe gegen alle gestreiften und schwarzen Stücke unter den Schafen Labans; so legte er sich besondere Herden an, die that er nicht zu den Schafen Labans.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'Und so oft die Brunstzeit der kräftigen Tiere kam, legte Jakob den Schafen die Stäbe vor Augen in die Rinnen, damit sie sich vor den Stäben begatteten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'Waren es aber die schwachen Tiere, so legte er sie nicht hin; daher wurden die schwachen dem Laban, die kräftigen aber dem Jakob zu teil.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'So wurde der Mann über die Maßen reich und gelangte zu vielen Schafen und Sklavinnen und Sklaven und Kamelen und Eseln.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'Da kam ihm zu Ohren, welche Reden die Söhne Labans führten: Jakob hat alles an sich gebracht, was unserem Vater gehörte, und von dem, was unserem Vater gehörte, hat er all diesen Reichtum zuwege gebracht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'Und Jakob achtete auf die Mienen Labans; der aber bezeigte sich nicht mehr gegen ihn, wie früher.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'Da sprach Jahwe zu Jakob: Kehre zurück in das Land deiner Väter und zu deiner Verwandtschaft, so will ich mit dir sein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'Da sandte Jakob hin und ließ Rahel und Lea rufen auf das Feld zu seiner Herde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'Da sprach er zu ihnen: Ich sehe wohl, daß mir euer Vater nicht mehr dasselbe Gesicht zeigt, wie früher; aber der Gott meines Vaters war mit mir.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'Ihr wißt, daß ich aus allen meinen Kräften eurem Vater gedient habe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'Euer Vater aber hat mich betrogen und mir den Lohn zehnmal abgeändert; aber Gott ließ nicht zu, daß er mir Schaden zufügte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'Wenn er sprach: die gesprenkelten sollen dein Lohn sein, so warf die ganze Herde gesprenkelte, sprach er dagegen: die gestreiften sollen dein Lohn sein, so warf die ganze Herde gestreifte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'Und so entzog Gott eurem Vater das Vieh und gab es mir.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'Zu der Zeit aber, wo die Schafe brünstig wurden, da sah ich deutlich im Traum, wie die Böcke, die die Schafe besprangen, gestreift, gesprenkelt und gescheckt waren.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'Und der Engel Gottes sprach zu mir im Traum: Jakob! Ich antwortete: Hier bin ich!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'Da sagte er: Sieh einmal, wie alle Böcke, die die Schafe bespringen, gestreift, gesprenkelt und gescheckt sind. Denn ich habe alles gesehen, was Laban dir anthut.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'Ich bin der Gott von Bethel, woselbst du einen Malstein gesalbt, woselbst du mir ein Gelübde gethan hast. So mache dich nun auf, ziehe aus diesem Lande und kehre zurück in dein Heimatland.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'Da erwiderten Rahel und Lea und sprachen zu ihm: Haben wir etwa noch Teil und Erbe im Hause unseres Vaters?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, 'Gelten wir ihm nicht als Fremde, nachdem er uns verkauft und das Geld, das er für uns bekam, längst verzehrt hat?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'Denn all der Reichtum, den Gott unserem Vater entzogen hat, gehört uns und unseren Kindern. So thue du nur ganz, wie Gott zu dir gesagt hat!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'Da setzte Jakob seine Kinder und seine Weiber auf die Kamele;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, 'sodann führte er all sein Vieh hinweg und alle seine Habe, die er erworben hatte, das Vieh, das er besaß, welches er in Mesopotamien erworben hatte, um sich zu seinem Vater Isaak ins Land Kanaan zu begeben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, 'Während aber Laban hingegangen war, seine Schafe zu scheren, stahl Rahel den Teraphim ihres Vaters.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'Und Jakob überlistete Laban, den Aramäer, weil er ihm verheimlichte, daß er fliehen wolle.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'Also entfloh er mit allem, was ihm gehörte; und er brach auf, setzte über den Strom und schlug die Richtung nach dem Gebirge Gilead ein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'Am dritten Tage wurde dem Laban hinterbracht, daß Jakob entflohen sei.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'Da nahm er seine Stammesgenossen mit sich, verfolgte ihn sieben Tagereisen weit und ereilte ihn auf dem Gebirge Gilead.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, 'Gott aber kam des Nachts im Traum zu Laban, dem Aramäer, und sprach zu ihm: Hüte dich, Jakob ein böses Wort zu sagen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'Da erreichte Laban den Jakob; Jakob aber hatte sein Zelt auf dem Gebirge aufgeschlagen, während Laban mit seinen Stammesgenossen sein Zelt auf dem Gebirge Gilead aufgeschlagen hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'Da sprach Laban zu Jakob: Was soll das heißen, daß du mich überlisten wolltest und führtest meine Töchter fort wie Kriegsgefangene?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, 'Warum bist du heimlich geflohen und täuschtest mich und hast es mich nicht wissen lassen, daß ich dir hätte das Geleite geben können mit Jauchzen und Gesängen, mit Pauken und Harfen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, 'und hast mich meine Enkel und Töchter nicht küssen lassen? Ja, du hast thöricht gehandelt!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'Ich hätte es wohl in der Gewalt, schlimm mit euch zu verfahren; aber der Gott deines Vaters hat in der vergangenen Nacht zu mir gesagt: Hüte dich, Jakob ein böses Wort zu sagen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'Aber mag es sein, du bist nun einmal fortgegangen, weil du dich gar so sehr nach deiner Heimat sehntest - warum hast du meinen Gott gestohlen?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'Da antwortete Jakob und sprach zu Laban: Ja, ich fürchtete mich; denn ich dachte, du könntest mir deine Töchter entreißen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'Derjenige, bei dem du deinen Gott findest, der soll nicht am Leben bleiben! Im Beisein unserer Stammesgenossen untersuche, was ich bei mir habe, und nimm dir. Jakob aber wußte nichts davon, daß Rahel ihn gestohlen hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'Da ging Laban in das Zelt Jakobs und das Zelt Leas und in das Zelt der beiden Leibmägde und fand nichts; dann verließ er das Zelt Leas und trat in das Zelt Rahels.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'Rahel aber hatte den Teraphim genommen, in die Kamelsänfte gelegt und sich darauf gesetzt. Und Laban durchstöberte das ganze Zelt, fand aber nichts.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'Da sprach sie zu ihrem Vater: O Herr, sei nicht böse, wenn ich vor dir nicht aufstehen kann; es ergeht mir, wie es den Frauen ergeht! Und er suchte und suchte, fand aber den Teraphim nicht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'Jakob aber wurde zornig und schalt Laban. Und Jakob hob an und sprach zu Laban: Was habe ich verschuldet, was habe ich gefehlt, daß du mir so hitzig nachgesetzt bist?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'Du hast nun meinen ganzen Hausrat durchstöbert - hast du irgend etwas von deinem Hausgerät gefunden? Lege es hierher vor meine und deine Stammesgenossen, damit sie entscheiden, wer von uns beiden recht hat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'Zwanzig Jahre sind es nun, daß ich bei dir bin; deine Mutterschafe und deine Ziegen haben nie eine Fehlgeburt gethan, und Widder aus deiner Herde habe ich nicht gegessen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'Was zerrissen ward, habe ich dir nicht gebracht - ich selbst mußte es ersetzen; von mir fordertest du es, mochte es bei Tage oder bei Nacht geraubt sein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'Bei Tage verging ich vor Hitze und des Nachts vor Frost, und kein Schlaf kam in meine Augen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'Volle zwanzig Jahre habe ich dir in deinem Hause gedient: vierzehn Jahre um deine beiden Töchter und sechs Jahre um Schafe von dir; aber zehnmal ändertest du meinen Lohn!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'Wenn nicht der Gott meines Ahnherrn, der Gott Abrahams, er, den auch Isaak fürchtet, für mich gewesen wäre, - ja dann hättest du mich mit leeren Händen ziehen lassen! Wie ich geplagt war und mich abgearbeitet habe, hat Gott gesehen und darnach in vergangener Nacht entschieden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'Da antwortete Laban und sprach zu Jakob: Mein sind die Frauen und mein sind die Kinder und mein ist das Vieh, und alles, was du erblickst, das ist mein. Aber was kann ich nun machen gegenüber diesen meinen Töchtern oder den Kindern, die sie geboren haben?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'Aber wohlan, laß uns einen Vertrag miteinander schließen; der soll dann Zeuge sein zwischen mir und dir.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'Hierauf nahm Jakob einen Stein und richtete ihn auf als Malstein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'Da sprach Jakob zu seinen Stammesgenossen: Lest Steine auf! Da lasen sie Steine auf und errichteten einen Steinhaufen; dann hielten sie dort auf dem Steinhaufen das Mahl.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'Und Laban nannte ihn Jegar Sahadutha; Jakob aber nannte ihn Galed.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'Da sprach Laban: Dieser Steinhaufe ist nunmehr Zeuge zwischen mir und dir - deshalb nannte er ihn Galed -');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'und die Warte, indem er sprach: Jahwe möge Wache halten zwischen mir und dir, wenn wir einander ferngerückt sind.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'Wenn du etwa meine Töchter schlecht behandeln oder noch mehr Weiber zu meinen Töchtern hinzunehmen wolltest - wenn dann niemand bei uns ist: bedenke wohl, Gott ist Zeuge zwischen mir und dir!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'Da sprach Laban zu Jakob: Wohlan, dieser Steinhaufe und der Malstein, den ich aufgerichtet habe zwischen mir und dir -');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, 'Zeuge soll sein dieser Steinhaufe und Zeuge soll sein der Malstein; weder ich darf über diesen Steinhaufen hinausgehen zu dir hinüber, noch darfst du über diesen Steinhaufen und diesen Malstein in böser Absicht hinausgehen zu mir herüber.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'Der Gott Abrahams und der Gott Nahors sei Richter zwischen uns, der Gott ihres Vaters. Jakob aber schwur bei dem, den sein Vater Isaak fürchtete.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'Hierauf schlachtete Jakob Opfertiere auf dem Berge und lud seine Stammesgenossen ein, das Mahl zu halten. Da hielten sie das Mahl und übernachteten auf dem Berge.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'Am andern Morgen früh aber küßte Laban seine Enkel und seine Töchter und nahm Abschied von ihnen. Sodann brach Laban auf und kehrte zurück an seinen Wohnsitz.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'Auch Jakob war seines Wegs gezogen; da begegneten ihm die Engel Gottes.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'Da sprach Jakob, als er sie erblickte: Das ist das Heerlager Gottes! Daher nannte er jenen Ort Mahanaim.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, 'Jakob aber sandte Boten voraus an seinen Bruder Esau nach Seir, ins Edomiterland,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'und trug ihnen Folgendes auf: So sollt ihr sagen zu meinem Gebieter Esau: Dein Sklave Jakob läßt dir sagen: bei Laban habe ich geweilt und verzog dort bis jetzt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'Ich kam aber in den Besitz von Rindern, Eseln und Schafen, Sklaven und Sklavinnen, und sende nun meinem Gebieter Botschaft, damit du mir wohlgeneigt werdest.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'Es kehrten aber die Boten zu Jakob zurück und meldeten: Wir trafen deinen Bruder Esau, als er schon unterwegs war, dir entgegenzuziehen in Begleitung von 400 Mann.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'Da geriet Jakob in große Furcht, und es wurde ihm bange. Sodann teilte er die Leute, die er bei sich hatte, sowie die Schafe, die Rinder und die Kamele, in zwei Heerlager.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'Denn er dachte: Wenn Esau das eine Lager überfällt und niedermetzelt, so kann doch das andere Lager entrinnen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, 'Und Jakob sprach: Du Gott meines Ahnherrn Abraham und meines Vaters Isaak, Jahwe, der du zu mir sprachst: Kehre heim in dein Vaterland und zu deiner Verwandtschaft, und ich will sorgen, daß es dir wohlgeht! -');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'ich bin nicht wert aller der Wohlthaten und aller der Treue, die du deinem Diener bewiesen hast. Denn nur mit meinem Stab überschritt ich den Jordan da, und jetzt gebiete ich über zwei Heerlager.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'Ach, errette mich aus der Gewalt meines Bruders, aus der Gewalt Esaus; denn ich fürchte mich vor ihm, daß er nicht etwa kommt und uns niedermetzelt, Mütter samt Kindern.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, 'Du aber hast ja verheißen: ich will sorgen, daß es dir wohlgehe, und will deine Nachkommen so zahlreich werden lassen, wie die Sandkörner am Meere, die nicht zu zählen sind vor Menge!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'Und er blieb dort über Nacht. Hierauf schied er einen Teil seines Besitzes aus zu einem Geschenk für seinen Bruder Esau:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, '200 Ziegen und 20 Böcke, 200 Mutterschafe und 20 Widder,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, '30 säugende Kamelinnen mit ihren Füllen, 40 junge Kühe und 10 junge Stiere, 20 Eselinnen und 10 Eselsfüllen;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'diese übergab er seinen Sklaven, jede Herde besonders, und gebot seinen Sklaven: Zieht voraus und laßt jedesmal einen Zwischenraum zwischen den Herden!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'Sodann wies er den vordersten an: Wenn mein Bruder Esau auf dich stößt und dich fragt: Wem gehörst du an und wohin willst du und wem gehören diese da vor dir?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'so sprich: Sie sind ein Geschenk deines Sklaven Jakob, das für meinen Gebieter Esau bestimmt ist; er selbst aber folgt uns auf dem Fuße nach.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'Ebenso wies er auch den zweiten und den dritten und alle übrigen an, welche die Herden trieben, und sprach: Ganz ebenso sollt ihr zu Esau sagen, wenn ihr ihn antrefft,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'und sollt sprechen: Dein Sklave Jakob selbst folgt uns auf dem Fuße nach. Er dachte nämlich: Ich will ihn besänftigen mit dem Geschenk, das mir vorausgeht; erst dann will ich ihm unter die Augen treten, vielleicht wird er mich gnädig aufnehmen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'So ging also das Geschenk voraus, während er selbst jene Nacht im Lager zubrachte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'Sodann erhob er sich in jener Nacht und überschritt mit seinen beiden Frauen, seinen beiden Leibmägden und seinen elf Söhnen die Furt des Jabbok.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'Hierauf brachte er sie über den Fluß hinüber und brachte hinüber alles, was ihm gehörte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'Jakob aber blieb allein zurück. Da rang einer mit ihm bis zum Anbruch der Morgenröte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'Und als er sah, daß er ihn nicht bezwingen könne, schlug er ihn auf die Hüftpfanne, so daß die Hüftpfanne Jakobs verrenkt ward, während er mit ihm rang.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'Da sprach jener: Laß mich los, denn die Morgenröte bricht an! Er antwortete: Ich lasse dich nicht los, außer, du segnest mich!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'Da fragte er ihn: Wie heißest du? Er antwortete: Jakob!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'Da sprach er: Du sollst künftig nicht mehr Jakob heißen, sondern Israel; denn du hast mit Gott und mit Menschen gekämpft und bist Sieger geblieben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'Da bat Jakob: Thue mir doch deinen Namen kund! Er antwortete: Warum fragst du doch nach meinem Namen? Sodann segnete er ihn daselbst.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'Jakob aber nannte jene Stätte Pniel; denn, sprach er, ich habe Gott von Angesicht zu Angesicht gesehen und kam doch mit dem Leben davon.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'Und als er an Pniel vorüber war, ging die Sonne auf; er hinkte aber wegen seiner Hüfte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 33, 'Darum essen die Israeliten bis auf den heutigen Tag die Spannader nicht, die über die Hüftpfanne läuft, weil er Jakob auf die Hüftpfanne, die Spannader, geschlagen hat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'Als nun Jakob gewahrte, daß Esau herankam in Begleitung von 400 Mann, da verteilte er die Kinder auf Lea und Rahel und die beiden Leibmägde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'Und zwar stellte er die Leibmägde mit ihren Kindern an die Spitze, dahinter Lea mit ihren Kindern und dahinter Rahel mit Joseph.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'Er selbst aber ging voraus und verneigte sich siebenmal bis auf den Boden, bis er ganz nahe an seinen Bruder herangekommen war.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'Da lief ihm Esau entgegen und schloß ihn in seine Arme, fiel ihm um den Hals und küßte ihn, und sie weinten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'Als er aber aufblickte und die Frauen mit den Kindern gewahrte, fragte er: Wer sind denn diese da bei dir? Er antwortete: Die Kinder, die Gott deinem Sklaven geschenkt hat!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'Da traten die Leibmägde mit ihren Kindern herzu und verneigten sich;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'sodann traten auch Lea und ihre Kinder herzu und verneigten sich, und darnach trat Joseph herzu und Rahel und verneigten sich.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'Da fragte er: Was wolltest du denn mit diesem ganzen Zug, auf den ich stieß? Er erwiderte: Ich wünschte meinen Gebieter freundlich zu stimmen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'Da sprach Esau: Ich habe Besitztum genug; behalte, lieber Bruder, was dir gehört!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'Jakob erwiderte: Nicht doch! Wenn ich dir irgend etwas gelte, so mußt du meine Gabe von mir annehmen. Habe ich ja doch dein Antlitz erschaut, wie das eines himmlischen Wesens, indem du mich zu Gnaden annahmst.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'Nimm doch das Begrüßungs-Geschenk von mir an, das dir überbracht worden ist; denn Gott hat mich reich gesegnet, und ich habe vollauf! So drang er in ihn, bis er es annahm.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'Hierauf sagte er: Laß uns aufbrechen und weiter ziehen; ich aber will vor dir herziehen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'Er antwortete ihm: Mein Gebieter sieht selbst, daß die Kinder noch zart sind, und unter den Schafen und Rindern sind säugende Tiere; wollte ich die auch nur einen Tag lang über Gebühr anstrengen, so würde die ganze Herde sterben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'Mein Gebieter wolle doch vor seinem Sklaven vorausziehen; ich aber werde in aller Gemächlichkeit weiterziehen, so wie es die Kräfte der Herde, die ich zu treiben habe, und die Kräfte der Kinder zulassen, bis ich zu meinem Gebieter nach Seir gelange.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'Da erwiderte Esau: So will ich wenigstens einen Teil der Leute, die ich bei mir habe, bei dir lassen! Er antwortete: Wozu doch? Möchte ich nur Gnade in den Augen meines Gebieters finden!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, 'So zog Esau an jenem Tage wiederum seines Wegs nach Seir.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, 'Jakob aber zog weiter nach Sukkoth und erbaute sich ein Haus; für sein Vieh aber errichtete er Laubhütten. Daher nennt man den Ort Sukkoth.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'Und Jakob gelangte wohlbehalten nach der Stadt Sichems, die im Lande Kanaan liegt, als er aus Mesopotamien kam. Und er schlug vor der Stadt sein Lager auf.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'Das Stück Feld aber, auf dem er sein Zelt aufgeschlagen hatte, erwarb er von den Söhnen Hemors, des Vaters Sichems, um den Preis von 100 Kesita.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'Und er stellte daselbst einen Altar auf und nannte ihn El, Gott Israels.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'Als nun einst Dina, die Tochter Leas, die sie Jakob geboren hatte, ausging, um die Bewohnerinnen des Landes zu besuchen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'da erblickte sie Sichem, der Sohn des Heviters Hemor, des Landesfürsten; der ergriff sie, wohnte ihr bei und vergewaltigte sie.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, 'Und er hing mit ganzer Seele an Dina, der Tochter Jakobs, und gewann das Mädchen lieb und suchte das Mädchen zu beruhigen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'Hierauf bat Sichem seinen Vater Hemor: Wirb für mich um dieses Mädchen, daß sie mein Weib werde!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'Jakob aber hatte es erfahren, daß er seine Tochter Dina geschändet habe; seine Söhne aber waren mit seinem Vieh auf dem Weideplatz, und Jakob unternahm nichts bis zu ihrer Rückkehr.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'Da begab sich Hemor, der Vater Sichems, zu Jakob, um mit ihm Rücksprache zu nehmen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'Als nun die Söhne Jakobs vom Weideplatz kamen und es hörten, da wurden sie erbittert und gerieten in großen Zorn. Denn damit, daß er die Tochter Jakobs beschlief, hatte er gethan, was als eine schwere Schandthat in Israel empfunden wurde; derartiges hätte nimmermehr geschehen sollen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'Und Hemor nahm das Wort und sprach zu ihnen: Mein Sohn Sichem hat sein Herz an das Mädchen aus eurer Familie gehängt; bitte, gebt sie ihm zum Weibe');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'und verschwägert euch mit uns. Ihr gebt uns eure Töchter und nehmt euch unsere Töchter');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'und bleibt bei uns wohnen: das Land soll euch offen stehen; bleibt da und zieht in ihm umher und setzt euch fest darin!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'Sichem aber sprach zu ihrem Vater und zu ihren Brüdern: Möchte ich doch Gnade finden in euren Augen! Was ihr auch fordern mögt, ich will es geben!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'Mögt ihr noch so viel an Morgengabe und Geschenken von mir verlangen, ich will\'s geben, wie ihr es von mir fordern werdet; nur gebt mir das Mädchen zum Weibe!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'Da antworteten die Söhne Jakobs dem Sichem und seinem Vater Hemor und redeten mit Arglist, weil er ihre Schwester Dina geschändet hatte,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, 'und sprachen zu ihnen: Wir können uns nicht darauf einlassen, unsere Schwester einem Manne zu geben, der nicht beschnitten ist; denn dies gilt uns als schmachvoll.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'Nur unter der Bedingung wollen wir euch willfahren, wenn ihr werden wollt, wie wir, indem ihr alles, was männlich ist unter euch, beschneiden laßt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'Dann wollen wir euch unsere Töchter geben und uns eure Töchter nehmen und wollen bei euch wohnen bleiben, damit wir zu einem Volke werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'Wollt ihr aber nicht darein willigen, euch beschneiden zu lassen, so nehmen wir unsere Tochter und ziehen fort!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'Ihr Vorschlag gefiel Hemor und Sichem, dem Sohn Hemors.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'Und der Jüngling zögerte nicht, so zu thun; denn er hatte Gefallen an der Tochter Jakobs, und er war der Angesehenste in seiner ganzen Familie.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'Da begaben sich Hemor und sein Sohn Sichem zum Stadtthor und redeten also zu ihren Mitbürgern:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, 'Diese Männer sind friedlich gegen uns gesinnt. Laßt sie sich ansiedeln im Lande und es durchziehen; hat doch das Land Raum für sie nach allen Seiten! Ihre Töchter wollen wir uns zu Weibern nehmen und ihnen unsere Töchter geben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'Jedoch nur unter der Bedingung sind diese Männer willens, bei uns wohnen zu bleiben, damit wir zu einem Volke werden, wenn sich alles, was männlich ist unter uns, beschneiden läßt, wie sie selbst beschnitten sind.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'Ihre Herden und ihre Habe und all ihr Vieh wird dann uns gehören. So wollen wir ihnen doch zu Willen sein, damit sie bei uns wohnen bleiben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'Da fügten sie sich dem Vorschlage Hemors und seines Sohnes Sichem, so viele ihrer durch das Thor seiner Stadt aus und ein gingen, und alle Männer, so viele ihrer durch das Thor seiner Stadt aus und ein gingen, ließen sich beschneiden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'Am dritten Tage aber, als sie wundkrank waren, da griffen die beiden Söhne Jakobs, Simeon und Levi, die Brüder der Dina, zum Schwert, überfielen die arglose Stadt und erschlugen alle Männer.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'Auch Hemor und seinen Sohn Sichem töteten sie mit dem Schwert, holten Dina aus dem Hause Sichems und zogen ab.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'Die Söhne Jakobs fielen über die Erschlagenen her und plünderten die Stadt, weil man ihre Schwester geschändet hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'Ihre Schafe, Rinder, Esel und was in der Stadt und was draußen war, nahmen sie weg');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'und alle ihre Habe und alle ihre kleinen Kinder und ihre Weiber führten sie fort als Gefangene und plünderten dazu alles, was in den Häusern war.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'Da sprach Jakob zu Simeon und Levi: Ihr habt mich ins Unglück gestürzt; denn ihr habt mich verhaßt gemacht bei den Bewohnern des Landes, den Kanaanitern und Pheresitern, während ich doch nur wenig Leute unter mir habe, wenn sie sich nun wider mich zusammenrotten und mich besiegen, so werde ich samt meiner Familie vernichtet werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, 'Da erwiderten sie: Durfte er unsere Schwester wie eine Hure behandeln?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, 'Da sprach Gott zu Jakob: Auf, ziehe hinauf nach Bethel, verweile dort und errichte dort einen Altar dem Gotte, der dir erschien, als du vor deinem Bruder Esau flohst.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'Da gebot Jakob seiner Familie und allen, die mit ihm waren: Schafft die ausländischen Götter weg, die ihr bei euch habt, reinigt euch und wechselt eure Kleider,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'damit wir hinauf nach Bethel ziehen. Denn ich will dort einen Altar errichten dem Gott, der mich erhört hat in der Zeit meiner Drangsal und der mit mir war auf dem Wege, den ich gezogen bin.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'Da übergaben sie Jakob alle ausländischen Götter, die in ihrem Besitze waren, sowie die Ringe, die sie an ihren Ohren trugen, und Jakob verscharrte sie unter der Terebinthe, die bei Sichem steht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'Sodann brachen sie auf; es lag aber ein von Gott gewirkter Schrecken auf den Städten, die rings um sie her waren, so daß man die Söhne Jakobs nicht verfolgte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'Und Jakob gelangte nach Lus, welches im Lande Kanaan liegt, - das ist Bethel - samt allen den Leuten, die er bei sich hatte,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, 'und er errichtete daselbst einen Altar und nannte die Stätte “Gott von Bethel”, weil sich ihm Gott dort offenbart hatte, als er vor seinem Bruder floh.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, 'Es starb aber Debora, die Amme der Rebeka, und wurde begraben unterhalb Bethel unter der Eiche; man nennt sie deshalb Klageeiche.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'Da erschien Gott dem Jakob abermals bei seiner Rückkunft aus Mesopotamien und segnete ihn.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'Und Gott sprach zu ihm: Du heißest Jakob; du sollst fortan nicht mehr Jakob heißen, sondern Israel soll dein Name sein. Daher nennt man ihn Israel.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'Und Gott sprach zu ihm: Ich bin Gott, der Allmächtige; du sollst fruchtbar sein und zahlreiche Nachkommen haben. Ein Volk, ja eine Schar von Völkern soll von dir abstammen und Könige werden aus deinen Lenden hervorgehn.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'Und das Land, welches ich Abraham und Isaak verliehen habe, dir will ich es verleihen und deinen Nachkommen will ich das Land verleihen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'Und Gott fuhr auf von ihm an der Stätte, wo er mit ihm geredet hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'Da errichtete Jakob einen Malstein an der Stätte, wo er mit ihm geredet hatte - ein Steinmal -, und goß ein Trankopfer darüber aus und schüttete Öl darüber.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'Und Jakob nannte die Stätte, woselbst Gott mit ihm geredet hatte, Bethel.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'Sodann zogen sie von Bethel weiter, und als sie nur noch eine Strecke Wegs bis Ephrath hatten, wurde Rahel von Geburtswehen befallen, und sie hatte eine schwere Geburt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'Und als ihr die Geburt so schwer wurde, sprach die Geburtshelferin zu ihr: Sei getrost, du hast auch diesmal einen Sohn!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'Als aber ihr Leben entfloh - denn sie mußte sterben -, da nannte sie ihn Schmerzenskind; sein Vater aber nannte ihn Benjamin.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'Hierauf starb Rahel und wurde begraben an der Straße nach Ephrath, das ist Bethlehem.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'Und Jakob errichtete einen Malstein auf ihrem Grabe; das ist der Malstein auf dem Grabe Rahels, der noch heute vorhanden ist.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'Hierauf zog Israel weiter und schlug sein Lager auf jenseits von Migdal Eder.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'Während aber Israel in dieser Gegend wohnte, ging Ruben hin und beschlief Bilha, das Kebsweib seines Vaters. Und Israel hörte es. Es waren aber die Söhne Jakobs ihrer zwölf.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'Von Lea: Der Erstgeborene Jakobs, Ruben, und Simeon, Levi, Juda, Issachar und Sebulon.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'Von Rahel: Joseph und Benjamin.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'Und von Bilha, der Leibmagd Rahels: Dan und Naphtali;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'und von Silpa, der Leibmagd Leas: Gad und Asser. Das sind die Söhne Jakobs, die ihm in Mesopotamien geboren wurden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'Und Jakob gelangte zu seinem Vater Isaak nach Mamre, der Stadt der vier - das ist Hebron -, woselbst Abraham und Isaak als Fremdlinge geweilt hatten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'Es betrug aber die Lebensdauer Isaaks 180 Jahre.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'Da verschied Isaak und starb und ging ein zu seinen Stammesgenossen, alt und lebenssatt, und seine Söhne Esau und Jakob bestatteten ihn.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'Dies sind die Nachkommen Esaus, das ist Edom.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'Esau hatte sich Kanaaniterinnen zu Weibern genommen: Ada, die Tochter des Hethiters Elon, und Oholibama, die Tochter Anas, des Sohnes Zibeons, des Horiters;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'und Basmath, die Tochter Ismaels, die Schwester Nebajoths.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'Ada aber gebar Esau den Eliphas, Basmath gebar Reguel,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'und Oholibama gebar Jehus, Jaelam und Korah. Das sind die Söhne Esaus, die ihm im Lande Kanaan geboren wurden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'Und Esau nahm seine Weiber, seine Söhne und Töchter und alle Sklaven, die zu seinem Hausstande gehörten, sowie seine Herde, all sein Vieh und alle seine Habe, die er im Lande Kanaan erworben hatte, und zog von seinem Bruder Jakob hinweg ins Land Seir.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'Denn ihr Besitz war zu groß, als daß sie hätten bei einander bleiben können, und das Land, in welchem sie als Fremdlinge weilten, reichte für sie nicht aus wegen ihrer Herden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'Und Esau nahm seinen Aufenthalt auf dem Gebirge Seir - Esau, das ist Edom.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'Dies sind die Nachkommen Esaus, des Stammvaters der Edomiter, auf dem Gebirge Seir.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'Dies sind die Namen der Söhne Esaus: Eliphas, der Sohn Adas, des Weibes Esaus; Reguel, der Sohn Basmaths, des Weibes Esaus.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'Die Söhne des Eliphas aber waren: Theman, Omar, Zepho, Gaetham und Kenas.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'Und Thimna war ein Kebsweib des Eliphas, des Sohnes Esaus; die gebar dem Eliphas den Amalek. Dies sind die Söhne Adas, des Weibes Esaus.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'Und dies sind die Söhne Reguels: Nahath, Serah, Samma und Missa. Dies waren die Söhne Basmaths, des Weibes Esaus.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, 'Und dies waren die Söhne Oholibamas, der Tochter Anas, des Sohnes Zibeons, des Weibes Esaus; die gebar dem Esau Jehus, Jaelam und Korah.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'Dies sind die Häuptlinge der Söhne Esaus. Die Söhne des Eliphas, des Erstgebornen Esaus, waren der Häuptling Theman, der Häuptling Omar, der Häuptling Zepho, der Häuptling Kenas.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, 'Der Häuptling Korah, der Häuptling Gaetham, der Häuptling Amalek. Dies sind die Häuptlinge von Eliphas im Lande Edom. Dies sind die Söhne Adas.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'Und dies waren die Söhne Reguels, des Sohnes Esaus: der Häuptling Nahath, der Häuptling Serah, der Häuptling Samma, der Häuptling Missa. Dies sind die Häuptlinge von Reguel im Lande Edom; dies sind die Söhne Basmaths, des Weibes Esaus.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'Und dies sind die Söhne Oholibamas, des Weibes Esaus: der Häuptling Jehus, der Häuptling Jaelam, der Häuptling Korah. Dies sind die Häuptlinge von Oholibama, der Tochter Anas, dem Weibe Esaus.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, 'Dies sind die Söhne Esaus und dies ihre Häuptlinge: das ist Edom.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'Dies sind die Söhne Seirs, des Horiters, die Ureinwohner des Landes: Lotan, Sobal, Zibeon, Ana,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'Dison, Ezer und Disan. Dies sind die Häuptlinge der Horiter, die Söhne Seirs, im Lande Edom.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'Die Söhne Lotans aber waren Hori und Heman; und die Schwester Lotans war Thimna.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'Und dies sind die Söhne Sobals: Alwan, Manahath, Ebal, Sepho und Onam.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, 'Und dies sind die Söhne Zibeons: Ajja und Ana; das ist derselbe Ana, der die heißen Quellen in der Steppe fand, als er die Esel seines Vaters Zibeon weidete.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'Und dies sind die Söhne Anas: Dison; und Oholibama war die Tochter Anas.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'Und dies sind die Söhne Disons: Hemdan, Esban, Jithran und Keran.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'Dies sind die Söhne Ezers: Bilhan, Sawan und Akan.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'Dies sind die Söhne Disans: Uz und Aran.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'Dies sind die Häuptlinge der Horiter: der Häuptling Lotan, der Häuptling Sobal, der Häuptling Zibeon, der Häuptling Ana.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'Der Häuptling Dison, der Häuptling Ezer, der Häuptling Disan. Dies sind die Häuptlinge der Horiter nach ihren Häuptlingen im Lande Seir.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'Und dies sind die Könige, welche im Lande Edom geherrscht haben, bevor es einen König der Israeliten gab.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'Es war König über Edom Bela, der Sohn Beors, und seine Residenz hieß Dinhaba.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'Als Bela gestorben war, wurde Jobab, der Sohn Serahs, aus Bosra König an seiner Statt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'Als Jobab gestorben war, wurde Husam aus dem Lande der Themaniter König an seiner Statt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'Als Husam gestorben war, wurde Hadad, der Sohn Bedads, König an seiner Statt, derselbe, der die Midianiter auf der Ebene von Moab schlug; und seine Residenz hieß Awith.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'Als Hadad gestorben war, wurde Samla aus Masreka König an seiner Statt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'Als Samla gestorben war, wurde Saul aus Rehoboth am Euphratstrom König an seiner Statt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'Als Saul gestorben war, wurde Baal-hanan, der Sohn Achbors, König an seiner Statt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'Als Baal-hanan, der Sohn Achbors, gestorben war, wurde Hadar König an seiner Statt; seine Residenz aber hieß Pagu und sein Weib Mehetabeel, die Tochter Matreds, der Tochter Mesahabs.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'Dieses sind die Namen der Häuptlinge Esaus nach ihren Geschlechtern, ihren Ortschaften, ihren Namen: der Häuptling Thimna, der Häuptling Alwa, der Häuptling Jetheth,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'der Häuptling Oholibama, der Häuptling Ela, der Häuptling Pinon,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'der Häuptling Kenas, der Häuptling Theman, der Häuptling Mibzar,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'der Häuptling Magdiel, der Häuptling Iram. Dies sind die Häuptlinge von Edom nach ihren Wohnsitzen in dem Lande, das sie in Besitz genommen hatten, das ist von Esau, dem Stammvater Edoms.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'Jakob aber blieb wohnen im Lande, wo sein Vater als Fremdling geweilt hatte, im Lande Kanaan.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'Das ist die Geschichte Jakobs: Als Joseph siebzehn Jahre alt war, pflegte er mit seinen Brüdern die Schafe zu hüten - er war aber noch jung - mit den Söhnen Bilhas und Silpas, der Weiber seines Vaters; und wenn man ihnen etwas Schlimmes nachsagte, so hinterbrachte es Joseph ihrem Vater.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'Israel aber liebte Joseph mehr, als alle seine anderen Söhne, weil er ihm in seinem Alter geboren worden war, und er ließ ihm Ärmelkleider machen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'Als nun seine Brüder gewahrten, daß ihr Vater ihn mehr liebte, als alle seine anderen Söhne, warfen sie einen Haß auf ihn und brachten es nicht über sich, ihm ein freundliches Wort zu gönnen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'Einst hatte Joseph einen Traum, den erzählte er seinen Brüdern; da haßten sie ihn noch ärger.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, 'Und er sprach zu ihnen: Hört einmal, was für einen Traum ich gehabt habe!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, 'Wir waren beschäftigt, draußen auf dem Felde Garben zu binden. Da richtete sich meine Garbe auf und blieb stehen; eure Garben aber stellten sich rings herum und warfen sich vor meiner Garbe nieder.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'Da sprachen seine Brüder zu ihm: Willst du etwa gar König über uns werden oder über uns herrschen? Seitdem haßten sie ihn noch ärger wegen seiner Träume und wegen seiner Reden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'Und ein andermal hatte er wieder einen Traum, den erzählte er seinen Brüdern und sprach: Hört, ich habe noch einen Traum gehabt! Da war die Sonne und der Mond und elf Sterne, die warfen sich vor mir nieder.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'Als er das seinem Vater und seinen Brüdern erzählte, da schalt ihn sein Vater und sprach zu ihm: Was ist das für ein Traum, den du da gehabt hast? Sollen etwa ich und deine Mutter und deine Brüder kommen und uns vor dir niederwerfen auf den Boden?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'Seitdem waren seine Brüder eifersüchtig auf ihn; sein Vater aber merkte sich die Sache.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, 'Als nun einst seine Brüder hingegangen waren, um bei Sichem die Schafe ihres Vaters zu weiden,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'da sprach Israel zu Joseph: Deine Brüder weiden bei Sichem; wohlan, ich will dich zu ihnen schicken! Er erwiderte: Ich bin bereit!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'Da sprach er zu ihm: Geh und sieh zu, ob es deinen Brüdern und der Herde wohl geht, und bringe mir Bescheid! So schickte er ihn hinweg aus dem Thale von Hebron und er gelangte nach Sichem.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'Da traf ihn jemand, wie er auf freiem Felde umherrirrte, und fragte ihn: Was suchst du?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, 'Er antwortete: Meine Brüder suche ich; sage mir doch, wo sie jetzt weiden!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'Der Mann erwiderte: Sie sind von hier weggezogen, denn ich hörte sie sagen: Wir wollen nach Dothan gehen! Da ging Joseph seinen Brüder nach und traf sie in Dothan.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'Als sie ihn nun in der Ferne erblickten, und ehe er noch zu ihnen herangekommen war, da machten sie einen tückischen Anschlag wider ihn, ihn umzubringen;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'da riefen sie einander zu: Da kommt ja der Träumer her!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, 'Kommt, wir wollen ihn totschlagen und in die erste beste Zisterne werfen und wollen vorgeben, ein reißendes Tier habe ihn gefressen; dann wird sich zeigen, was an seinen Träumen ist!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'Als Ruben das hörte, suchte er ihn aus ihren Händen zu retten und sprach: Nein, totschlagen wollen wir ihn nicht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'Da sprach Ruben zu ihnen: Vergießt nur kein Blut! Werft ihn in die Zisterne da auf der Trift, aber legt nicht Hand an ihn! - um ihn aus ihren Händen zu erretten, um ihn seinem Vater zurückzubringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, 'Als nun Joseph zu seinen Brüdern herangekommen war, da zogen sie Joseph sein Kleid aus - das Ärmelkleid, das er anhatte -,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'packten ihn und warfen ihn in die Zisterne; die Zisterne aber war leer und kein Wasser darin.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, 'Als sie sich nun hingesetzt hatten, um ihre Mahlzeit zu halten, da gewahrten sie eine Karawane von Ismaelitern, die eben aus Gilead herüberkam; deren Kamele waren beladen mit Tragakanth, Balsam und Ladanum: damit waren sie unterwegs nach Ägypten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'Da sprach Juda zu seinen Brüdern: Was hätten wir davon, wenn wir unseren Bruder umbrächten und den Mord verheimlichten?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'Kommt, wir wollen ihn an die Ismaeliter verkaufen, nicht aber Hand an ihn legen; denn er ist unser Bruder, unser Fleisch. Seine Brüder willigten ein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'Es kamen aber midianitische Händler vorüber; und sie zogen ihn heraus und holten Joseph herauf aus der Zisterne und verkauften Joseph an die Ismaeliter für zwanzig Silberstücke, und sie führten Joseph fort nach Ägypten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'Als nun Ruben wieder zur Zisterne kam, da war Joseph nicht mehr in der Zisterne! Da zerriß er seine Kleider,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'kehrte zurück zu seinen Brüdern und rief: Der Knabe ist verschwunden! Wo soll ich nun hin!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'Hierauf nahmen sie das Kleid Josephs, sodann schlachteten sie einen Ziegenbock und tauchten den Rock ins Blut.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'Dann schickten sie das Ärmelkleid, brachten es ihrem Vater und gaben vor: Dies haben wir gefunden - sieh doch zu, ob es der Rock deines Sohnes ist oder nicht!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'Und als er ihn näher angesehen hatte, da schrie er: Der Rock meines Sohnes! ein reißendes Tier hat ihn gefressen! Ja, ja, zerrissen ist Joseph!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'Da zerriß Jakob seine Kleider, legte ein härenes Gewand um seine Hüften und trauerte um seinen Sohn lange, lange Zeit.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'Und ob auch alle seine Söhne und Töchter ihn zu trösten suchten, wollte er sich doch nicht trösten lassen, sondern sprach: Trauernd werde ich zu meinem Sohne hinabsteigen in die Unterwelt! So beweinte ihn sein Vater.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'Die Midianiter aber verkauften ihn nach Ägypten an Potiphar, einen Verschnittenen des Pharao, den Anführer der Leibwächter.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, 'Um dieselbe Zeit trug es sich zu, daß Juda seine Brüder verließ und sich an einen Einwohner von Adullam, Namens Hira, anschloß.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'Dort erblickte Juda die Tochter eines Kanaaniters, Namens Sua; die nahm er zum Weibe und wohnte ihr bei.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'Da wurde sie schwanger und gebar einen Sohn; den nannte sie Ger.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'Hierauf wurde sie abermals schwanger und gebar einen Sohn; den nannte sie Onan.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'Sodann gebar sie noch einen Sohn; den nannte sie Sela. Und zwar befand sie sich zu Kesib, als sie ihn gebar.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'Juda aber freite für Ger, seinen Erstgebornen, ein Weib Namens Thamar.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'Nun machte sich aber Ger, der Erstgeborne Judas, Jahwe mißfällig; daher ließ ihn Jahwe sterben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'Da gebot Juda dem Onan: Begieb dich zum Weibe deines Bruders und leiste ihr die Schwagerpflicht, damit du deinem Bruder Nachkommen verschaffst.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'Da aber Onan wußte, daß die Kinder nicht ihm gehören sollten, so ließ er es, so oft er dem Weibe seines Bruders beiwohnte, daneben fallen, um seinem Bruder nicht Nachkommen zu verschaffen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'Solches Thun aber mißfiel Jahwe, daher ließ er auch ihn sterben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'Da gebot Juda seiner Schwiegertochter Thamar: Bleibe als Witwe im Hause deines Vaters, bis mein Sohn Sela herangewachsen ist! Er fürchtete nämlich, es könne auch dieser sterben, wie seine Brüder. Da ging Thamar hin und blieb im Hause ihres Vaters.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, 'Als nun längere Zeit verstrichen war, starb die Tochter Suas, das Weib Judas. Nachdem Juda ausgetrauert hatte, begab er sich mit seinem Freunde, dem Adullamiter Hira, hinauf nach Thimna, um nach seinen Scherern zu sehen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'Als nun Thamar berichtet ward: eben kommt dein Schwiegervater herauf nach Thimna zur Schafschur!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'da legte sie ihre Witwenkleider ab, bedeckte sich mit dem Schleier, vermummte sich und setzte sich nieder da, wo es nach Enaim hineingeht, das an dem Wege nach Thimna liegt. Denn sie hatte wohl bemerkt, daß Sela herangewachsen war, und doch war sie ihm nicht zum Weibe gegeben worden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'Als Juda sie erblickte, hielt er sie für eine Buhldirne; denn sie hatte ihr Gesicht verhüllt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'Da bog er zu ihr ab und sprach: Laß mich dir beiwohnen! Denn er wußte nicht, daß es seine Schwiegertochter war. Sie erwiderte: Was giebst du mir dafür, daß du mir beiwohnen darfst?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, 'Er antwortete: Ich werde dir ein Ziegenböckchen von der Herde schicken! Sie sprach: Wenn du mir ein Pfand giebst bis dahin, wo du es schicken wirst.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, 'Da fragte er: Was für ein Pfand soll ich dir geben? Sie erwiderte: Deinen Siegelring, deine Schnur und den Stab, den du in der Hand hast. Da gab er es ihr und wohnte ihr bei, und sie wurde schwanger von ihm.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'Hierauf ging sie von dannen, legte ihren Schleier ab und zog ihre Witwenkleider an.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'Juda aber schickte das Böckchen durch seinen Freund, den Adullamiter, um dagegen das Pfand von dem Weibe in Empfang zu nehmen; aber er fand sie nicht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'Da fragte er die Leute jenes Orts: Wo ist die Lustdirne, die hier bei Enaim am Wege saß? Sie antworteten: Hier ist keine Lustdirne gewesen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'Da kehrte er zu Juda zurück und berichtete: Ich habe sie nicht gefunden, und die Leute dort haben behauptet: Hier ist keine Lustdirne gewesen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'Juda erwiderte: Mag sie es behalten, wenn wir nur nicht zum Gespött werden. Ich habe richtig das Böckchen geschickt, du konntest sie aber nicht auffinden!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'Nach Verlauf von ungefähr drei Monaten aber wurde Juda berichtet: Deine Schwiegertochter Thamar hat gehurt und ist richtig dadurch schwanger geworden! Da gebot Juda: Führt sie hinaus, daß sie verbrannt werde!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'Als sie aber schon hinausgeführt war, da schickte sie zu ihrem Schwiegervater und ließ ihm sagen: Von dem Manne, dem diese Gegenstände gehören, bin ich schwanger! und ließ ihm sagen: Sieh doch zu, wem der Siegelring, die Schnüre und der Stab da gehören!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'Und als Juda sie näher angesehen hatte, sprach er: Sie ist in ihrem Rechte gegen mich; warum habe ich sie auch nicht meinem Sohne Sela zum Weibe gegeben! Er hatte aber fortan keinen Umgang mehr mit ihr.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'Als nun die Zeit da war, daß sie gebären sollte, da befand sich, daß Zwillinge in ihrem Leibe waren.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'Während der Geburt aber streckte einer eine Hand vor. Da nahm die Geburtshelferin einen roten Faden und band ihm den um die Hand; das wollte sagen: dieser ist zuerst herausgekommen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, 'Er zog jedoch seine Hand wieder zurück, und nun kam sein Bruder zum Vorschein. Da rief sie: Was hast du für einen Riß für dich gemacht! Daher nannte sie ihn Perez.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'Darnach kam sein Bruder zum Vorschein, an dessen Hand der rote Faden war; daher nannte sie ihn Serah.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'Als nun Joseph nach Ägypten gebracht worden war, kaufte ihn Potiphar, ein Verschnittener des Pharao, der Anführer der Leibwächter, ein Ägypter, von den Ismaelitern, die ihn dorthin gebracht hatten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'Jahwe aber war mit Joseph, so daß ihm alles gelang, und er hatte seinen Aufenthalt im Hause seines Herrn, des Ägypters.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'Als nun sein Herr sah, daß Jahwe mit ihm sei und daß Jahwe ihm alles gelingen ließ, was er unternahm,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'da kam Joseph in große Gunst bei ihm und er mußte ihn bedienen, und er machte ihn zum Aufseher über sein Hauswesen und vertraute ihm sein gesamtes Eigentum an.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'Und von der Zeit an, wo er ihn zum Aufseher über sein Hauswesen und sein gesamtes Eigentum bestellt hatte, segnete Jahwe das Haus des Ägypters um Josephs willen, und der Segen Jahwes ruhte auf allem, was ihm gehörte, im Hause und draußen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'Und er überließ Joseph sein gesamtes Eigentum und kümmerte sich neben ihm um gar nichts, nur daß er aß und trank. Joseph aber war schön von Gestalt und schön von Antlitz.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'Nach einiger Zeit nun warf das Weib seines Herrn ihre Augen auf Joseph und sprach: Schlafe bei mir!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'Er aber weigerte sich und sprach zu dem Weibe seines Herrn: Bedenke, mein Herr bekümmert sich neben mir um nichts im Hause und hat mir all sein Eigentum anvertraut.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'Er hat in diesem Hause nicht mehr Macht, als ich, und hat mir gar nichts vorenthalten, ausgenommen dich, da du sein Weib bist. Wie sollte ich nun dieses schwere Unrecht begehen und mich wider Gott versündigen?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'Und obgleich sie Tag für Tag auf Joseph einredete, war er ihr doch nicht zu Willen, daß er sich zu ihr gelegt und Umgang mit ihr gehabt hätte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, 'Eines Tages aber, als er ins Haus hineingekommen war, um seinen Geschäften obzuliegen, während gerade niemand von den Hausangehörigen drinnen anwesend war,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'ergriff sie ihn beim Gewand und verlangte: Schlafe bei mir! Er aber ließ sein Gewand in ihren Händen, ergriff die Flucht und lief zum Hause hinaus.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, 'Als sie nun sah, daß er sein Gewand in ihren Händen gelassen hatte und entflohen war,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'da rief sie die Hausangehörigen herbei und sprach zu ihnen: Ei, seht doch, hat er uns da einen Hebräer hergebracht, daß er seinen Mutwillen mit uns treibe! Er kam zu mir herein, um bei mir zu liegen, ich aber schrie laut.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'Als er nun hörte, daß ich ein lautes Geschrei erhob, da ließ er sein Gewand bei mir zurück und floh und lief zum Hause hinaus.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'Hierauf legte sie sein Gewand neben sich, bis sein Herr heimkam.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'Sodann berichtete sie ihm ganz ebenso: Kommt da der hebräische Sklave, den du uns hergebracht hast, zur mir herein, um seinen Mutwillen mit mir zu treiben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'Als ich aber ein lautes Geschrei erhob, ließ er sein Gewand bei mir zurück und floh zum Hause hinaus.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'Als nun sein Herr vernahm, was ihm sein Weib berichtete, indem sie erzählte: So und so hat dein Sklave gegen mich gehandelt! da wurde er sehr zornig.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'Und der Herr Josephs ließ ihn ergreifen und ins Gefängnis werfen, dahin, wo die königlichen Gefangenen gefangen saßen, und so lag er dort im Gefängnis.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'Aber Jahwe war mit Joseph und machte ihm die Herzen zugeneigt und verschaffte ihm die Gunst des obersten Aufsehers über das Gefängnis.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'Und der oberste Aufseher über das Gefängnis vertraute Joseph alle Gefangenen an, die sich im Gefängnis befanden, und alles, was dort geschah, geschah nach seiner Anordnung.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'Der oberste Aufseher über das Gefängnis kümmerte sich um gar nichts, was durch ihn geschah, da Jahwe mit ihm war; was er auch unternahm, das ließ Jahwe gelingen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'Einige Zeit darnach aber vergingen sich der Mundschenk des Königs von Ägypten und der Bäcker gegen ihren Herrn, den König von Ägypten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'Da wurde der Pharao zornig über seine beiden Verschnittenen, den Obermundschenk und den Oberbäcker,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'und ließ sie in Gewahrsam legen in das Haus des Anführers der Leibwächter, ins Gefängnis, dahin, wo Joseph gefangen saß.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, 'Und der Anführer der Leibwächter gab ihnen Joseph bei, damit er sie bediene, und so waren sie längere Zeit in Gewahrsam.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'Da hatten sie beide in einer und derselben Nacht einen Traum und zwar jeder einen Traum von besonderer Bedeutung, der Mundschenk und der Bäcker des Königs von Ägypten, die im Gefängnis saßen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'Als nun Joseph des Morgens zu ihnen hineinkam, merkte er ihnen an, daß sie verstimmt waren.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'Da fragte er die Verschnittenen des Pharao, die mit ihm im Gewahrsam waren im Hause seines Herrn: Warum macht ihr denn heute ein so böses Gesicht?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, 'Sie antworteten ihm: Wir haben einen Traum gehabt, und nun ist niemand da, der ihn deuten könnte. Da sprach Joseph zu ihnen: Traumdeutung hängt von Gott ab - erzählt mir einmal!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, 'Da erzählte der Obermundschenk dem Joseph seinen Traum und sprach zu ihm: Mir war\'s im Traum, als stehe ein Weinstock vor mir.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'An diesem Weinstock waren drei Zweige, und als er nun zu treiben begann, da kamen alsbald auch Blüten zum Vorschein, und seine Kämme trugen reife Trauben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'Ich aber hielt den Becher des Pharao in der Hand; und ich nahm die Trauben, drückte sie aus in den Becher des Pharao und gab sodann dem Pharao den Becher in die Hand.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'Da erwiderte ihm Joseph: Das ist so zu deuten: die drei Zweige bedeuten drei Tage.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'In drei Tagen von heute ab wird dich der Pharao emporziehen und dich wieder auf deinen Posten setzen. Dann wirst du dem Pharao seinen Becher reichen ganz so wie früher, als du sein Mundschenk warst.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'Aber - denke an mich, wenn es dir wohlgeht, und thu mir die Liebe an und lege bei dem Pharao ein gutes Wort für mich ein, damit du mich aus diesem Hause befreist!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'Denn ich bin schmählich geraubt aus dem Lande der Hebräer, und auch hier habe ich es mit nichts verschuldet, daß sie mich ins Gefängnis geworfen haben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'Als nun der Oberbäcker sah, daß er eine erfreuliche Deutung gab, da sprach er zu Joseph: In meinem Traume war es mir, als trüge ich drei Körbe mit Backwerk auf dem Haupte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'Im obersten Korbe befand sich allerlei Eßware für den Pharao, wie sie der Bäcker macht; aber die Vögel fraßen sie weg aus dem Korb auf meinem Haupte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'Da antwortete Joseph und sprach: Das ist so zu deuten: die drei Körbe bedeuten drei Tage.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'In drei Tagen von heute ab wird dich der Pharao enthaupten lassen und ans Holz hängen; da werden dann die Vögel dein Fleisch wegfressen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'Und am dritten Tage darauf, dem Geburtstage des Pharao, da veranstaltete er ein Gastmahl für alle seine Untergebenen. Da zog er den Obermundschenk und den Oberbäcker empor im Beisein seiner Untergebenen;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'den Obermundschenk setzte er wieder in sein Schenkenamt ein, so daß er dem Pharao wieder den Becher reichen durfte,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'den Oberbäcker aber ließ er hängen, wie ihnen Joseph vorhergesagt hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'Der Obermundschenk jedoch dachte nicht mehr an Joseph, sondern vergaß ihn.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'Zwei Jahre darauf träumte einmal dem Pharao und zwar, er stehe am Nil.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'Aus dem Nil aber stiegen sieben Kühe herauf von stattlichem Aussehen und fetten Leibes; die weideten im Riedgras.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'Nach ihnen aber stiegen sieben andere Kühe aus dem Nil herauf, von häßlichem Aussehen und mageren Leibes; die stellten sich neben die ersten Kühe am Ufer des Nil.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'Hierauf fraßen die häßlich aussehenden und mageren Kühe die sieben schönen und fetten Kühe - da erwachte der Pharao.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'Als er wieder eingeschlafen war, träumte ihm abermals und zwar, es wüchsen sieben Ähren an einem Halme, dick und schön.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'Nach ihnen aber sproßten sieben dürre und vom Ostwind versengte Ähren auf;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'diese dürren Ähren verschlangen die sieben dicken und vollen Ähren. Da erwachte der Pharao und merkte, daß er geträumt habe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'Frühmorgens aber ließ es ihm keine Ruhe, da sandte er aus und ließ alle Schriftkundigen und Weisen Ägyptens herbeirufen; denen erzählte der Pharao seine Träume. Aber da war keiner, der sie dem Pharao deuten konnte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, 'Da nahm der Obermundschenk das Wort und sprach zum Pharao: Ich muß heute meine Verschuldung in Erinnerung bringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'Der Pharao war zornig auf seine Diener und ließ sie ins Haus des Anführers der Leibwächter gefangen setzen, mich und den Oberbäcker.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'Da hatten wir beide in einer und derselben Nacht einen Traum, und zwar jeder einen Traum von besonderer Bedeutung.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'Nun war da bei uns ein hebräischer Jüngling, ein Sklave des Anführers der Leibwächter; dem erzählten wir unsere Träume, und er deutete sie uns und offenbarte uns genau, was eines jeden Traum bedeutete.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'Und wie er uns vorhergesagt, so ist\'s geschehen: mich hat man wieder auf meinen Posten gesetzt, und ihn hat man gehenkt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'Da sandte der Pharao hin und ließ Joseph rufen. Da entließen sie ihn schleunigst aus dem Gefängnis, und er ließ sich scheren, wechselte seine Kleider und begab sich hinein zum Pharao.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'Da sprach der Pharao zu Joseph: Ich habe einen Traum gehabt, und es ist niemand da, der ihn zu deuten vermöchte. Nun habe ich aber von dir gehört: du brauchst einen Traum nur zu hören, um ihn alsbald zu deuten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'Da erwiderte Joseph dem Pharao: O nein, ich nicht; aber Gott wird etwas offenbaren, was dem Pharao zum Heile gereicht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'Da erzählte der Pharao dem Joseph: Mir träumte, ich stehe am Ufer des Nil.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'Da stiegen aus dem Nil sieben Kühe herauf, fetten Leibes und von stattlichem Aussehen, und weideten im Riedgras.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'Nach ihnen aber stiegen sieben andere Kühe herauf, elend und überaus häßlich anzusehen und mageren Leibes - nie habe ich in ganz Ägypten etwas so Häßliches gesehen wie sie!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'Hierauf fraßen die mageren und häßlichen Kühe die sieben ersten, die fetten Kühe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'Aber auch als sie sie hineingefressen hatten, merkte man nichts davon, daß sie sie gefressen hatten, vielmehr war ihr Aussehen häßlich wie zuvor. Da erwachte ich.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'Weiter aber sah ich im Traume sieben Ähren an einem Halme wachsen, die waren voll und schön.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'Nach ihnen aber sproßten sieben taube, dürre, vom Ostwind versengte Ähren auf,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'und die dürren Ähren verschlangen die sieben schönen Ähren. Das erzählte ich den Schriftkundigen, aber keiner kann mir Bescheid geben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'Da antwortete Joseph dem Pharao: Die Träume des Pharao sind gleichbedeutend; Gott hat dem Pharao vorausverkündigt, was er demnächst thun wird.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'Die sieben schönen Kühe bedeuten sieben Jahre, und die sieben schönen Ähren bedeuten sieben Jahre - beide Träume sind gleichbedeutend.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'Und die sieben mageren und häßlichen Kühe, die nach ihnen heraufstiegen, bedeuten sieben Jahre, und die sieben leeren, vom Ostwind versengten Ähren sind, wie sich zeigen wird, sieben Hungerjahre.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'Deshalb habe ich vorhin zum Pharao gesagt: Was Gott zu thun vorhat, hat er dem Pharao gezeigt!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'Es kommen jetzt sieben Jahre, da wird großer Überfluß in ganz Ägypten herrschen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'Nach ihnen aber werden sieben Hungerjahre eintreten, so daß ganz in Vergessenheit geraten wird, welcher Überfluß in Ägypten herrschte, und der Hunger wird das Land aufreiben;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'und man wird nichts mehr wissen von dem Überfluß im Lande infolge dieser Hungersnot, die hinterdrein kommt, denn sie wird überaus drückend sein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'Und was das betrifft, daß dem Pharao zweimal nacheinander träumte, so wisse: die Sache ist fest beschlossen bei Gott, und Gott wird sie eilends ins Werk setzen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'So wolle sich denn der Pharao einen klugen und weisen Mann ersehen, daß er ihm Ägypten unterstelle.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'Und der Pharao wolle dazu thun und Aufseher über das Land bestellen, um während der sieben Jahre des Überflusses den Fünften von Ägypten erheben zu lassen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'Und zwar soll man den gesamten Ernteertrag der nun kommenden guten Jahre ansammeln und Getreide aufspeichern zur Verfügung des Pharao und soll den Ernteertrag in die Städte legen und aufbewahren.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'Dieser Vorrat soll dem Land als Rückhalt dienen für die sieben Hungerjahre, die über Ägypten kommen werden; so wird das Land nicht zu Grunde gehen durch die Hungersnot.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'Diese Rede fand Beifall bei dem Pharao und bei allen seinen Untergebenen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'Da sprach der Pharao zu seinen Untergebenen: Könnten wir wohl einen finden, in dem der Geist Gottes ist, wie in ihm?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'Sodann sprach der Pharao zu Joseph: Nachdem dir Gott dieses alles offenbart hat, giebt es niemand, der so klug und weise wäre, wie du.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'Du sollst meinem Hause vorstehen, und deinem Befehle soll sich mein gesamtes Volk fügen - nur den Besitz des Throns will ich vor dir voraus haben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'Da sprach der Pharao zu Joseph: Wohlan, ich setze dich über ganz Ägypten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'Hierauf zog der Pharao seinen Siegelring von seiner Hand ab und steckte ihn Joseph an; sodann ließ er ihn mit Byssusgewändern bekleiden und legte ihm die goldene Kette um den Hals.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'Hierauf ließ er ihn auf dem Wagen fahren, der im Range dem seinigen folgte, und man rief vor ihm aus: Abrekh! So setzte er ihn über ganz Ägypten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'Und der Pharao sprach zu Joseph: ich bin der Pharao - aber ohne deinen Willen soll niemand Hand oder Fuß regen in ganz Ägypten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'Und der Pharao legte Joseph den Namen Zaphenat Paneach bei und gab ihm Asnath, die Tochter Potipheras, des Oberpriesters von On, zum Weibe; und Joseph gebot über Ägypten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, 'Dreißig Jahre war Joseph alt, als er vor Pharao, dem König von Ägypten, stand. Darnach begab sich Joseph hinweg von dem Pharao und durchzog ganz Ägypten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, 'Das Land aber trug in den sieben Jahren des Überflusses haufenweise.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'Da sammelte er den gesamten Ernteertrag der sieben Jahre, während welcher in Ägypten Überfluß herrschte, und legte Vorrat in die Städte; in einer jeden Stadt speicherte er den Ertrag der Felder auf, die rings um sie her lagen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'So häufte Joseph Getreide auf, wie Sand am Meer, in ungeheuren Massen, bis er davon abstand, es zu messen, denn es war nicht zu messen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'Und Joseph wurden zwei Söhne geboren, ehe das Hungerjahr anbrach; die gebar ihm Asnath, die Tochter Poti-pheras, des Oberpriesters von On.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'Den Erstgeborenen nannte Joseph Manasse; denn Gott, sprach er, hat mich alle meine Not und meine gesamte Familie vergessen lassen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'Den zweiten aber nannte er Ephraim; denn Gott, sprach er, hat mich fruchtbar sein lassen im Lande meiner Trübsal.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'Als nun die sieben Jahre des Überflusses in Ägypten vorüber waren,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'da brachen die sieben Hungerjahre an, wie Joseph vorhergesagt hatte. Und zwar kam eine Hungersnot über alle Länder; aber in ganz Ägypten gab es Brot.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'Als nun ganz Ägypten die Hungersnot empfand, da forderte das Volk ungestüm Brot vom Pharao. Da sprach der Pharao zu allen Ägyptern: Geht hin zu Joseph: was er euch gebieten wird, das thut!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'Es lastete aber die Hungersnot auf aller Welt. Da eröffnete Joseph alle Kornspeicher und verkaufte den Ägyptern Getreide. Und die Hungersnot wurde immer drückender in Ägypten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'Da kam alle Welt zu Joseph nach Ägypten, um Getreide zu kaufen; denn überall herrschte drückende Hungersnot.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'Als nun Jakob vernahm, daß es in Ägypten Getreide gebe, da sprach Jakob zu seinen Söhnen: Was zaudert ihr?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'Da sprach er: Ich höre mit Bestimmtheit, daß es in Ägypten Getreide giebt. Zieht hin und holt uns von dort Getreide, damit wir am Leben bleiben und nicht sterben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'Da zogen zehn von den Brüdern Josephs hin, um Getreide aus Ägypten zu holen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'Benjamin aber, den Bruder Josephs, ließ Jakob nicht mit seinen Brüdern ziehen; denn er trug Sorge, es könne ihm ein Unfall zustoßen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'Da kamen unter denen, die hinströmten, auch die Söhne Israels hin, um Getreide zu kaufen; denn in Kanaan herrschte Hungersnot.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, 'Und Joseph, der da Machthaber war im Lande, der verkaufte aller Welt Getreide. Als nun die Brüder Josephs hereinkamen und sich bis auf den Boden vor ihm verneigten,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'da erkannte Joseph seine Brüder, sobald er ihrer ansichtig wurde. Aber er stellte sich fremd gegen sie und er ließ sie hart an und fragte sie: Woher kommt ihr? Sie antworteten: Aus Kanaan, um Getreide zu kaufen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'Und Joseph erkannte seine Brüder; sie aber erkannten ihn nicht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'Da mußte Joseph an die Träume denken, die er in Bezug auf sie gehabt hatte. Und er sprach zu ihnen: Ihr seid Spione! Ihr seid nur hergekommen, um zu erspähen, wo das Land eine schwache Stelle hat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, 'Sie antworteten ihm: O nein, Herr! Deine Sklaven sind vielmehr hergekommen, um Mundvorrat zu kaufen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'Wir sind alle Söhne eines Mannes, wir sind ehrliche Leute; deine Sklaven sind keine Spione!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'Er erwiderte ihnen: Nichts da! Ihr seid hergekommen, um zu erspähen, wo das Land eine schwache Stelle hat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'Sie antworteten: Unser zwölf sind deine Sklaven, lauter Brüder, Söhne eines Mannes in Kanaan; der Jüngste ist gegenwärtig noch bei unserem Vater, und einer ist verschwunden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'Da sprach Joseph zu ihnen: Es ist so, wie ich euch gesagt habe: Spione seid ihr!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'Damit sollt ihr euch ausweisen: so wahr der Pharao lebt, ihr sollt nicht eher von hier wegziehen, bis euer jüngster Bruder hierher gekommen ist.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'Schickt einen von euch hin, daß er euren Bruder hole; ihr aber müßt gefangen bleiben. So sollen eure Aussagen geprüft werden, ob ihr mit der Wahrheit umgeht oder nicht. So wahr der Pharao lebt - ihr seid doch Spione!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'Hierauf ließ er sie drei Tage in Gewahrsam legen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'Am dritten Tag aber sprach Joseph zu ihnen: Folgendes müßt ihr thun, um am Leben zu bleiben - denn ich bin ein gottesfürchtiger Mann.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'Wenn ihr ehrliche Leute seid, so mag einer von euch Brüdern als Gefangener zurückbleiben, da wo ihr in Gewahrsam lagt; ihr andern aber zieht hin und schafft das Getreide hin, dessen ihr für eure Familien bedürft.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'Euren jüngsten Bruder aber müßt ihr mir herbringen; so werden sich eure Aussagen bewahrheiten, und ihr werdet dem Tode entgehen. Und sie thaten also.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'Da sprachen sie einer zum andern: Wahrlich, das haben wir an unserem Bruder verschuldet; denn wir sahen seine Angst, wie er uns anflehte; aber wir blieben taub! Darum sind nun diese Ängste über uns gekommen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'Ruben aber sprach zu ihnen: Habe ich euch nicht gesagt: versündigt euch nicht an dem Kinde! Aber ihr wolltet nicht hören - nun aber wird Rechenschaft gefordert für sein Blut!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'Sie wußten aber nicht, daß Joseph sie verstand; denn sie verkehrten durch einen Dolmetscher.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'Da wendete er sich abseits, um zu weinen, kehrte dann wieder zu ihnen zurück und redete mit ihnen; hierauf ließ er Simeon aus ihrer Mitte greifen und vor ihren Augen fesseln.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'Sodann gab Joseph Befehl, ihre Säcke mit Getreide zu füllen, dabei aber einem jeden sein Geld wieder in seinen Sack zu thun, auch ihnen Zehrung mit auf den Weg zu geben. Nachdem man sie demgemäß versorgt,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'luden sie ihr Getreide auf ihre Esel und zogen von dannen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'Als aber einer von ihnen im Nachtquartier seinen Sack öffnete, um seinem Esel Futter zu geben, da sah er sein Geld in seinem Getreidesack obenauf liegen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, 'Da berichtete er seinen Brüdern: Mein Geld ist wieder da, hier liegt es in meinem Getreidesack! Da entsank ihnen der Mut, und bebend sahen sie einander an und riefen: Was hat uns da Gott angethan!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'Als sie nun zu ihrem Vater Jakob nach Kanaan zurückgekehrt waren, berichteten sie ihm alles, was ihnen begegnet war, und sprachen:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, 'Er, der Herr des Landes, ließ uns hart an und beschuldigte uns, wir wollten das Land auskundschaften.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'Wir versicherten ihm zwar: Wir sind ehrliche Leute, wir sind keine Spione!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'Wir sind unser zwölf Brüder, Söhne eines Vaters. Einer ist verschwunden, und der Jüngste ist zur Zeit bei unserem Vater in Kanaan.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'Aber der Mann, der Herr des Landes, antwortete uns: Daran will ich erkennen, daß ihr ehrliche Leute seid: laßt einen von euch Brüdern bei mir zurück! Was ihr an Getreide für eure Familien bedürft, mögt ihr nehmen und abziehen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'Aber bringt mir euren jüngsten Bruder her, damit ich erkenne, daß ihr keine Spione, daß ihr ehrliche Leute seid. Alsdann werde ich euch euren Bruder wiedergeben, und ihr könnt das Land frei durchziehen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'Als sie aber ihre Säcke ausschütteten, fand sich das Geld eines jeden in seinem Sack. Und als sie samt ihrem Vater ihr Geld erblickten, da erschraken sie.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'Da sprach ihr Vater Jakob zu ihnen: Mich beraubt ihr der Kinder! Joseph ist verschwunden, und Simeon ist verschwunden und Benjamin wollt ihr wegnehmen - mich trifft das alles!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'Da antwortete Ruben seinem Vater: Meine beiden Söhne magst du umbringen, wenn ich dir ihn nicht zurückbringe. Vertraue mir ihn an, ich werde ihn dir zurückbringen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, 'Er antwortete: Mein Sohn soll nicht mit euch reisen; denn sein Bruder ist tot, und er ist allein übrig. Wenn ihm ein Unfall zustieße auf dem Wege, den ihr ziehen müßt, so würdet ihr schuld daran sein, wenn ich mit meinem grauen Haar voller Jammer hinunter müßte in die Unterwelt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, 'Es lastete aber die Hungersnot schwer auf dem Lande.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'Als sie nun das Getreide, das sie aus Ägypten geholt, vollständig aufgezehrt hatten, da gebot ihnen ihr Vater: zieht wieder hin, etwas Getreide für uns zu kaufen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'Da antwortete ihm Juda: Jener Mann hat uns nachdrücklich eingeschärft: Ihr dürft mir nicht vor die Augen kommen, wenn ihr nicht euren Bruder mitbringt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'Willst du uns also unseren Bruder mitgeben, so wollen wir hinreisen und Getreide für dich kaufen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'Giebst du ihn uns aber nicht mit, so reisen wir nicht. Denn der Mann hat uns erklärt: Ihr dürft mir nicht vor die Augen kommen, wenn ihr nicht euren Bruder mitbringt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'Israel antwortete: Warum habt ihr mir das zuleide gethan und dem Manne verraten, daß ihr noch einen Bruder habt?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'Sie antworteten: Der Mann erkundigte sich genau nach uns und unserer Familie und fragte: Ist euer Vater noch am Leben? Habt ihr noch einen Bruder? Da gaben wir ihm Bescheid, ganz wie es sich verhält. Konnten wir denn wissen, daß er nun sagen würde: Bringt euren Bruder her?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'Juda aber sprach zu seinem Vater Israel: Gieb mir den Knaben mit, so wollen wir aufbrechen und hinziehen, damit wir leben bleiben und nicht sterben, wir und du und unsere Kinder.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'Ich will dir für ihn bürgen; mich sollst du für ihn verantwortlich machen. Wenn ich dir ihn nicht wiederbringe und vor Augen stelle, so will ich all meine Lebtage schuldig vor dir dastehen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'Wenn wir nicht über Gebühr gezaudert hätten, so hätten wir unterdes zweimal hin- und herreisen können.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, 'Da antwortete ihnen ihr Vater Israel: Wenn es denn sein muß, so thut Folgendes: Nehmt in euren Säcken etwas von den Erzeugnissen des Landes mit und bringt dem Manne ein Geschenk: ein wenig Balsam und ein wenig Honig, Spezereien und Ladanum, Pistazien und Mandeln.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'Sodann nehmt den gleichen Betrag an Geld noch einmal mit: auch das Geld, das sich wiedergefunden hat oben in euren Säcken, nehmt wieder mit - vielleicht liegt ein Irrtum vor.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'Dazu nehmt auch euren Bruder hin, brecht auf und zieht wieder hin zu dem Manne.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'Und Gott, der Allmächtige, verleihe, daß sich der Mann barmherzig gegen euch erzeigt, daß er euren anderen Bruder wieder mit euch ziehen läßt, dazu auch Benjamin; ich aber - wenn es denn sein muß, nun so bin ich eben verwaist.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'Da nahmen die Männer das erwähnte Geschenk, nahmen auch anderes Geld mit sich, dazu Benjamin, brachen auf, zogen nach Ägypten und traten vor Joseph.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'Als nun Joseph wahrnahm, daß Benjamin unter ihnen sei, gebot er seinem Hausmeister: Führe diese Männer hinein ins Haus, schlachte ein Stück Vieh und richte zu; denn diese Männer sollen mittags mit mir essen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'Der Mann that, wie Joseph befohlen hatte, und der Mann führte die Männer hinein in das Haus Josephs.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'Da fürchteten sich die Männer, daß sie ins Haus Josephs geführt wurden, und sprachen: Wegen des Geldes, das sich bei unserer ersten Anwesenheit wieder in unsere Säcke verirrte, werden wir hineingeführt: man will sich auf uns werfen, uns überfallen und uns zu Sklaven machen, samt unseren Eseln.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'Da traten sie an den Hausmeister Josephs heran und redeten ihn am Eingange des Hauses');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, 'also an: Bitte, mein Herr! Wir sind das erste Mal hierher gereist, nur um Getreide zu kaufen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'Als wir aber ins Nachtquartier gelangt waren und unsere Getreidesäcke aufbanden, da fand sich das Geld eines jeden oben in seinem Getreidesack - unser Geld nach seinem vollen Gewicht; wir haben es jetzt wieder mitgebracht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'Aber auch anderes Geld haben wir mitgebracht, um Getreide zu kaufen. Wir begreifen nicht, wer uns das Geld in die Getreidesäcke gelegt hat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, 'Da antwortete er: Beruhigt euch; seid ohne Sorge! Euer und eures Vaters Gott hat euch heimlich einen Schatz in eure Getreidesäcke gelegt. Euer Geld ist mir zugekommen. Hierauf führte er Simeon zu ihnen heraus.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'Sodann brachte er die Männer ins Haus Josephs. Er gab ihnen Wasser, und sie wuschen ihre Füße, und ihren Eseln reichte er Futter.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'Sodann legten sie das Geschenk zurecht und warteten, bis Joseph mittags käme; denn sie hatten vernommen, daß sie dort das Mahl einnehmen sollten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'Als nun Joseph ins Haus eingetreten war, brachten sie ihm das Geschenk, das sie mit sich führten, hinein und verneigten sich vor ihm bis auf den Boden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'Er aber erkundigte sich nach ihrem Befinden und fragte: Geht es eurem alten Vater, von dem ihr spracht, wohl? Ist er noch am Leben?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, 'Sie antworteten: Es geht deinem Diener, unserem Vater, wohl; er ist noch am Leben. Dabei bückten sie sich und verneigten sich.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'Da gewahrte er Benjamin, seinen leiblichen Bruder, und fragte: ist das euer jüngster Bruder, von dem ihr mir sagtet? und sprach: Gott gebe dir Gnade, mein Sohn!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'Dann aber brach Joseph schnell ab, denn er wurde von tiefer Rührung ergriffen, als er so seinem Bruder gegenüberstand, und suchte, wie er seinen Thränen freien Lauf lassen könne. Daher ging er hinein in das innere Gemach und weinte sich dort aus.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, 'Dann wusch er sich das Gesicht und kam wieder heraus, that sich Gewalt an und befahl: Tragt auf!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'Da trug man ihm besonders auf und ihnen besonders und ebenso den Ägyptern, die mit ihm speisten. Die Ägypter dürfen nämlich nicht mit den Hebräern zusammen speisen, denn das gilt den Ägyptern als eine Verunreinigung.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'Sie kamen aber vor ihn zu sitzen, vom Ältesten bis zum Jüngsten genau nach dem Alter geordnet; staunend sahen die Männer einander an.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'Hierauf ließ er ihnen von den Gerichten vorlegen, die vor ihm standen; es war aber dessen, was man Benjamin vorlegte, fünfmal so viel, als was man allen anderen vorlegte. Sodann tranken sie mit ihm und wurden guter Dinge.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'Hierauf gebot er seinem Hausmeister: Fülle den Männern ihre Säcke mit Getreide, soviel sie fortbringen können; lege aber einem jeden sein Geld obenauf in seinen Sack.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'Und meinen silbernen Becher legst du obenauf in den Sack des Jüngsten samt dem Geld für sein Getreide. Da that jener so, wie Joseph befohlen hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'Kaum war der Morgen angebrochen, ließ man die Männer samt ihren Eseln ziehen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'Eben hatten sie die Stadt verlassen und waren noch nicht weit gekommen, da befahl Joseph seinem Hausmeister: Auf, jage den Männern nach, und wenn du sie eingeholt hast, so sprich zu ihnen: Warum habt ihr Gutes mit Bösem vergolten? Warum habt ihr meinen silbernen Becher gestohlen?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, 'Ist\'s doch derselbe, aus dem mein Gebieter zu trinken pflegt und aus dem er wahrsagt - daran habt ihr sehr übel gethan!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'Als er sie nun eingeholt hatte, redete er solchergestalt mit ihnen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'Sie erwiderten ihm: O Herr! warum sprichst du so? Es liegt deinen Sklaven durchaus fern, so etwas zu thun.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'Haben wir dir doch das Geld, das wir oben in unseren Säcken fanden, aus Kanaan wieder mitgebracht: wie sollten wir da aus dem Hause deines Gebieters Silber und Gold stehlen?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, 'Derjenige deiner Sklaven, bei dem er sich findet, der soll sterben, und wir anderen wollen dir leibeigen werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, 'Er antwortete: Gut! wie ihr sagt, soll es geschehen. Der, bei welchem er sich findet, soll mein Sklave werden; ihr aber sollt frei ausgehn.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'Da ließ ein jeder schnell seinen Sack auf den Boden herab und ein jeder öffnete seinen Sack.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'Er aber fing an zu suchen: bei dem Ältesten hob er an und bei dem Jüngsten hörte er auf - da fand sich der Becher im Sacke Benjamins.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'Da zerrissen sie ihre Kleider, beluden ein jeder seinen Esel und kehrten wieder in die Stadt zurück.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'Und als Juda mit seinen Brüdern in das Haus Josephs kam - dieser war gerade noch dort anwesend -, da warfen sie sich vor ihm nieder auf den Boden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'Joseph aber sprach zu ihnen: Was habt ihr da angestellt! Bedachtet ihr denn nicht, daß ein Mann, wie ich, wahrsagen werde?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'Da antwortete Juda: Was sollen wir unserem Gebieter sagen? Was sollen wir reden und wie uns rechtfertigen, nachdem Gott die Schuld deiner Sklaven ausfindig gemacht hat! Wir gehören dir leibeigen, wir, sowie derjenige, in dessen Besitze sich der Becher gefunden hat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, 'Er erwiderte: Ferne sei es von mir, so zu verfahren! Derjenige, in dessen Besitze sich der Becher gefunden hat, der soll mir leibeigen werden; ihr aber mögt unangefochten zu eurem Vater ziehn.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'Da trat Juda zu ihm heran und sprach: Bitte, mein Herr! Möchte doch dein Sklave ein freimütiges Wort an dich richten dürfen, ohne daß du darum deinem Sklaven zürnst - stehst du doch dem Pharao gleich!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'Mein Gebieter fragte seine Sklaven: Habt ihr euren Vater noch oder noch einen Bruder?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'Wir antworteten dir: Unser alter Vater lebt noch, und auch ein kleiner spätgeborener Sohn ist vorhanden. Sein leiblicher Bruder ist tot, und so ist er allein übrig von seiner Mutter und wurde der Liebling seines Vaters.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'Da befahlst du deinen Sklaven: Bringt ihn her zu mir, damit ich ihn mit Augen sehe!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'Wir erwiderten dir: Der Knabe kann seinen Vater nicht verlassen; denn würde er seinen Vater verlassen, so würde dieser sterben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'Da sprachst du zu deinen Sklaven: Wenn ihr euren jüngsten Bruder nicht mitbringt, so dürft ihr mir nicht mehr unter die Augen kommen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'Als wir nun zu deinem Sklaven, meinem Vater, zurückgekehrt waren, berichteten wir ihm dein Begehren.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'Als sodann unser Vater gebot: Zieht wieder hin, etwas Getreide für uns zu kaufen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'da antworteten wir: Wir können unmöglich hinziehn! Wenn unser jüngster Bruder mit uns geht, so wollen wir hinziehn; denn wir dürfen ja dem Manne nicht mehr unter die Augen kommen, wenn unser jüngster Bruder nicht bei uns ist.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'Da antwortete uns dein Sklave, mein Vater: Ihr wißt ja selbst, daß mir mein Weib nur zwei Söhne geboren hat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'Der eine ging fort von mir, und ich mußte mir sagen: Sicherlich ist er zerrissen worden! und bis heute habe ich ihn nicht wiedergesehen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'Wenn ihr mir nun auch diesen noch wegnehmt, und ihm ein Unglück zustoßen sollte, so wäret ihr schuld daran, wenn ich mit meinem grauen Haar in schwerem Leid hinunter müßte in die Unterwelt!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'Und in der That, wenn ich jetzt zu deinem Sklaven, meinem Vater, käme, und der Knabe, an dem er doch mit ganzer Seele hängt, wäre nicht bei uns,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, 'so würde er, sobald er gewahr würde, daß der Knabe nicht mehr bei uns ist, sterben, und deine Sklaven wären schuld daran, wenn dein Sklave, unser Vater, mit seinem grauen Haar voller Jammer hinab müßte in die Unterwelt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'Denn dein Sklave hat sich gegenüber meinem Vater für den Knaben verbürgt und gelobt: Wenn ich dir ihn nicht wiederbringe, so will ich mein Leben lang schuldig dastehen vor meinem Vater.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'Möchte somit dein Sklave an Stelle des Knaben zurückbleiben dürfen als Leibeigener meines Gebieters, der Knabe aber heimkehren dürfen mit seinen Brüdern.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'Denn wie könnte ich heimkehren zu meinem Vater, ohne daß der Knabe bei mir wäre! Ich könnte den Jammer nicht mit ansehen, der über meinen Vater kommen würde!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'Da konnte Joseph nicht länger an sich halten, wie er bisher aus Rücksicht auf seine Umgebung gethan, und rief: Laßt jedermann hinausgehen! So war niemand weiter zugegen, als sich Joseph seinen Brüdern zu erkennen gab.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'Da brach er in lautes Weinen aus, so daß es die Ägypter und die Höflinge des Pharao hörten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'Da sprach Joseph zu seinen Brüdern: Ich bin Joseph! Lebt mein Vater noch? Aber seine Brüder vermochten ihm nicht zu antworten, so bestürzt waren sie ihm gegenüber.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'Da sprach Joseph zu seinen Brüdern: Tretet doch her zu mir! Und als sie herzutraten, sprach er: Ich bin euer Bruder Joseph, den ihr nach Ägypten verkauft habt!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'Nun aber laßt euch das nicht anfechten und geratet nicht in Unmut darüber, daß ihr mich hierher verkauft habt; denn um euch am Leben zu erhalten, hat mich Gott euch vorausgesandt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'Zwei Jahre lastet nun schon die Hungersnot auf dem Lande, und noch stehen fünf Jahre bevor, in denen es kein Pflügen und kein Ernten geben wird.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'Gott aber schickte mich euch voraus, um Sorge zu tragen für den Fortbestand eures Stammes, und daß welche von euch am Leben blieben, daß es zu einer großen Errettung käme.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'Somit habt nicht ihr mich hierher geschickt, sondern Gott; er machte mich zum vertrauten Ratgeber des Pharao und zum Obersten über seinen ganzen Hof und zum Gebieter über ganz Ägypten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'Zieht nun eilends hin zu meinem Vater und sagt ihm: So läßt dir dein Sohn Joseph sagen: Gott hat mich zum Herrn über ganz Ägypten gemacht; komm zu mir, säume nicht!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'In der Provinz Gosen sollst du wohnen und du sollst in meiner Nähe sein, samt deinen Söhnen und deinen Enkeln, deinen Schafen und Rindern und deinem ganzen Hausstand.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'Und ich werde daselbst für deinen Unterhalt sorgen. Denn noch fünf Jahre wird die Hungersnot währen; da könntest du verarmen samt deiner Familie und deinem ganzen Hausstand.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'Ihr seht es ja mit leiblichen Augen, und mein Bruder Benjamin sieht es mit leiblichen Augen, daß ich in eigner Person zu euch rede.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'Meinem Vater müßt ihr ausführlich berichten über meine hohe Würde in Ägypten und über alles, was ihr gesehen habt, und müßt eilends meinen Vater hierher bringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'Hierauf fiel er seinem Bruder Benjamin um den Hals und weinte, und Benjamin weinte an seinem Halse.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'Sodann küßte er alle seine Brüder und weinte, indem er sie umarmt hielt; darnach besprachen sich seine Brüder mit ihm.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, 'Und die Kunde drang an den Hof des Pharao: die Brüder Josephs sind angekommen! Und der Pharao und seine Umgebung waren erfreut darüber.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'Da sprach der Pharao zu Joseph: Sage deinen Brüdern: beladet also nun eure Lasttiere, zieht hin nach Kanaan,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'holt euren Vater und eure Familien und kommt her zu mir, so will ich euch zur Verfügung stellen, was Ägypten irgend Gutes bietet; so sollt ihr vom Besten genießen, was das Land erzeugt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'Du aber gebiete ihnen: Thut also! Nehmt euch aus Ägypten Wagen mit für eure kleinen Kinder und eure Weiber und laßt euren Vater aufsteigen und kommt her.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'Laßt euch\'s aber nicht leid sein um euren Hausrat; denn was Ägypten irgend Gutes bietet, das soll euer sein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'Und die Söhne Israels thaten also, und Joseph gab ihnen Wagen gemäß dem Befehl des Pharao und gab ihnen Zehrung für die Reise.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'Ihnen allen, Mann für Mann, schenkte er Ehrenkleider, und Benjamin schenkte er 300 Silbersekel und fünf Ehrenkleider.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'Seinem Vater aber sandte er gleichfalls zehn Esel, beladen mit den besten Erzeugnissen des Landes, sowie zehn Eselinnen, beladen mit Getreide, Brot und Zehrung für seinen Vater auf die Reise.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'Alsdann verabschiedete er seine Brüder, und sie zogen ab, nachdem er sie noch ermahnt hatte: Ereifert euch nicht unterwegs!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'So zogen sie fort aus Ägypten und gelangten nach Kanaan zu ihrem Vater Jakob.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'Da berichteten sie ihm: Joseph ist noch am Leben, ja er ist sogar Gebieter über ganz Ägypten. Da wurde er ganz starr, denn er konnte ihnen nicht glauben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'Als sie ihm aber alles berichteten, was Joseph ihnen aufgetragen hatte, und als er die Wagen erblickte, die Joseph gesandt, um ihn hinzubringen, da kam wieder Leben in ihren Vater Jakob.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, 'Da sprach Israel: Genug - mein Sohn Joseph ist noch am Leben! ich will hin und ihn sehen, bevor ich sterbe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'Da brach Israel auf mit seinem ganzen Hausstand und gelangte nach Beerseba; da brachte er dem Gotte seines Vaters Isaak Opfer dar.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'Da rief Gott in einem nächtlichen Gesicht Israel und sprach: Jakob, Jakob! Er antwortete: Ich höre!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'Da sprach er: Ich bin El, der Gott deines Vaters. Ziehe unbedenklich nach Ägypten, denn dort will ich dich zu einem großen Volke werden lassen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'Ich selbst werde mit dir nach Ägypten ziehn und ich selbst werde dich auch wieder zurückbringen; aber Joseph soll dir die Augen zudrücken.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'Da brach Jakob auf von Beerseba, und die Söhne Israels hoben ihren Vater Jakob, ihre kleinen Kinder und ihre Frauen auf die Wagen, die der Pharao gesandt hatte, um ihn hinzubringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'Und sie nahmen ihre Herden und ihre Fahrhabe, die sie in Kanaan erworben hatten, und gelangten nach Ägypten, Jakob mit seiner gesamten Nachkommenschaft;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'seine Söhne und Enkel, seine Töchter und Enkelinnen und seine gesamte Nachkommenschaft brachte er mit sich nach Ägypten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'Dies aber sind die Namen der Nachkommen Israels, die nach Ägypten kamen. Jakob und seine Nachkommen: der erstgeborene Sohn Jakobs Ruben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'Die Söhne Rubens waren: Hanoch, Pallu, Hezron und Karmi.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'Die Söhne Simeons: Jemuel, Jamin, Ohad, Jachin, Zohar und Saul, der Sohn der Kanaaniterin.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'Die Söhne Levis: Gerson, Kahath und Merari.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'Die Söhne Judas: Ger, Onan, Sela, Perez und Serah; Ger und Onan jedoch starben in Kanaan. Die Söhne des Perez aber waren Hezron und Hamul.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'Die Söhne Issachars: Tola, Puvva, Job und Simron.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'Die Söhne Sebulons: Sered, Elon und Jahleel.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, 'Dies sind die Söhne Leas, die sie Jakob in Mesopotamien gebar, samt seiner Tochter Dina, zusammen 33 Söhne und Töchter.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'Die Söhne Gads aber waren: Zaphon, Haggi, Suni und Ezbon, Eri, Arodi und Areli.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, 'Die Söhne Assers: Jimna, Jisva, Jisvi, Bria, dazu ihre Schwester Serah, und die Söhne Brias waren Heber und Malkiel.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, 'Dies sind die Söhne Silpas, die Laban seiner Tochter Lea mitgab; diese gebar sie Jakob, sechzehn Seelen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'Die Söhne Rahels, des Weibes Jakobs, waren Joseph und Benjamin.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'Dem Joseph aber wurden in Ägypten Söhne geboren; die gebar ihm Asnath, die Tochter Potipheras, des Oberpriesters von On: Manasse und Ephraim.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'Die Söhne Benjamins aber waren Bela und Becher und Asbel, Gera und Naaman, Ehi und Ros, Muppim und Huppim und Ard.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, 'Dies sind die Söhne Rahels, die sie Jakob gebar, zusammen vierzehn Seelen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'Die Söhne Dans aber waren Husim,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'und die Söhne Naphthalis: Jahzeel, Guni, Jezer und Sillem.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, 'Dies sind die Söhne Bilhas, welche Laban seiner Tochter Rahel mitgab; diese gebar sie Jakob, zusammen sieben Seelen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'Die Gesamtzahl der leiblichen Nachkommen Jakobs, die nach Ägypten übersiedelten, ungerechnet die Frauen der Söhne Jakobs, betrug 66 Seelen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'Die Söhne Josephs aber, die ihm in Ägypten geboren wurden, waren zwei an der Zahl. Die Gesamtzahl der Angehörigen Jakobs, die nach Ägypten gelangten, betrug siebzig.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'Juda aber sandte er voraus zu Joseph, damit er vor ihm nach Gosen Weisung gebe. Als sie nun nach der Provinz Gosen gelangt waren,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'ließ Joseph seinen Wagen anspannen und fuhr hin nach Gosen seinem Vater Israel entgegen. Und als er mit ihm zusammentraf, fiel er ihm um den Hals und weinte lange an seinem Halse.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'Israel aber sprach zu Joseph: Nun will ich gern sterben, nachdem ich dich wiedergesehen habe, daß du noch am Leben bist.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'Da sprach Joseph zu seinen Brüdern und zu den Angehörigen seines Vaters: Ich will hin, dem Pharao Bericht zu erstatten, und will ihm sagen: Meine Brüder und die Angehörigen meines Vaters, die in Kanaan waren, sind zu mir gekommen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'Und zwar sind diese Leute Schafhirten - denn sie waren Viehzüchter - und haben ihre Schafe und Rinder und ihre ganze Habe mit hergebracht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'Wenn euch nun der Pharao rufen läßt und fragt: Welches ist euer Beruf?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'so antwortet: Deine Sklaven sind Viehzüchter gewesen von Jugend auf bis heute, sowohl wir, wie unsere Vorfahren - damit ihr in der Provinz Gosen bleiben dürft. Die Schafhirten sind nämlich den Ägyptern ein Gegenstand des Abscheus.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'Hierauf ging Joseph hin, that dem Pharao Meldung und sprach: Mein Vater und meine Brüder sind mit ihren Schafen und Rindern und ihrer gesamten Habe aus Kanaan hergekommen und sind nun in der Provinz Gosen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'Er hatte aber fünf aus der Zahl seiner Brüder mitgebracht, die stellte er dem Pharao vor.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'Da fragte der Pharao die Brüder Josephs: Welches ist euer Beruf? Sie antworteten dem Pharao: Schafhirten sind deine Sklaven, sowohl wir, wie schon unsere Vorfahren.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'Und sie sprachen zum Pharao: Wir sind hergekommen, um uns eine Zeitlang hier aufzuhalten, weil es an Weide gebrach für die Schafherden, die deinen Sklaven gehören; denn die Hungersnot lastet schwer auf dem Lande Kanaan. Möchten also deine Sklaven in der Provinz Gosen verweilen dürfen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'Da sprach der Pharao zu Joseph: Sie mögen in der Provinz Gosen wohnen, und wenn du findest, daß besonders geeignete Leute unter ihnen sind, so mache sie zu Oberhirten über meine Herden. Und Jakob und seine Söhne gelangten zu Joseph nach Ägypten. Als nun der Pharao, der König von Ägypten, davon hörte, da sprach der Pharao zu Joseph: Also dein Vater und deine Brüder sind zu dir gekommen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'Ägypten steht dir zur Verfügung; laß deinen Vater und deine Brüder im fruchtbarsten Teile des Landes wohnen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'Hierauf brachte Joseph seinen Vater Jakob hinein und stellte ihn dem Pharao vor. Jakob aber begrüßte den Pharao mit einem Segenswunsch.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'Da fragte der Pharao Jakob: Wie viele Lebensjahre zählst du?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'Jakob antwortete dem Pharao: Die Dauer meiner Wanderschaft beträgt 130 Jahre. Gering an Zahl und voller Trübsal waren meine Lebensjahre und reichen nicht heran an die Lebensjahre meiner Vorfahren, die sie auf der Wanderschaft zubrachten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'Hierauf nahm Jakob mit einem Segenswunsch Abschied vom Pharao und ging vom Pharao hinweg.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'Joseph aber wies seinem Vater und seinen Brüdern Wohnsitze an und gab ihnen eigenen Besitz in Ägypten, im fruchtbarsten Teile des Landes, in der Provinz Ramses, wie der Pharao befohlen hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'Und Joseph versorgte seinen Vater und seine Brüder und die ganze Familie seines Vaters mit Brotkorn, unter Berücksichtigung der Kinderzahl.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, 'Es gab aber in allen Landen kein Brotkorn, denn die Hungersnot war überaus drückend, und Ägypten wie Kanaan waren erschöpft infolge der Hungersnot.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'Schließlich brachte Joseph alles Geld an sich, das es in Ägypten und Kanaan gab, für das Getreide, das sie kaufen mußten, und Joseph lieferte das Geld ein in den Palast des Pharao.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'Als aber das Geld in Ägypten und Kanaan ausgegangen war, kamen alle Ägypter zu Joseph und riefen: Schaff uns Brot! oder sollen wir vor deinen Augen sterben? Denn das Geld ist zu Ende!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'Joseph antwortete: Tretet eure Herden ab, so will ich euch Brotkorn für eure Herden geben, wenn das Geld zu Ende ist.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'Da brachten sie ihre Herden zu Joseph, und Joseph gab ihnen Brotkorn für die Rosse, die Schaf- und Rinderherden und für die Esel, und versorgte sie um den Preis aller ihrer Herden in selbigem Jahre mit Brotkorn.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'So ging das Jahr herum. Im folgenden Jahre aber kamen sie wieder zu ihm und sprachen zu ihm: Wir können dir nicht verhehlen, Herr: das Geld ist zu Ende, und der Besitz an Vieh ist an dich übergegangen. Nichts ist übrig, was du nehmen könntest, außer unser Leib und unsere Äcker.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, 'Sollen wir etwa vor deinen Augen zu Grunde gehen - wir und unsere Äcker? Kaufe uns und unsere Äcker um Brotkorn, so wollen wir samt unseren Äckern dem Pharao fronpflichtig werden! Aber gieb Saatkorn her, damit wir am Leben bleiben und nicht sterben, und die Äcker nicht zur Wüste werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'Da kaufte Joseph alle Äcker der Ägypter für den Pharao. Denn die Ägypter verkauften Mann für Mann ihr Feld, weil die Hungersnot auf ihnen lastete; so kam das Land in den Besitz des Pharao.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'Und was die Einwohner betrifft, so machte er sie zu Leibeigenen von einem Ende Ägyptens bis zum andern.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'Nur die Äcker der Priester kaufte er nicht an. Denn die Priester bezogen ein festes Einkommen vom Pharao und lebten von dem festen Einkommen, welches ihnen der Pharao gewährte; infolgedessen verkauften sie ihre Äcker nicht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, 'Da sprach Joseph zu den Landesbewohnern: So habe ich euch also nunmehr samt euren Äckern für den Pharao erkauft. Da habt ihr Saatkorn, damit ihr die Äcker besäen könnt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'Aber von den Erträgnissen müßt ihr ein Fünftel an den Pharao abliefern; die anderen vier Fünftel sollen euch verbleiben zum Besäen der Felder, sowie zu eurem Unterhalt und dem eurer Hausgenossen und zur Ernährung eurer kleinen Kinder.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'Da riefen sie: Du hast uns das Leben gerettet! Möchten wir uns deiner Huld erfreuen, o Herr, so wollen wir dem Pharao leibeigen sein!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'So legte Joseph den Ägyptern die noch heute bestehende Verpflichtung auf, dem Pharao von ihren Äckern den Fünften abzuliefern; nur die Äcker der Priester fielen dem Pharao nicht zu.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'Israel aber blieb in Ägypten, in der Provinz Gosen, wohnen, und sie setzten sich darin fest und mehrten sich, so daß sie überaus zahlreich wurden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'Es lebte aber Jakob in Ägypten 17 Jahre, und es belief sich die Lebensdauer Jakobs, seine Lebensjahre, auf 147 Jahre.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'Als es nun mit Israel zum Sterben ging, ließ er seinen Sohn Joseph rufen und sprach zu ihm: Wenn ich dir etwas gelte, so lege deine Hand unter meine Hüfte und erweise mir die Liebe und Treue: begrabe mich nicht in Ägypten!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'Vielmehr möchte ich bei meinen Vorfahren liegen; darum sollst du mich wegbringen aus Ägypten und mich in ihrem Grabe beisetzen. Da antwortete er: Ich werde thun, wie du wünschest.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, 'Da sprach er: Schwöre mir! Und er schwur ihm; Israel aber verneigte sich auf das Kopfende des Bettes hin.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, 'Nach diesen Begebenheiten berichtete man Joseph: Dein Vater liegt krank! Da nahm er seine beiden Söhne, Manasse und Ephraim, mit sich.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, 'Als man nun Jakob meldete: dein Sohn Joseph ist angekommen, da nahm Israel seine Kräfte zusammen und setzte sich im Bette auf.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'Und Jakob sprach zu Joseph: Gott, der Allmächtige, erschien mir zu Lus in Kanaan, segnete mich');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, 'und sprach zu mir: Ich werde dich fruchtbar sein lassen und dir eine zahlreiche Nachkommenschaft verleihen und will einen Haufen von Völkern aus dir hervorgehen lassen, und dieses Land werde ich deinen Nachkommen für immer zum Besitz verleihen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'Deine beiden Söhne aber, die dir in Ägypten geboren wurden, bevor ich zu dir nach Ägypten kam, die sollen mir angehören: Ephraim und Manasse - wie Ruben und Simeon sollen sie mir gelten!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'Die Kinder aber, die du nach ihnen erzeugt hast, sollen dir angehören; den Namen eines ihrer Brüder sollen sie führen in dem ihnen zugewiesenen Erbteil.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, 'Als ich aus Mesopotamien zurückkam, da starb mir Rahel unterwegs in Kanaan, als nur noch eine Strecke Wegs bis Ephrath war, und ich begrub sie dort am Wege nach Ephrath, das ist Bethlehem.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, 'Als aber Israel die Söhne Josephs erblickte, da fragte er: Wer sind diese da?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'Joseph antwortete seinem Vater: Es sind meine Söhne, die mir Gott allhier geschenkt hat! Da sprach er: Bringe sie her zu mir, daß ich sie segne.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'Es waren aber die Augen Israels stumpf vor Alter, so daß er nicht sehen konnte. Als er sie nun näher zu ihm herangebracht hatte, küßte und herzte er sie.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'Darauf sprach Israel zu Joseph: Ich hätte nimmermehr geglaubt, dich wiederzusehen: nun hat mich Gott sogar Nachkommen vor dir schauen lassen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'Hierauf ließ sie Joseph wieder zurücktreten und neigte sich tief vor ihm.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'Da nahm Joseph die beiden, Ephraim mit seiner Rechten, so daß er zur Linken Israels stand, und Manasse mit seiner Linken, so daß er zur Rechten Israels stand, und führte sie so zu ihm heran.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'Da streckte Israel seine Rechte aus und legte sie auf das Haupt Ephraims, obschon er der Jüngere war, und seine Linke auf das Haupt Manasses, legte also seine Hände übers Kreuz, denn Manasse war der ältere.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'Sodann segnete er Joseph und sprach: Der Gott, vor dessen Angesicht meine Väter, Abraham und Isaak, gewandelt haben, der Gott, der mein Hirte war, von meinem ersten Atemzuge an bis auf diesen Tag,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'der Engel, der mich errettete aus allen Nöten, er segne die Knaben, und in ihnen soll mein Name und der meiner Vorväter, Abraham und Isaak, fortleben, und sie sollen sich ungemein vermehren auf Erden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'Als nun Joseph wahrnahm, daß sein Vater seine rechte Hand auf das Haupt Ephraims legte, da war ihm das störend; daher ergriff er die Hand seines Vaters, um sie vom Haupt Ephraims hinüberzulegen auf das Haupt Manasses.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'Dabei sprach Joseph zu seinem Vater: Nicht so, lieber Vater, denn dieser da ist der Erstgeborene; lege deine Rechte auf sein Haupt!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'Sein Vater aber weigerte sich und sprach: Ich weiß wohl, mein Sohn, ich weiß wohl! Auch er soll zu einem Volk und auch er soll mächtig werden. Aber bei alledem soll doch sein jüngerer Bruder mächtiger werden, als er, und seine Nachkommen sollen eine wahre Völkermenge werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'Und er segnete sie an jenem Tag, indem er sprach: Deinen Namen sollen die Israeliten brauchen, um Segen zu wünschen, indem sie sprechen: Gott mache dich Ephraim und Manasse gleich! und stellte so Ephraim dem Manasse voran.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'Hierauf sprach Israel zu Joseph: Ich werde nun bald sterben, aber Gott wird mit euch sein und euch in das Land eurer Väter zurückbringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'Ich aber verleihe dir einen Bergrücken, den ich den Amoritern abgenommen habe mit meinem Schwert und Bogen, daß du ihn voraus habest vor deinen Brüdern.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'Da berief Jakob seine Söhne und sprach: versammelt euch, damit ich euch verkündige, was euch in der Folgezeit widerfahren wird!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'Schart euch zusammen und hört zu, ihr Söhne Jakobs, ja höret zu eurem Vater Israel!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'Ruben! Mein Erstgeborener bist du, meine Kraft und der Erstling meiner Stärke - der erste an Hoheit und der erste an Macht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'Du braustest auf wie Wasser - du sollst nicht der erste sein! Denn du bestiegst das Bett deines Vaters, verübtest damals Entweihung - mein Lager hat er bestiegen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'Simeon und Levi, die Brüder, - Werkzeuge des Frevels sind ihre Schwerter.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, 'Ich will nichts zu schaffen haben mit ihren Entwürfen, nichts gemein haben mit ihren Beschlüssen. Denn in ihrem Zorn haben sie Männer gemordet und in ihrem Übermut Stiere verstümmelt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'Verflucht sei ihr Zorn, daß er so heftig war, und ihr Grimm, daß er sich grausam erzeigte! Ich will sie verteilen in Jakob und will sie zerstreuen in Israel.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'Juda, dich, dich werden preisen deine Brüder! Es packt deine Hand das Genick deiner Feinde; vor dir werden sich beugen die Söhne deines Vaters.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'Ein Löwenjunges ist Juda - vom Raube bist du, mein Sohn, hinaufgestiegen. Er hat sich gestreckt, gelagert, wie ein Löwe und wie eine Löwin: wer darf ihn aufreizen?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, 'Nicht wird das Scepter von Juda weichen, noch der Herrscherstab aus seinen Händen, bis der kommt, dem es bestimmt ist, und die Völker sich ihm unterwerfen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'Er bindet an den Weinstock sein Eselsfüllen und an die Edelrebe das Junge seiner Eselin. Er wäscht in Wein sein Kleid und in Traubenblut sein Gewand,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'die Augen trübe von Weinund die Zähne weiß von Milch.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, 'Sebulon wird am Meeresufer wohnen, am Gestade der Schiffe, während seine Flanke sich an Zidon lehnt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, 'Issachar ist ein knochiger Esel, gelagert zwischen den Pferchen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'Und da er fand, daß Ruhe etwas Schönes, und sein Gebiet gar einladend sei, da beugte er seinen Nacken zum Lasttragen und wurde zum dienstbaren Fröner.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'Dan wird Recht schaffen seinem Volk, wie irgend einer der Stämme Israels.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'Dan wird eine Schlange an der Straße sein, eine Hornviper am Wege, die das Roß in die Fersen beißt, so daß der Reiter rückwärts sinkt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'Auf dein Heil harre ich, Jahwe!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'Gad - Streifscharen scharen sich wider ihn; er aber drängt ihnen nach auf ihrer Ferse.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'Ascher lebt in Überfluß - ja Königsleckerbissen liefert er.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, 'Naphthali ist eine freischweifende Hirschkuh; von ihm kommen anmutige Reden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, 'Ein junger Fruchtbaum ist Joseph, ein junger Fruchtbaum am Quell. Seine Schößlinge ranken empor an der Mauer.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'Es setzten ihm zu und schossen und es befehdeten ihn Pfeilschützen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'Doch unerschütterlich hielt sein Bogen stand, und flink regten sich seine Hände, durch die Hilfe des Starken Jakobs, von dort her, dem Hirten, dem Steine Israels,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'vom Gott deines Vaters - er helfe dir! - und von Gott, dem Allmächtigen, - er segne dich mit Segensfülle vom Himmel droben, mit Segensfülle aus der Wassertiefe, die drunten lagert, mit Segensfülle aus Brüsten und Mutterschoß.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'Die Segnungen, die deinem Vater wurden, überragten die Segensfülle der ewigen Berge, die Pracht der ewigen Hügel. Möchten sie kommen auf das Haupt Josephs und auf den Scheitel des Fürsten unter seinen Brüdern!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, 'Benjamin ist ein räuberischer Wolf: am Morgen verzehrt er Raub und abends verteilt er Beute.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'Das alles sind die Stämme Israels, zwölf an der Zahl, und das war es, was ihr Vater zu ihnen redete. Und er segnete sie, und zwar segnete er jeden einzelnen mit einem besonderen Segen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'Und er gebot ihnen und sprach zu ihnen: Wenn ich eingegangen bin zu meinen Stammesgenossen, so bringt mich in die Gruft meiner Vorfahren, in die Höhle auf dem Grundstück des Hethiters Ephron,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'in die Höhle auf dem Grundstück Machpela, welches gegenüber Mamre liegt in Kanaan, dem Grundstück, welches Abraham vom Hethiter Ephron zum Erbbegräbnis gekauft hat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'Dort haben sie Abraham und sein Weib Sara bestattet; dort haben sie Isaak und sein Weib Rebeka bestattet, und dort habe ich Lea bestattet,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'auf dem Grundstück, das mit der Höhle darauf von den Hethitern erkauft wurde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, 'Als aber Jakob mit den Aufträgen an seine Söhne zu Ende war, legte er sich zurück auf das Bett und verschied und ging ein zu seinen Stammesgenossen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'Da warf sich Joseph über seinen Vater her und weinte über ihm und küßte ihn.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'Sodann befahl Joseph den Ärzten, die ihm dienten, seinen Vater einzubalsamieren. Da balsamierten die Ärzte Israel ein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'Darüber vergingen 40 Tage, denn diesen Zeitraum erfordert das Einbalsamieren. Die Ägypter aber hielten ihm 70 Tage lang die Totenklage.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, 'Als nun die Klagezeit vorüber war, trug Joseph den Höflingen des Pharao die Bitte vor: Wenn ich euch irgend etwas gelte, so legt für mich ein gutes Wort ein bei dem Pharao in folgender Angelegenheit:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, 'Mein Vater hat mir einen Eid abgenommen und gesagt: Ich werde nun bald sterben; in der Gruft, die ich mir in Kanaan gegraben habe, dort sollst du mich beisetzen. Daher möchte ich nun hinziehn und meinen Vater bestatten, dann werde ich wiederkommen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'Da ließ ihm der Pharao antworten: Ziehe hin und bestatte deinen Vater gemäß dem Eid, den er dich hat schwören lassen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'So zog denn Joseph hin, um seinen Vater zu bestatten, und mit ihm zogen alle Untergebenen Pharaos, seine ersten Beamten und alle Würdenträger von Ägypten,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'dazu alle Angehörigen Josephs, sowie seine Brüder und die Angehörigen seines Vaters; nur ihre kleinen Kinder, sowie ihre Schafe und Rinder ließen sie in der Provinz Gosen zurück.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'Nicht minder begleiteten ihn Wagen und Reiter, so daß es ein ganz gewaltiger Zug war.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'Als sie nun bis nach Goren-Haatad gelangt waren, welches jenseits des Jordans liegt, hielten sie dort eine große und sehr feierliche Totenklage ab und er veranstaltete für seinen Vater eine siebentägige Totenfeier.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'Als aber die Bewohner des Landes, die Kanaaniter, die Totenfeier zu Goren-haatad gewahrten, sprachen sie: Da findet eine große Totenfeier der Ägypter statt! Von daher heißt der Ort Abel Mizraim; derselbe liegt jenseits des Jordans.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'Seine Söhne aber verfuhren mit ihm, wie er ihnen geboten hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'Und zwar führten ihn seine Söhne nach Kanaan über und bestatteten ihn in der Höhle auf dem Grundstück Machpela, dem Grundstück, das Abraham von dem Hethiter Ephron zum Erbbegräbnis erworben hatte, gegenüber Mamre.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'Hierauf kehrte Joseph, nachdem er seinen Vater bestattet hatte, nach Ägypten zurück, er und seine Brüder und alle, die mit ihm hingezogen waren, um seinen Vater zu bestatten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'Da überlegten die Brüder Josephs - im Hinblick darauf, daß ihr Vater nun tot war -: Wenn nun Joseph etwa feindselig gegen uns auftreten und uns alles das Böse heimzahlen sollte, das wir ihm angethan haben?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'Da schickten sie eine Abordnung an Joseph und ließen ihm sagen: Dein Vater hat vor seinem Tode Folgendes angeordnet:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, 'Sprecht also zu Joseph: Ach vergieb doch deinen Brüdern ihre Sünde und Verschuldung, daß sie dir Böses angethan haben! Also vergieb uns, die wir ja auch den Gott deines Vaters verehren, unsere Sünde! Da weinte Joseph, als sie so zu ihm sprachen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'Hierauf gingen seine Brüder selbst hin, warfen sich vor ihm nieder und sprachen: Hier, nimm uns zu Leibeigenen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'Joseph aber erwiderte ihnen: Seid getrost! denn bin ich etwa an Gottes Statt?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'Ihr freilich sannet Böses wider mich; Gott aber hat es zum Guten gewendet, um auszuführen, was jetzt vorliegt - viele Menschen am Leben zu erhalten!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'Seid also nur getrost! Ich werde für euren und eurer Kinder Unterhalt sorgen. So tröstete er sie und sprach ihnen Mut ein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'Es blieben aber Joseph und die zur Familie seines Vaters gehörten in Ägypten wohnen, und Joseph wurde 110 Jahre alt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'Und Joseph erlebte von Ephraim Enkel; auch Machir, dem Sohne Manasses, wurden bei Lebzeiten Josephs Söhne geboren.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'Joseph aber sprach zu seinen Brüdern: Wenn ich längst tot bin, wird sich Gott eurer annehmen und euch aus diesem Land in das Land bringen, das er Abraham, Isaak und Jakob zugeschworen hat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'Da ließ Joseph die Söhne Israels schwören und sprach: Wenn sich Gott dereinst eurer annehmen wird, müßt ihr meine Gebeine von hier wegbringen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, 'Und Joseph starb 110 Jahre alt. Da balsamierten sie ihn ein und legten ihn in Ägypten in einen Sarg.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'So hießen die Söhne Israels, die nach Ägypten gekommen waren; mit Jakob waren sie gekommen, jeder nebst seiner Familie:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Ruben, Simeon, Levi und Juda.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Issachar, Sebulon und Benjamin.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Dan und Naphthali, Gad und Asser.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'Die Gesamtzahl der Nachkommen Jakobs aber betrug 70 Seelen; Joseph aber war schon in Ägypten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'Hierauf starb Joseph und alle seine Brüder, sowie jenes ganze Geschlecht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'Und die Israeliten waren fruchtbar und nahmen überhand und wurden viel und überaus zahlreich, so daß das Land von ihnen voll war.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'Da trat ein neuer König in Ägypten auf, der Joseph nicht mehr gekannt hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'Der sprach zu seinen Unterthanen: Das Volk der Israeliten wird ja zahlreicher und mächtiger als wir.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'Wohlan, wir wollen klug gegen es verfahren, sonst könnte es allzu zahlreich werden und sich, falls wir in einen Krieg verwickelt werden, auch noch zu unseren Feinden schlagen, uns bekämpfen und aus dem Lande wegziehn!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'Da bestellten sie über es Fronvögte, um es zu drücken mit ihren Fronarbeiten, und es baute dem Pharao Vorratsstädte, Pithom und Ramses.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'Je mehr sie es aber drückten, desto mehr nahm es zu und breitete sich aus, so daß sie vor den Israeliten Angst bekamen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'Da zwangen die Ägypter die Israeliten zu harter Sklavenarbeit');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'und verbitterten ihnen das Leben mit harter Arbeit in Lehm und Ziegeln und allerlei Feldarbeiten, lauter Arbeiten, die sie mit Zwang durch sie ausführen ließen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'Der König von Ägypten aber befahl den Hebammen der Hebräer - die eine derselben hieß Sifra, die andere Pua:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, 'Wenn ihr die Hebräerinnen entbindet, so sollt ihr auf den Gebärstuhl sehen: wenn es ein Knäblein ist, so sollt ihr es ums Leben bringen; wenn es aber ein Mädchen ist, so mag es am Leben bleiben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'Die Hebammen jedoch waren gottesfürchtig und führten nicht aus, was der König von Ägypten ihnen geboten hatte, sondern ließen die Knäblein am Leben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'Da ließ der König von Ägypten die Hebammen rufen und fragte sie: Warum handelt ihr so und laßt die Knäblein am Leben?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'Die Hebammen antworteten dem Pharao: Ja, die Hebräerinnen sind nicht, wie die ägyptischen Weiber, sondern kräftig; ehe noch die Hebamme zu ihnen kommt, haben sie immer schon geboren.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'Gott aber ließ es den Hebammen gut ergehen, und das Volk wurde zahlreich und sehr stark.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'Und weil die Hebammen Gott fürchteten, verlieh er ihnen Kinderreichtum.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'Hierauf befahl der Pharao allen seinen Unterthanen: Alle Knäblein, die den Hebräern geboren werden, sollt ihr in den Nil werfen; alle Mädchen aber mögt ihr am Leben lassen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, 'Ein Mann aus dem Stamme Levis aber heiratete die Tochter Levis.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'Da wurde die Frau schwanger und gebar einen Sohn. Als sie nun sah, daß er stattlich war, verheimlichte sie ihn drei Monate lang.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'Als sie ihn aber nicht länger verbergen konnte, holte sie für ihn ein Kästchen aus Papyrusschilf, verpichte es mit Asphalt und Pech und setzte es, nachdem sie das Kind hineingelegt hatte, ins Schilf am Ufer des Nils.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'Seine Schwester aber paßte nicht weit davon auf, um zu erfahren, was mit ihm geschehen würde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'Da kam die Tochter des Pharao an den Nil, um zu baden. Während nun ihre Begleiterinnen am Ufer des Nils entlang gingen, erblickte sie zwischen dem Röhricht das Kästchen; da schickte sie ihre Sklavin hin und ließ es holen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'Als sie es nun öffnete, war ein weinender Knabe darin. Sie aber fühlte Mitleid mit ihm, denn sie dachte: es wird einer von den Knaben der Hebräer sein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'Da fragte seine Schwester die Tochter des Pharao: Soll ich etwa hingehn und dir eine Amme hebräischer Abkunft herbeirufen, damit sie dir das Knäblein säuge?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, 'Die Tochter des Pharao erwiderte: Ja, geh! Da ging das Mädchen hin und rief die Mutter des Knäbleins herbei.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'Und die Tochter des Pharao sprach zu ihr: Wenn du dieses Knäblein mitnimmst und es für mich säugst, so will ich dir den Lohn dafür bezahlen! Da nahm das Weib das Knäblein und säugte es.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'Als aber der Knabe herangewachsen war, brachte sie ihn der Tochter des Pharao, und sie nahm ihn als Sohn an und gab ihm den Namen Mose; denn sie sagte: Aus dem Wasser habe ich ihn ja gezogen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'Zu jener Zeit aber begab sich einst Mose, als er herangewachsen war, zu seinen Volksgenossen hinaus und sah, wie sie Frondienste leisten mußten; da bemerkte er, wie ein Ägypter einen Hebräer, einen seiner Volksgenossen, schlug.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'Da wandte er sich nach allen Seiten um, und wie er sah, daß niemand zugegen war, erschlug er den Ägypter und verscharrte ihn im Sande.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'Am folgenden Tag ging er wieder hinaus, da traf er zwei Hebräer im Streit miteinander. Da fragte er den, der im Unrecht war: Warum schlägst du deinen Genossen?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'Der aber sprach: Wer hat dich zum Herrn und Richter über uns bestellt? Gedenkst du mich etwa auch totzuschlagen, wie du den Ägypter totgeschlagen hast? Da bekam Mose Angst, denn er sagte sich: so ist also die Sache doch ruchbar geworden!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'Aber auch der Pharao hörte von der Sache; da trachtete er darnach, Mose umbringen zu lassen. Mose jedoch ergriff die Flucht vor dem Pharao und begab sich nach dem Lande der Midianiter. Dort setzte er sich an den Brunnen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'Der Priester der Midianiter aber hatte sieben Töchter; die kamen herbei und wollten Wasser schöpfen und die Tränkrinnen füllen, um die Schafe ihres Vaters zu tränken.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'Aber die Hirten kamen herzu und drängten sie auf die Seite. Da stand Mose auf, unterstützte sie und verschaffte ihren Schafen zu trinken.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'Als sie nun zu ihrem Vater Reguel kamen, fragte er sie: Warum kommt ihr denn heute so früh?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'Sie erwiderten: Ein Mann aus Ägypten hat uns vor den Hirten in Schutz genommen; dazu hat er uns sogar Wasser geschöpft und die Schafe getränkt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'Da sagte er zu seinen Töchtern: Wo ist er denn? Warum habt ihr den Mann dort stehen lassen? Ladet ihn doch ein zur Mahlzeit!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'Mose aber entschloß sich, bei dem Manne zu bleiben, und er gab Mose seine Tochter Zipora zum Weibe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'Die gebar einen Sohn, den nannte er Gersom; denn er sprach: Ein Fremdling bin ich geworden in einem fremden Lande.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, 'Da ereignete es sich lange Zeit hernach, daß der König von Ägypten starb. Da seufzten die Israeliten unter der schweren Arbeit und schrieen laut auf, so daß ihr Ruf um Befreiung von der schweren Arbeit zu Gott drang.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'Und Gott erhörte ihr Wehklagen und Gott gedachte an seinen Bund mit Abraham, Isaak und Jakob.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'Und Gott schaute auf die Israeliten und offenbarte sich ihnen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'Mose aber hütete bei Jethro, seinem Schwiegervater, dem Priester der Midianiter, die Schafe. Als er nun einst die Schafe bis jenseits der Steppe trieb, gelangte er zum Berge Gottes, dem Horeb.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'Da erschien ihm der Engel Jahwes in einer Feuerflamme, die aus einem Dornstrauch hervorschlug. Als er aber näher zusah, da brannte der Dornstrauch, ohne daß der Dornstrauch vom Feuer verzehrt wurde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'Da dachte Mose: Ich will doch hingehn und dieses merkwürdige Schauspiel betrachten, warum der Dornstrauch nicht in Feuer aufgeht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'Als nun Jahwe sah, daß er hinging, um es anzusehen, da rief ihn Gott aus dem Dornbusch heraus an: Mose, Mose! Er antwortete: Ich höre!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, 'Hierauf sprach er: Tritt nicht näher herzu! ziehe deine Sandalen aus; denn die Stätte, auf die du trittst, ist heiliger Boden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'Dann sprach er: Ich bin der Gott deines Vaters, der Gott Abrahams, der Gott Isaaks und der Gott Jakobs. Da verhüllte Mose sein Antlitz; denn er fürchtete sich, auf Gott hinzublicken.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'Jahwe aber sprach: Ich habe die Bedrückung meines Volks, das in Ägypten ist, zur Genüge angesehen und ihr Rufen um Befreiung von seinen Fronvögten gehört; ja ich weiß, wie sehr es leidet.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'Daher komme ich nun herab, es aus der Gewalt der Ägypter zu erretten und es wegzuführen aus jenem Land in ein treffliches und weit ausgedehntes Land, in ein Land, das von Milch und Honig überfließt, in die Wohnsitze der Kanaaniter, Hethiter, Amoriter, Pheresiter, Heviter und Jebusiter.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'Und nun ist der Hilferuf der Israeliten zu mir gedrungen, und ich habe wohl gesehen, wie sehr die Ägypter sie quälen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'So laß dich nun von mir zum Pharao senden und führe mein Volk, die Israeliten, aus Ägypten hinweg.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'Mose aber sprach zu Gott: Wer bin ich, daß ich zum Pharao gehen und daß ich die Israeliten aus Ägypten wegführen könnte?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'Da sprach er: Ich bin ja mit dir! Und dies soll für dich das Wahrzeichen sein, daß ich dich sende: wenn du das Volk aus Ägypten wegführst, werdet ihr Gott auf diesem Berge verehren.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'Und Mose sprach zu Gott: Wenn ich nun aber zu den Israeliten komme und ihnen sage: der Gott eurer Väter hat mich zu euch gesandt, und sie mich fragen: wie heißt er? was soll ich ihnen antworten?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'Da erwiderte Gott Mose: Der “Ich bin, der ich bin”; dann sprach er: So sollst du den Israeliten sagen: Der “Ich bin” hat mich zu euch gesandt!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'Hierauf sprach Gott weiter zu Mose: So sollst du zu den Israeliten sagen: Jahwe, der Gott eurer Väter, der Gott Abrahams, der Gott Isaaks und der Gott Jakobs hat mich zu euch gesandt; dies ist mein Name auf ewie Zeiten und dies meine Benennung auf Geschlecht und Geschlecht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, 'Geh hin, rufe die Vornehmsten der Israeliten zusammen und sage ihnen: Jahwe, der Gott eurer Väter, ist mir erschienen, der Gott Abrahams, Isaaks und Jakobs, und hat zugesagt: Ich will Rücksicht nehmen auf euch und auf das, was euch widerfahren ist in Ägypten;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'und ich habe beschlossen: ich will euch aus der Bedrückung in Ägypten befreien und in das Land der Kanaaniter, Hethiter, Amoriter, Pheresiter, Heviter und Jebusiter führen, in ein Land, das von Milch und Honig überfließt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'Und sie werden auf dich hören; dann sollst du mit den Vornehmsten der Israeliten zum Könige von Ägypten gehen, und ihr sollt zu ihm sprechen: Jahwe, der Gott der Hebräer, ist uns begegnet; laß uns daher drei Tagereisen weit in die Steppe ziehen, um Jahwe, unserem Gott, Opfer zu bringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'Aber ich weiß, daß der König von Ägypten euch nicht gestatten wird, wegzuziehen, wenn nicht durch Zwang.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'Dann will ich meine Hand ausrecken und die Ägypter mit allen meinen Wunderthaten, die ich an ihnen verrichten werde, heimsuchen; hernach werden sie euch ziehen lassen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'Auch werde ich diesem Volke bei den Ägyptern Ansehen verschaffen, damit, wenn ihr wegzieht, ihr nicht mit leeren Händen wegzieht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'Sondern jedes Weib soll von ihrer Nachbarin und Hausgenossin verlangen, daß sie ihr silberne und goldene Geräte und Kleider leihe; die sollt ihr euren Söhnen und Töchtern anlegen und sollt so die Ägypter um ihr Eigentum bringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'Mose aber entgegnete: Wenn sie mir nun aber nicht glauben und mir nicht folgen wollen, sondern sagen: Jahwe ist dir nicht erschienen?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'Da sprach Jahwe zu ihm: Was hast du da in der Hand? Er antwortete: Einen Stab.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'Da befahl er: Wirf ihn hin auf den Boden! Als er ihn nun auf den Boden warf, verwandelte er sich in eine Schlange, und Mose ergriff vor ihr die Flucht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'Da befahl Jahwe Mose: Strecke deine Hand aus und ergreife sie beim Schwanze! Da streckte er seine Hand aus und faßte sie fest an; da verwandelte sie sich in seiner Hand in einen Stab.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, 'So müssen sie es glauben, daß dir Jahwe, der Gott ihrer Väter, der Gott Abrahams, der Gott Isaaks und der Gott Jakobs, erschienen ist.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'Hierauf befahl ihm Jahwe nochmals: Stecke deine Hand in deine Busentasche! Da steckte er seine Hand in die Busentasche. Als er sie aber wieder herauszog, war sie unversehens aussätzig und schneeweiß geworden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'Hierauf befahl er: Stecke deine Hand nochmals in die Busentasche. Da stecke er seine Hand in die Busentasche; als er sie aber wieder herauszog, war sie unversehens seinem Fleische wieder gleich geworden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, 'Und wenn sie dir nicht glauben und auf das erste Wunderzeichen hin nicht folgen, so werden sie auf das zweite Wunderzeichen hin glauben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, 'Wenn sie aber auch auf diese beiden Wunderzeichen hin nicht glauben und dir nicht folgen wollen, so sollst du etwas Wasser aus dem Nil schöpfen und es auf den Boden gießen; dann soll sich das Wasser, das du aus dem Nile schöpfest, auf dem Boden in Blut verwandeln.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, 'Da sprach Mose zu Jahwe: Mit Verlaub, Herr! Ich bin kein Mann, der reden kann, sondern meine Sprache und meine Zunge sind schwerfällig.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'Jahwe aber antwortete ihm: Wer hat denn dem Menschen den Mund erschaffen? oder wer macht einen stumm oder taub oder sehend oder blind? Bin nicht ich es, Jahwe?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'Geh also nur! Ich werde dir helfen zu reden und dich unterweisen, was du sagen sollst.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, 'Er aber sprach: Bitte, Herr! sende doch lieber irgend einen andern!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'Da wurde Jahwe zornig über Mose und sprach: Ist denn nicht Aaron, dein Bruder, der Levit, da? Von dem weiß ich, daß er gar wohl reden kann. Zudem wird er dir entgegen kommen und eine große Freude haben, wenn er dich erblickt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'Dann magst du mit ihm sprechen und ihm die Reden überweisen; ich aber werde sowohl dir, als ihm, helfen zu reden und euch unterweisen, was ihr zu thun habt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'So soll er dann für dich zum Volke reden und dein Mund sein; du aber sollst für ihn gleichsam Gott sein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'Und den Stab da nimm in die Hand; damit sollst du die Wunderzeichen verrichten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, 'Hierauf kehrte Mose zu seinem Schwiegervater Jethro zurück und sprach zu ihm: Ich möchte aufbrechen und zu meinen Verwandten in Ägypten zurückkehren, um zu sehen, ob sie noch am Leben sind. Jethro antwortete Mose: Ziehe hin, möge es dir wohlgehen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'Und Jahwe sprach zu Mose in Midian: Auf! kehre nach Ägpyten zurück; denn alle die, die dir nach dem Leben trachteten, sind gestorben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'Da ließ Mose sein Weib und seine Söhne auf einen Esel sitzen und brach auf nach Ägypten; den Stab Gottes aber nahm Mose in die Hand.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'Hierauf sprach Jahwe zu Mose: Wenn du nach Ägypten zurückkehrst, so habe acht: alle die Wunderthaten, die ich in deine Macht lege, sollst du vor dem Pharao ausführen; ich aber werde seinen Sinn verhärten, so daß er das Volk nicht wird ziehen lassen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'Du aber sollst zum Pharao sagen: So spricht Jahwe: Mein erstgeborener Sohn ist Israel.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'Ich befehle dir hiermit: Laß meinen Sohn ziehen, damit er mich verehre; wenn du dich aber weigerst, ihn ziehen zu lassen, so werde ich deinen erstgeborenen Sohn sterben lassen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'Unterwegs aber in einer Herberge überfiel ihn Jahwe und suchte ihm das Leben zu nehmen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'Da nahm Zipora einen scharfen Stein, schnitt damit die Vorhaut ihres Sohnes ab und berührte damit seine Scham, indem sie sprach: Ein Blutbräutigam bist du mir!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'Da ließ er von ihm ab. Damals sprach sie Blutbräutigam zu den Beschneidungen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, 'Da befahl Jahwe Aaron: Geh Mose entgegen in die Steppe! Der ging hin und begegnete ihm am Berge Gottes; da küßte er ihn.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'Und Mose berichtete Aaron alle Reden Jahwes, mit denen er ihn beauftragt, und alle Wunderzeichen, die er ihm anbefohlen hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, 'Hierauf gingen Mose und Aaron hin und riefen alle Vornehmen der Israeliten zusammen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'Und Aaron verkündete alle die Aufträge, die Jahwe Mose gegeben hatte, und dieser verrichtete die Wunderzeichen vor den Augen des Volks.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'Da glaubte das Volk daran, als sie vernahmen, daß Jahwe sich der Israeliten angenommen und ihre Bedrückung beachtet habe, und sie verneigten sich und warfen sich zu Boden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'Hernach gingen Mose und Aaron hin und sprachen zum Pharao: So befiehlt Jahwe, der Gott Israels: Laß mein Volk ziehen, damit sie mir in der Steppe ein Fest feiern!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'Der Pharao aber erwiderte: Wer ist Jahwe, daß ich ihm gehorchen und Israel ziehen lassen sollte? Ich weiß nichts von Jahwe und werde Israel auch nicht ziehen lassen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, 'Sie sprachen: Der Gott der Hebräer ist uns begegnet; laß uns also drei Tagereisen weit in die Steppe ziehen, um Jahwe, unserem Gott, Opfer zu bringen; sonst sucht er uns heim mit Pest oder Schwert.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'Der König von Ägypten aber erwiderte ihnen: Warum, Mose und Aaron, wollt ihr das Volk von seiner Arbeit abziehn? Geht an eure Frondienste!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'Und der Pharao sprach: Es ist des Volkes wahrlich schon so genug im Land, und da wollt ihr noch, daß es aufhört, Frondienste zu verrichten?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'An eben demselben Tage gab der Pharao den Fronvögten, die über das Volk gesetzt waren, und seinen Aufsehern folgenden Befehl:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, 'Ihr sollt nicht mehr, wie bisher, dem Volk Häckerling liefern zur Verfertigung der Backsteine, sondern sie selbst sollen hingehen und sich Häckerling suchen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'Aber die festgesetzte Zahl von Backsteinen, die sie bisher verfertigten, sollt ihr ihnen auferlegen und nichts davon ablassen. Denn sie gehen müßig; deshalb verlangen sie ungestüm: Wir wollen hingehen, um unserem Gott Opfer zu bringen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'Die Arbeit muß den Leuten erschwert werden, so daß sie daran zu thun haben und nicht auf Vorspiegelungen achten!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'Da gingen die Fronvögte und Aufseher des Volkes hin und berichteten dem Volke: So hat der Pharao angeordnet: Ich lasse euch keinen Häckerling mehr liefern.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'Ihr selbst müßt hingehen, euch Häckerling zu suchen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, 'Die Fronvögte aber setzten ihnen hart zu und befahlen: Ihr müßt Tag für Tag die volle Arbeit liefern, wie zu der Zeit, wo Häckerling da war.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'Den Aufsehern der Israeliten aber, welche die Fronvögte des Pharao ihnen als Vorgesetzte gegeben hatten, ließ man Schläge geben und fragte sie: Warum habt ihr den Betrag an Backsteinen, der euch bisher auferlegt war, in den letzten Tagen nicht voll geliefert?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'Da gingen die Aufseher der Israeliten hin und beklagten sich flehentlich beim Pharao, indem sie sprachen: O Herr! Warum lässest du uns so behandeln?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, 'Häckerling wird uns nicht mehr geliefert, und dennoch heißt es: Schafft Ziegel! Nun werden wir gar noch geschlagen! Du versündigst dich an deinem Volk.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'Er aber erwiderte: Faul seid ihr, faul! Deswegen sagt ihr: Wir wollen hingehen, um Jahwe Opfer zu bringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, 'Geht sofort an eure Arbeit; Häckerling wird euch nicht geliefert, aber den vollen Betrag an Backsteinen müßt ihr liefern!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'So fanden sich die Aufseher der Israeliten in der schlimmen Lage, sagen zu müssen: Ihr bekommt von eurem täglichen Betrag an Backsteinen nichts erlassen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, 'Als sie nun den Pharao verließen, trafen sie auf Mose und Aaron, die dort standen, um ihnen zu begegnen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'und sagten zu ihnen: Jahwe strafe euch und helfe uns zum Recht, daß ihr uns beim Pharao und seinen Höflingen in schwere Ungnade gebracht, ja ihnen das Schwert in die Hand gedrückt habt, um uns das Leben zu nehmen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, 'Da wandte sich Mose wieder an Jahwe zu sprach: O Herr! Warum lässest du diesem Volke solches Unheil widerfahren? Wozu hast du mich denn gesandt?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'Denn seitdem ich zum Pharao gegangen bin, um in deinem Namen zu reden, behandelt er dieses Volk nur noch härter, und du hast dein Volk keineswegs errettet!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, '');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'Jahwe aber erwiderte Mose: Nun sollst du sehen, was ich dem Pharao anthun werde: von starker Hand gezwungen wird er sie ziehen lassen und von starker Hand gezwungen wird er sie aus seinem Lande treiben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'Da redete Gott mit Mose und sprach zu ihm: Ich bin Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'Ich bin einst als Gott, der Allmächtige, Abraham, Isaak und Jakob erschienen; aber unter meinem Namen Jahwe habe ich mich ihnen nicht offenbart.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'Und ich habe mit ihnen sogar auch ein Abkommen getroffen, daß ich ihnen das Land Kanaan, das Land, in dem sie als Fremdlinge weilten, zu eigen geben wolle.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'Nun aber habe ich das Wehklagen der Israeliten über die Knechtung, die ihnen von den Ägyptern widerfährt, erhört und gedachte an meine Zusage.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'Sage daher den Israeliten: Ich bin Jahwe; ich will euch erlösen von dem Frondienste, den ihr den Ägyptern leistet, und euch herausreißen aus eurer Sklavenarbeit und euch befreien mit ausgerecktem Arm und mit großartigen Machterweisen');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'und will euch zu meinem Volk erwählen und will euer Gott sein, und ihr sollt erkennen, daß ich Jahwe, euer Gott, bin, der euch erlöst von dem Frondienst in Ägypten,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'und ich will euch in das Land bringen, das ich geschworen habe, Abraham, Isaak und Jakob zu verleihen, und will es euch zum Besitz geben, ich, Jahwe!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'Mose richtete dies den Israeliten aus; sie aber hörten nicht auf Mose, aus Kleinmut und weil sie so hart zu arbeiten hatten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, 'Hierauf sprach Jahwe zu Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, 'Geh hin und fordere den Pharao, den König von Ägypten, auf, er solle die Israeliten aus seinem Lande wegziehen lassen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'Mose aber redete vor Jahwe also: Haben die Israeliten nicht auf mich gehört, wie sollte denn der Pharao auf mich hören, zumal ich unbeholfen bin im Reden!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'Da redete Jahwe mit Mose und Aaron und ordnete sie ab an die Israeliten und an den Pharao, den König von Ägypten, um die Israeliten aus Ägypten wegzuführen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'Dies sind die Familienhäupter ihrer Stammväter: Die Söhne Rubens, des Erstgeborenen Israels, waren Hanoch, Pallu, Hezron und Charmi; dies sind die Geschlechter Rubens;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'Und die Söhne Simeons: Jemuel, Jamin, Ohad, Jachin, Zohar und Saul, der Sohn der Kanaaniterin; dies sind die Geschlechter Simeons.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'Und so hießen die Söhne Levis nach ihrem Stammbaum: Gerson, Kahath, Merari. Levi aber wurde 137 Jahre alt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'Die Söhne Gersons waren Libni und Simei nach ihren Geschlechtern.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'Und die Söhne Kahaths waren Amram, Jezear, Hebron und Usiel. Kahath aber wurde 133 Jahre alt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'Und die Söhne Meraris waren Maheli und Musi; dies sind die Geschlechter Levis nach ihrem Stammbaum.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'Amram aber heiratete Jochebed, seine Muhme; die gebar ihm Aaron und Mose. Und Amram wurde 137 Jahre alt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'Und die Söhne Jezears waren Korah und Nepheg und Sichri,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'und die Söhne Usiels: Misael, Elzaphan und Sithri.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'Aaron aber heiratete Eliseba, die Tochter Amminadabs, die Schwester Nahassons; die gebar ihm Nadab und Abihu, Eleasar und Ithamar.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'Und die Söhne Korahs waren Assir, Elkana und Abiasaph; dies sind die Geschlechter der Korahiter.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'Eleasar aber, der Sohn Aarons, heiratete eine der Töchter Putiels, die gebar ihm Pinehas; das sind die Stammhäupter der Leviten nach ihren Geschlechtern.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'Das waren Aaron und Mose, denen Jahwe befahl: Führt die Scharen der Israeliten aus Ägypten hinweg!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'Das waren die, welche dem Pharao, dem Könige von Ägypten ankündigten, daß sie die Israeliten aus Ägypten wegführen würden - Mose und Aaron.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'Als nun Jahwe mit Mose in Ägypten redete,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'da sprach Jahwe zu Mose also: Ich bin Jahwe! Richte dem Pharao, dem Könige von Ägypten, alles aus, was ich dir sagen werde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'Mose aber sprach vor Jahwe: Ich bin ja unbeholfen im Reden; wie wird der Pharao auf mich hören?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'Jahwe aber erwiderte Mose: Ich will dich für den Pharao wie zu einem Gotte machen; dein Bruder Aaron aber soll dein Sprecher sein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'Du sollst alles, was ich dir sage, weiter berichten; dein Bruder Aaron aber soll es dem Pharao vortragen, damit er die Israeliten aus seinem Lande wegziehen läßt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'Ich aber will den Sinn des Pharao verhärten und will zahlreiche Zeichen und Wunderthaten in Ägypten verrichten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'Der Pharao jedoch wird euch kein Gehör geben; dann will ich Hand anlegen an die Ägypter und meine Heerescharen, mein Volk, die Israeliten, unter großartigen Machtbeweisen aus Ägypten hinwegführen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'Dann sollen die Ägypter erkennen, daß ich Jahwe bin, wenn ich die Ägypter meine Macht fühlen lasse und die Israeliten aus ihrer Mitte hinwegführe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'Da thaten Mose und Aaron, wie ihnen Jahwe befohlen hatte; also thaten sie.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'Mose aber war achtzig Jahre und Aaron dreiundachtzig Jahre alt, als sie mit dem Pharao verhandelten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'Hierauf sprach Jahwe zu Mose und Aaron also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, 'Wenn euch der Pharao auffordert: verrichtet ein Wunder! so sollst du Aaron gebieten: Auf, wirf deinen Stab vor den Pharao hin, so wird er sich in eine große Schlange verwandeln.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, 'Da begaben sich Mose und Aaron zum Pharao hinein und thaten so, wie Jahwe geboten hatte: Aaron warf seinen Stab vor dem Pharao und seinen Höflingen hin, da verwandelte er sich in eine große Schlange.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'Der Pharao aber ließ die Gelehrten und Zaubereikundigen rufen; da machten sie, die Zauberer von Ägypten, mittels ihrer Geheimkünste es ebenso:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'ein jeder warf seinen Stab hin, da verwandelten sich diese in große Schlangen; jedoch der Stab Aarons verschlang ihre Stäbe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, 'Aber der Sinn des Pharao blieb verhärtet, und er willfahrte ihnen nicht, wie Jahwe vorausgesagt hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'Hierauf sprach Jahwe zu Mose: Der Sinn des Pharao ist verstockt; er weigert sich, das Volk ziehen zu lassen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'Begieb dich morgen früh zum Pharao und tritt ihm, wenn er hingeht ans Wasser, am Ufer des Nils entgegen mit dem Stabe, der sich in eine Schlange verwandelt hat, in der Hand,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'und sprich zu ihm: Jahwe, der Gott der Hebräer, hat mich zu dir gesandt, um dich aufzufordern: laß mein Volk ziehen, damit sie mich in der Steppe verehren. Aber du hast bis jetzt nicht gehorcht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'So spricht Jahwe: Daran sollst du erkennen, daß ich Jahwe bin: ich werde mit dem Stabe, den ich in der Hand habe, ins Wasser des Nils schlagen, so soll es sich in Blut verwandeln.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'Die Fische aber die im Nile sind, sollen umkommen, und der Nil soll stinken, so daß es die Ägypter ekeln wird, Wasser aus dem Nile zu trinken.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'Da sprach Jahwe zu Mose: Befiehl Aaron: Nimm deinen Stab und recke deine Hand aus über die Gewässer Ägyptens, über seine Bäche, Kanäle, Teiche und alle Behälter mit Wasser: es soll zu Blut werden, und Blut soll entstehen in ganz Ägypten, sowohl in hölzernen als in steinernen Gefäßen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'Da thaten Mose und Aaron so, wie ihnen Jahwe geboten hatte. Und er hob den Stab und schlug damit das Wasser im Nil vor den Augen des Pharao und seiner Höflinge: da verwandelte sich alles Wasser, das im Nil war, in Blut.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'Und die Fische im Nil kamen um und der Nil wurde stinkend, so daß die Ägypter kein Wasser aus dem Nile mehr trinken konnten. Da entstand Blut überall in Ägypten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'Die Zauberer Ägyptens aber brachten mittels ihrer Geheimkünste dasselbe zustande. Da blieb der Sinn des Pharao verhärtet, und er willfahrte ihnen nicht, wie Jahwe vorausgesagt hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'Da wandte sich der Pharao ab und begab sich nach Hause, ohne daß er selbst dies zu Herzen nahm.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'Die Ägypter aber gruben insgesamt in der Umgebung des Nils nach Wasser, um es zu trinken, denn sie konnten das Wasser des Nils nicht trinken.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'Und die Plage, welche Jahwe mit dem Nil eintreten ließ, währte sieben volle Tage.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 26, 'Hierauf befahl Jahwe Mose: Begieb dich zum Pharao und kündige ihm an: So spricht Jahwe: Laß mein Volk ziehen, damit es mich verehre!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 27, 'Wenn du dich aber weigerst, es ziehen zu lassen, so werde ich über dein ganzes Land eine Froschplage bringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 28, 'Und im Nile soll\'s wimmeln von Fröschen, und sie sollen herauskommen und bis in deinen Palast und in dein Schlafgemach und auf dein Ruhelager dringen, sowie in die Wohnungen deiner Höflinge und deiner Unterthanen, auch in deine Backöfen und deine Teigmulden,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 29, 'ja an dich selbst, deine Unterthanen und alle deine Höflinge sollen die Frösche herankriechen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'Und Jahwe sprach zu Mose: Gebiete Aaron: Recke deine Hand nebst dem Stabe aus über die Bäche, die Kanäle und Teiche und führe Frösche herbei über Ägypten!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'Da reckte Aaron seine Hand aus über die Gewässer Ägyptens und führte Frösche herbei, so daß sie Ägypten bedeckten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'Aber auch die Zauberer brachten dies mittels ihrer Geheimkünste zustande, und führten Frösche herbei über ganz Ägypten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'Da ließ der Pharao Mose und Aaron rufen und bat: Legt bei Jahwe Fürbitte ein, daß er mich und mein Volk von den Fröschen befreie; so will ich das Volk ziehen lassen, damit sie Jahwe Opfer bringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'Mose erwiderte dem Pharao: Beliebe zu bestimmen, auf wann ich für dich, deine Höflinge und Unterthanen Fürbitte einlegen soll, daß du und deine Paläste von den Fröschen befreit werden, und nur im Nile noch welche übrig bleiben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, 'Er antwortete: Morgen! Da sprach er: Wie du es wünschtest, damit du erfahrest, daß es keinen giebt, wie Jahwe unsern Gott.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'Du und deine Paläste, deine Höflinge und Unterthanen sollen von den Fröschen befreit werden; nur im Nile sollen welche übrig bleiben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'Als nun Mose und Aaron den Pharao verlassen hatten, da betete Mose inständig zu Jahwe in betreff der Frösche, mit denen er den Pharao heimgesucht hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'Jahwe aber that, wie Mose erbeten hatte: da starben die Frösche, die in den Häusern, Höfen und auf den Feldern waren, hinweg,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, 'und man schüttete sie auf zahllose Haufen zusammen; im ganzen Land aber gab es üblen Geruch.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'Als jedoch der Pharao merkte, daß er Luft bekommen hatte, wurde er wieder verstockt und willfahrte ihnen nicht, wie Jahwe vorausgesagt hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'Hierauf sprach Jahwe zu Mose: Befiehl Aaron: Strecke deinen Stab aus und schlage damit den Staub auf dem Boden, so soll er sich in Stechmücken verwandeln überall in Ägypten!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'Und sie thaten so: Aaron reckte seine Hand nebst dem Stabe aus und schlug damit den Staub auf dem Boden. Da kamen Stechmücken an die Menschen und an das Vieh; aller Staub auf dem Boden wurde zu Stechmücken in ganz Ägypten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'Da suchten die Zauberer mittels ihrer Geheimkünste ebenso Stechmücken hervorzubringen; aber sie waren es nicht imstande. Die Stechmücken aber kamen an Menschen und Vieh.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, 'Da sprachen die Zauberer zum Pharao: Das ist Gottes Finger! Aber der Sinn des Pharao blieb verstockt, und er willfahrte ihnen nicht, wie Jahwe vorausgesagt hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'Hierauf befahl Jahwe Mose: Tritt morgen früh vor den Pharao, wenn er ans Wasser geht, und sprich zu ihm: So gebietet Jahwe: Laß mein Volk ziehen, damit es mich verehre!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, 'Denn wenn du mein Volk nicht ziehen lässest, so will ich über dich, deine Höflinge, deine Unterthanen und deine Paläste Hundsfliegen kommen lassen; die Wohnungen der Ägypter sollen voll von Hundsfliegen sein, ja selbst der Boden, auf dem sie stehen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, 'Mit dem Lande Gosen aber, in welchem mein Volk sich aufhält, werde ich eine Ausnahme machen, so daß sich dort keine Hundsfliegen zeigen sollen, damit du erkennest, daß ich Herr bin auf Erden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'Und ich will einen Unterschied machen zwischen meinem und deinem Volk; morgen soll dieses Wunder geschehen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'Und Jahwe that so; da drang ein großer Schwarm von Hundsfliegen in den Palast des Pharao und die Wohnungen seiner Höflinge in ganz Ägypten, und das Land litt schwer unter den Hundsfliegen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'Da ließ der Pharao Mose und Aaron rufen und sprach zu ihnen: Wohlan! bringt doch euerem Gott hier im Lande Opfer!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'Mose aber erwiderte: es geht nicht an, daß wir so thun; denn wir bringen Jahwe, unserem Gott, Opfer, die den Ägyptern ein Greuel sind. Wenn wir nun vor der Ägypter Augen Opfer bringen wollten, die ihnen ein Greuel sind, werden sie uns da nicht steinigen?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'Wir wollen drei Tagereisen weit in die Steppe ziehen und dort Jahwe, unserem Gott, ein Opfer bringen, wie er es uns geboten hat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, 'Der Pharao aber sprach: Ich will euch ziehen lassen, damit ihr Jahwe, euerem Gott, in der Steppe opfern könnt; nur entfernt euch nicht allzuweit! Legt Fürbitte für mich ein!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'Mose erwiderte: O König! Sobald ich draußen bin, werde ich bei Jahwe Fürbitte einlegen, daß morgen die Hundsfliegen von dir, deinen Höflingen und Unterthanen weichen sollen; nur halte das Volk nicht abermals zum besten, indem du es doch nicht ziehen lässest, um Jahwe Opfer zu bringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'Hierauf verließ Mose den Pharao; sodann legte er Fürbitte bei Jahwe ein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'Jahwe aber that, wie Mose erbeten hatte, und erlöste den Pharao, sowie seine Höflinge und Unterthanen von den Hundsfliegen, so daß auch nicht eine übrig blieb.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'Der Sinn des Pharao wurde jedoch auch diesmal wieder verstockt, und er ließ das Volk nicht ziehen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'Hierauf befahl Jahwe Mose: Begieb dich zum Pharao und kündige ihm an: So spricht Jahwe, der Gott der Hebräer: Laß mein Volk ziehen, damit es mich verehre!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'Denn wenn du dich weigerst, sie ziehen zu lassen, und sie noch ferner zurückhältst,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'so wird Jahwes Hand über dein Vieh auf dem Felde, die Pferde, Esel, Kamele, Rinder und Schafe kommen in Gestalt einer sehr schweren Pest.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'Jahwe aber wird zwischen dem Vieh der Israeliten und dem der Ägypter einen Unterschied machen: von allem, das den Israeliten gehört, soll kein Stück fallen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'Hierauf bestimmte Jahwe eine Frist, indem er sprach: Morgen wird Jahwe dies über das Land bringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'Am folgenden Tage ließ Jahwe dies eintreten. Da fiel alles Vieh der Ägypter; aber von dem Vieh der Israeliten fiel nicht ein einziges Stück.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'Der Pharao aber sandte Boten aus; da ergab sich, daß von dem Vieh der Israeliten auch nicht ein Stück gefallen war. Hierauf wurde der Sinn des Pharao wieder verstockt, und er ließ das Volk nicht ziehen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'Hierauf befahl Jahwe Mose und Aaron: Nehmt euch beide Hände voll Ofenruß, und Mose soll ihn vor den Augen des Pharao emporstreuen;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'so soll er dann als eine feine Staubwolke auf ganz Ägypten fallen und sowohl an den Menschen als an den Tieren in ganz Ägypten zu Geschwüren werden, die in Blattern ausbrechen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'Da nahmen sie den Ofenruß und traten vor den Pharao; dort streute ihn Mose empor, und es entstanden aufbrechende Geschwüre mit Pusteln, an den Menschen sowohl, wie an den Tieren.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'Die Zauberer aber waren nicht imstande, Mose die Spitze zu bieten, infolge der Geschwüre; denn die Geschwüre brachen an den Zauberern aus, wie an allen Ägyptern.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'Jahwe aber machte den Sinn des Pharao verstockt, und er willfahrte ihnen nicht, wie Jahwe Mose vorausgesagt hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, 'Hierauf befahl Jahwe Mose: Tritt morgen früh vor den Pharao und kündige ihm an: So spricht Jahwe, der Gott der Hebräer: Laß mein Volk ziehen, damit es mich verehre!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'Denn diesmal will ich alle meine Plagen dich selbst, deine Höflinge und Unterthanen fühlen lassen, damit du erkennest, daß es keinen giebt, wie ich, auf der ganzen Erde!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'Eben hätte ich meine Hand ausrecken und dich und deine Unterthanen mit der Pest zu Grunde richten können, so daß du weggefegt worden wärest vom Erdboden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'Aber ich habe dich nur deswegen verschont, damit ich dir meine Macht zu fühlen gebe, und mein Name auf der ganzen Erde gepriesen werde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, 'Noch stemmst du dich dagegen, mein Volk ziehen zu lassen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'Ich werde aber morgen um diese Zeit einen sehr schweren Hagelschlag herniederfallen lassen, dessengleichen in Ägypten nicht dagewesen ist, seitdem es erschaffen wurde, bis jetzt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'Schicke daher hin und laß dein Vieh und alles, was du draußen im Freien hast, in Sicherheit bringen; denn alle Menschen und Tiere, die sich im Freien befinden und nicht in ihre Behausungen zurückziehen werden, die wird der Hagel tot schlagen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'Wer sich nun von den Höflingen des Pharao vor der Drohung Jahwes fürchtete, der ließ seine Sklaven und sein Vieh in die Wohnungen flüchten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'Wer aber die Drohung Jahwes unbeachtet ließ, der ließ seine Sklaven und sein Vieh im Freien.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'Da befahl Jahwe Mose: Recke deine Hand gen Himmel empor; so soll Hagel fallen auf ganz Ägypten, sowohl auf die Menschen, als auf die Tiere und auf alle Feldgewächse in Ägypten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'Da reckte Mose seinen Stab gen Himmel empor, und Jahwe ließ Donner und Hagel entstehen und Feuer fuhr hernieder; und Jahwe ließ Hagel fallen auf Ägypten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'Und es fiel ein sehr starker Hagel und unaufhörliches Feuer unter dem Hagel, wie seinesgleichen nie gefallen war in Ägypten, seitdem es von Menschen bewohnt war.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'Und der Hagel erschlug in ganz Ägypten alles, was im Freien war, sowohl Menschen als Tier, und alle Feldgewächse zerschlug der Hagel und alle Bäume auf dem Felde knickte er.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'Bloß in der Provinz Gosen, woselbst die Israeliten wohnten, fiel kein Hagel.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, 'Da sandte der Pharao Boten, ließ Mose und Aaron rufen und sprach zu ihnen: Ich habe diesmal gefehlt; Jahwe ist im Recht und ich und meine Unterthanen sind im Unrecht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'Legt bei Jahwe Fürbitte ein - es ist mehr als genug an den Donnerschlägen und dem Hagel -, so will ich euch ziehen lassen und ihr sollt nicht länger hier verweilen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, 'Mose antwortete ihm: Wenn ich zur Stadt hinausgehe, will ich meine Hände zu Jahwe ausbreiten; so sollen die Donnerschläge aufhören und der Hagel nicht mehr fallen, damit du erkennst, daß Jahwe die Erde gehört.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'Aber du und deine Höflinge, ich weiß es, fürchtet euch noch nicht vor dem Gott Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, 'Der Flachs aber und die Gerste wurden vernichtet; denn die Gerste stand in Ähren und der Flachs hatte Knospen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'Der Weizen jedoch und der Spelt wurden nicht vernichtet; denn sie kommen später.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'Hierauf verließ Mose den Pharao und ging zur Stadt hinaus; da breitete er seine Hände zu Jahwe aus, und alsbald hörten die Donnerschläge und der Hagel auf, und es strömte kein Regen mehr hernieder.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'Als jedoch der Pharao merkte, daß der Regen, der Hagel und die Donnerschläge aufgehört hatten, verging er sich weiter und wurde verstockt, er und seine Höflinge.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'Aber der Sinn des Pharao blieb verhärtet, und er ließ die Israeliten nicht ziehen, wie Jahwe durch Mose vorausgesagt hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'Hierauf befahl Jahwe Mose: Begieb dich zum Pharao, denn ich habe seinen und seiner Höflinge Sinn verstockt, um diese meine Wunderthaten an ihm zu verrichten,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'und damit du deinem Sohne und Enkel erzählst, was ich den Ägyptern angethan habe, und meine Wunderthaten, die ich an ihnen verrichtet habe, damit ihr erkennet, daß ich Jahwe bin.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'Da begaben sich Mose und Aaron zum Pharao und sprachen zu ihm: So spricht Jahwe, der Gott der Hebräer: Wie lange willst du dich noch weigern, dich vor mir zu demütigen? Laß mein Volk ziehen, damit es mich verehre!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'Denn wenn du dich weigerst, mein Volk ziehen zu lassen, so will ich morgen Heuschrecken in dein Land einfallen lassen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'und sie sollen das ganze Land bedecken, so daß man den Boden nicht mehr sehen kann; sie werden den Rest, der gerettet ward und von dem Hagel euch noch übrig gelassen ist, fressen und werden alle eure Bäume, die draußen sprießen, abfressen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'Und sie werden scharenweise in deine Gemächer, die Gemächer aller deiner Höflinge und die Gemächer aller Ägypter dringen, wie es deine Ahnen und Urahnen, seit sie auf Erden sind, bisher nie erlebt haben. Hierauf kehrte er dem Pharao den Rücken und ging hinweg.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, 'Da sprachen die Höflinge des Pharao zu ihm: Wie lange noch soll uns dieser da zum Fallstrick dienen? Laß doch die Leute ziehen, damit sie ihren Gott Jahwe verehren. Siehst du denn noch nicht ein, daß Ägypten zu Grunde geht?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'Hierauf holte man Mose und Aaron zum Pharao zurück, und er sprach zu ihnen: Geht hin und verehrt eueren Gott Jahwe! Wer sind den eigentlich die, welche hingehen sollen?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, 'Mose erwiderte: Unsere Kinder und unsere Greise wollen wir mitnehmen, unsere Söhne und unsere Töchter, unsere Schafe und unsere Rinder wollen wir mitnehmen; denn wir haben Jahwe ein Fest zu feiern.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'Da erwiderte er ihnen: Nun wohl! Jahwe sei mit euch, wenn ich euch mit eueren kleinen Kindern zusammen ziehen lasse; wahrlich, ihr habt Böses im Sinne.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'Daraus wird nichts; die Männer dürfen hingehen und Jahwe verehren, denn dies wolltet ihr ja! Hierauf jagte man sie vom Pharao hinweg.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, 'Da befahl Jahwe Mose: Recke deine Hand aus über Ägypten und führe Heuschrecken herbei, und sie sollen über Ägypten heraufziehen und alle Bodengewächse, alles, was der Hagel übrig gelassen hat, abfressen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'Da reckte Mose seinen Stab aus über Ägypten, und Jahwe ließ einen Ostwind gegen das Land hin wehen den ganzen Tag und die ganze folgende Nacht hindurch; als es Morgen wurde, hatte der Ostwind die Heuschrecken herbeigetragen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'Da zogen die Heuschrecken herauf über ganz Ägypten und ließen sich nieder an allen Orten in Ägypten in ungeheuerer Menge; vorher war nie ein solcher Heuschreckenschwarm dagewesen, und es wird auch nie wieder einen solchen geben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'Und sie bedeckten das ganze Land, so daß der Boden nicht mehr sichtbar war; und sie fraßen alle Gewächse auf dem Feld und alle Baumfrüchte, welche der Hagel übrig gelassen hatte, so daß gar nichts Grünes übrig blieb an den Bäumen und an den Feldgewächsen in ganz Ägypten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, 'Da ließ der Pharao eiligst Mose und Aaron rufen und sprach: Ich habe gefehlt gegen Jahwe, eueren Gott, und gegen euch.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'Aber verzeih mir meinen Fehltritt nur dies eine Mal noch, und legt bei Jahwe, euerem Gotte, Fürbitte ein, daß er wenigstens diese schreckliche Plage von mir abwende!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'Da verließ er den Pharao und flehte zu Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'Jahwe aber ließ einen sehr starken Westwind als Gegenwind wehen; der nahm den Heuschreckenschwarm mit und warf ihn ins Schilfmeer: keine einzige Heuschrecke blieb übrig im ganzen Bereiche von Ägypten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'Aber Jahwe verstockte den Sinn des Pharao, und er ließ die Israeliten nicht ziehen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, 'Hierauf gebot Jahwe Mose: Recke deine Hand gen Himmel empor, so soll Finsternis über Ägypten kommen, so daß man die Finsternis wird greifen können.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'Und Mose reckte seine Hand gen Himmel empor, da kam dichte Finsternis über ganz Ägypten - drei Tage lang.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'Keiner konnte den anderen sehen, niemand von seinem Platze weggehen, drei Tage hindurch; die Israeliten aber hatten alle Licht in ihren Wohnungen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, 'Da ließ der Pharao Mose rufen und sprach: Geht hin, Jahwe einen Gottesdienst zu halten! Euere Schafe und Rinder jedoch müssen zurückbleiben; euere kleinen Kinder dürfen mitgehen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, 'Mose erwiderte: Du selbst mußt uns Schlacht- und Brandopfertiere mitgeben, damit wir sie für Jahwe, unseren Gott, zurichten;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, 'aber auch unser Vieh muß mitgehen - keine Klaue darf zurückbleiben, weil wir davon welche nehmen müssen, um Jahwe, unserem Gott, unsere Verehrung zu bezeigen; wir wissen ja nicht, wie wir Jahwe verehren sollen, bis wir dorthin kommen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'Aber Jahwe verstockte den Sinn des Pharao, und er weigerte sich, sie ziehen zu lassen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'Und der Pharao sprach zu ihm: Fort mit dir! Hüte dich, mir nochmals unter die Augen zu kommen; denn wenn du mir unter die Augen kommst, mußt du sterben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, 'Mose erwiderte: Also du hast es gesagt; ich werde dir nicht mehr unter die Augen kommen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, 'Hierauf sprach Jahwe zu Mose: Noch eine einzige Plage will ich über den Pharao und die Ägypter ergehen lassen; dann wird er euch von hier wegziehen lassen. Wenn er euch gänzlich entläßt, wird er euch sogar gewaltsam von hier wegtreiben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'Schärfe den Leuten ein, ein jeder solle sich von seinem Nachbar und eine jede von ihrer Nachbarin silberne und goldene Gegenstände ausbitten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'Jahwe aber verschaffte dem Volke bei den Ägyptern Ansehen; auch der Mann Mose galt sehr viel in Ägypten bei den Höflingen und Unterthanen des Pharao.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'Da sprach Mose: So spricht Jahwe: Um Mitternacht werde ich durch ganz Ägypten wandeln,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'da soll dann sterben jeder erstgeborene Sohn in Ägypten, vom Erstgeborenen des Pharao an, der auf seinem Throne sitzt, bis zum Erstgeborenen der Sklavin, welche an der Handmühle sitzt, sowie aller erste Wurf des Viehs.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'Und es soll ein großes Jammergeschrei entstehen in ganz Ägypten, desgleichen noch nicht dagewesen ist und desgleichen es niemals mehr geben wird.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'Aber gegen keinen Israeliten soll auch nur ein Hund mucksen, weder gegen Mensch noch Vieh, damit ihr erkennt, daß Jahwe zwischen den Ägyptern und Israeliten einen Unterschied macht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'Dann sollen alle diese deine Höflinge zu mir kommen, sich vor mir niederwerfen und mich bitten: Zieh doch weg samt allen deinen Leuten, die dir anhängen! und hernach werde ich wegziehen. Hierauf verließ er den Pharao in großem Zorn.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'Jahwe aber sprach zu Mose: Der Pharao wird euch nicht willfahren, damit meiner Wunderthaten an Ägypten viele werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'Und Mose und Aaron verrichteten alle diese Wunderthaten vor dem Pharao; Jahwe verstockte jedoch den Sinn des Pharao, so daß er die Israeliten nicht wegziehen ließ aus seinem Lande.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'Da sprach Jahwe zu Mose und Aaron in Ägypten folgendermaßen:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, 'Der laufende Monat soll für euch an der Spitze der Monate stehen; als erster unter den Monaten des Jahres soll er euch gelten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'Sprecht zu der ganzen Gemeinde Israel folgendermaßen: Am zehnten dieses Monats soll sich ein jeder ein Lamm verschaffen, je ein Lamm für jede einzelne Familie.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'Wenn aber die Familie zu klein ist für ein Lamm, so soll er mit seinem Nachbar, der seinem Hause zunächst wohnt, je nach dem Betrage der Seelenzahl eines anschaffen; für so viele, als es aufzuzehren vermögen, sollt ihr ein Lamm rechnen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'Ein fehlerfreies, männliches, einjähriges Lamm muß es sein; aus den Schafen oder Ziegen sollt ihr es wählen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'Und ihr sollt es aufbewahren bis zum vierzehnten Tage dieses Monats, und die gesamte Gemeinde Israel soll es schlachten gegen Abend.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'Dann sollen sie etwas von dem Blute nehmen und es an die beiden Thürpfosten und die Oberschwelle derjenigen Häuser streichen, in denen sie es verzehren.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'Das Fleisch aber sollen sie in derselben Nacht essen und zwar gebraten; ungesäuerte Brote nebst bitteren Kräutern sollen sie dazu essen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'Ihr sollt es nicht roh oder in Wasser gesotten verzehren, sondern am Feuer gebraten, und zwar so, daß der Kopf noch mit den Beinen und den inneren Teilen zusammenhängt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'Auch sollt ihr nichts davon bis zum Morgen übrig lassen; was davon bis zum Morgen übrig bleibt, sollt ihr verbrennen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'Und so sollt ihr es verzehren: mit Gürteln um den Leib, mit eueren Sandalen an den Füßen und mit dem Stabe in der Hand, und sollt es in eiliger Hast verzehren; ein Passah für Jahwe ist es.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'Denn ich will in derselben Nacht Ägypten durchziehen und jede Erstgeburt in Ägypten, sowohl unter den Menschen als unter dem Vieh, töten; auch alle Götter Ägyptens werde ich meine Macht fühlen lassen - ich, Jahwe!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'Und das Blut an den Häusern, in denen ihr seid, soll als Merkmal zu eueren Gunsten dienen; denn wenn ich das Blut erblicke, will ich schonend an euch vorübergehen und es soll euch kein Leid und Verderben treffen, wenn ich den Schlag gegen Ägypten führe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, 'Und dieser Tag soll für euch ein Gedächtnistag sein, und ihr sollt an ihm Jahwe ein Fest feiern von Geschlecht zu Geschlecht; als eine Einrichtung auf ewige Zeiten sollt ihr ihn feiern.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, 'Sieben Tage hindurch sollt ihr ungesäuertes Brot essen; bereits am ersten Tage sollt ihr den Sauerteig von eueren Wohnungen fern halten; denn wer irgend gesäuertes Brot genießt vom ersten Tag an bis zum siebenten, der soll weggetilgt werden aus Israel.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'Am ersten Tag aber sollt ihr eine Festversammlung beim Heiligtum und am siebenten Tag eine Festversammlung beim Heiligtum halten. An ihnen soll ganz und gar keine Arbeit verrichtet werden; nur was ein jeder zur Nahrung braucht, darf von euch zubereitet werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'Und die Anordnung in Bezug auf die ungesäuerten Brote sollt ihr beobachten; denn an eben diesem Tag habe ich eure Heerscharen aus Ägypten weggeführt. Daher sollt ihr diesen Tag beobachten von Geschlecht zu Geschlecht als eine Einrichtung auf ewige Zeiten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'Im ersten Monat, am vierzehnten Tage des Monats, am Abend, sollt ihr ungesäuertes Brot essen, bis zum Abend des einundzwanzigsten Tages des Monats.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'Sieben Tage hindurch darf kein Sauerteig in eueren Wohnungen zu finden sein; denn wer irgend gesäuertes Brot ißt, der soll weggetilgt werden aus der Gemeinde Israel, sowohl Fremde als Landeseingeborene.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'Keinen Bissen gesäuertes Brotes sollt ihr essen; überall, wo ihr auch wohnt, sollt ihr ungesäuertes Brot essen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'Da berief Mose alle Vornehmsten der Israeliten und gebot ihnen: Auf! verschafft euch ein Schaf für eure Familien und schlachtet das Passah!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'Und nehmt ein Büschel Ysop, taucht es in das Blut, das im Becken ist, und streicht etwas von dem Blut im Becken an die Oberschwelle und die beiden Thürpfosten; aber keiner von euch soll zur Thüre seiner Wohnung hinausgehen bis morgens früh.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'Denn Jahwe wird durchziehen, um gegen die Ägypter einen Schlag zu führen; wenn er dann das Blut an der Oberschwelle und an den beiden Thürpfosten erblickt, wird Jahwe schonend an jener Thüre vorübergehen und dem Verderben nicht gestatten, euere Wohnungen zu betreten, um jemand heimzusuchen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'Und ihr sollt dies beobachten als eine Satzung für dich und deine Kinder auf ewige Zeiten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'Wenn ihr nun in das Land kommt, das euch Jahwe zu eigen geben wird, wie er verheißen hat, so sollt ihr diesen gottesdienstlichen Brauch beobachten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'Und wenn euere Kinder euch dann fragen: Was habt ihr da für einen Brauch?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'so sollt ihr antworten: Es ist ein Passahopfer für Jahwe, der schonend vorüberging an den Wohnungen der Israeliten in Ägypten, als er die Ägypter heimsuchte, unsere Familien aber unangetastet ließ. Da neigten sich die Leute und warfen sich zu Boden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'Und die Israeliten gingen hin und thaten, wie Jahwe Mose und Aaron geboten hatte; so thaten sie.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, 'Um Mitternacht aber tötete Jahwe alle Erstgeburten in Ägypten, vom Erstgeborenen des Pharao an, der auf seinem Throne saß, bis zum Erstgeborenen des Gefangenen, der im Kerker lag, sowie alle Erstgeburten des Viehs.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, 'Da stand der Pharao samt seinen Höflingen und allen Ägyptern in jener Nacht auf, und es erhob sich ein großes Klagegeschrei in Ägypten: denn es gab kein Haus, in welchem nicht ein Toter war.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'Da ließ er Mose und Aaron zur Nachtzeit rufen und sprach: Auf! zieht ab, von meinem Volke weg, sowohl ihr selbst, als die Israeliten; geht hin und verehrt Jahwe, wie ihr verlangt habt!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'Auch euere Schafe und Rinder nehmt mit, wie ihr es verlangt habt; zieht ab und bittet auch für mich um Segen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'Die Ägypter aber drängten das Volk zu schleunigem Abzug aus dem Lande; denn sie sagten sich: wir sind sonst alle des Todes!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'Da nahmen die Leute ihren Brotteig mit, bevor er durchsäuert war und trugen die Backschüsseln eingewickelt in ihre Obergewänder auf den Schultern.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'Die Israeliten aber hatten gethan, wie ihnen Mose geboten hatte, und sich von den Ägyptern silberne und goldene Geräte, sowie Kleider erbeten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'Und Jahwe hatte den Leuten bei den Ägyptern Ansehen verschafft, so daß sie ihnen willfahrten; so plünderten sie die Ägypter.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, 'Da zogen die Israeliten von Ramses nach Suchoth, gegen sechshunderttausend Mann zu Fuß, die Männer abgesehen von den Kindern.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'Aber auch eine große Rotte zog mit ihnen, sowie Schafe und Rinder, ein gewaltiger Haufe Vieh.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'Da buken sie den Teig, den sie aus Ägypten mitgenommen hatten, zu Fladen ungesäuerten Brotes; denn er war nicht gesäuert, weil sie mit Gewalt aus Ägypten fortgetrieben worden waren und sich nicht mehr aufhalten noch sich Reisezehrung hatten bereiten können.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'Die Zeit aber, welche die Israeliten in Ägypten zugebracht hatten, betrug vierhundertunddreißig Jahre.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'Und nach Ablauf von vierhundertunddreißig Jahren, an eben diesem Tage, zogen alle Heerscharen Jahwes aus Ägypten weg.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'Eine Bewahrungsnacht Jahwes ist es, weil er sie wegführte aus Ägypten. Das ist diese Nacht Jahwes zur Beobachtung für alle Israeliten von Geschlecht zu Geschlecht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'Da sprach Jahwe zu Mose und Aaron: Dies ist die Satzung in Bezug auf das Passah: kein Fremder darf es mitessen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'Jeder um Geld erkaufte Sklave aber darf dann mitessen, wenn man ihn beschnitten hat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'Ein Beisaß oder Lohnarbeiter darf es nicht mitessen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'In einem Hause soll es verzehrt werden; man darf nichts von dem Fleisch aus dem Hause hinaustragen. Keinen Knochen sollt ihr an ihm brechen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'Die ganze Gemeinde Israel soll es halten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'Und wenn sich Ausländer bei euch aufhalten und Jahwe Passah feiern wollen, so soll alles, was männlich unter ihnen ist, beschnitten werden; alsdann mögen sie herzutreten, es zu feiern, und sie sollen dann wie Landeseingeborene gelten. Ein Unbeschnittener aber darf es unter keinen Umständen mitessen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'Ein und dasselbe Gesetz soll gelten für den Landeseingeborenen, wie für den Fremden, der sich in eurer Mitte aufhält.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'Da thaten alle Israeliten, wie Jahwe Mose und Aaron geboten hatte; so thaten sie.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'An eben diesem Tage führte Jahwe die Israeliten nach ihren Scharen aus Ägypten hinweg.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, 'Da redete Jahwe mit Mose folgendermaßen:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, 'Sondere mir alles Erstgeborene als heilig aus, alles was bei den Israeliten zuerst den Mutterschoß durchbricht, es sei Mensch oder Tier; mir soll es gehören.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'Und Mose sprach zum Volke: Gedenkt an diesen Tag, an dem ihr aus Ägypten, aus dem Lande, da ihr Sklaven wart, ausgezogen seid. Denn mit gewaltiger Hand hat euch Jahwe von dort weggeführt; daher darf kein gesäuertes Brot gegessen werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'Heute zieht ihr aus, im Monat Abib.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'Wenn dich nun Jahwe in das Land der Kanaaniter, Hethiter, Amoriter, Heviter und Jebusiter bringen wird, welches dir zu verleihen er deinen Ahnen zugeschworen hat, ein Land, welches von Milch und Honig überfließe, so sollst du diesen gottesdienstlichen Brauch in eben diesem Monat beobachten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'Sieben Tage hindurch sollt ihr ungesäuerte Brote essen; am siebenten Tag aber soll Jahwe ein Fest gefeiert werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'Ungesäuerte Brote sollen die sieben Tage hindurch gegessen werden, und es darf sich kein gesäuertes Brot und kein Sauerteig bei dir vorfinden in deinem ganzen Bereich.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'Und an jenem Tage sollst du deinem Sohne Folgendes erzählen: Dies hat Jahwe an mir gethan, als ich aus Ägypten wegzog.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'Und es soll dir sein, wie ein Wahrzeichen an deiner Hand und wie ein Gedenkzeichen an deiner Stirn, damit die Unterweisung Jahwes stets in deinem Munde sei; denn mit gewaltiger Hand hat dich Jahwe aus Ägypten weggeführt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'Daher sollst du diese Satzung beobachten Jahr für Jahr zur festgesetzten Zeit.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, 'Wenn dich aber Jahwe, wie er es dir und deinen Ahnen zugeschworen hat, in das Land der Kanaaniter bringen und dir dasselbe verleihen wird,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'so sollst du alles, was zuerst den Mutterschoß durchbricht, Jahwe weihen; jeder erste Wurf des Viehs, der dir zu teil wird: soweit es Männchen sind, sollen sie Jahwe gehören.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'Jeden ersten Wurf eines Esels aber sollst du mit einem Lamm auslösen; willst du ihn aber nicht auslösen, so sollst du ihm das Genick brechen. Aber jede erste Menschengeburt unter deinen Söhnen sollst du auslösen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'Und wenn dich dein Sohn einst fragen wird: Was bedeutet dies? so sollst du ihm antworten: Mit gewaltiger Hand hat uns Jahwe aus Ägypten, dem Lande, wo wir Sklaven waren, hinweggeführt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'Denn als der Pharao verstockt war und uns nicht wollte ziehen lassen, hat Jahwe alle Erstgeburt in Ägypten getötet, sowohl die Erstgeborenen unter den Menschen, als den ersten Wurf des Viehs; deswegen bringe ich Jahwe jeden ersten männlichen Wurf als Opfer, und jeden Erstgeborenen unter meinen Söhnen löse ich aus.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'Und es soll dir wie ein Wahrzeichen an deiner Hand und wie ein Gedenkzeichen an deiner Stirn sein, daß uns Jahwe mit gewaltiger Hand aus Ägypten weggeführt hat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, 'Als aber der Pharao das Volk hatte ziehen lassen, führte sie Gott nicht auf dem Wege nach dem Lande der Philister, obwohl dies der nächste gewesen wäre; denn Gott dachte: es könnte das Volk reuen, wenn es Kämpfe zu bestehen hätte, und sie könnten nach Ägypten zurückkehren wollen;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, 'sondern Gott ließ das Volk auf dem Wege nach der Wüste hin gegen das Schilfmeer umbiegen, und kampfgerüstet zogen die Israeliten aus Ägypten fort.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'Mose aber nahm die Gebeine Josephs mit; denn dieser hatte die Söhne Israels mit schwerem Eide verpflichtet: Wenn Gott sich dereinst eurer annehmen wird, müßt ihr meine Gebeine von hier mit euch nehmen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'Da brachen sie von Suchoth auf und lagerten sich in Etham, am Rande der Wüste.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'Jahwe aber zog vor ihnen her, Tags über in einer Wolkensäule, um ihnen den Weg zu zeigen, und des Nachts in einer Feuersäule, um ihnen Licht zu spenden, so daß sie bei Tag und bei Nacht weiter ziehen konnten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'Tags über wich die Wolkensäule nicht und des Nachts stand die Feuersäule vor dem Volke.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, 'Da sprach Jahwe zu Mose folgendermaßen:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, 'Befiehl den Israeliten, abzuschwenken und sich bei Pihachiroth zwischen Migdol und dem Meere zu lagern bei Baal Zephon; in dessen Nähe sollt ihr euch lagern am Meere.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'Der Pharao aber wird von den Israeliten denken: Sie sind verirrt im Lande; sie sind eingeschlossen in der Wüste.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'Dann werde ich den Sinn des Pharao verstocken, und er wird sie verfolgen; ich aber werde am Pharao und seinem ganzen Heere meine Macht erweisen, und die Ägypter sollen erkennen, daß ich Jahwe bin. Da thaten sie so.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'Hierauf wurde dem Könige von Ägypten berichtet, daß das Volk entwichen sei. Da wurden der Pharao und seine Höflinge gegen das Volk umgestimmt; denn sie sagten sich: Was haben wir gethan, daß wir die Israeliten ziehen ließen, so daß sie uns keine Dienste mehr thun!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'Da ließ er seine Wagen anspannen und nahm sein Kriegsvolk mit sich.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'Und er nahm sechshundert Streitwagen mit auserlesener Mannschaft mit und alle Streitwagen der Ägypter und Wagenkämpfer auf jedem derselben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'Jahwe aber verstockte den Sinn des Pharao, des Königs von Ägypten; da setzte er den Israeliten nach, während die Israeliten schlagbereit ihres Weges zogen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'Da setzten die Ägypter ihnen nach und erreichten sie, wie sie am Meere lagerten, alle Pferde, Kriegswagen, Reiter und Truppen des Pharao, bei Pihachiroth in der Nähe von Baal Zephon.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'Als nun der Pharao nahe herangekommen war, schauten die Israeliten auf und wurden gewahr, daß die Ägypter hinter ihnen dreinzogen. Da fürchteten sie sich sehr. Und die Israeliten riefen Jahwe um Hilfe an.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, 'Zu Mose aber sprachen sie: Gab es etwa keine Friedhöfe in Ägypten, daß du uns herausgelockt hast, damit wir in der Wüste sterben? Was hast du uns angethan, daß du uns aus Ägypten wegführtest!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, 'Haben wir dir nicht gerade dies schon in Ägypten vorgehalten: Laß uns in Ruhe, wir wollen den Ägyptern Sklavendienste verrichten. Denn es wäre besser für uns, den Ägyptern Sklavendienste zu verrichten, als in der Wüste umzukommen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'Mose jedoch sprach zu dem Volke: Habt keine Angst! Haltet Stand, so werdet ihr sehen, welche Hilfe euch Jahwe heute wird zu teil werden lassen; denn was ihr heute mit den Ägyptern werdet geschehen sehen, werdet ihr nie und nimmermehr an ihnen sehen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'Jahwe wird für euch streiten; ihr aber sollt euch still verhalten!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, 'Da sprach Jahwe zu Mose: Warum rufst du mich zu Hilfe? Befiehl den Israeliten, weiter zu ziehen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'Du aber hebe deinen Stab empor und recke deine Hand aus über das Meer; so soll es sich zerteilen, und die Israeliten sollen mitten durch das Meer ziehen, als ob sie auf trockenem Lande wären.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'Dann will ich die Ägypter verblenden, so daß sie ihnen folgen, und will meine Macht erweisen am Pharao und an seinem ganzen Heer, an seinen Streitwagen und an seinen Reitern,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'damit die Ägypter erkennen, daß ich Jahwe bin, wenn ich meine Macht erweise am Pharao und an seinem ganzen Heer, an seinen Streitwagen und Reitern.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, 'Da änderte der Engel Gottes, der dem Lager der Israeliten vorauszog, seine Stellung und trat hinter sie. Und die Wolkensäule änderte ihre Stellung vorn und trat hinter sie.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'Und er kam zwischen das Lager der Ägypter und das der Israeliten, und die Wolke erhellte die Nacht. Da konnten sie sich die ganze Nacht hindurch nicht zu nahe kommen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'Da reckte Mose seine Hand aus über das Meer. Da versetzte Jahwe das Meer die ganze Nacht hindurch durch einen heftigen Ostwind in Bewegung und legte das Meer trocken; die Gewässer traten auseinander.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'Die Israeliten aber zogen mitten durch das Meer hindurch, wie auf trockenem Lande, während das Gewässer zu ihrer Rechten und Linken einen Damm bildete.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'Die Ägypter aber verfolgten sie und kamen hinter ihnen drein, alle Rosse, Streitwagen und Reiter des Pharao, zwischen die Wassermassen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, 'In der letzten Nachtwache aber beugte sich Jahwe in der Feuer- und Wolkensäule gegen den Heereszug der Ägypter hinab und brachte Verwirrung im Heereszuge der Ägypter hervor.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, 'Und er machte, daß die Räder ihrer Wagen absprangen, und daß sie nur mühsam vorwärts kamen. Da sagten die Ägypter: Laßt uns vor den Israeliten fliehen! Denn Jahwe kämpfte für sie gegen die Ägypter.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, 'Da sprach Jahwe zu Mose: Recke deine Hand gegen das Meer aus; so sollen die Gewässer auf die Ägypter, ihre Streitwagen und ihre Reiter zurückfluten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'Und Mose reckte seine Hand gegen das Meer aus; da flutete gegen Morgen das Meer wieder in sein Bette zurück, während die Ägypter ihm gerade entgegen flohen, und Jahwe trieb die Ägypter mitten ins Meer hinein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'Und die Gewässer flossen wieder zusammen und überfluteten die Streitwagen und die Reiter - das ganze Heer des Pharao -, die ihnen ins Meer gefolgt waren; kein einziger von ihnen blieb am Leben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'Die Israeliten aber zogen durch das Meer hindurch wie auf trockenem Lande, während die Gewässer zu ihrer Rechten und Linken einen Damm bildeten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'So errettete Jahwe an jenem Tage Israel vor den Ägyptern, und die Israeliten sahen die Ägypter tot am Meeresufer liegen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'Da erkannte Israel die große Wunderthat, die Jahwe an den Ägyptern verrichtet hatte. Da fürchtete das Volk Jahwe und glaubte an Jahwe und seinen Diener Mose.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, 'Damals sang Mose mit den Israeliten Jahwe das nachfolgende Lied, und sie sangen also: Ich will Jahwe ein Lied singen, denn hoch erhaben ist er; Rosse und Reiter hat er ins Meer gestürzt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'Meine Stärke und mein Lobgesang ist Jahwe, und von ihm kam mein Heil. Er ist mein Gott; darum will ich ihn preisen - der Gott meines Vaters, darum will ich ihn hoch rühmen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'Jahwe ist ein Kriegsheld; Jahwe ist sein Name.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'Die Streitwagen und die Heeresmacht des Pharao hat er ins Meer gestürzt, und die auserlesensten seiner Wagenkämpfer wurden ins Schilfmeer versenkt;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, 'Meeresfluten bedeckten sie; in die Strudel stürzten sie, wie ein Stein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'Deine rechte Hand, o Jahwe! ist herrlich ob ihrer Kraft, Deine recht Hand, o Jahwe! zerschmettert die Feinde,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'und mit deiner gewaltigen Majestät schlägst du deine Gegner zu Boden. Wenn du deinen Grimm loslässest, verzehrt er sie wie Strohhalme.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'Durch dein zorniges Schnauben standen die Gewässer, wie ein Damm. Es stand aufrecht wie ein Wall, was strömte, wie geronnen war der Wasserschwall im Meere.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, 'Der Feind dachte: Ich will ihnen nachjagen, sie einholen, will Beute verteilen, mich an ihnen letzen. Das Schwert will ich ziehn; ausrotten soll sie meine Hand!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'Du bliesest drein mit deinem Odem, da bedeckte sie das Meer. Sie sanken unter, wie Blei, in gewaltigen Wassermassen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, 'Wer gleicht dir unter den Göttern, o Jahwe! Wer gleicht dir, du herrlich erhabener, du furchtbarer in Ruhmesthaten, der du Wunder verrichtest!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'Da du deine Hand ausrecktest, verschlang sie die Erde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'Du geleitetest mit deiner Huld das Volk, das du befreit hattest; du führtest es mit deiner Macht zu deiner heiligen Wohnstätte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, 'Als die Nationen davon hörten, erzitterten sie, Angst ergriff die Bewohner Philistäas.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'Damals erschraken die Stammesfürsten Edoms, die Anführer Moabs ergriff Beben; es verzagten alle Bewohner Kanaans.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'Es befiel sie Schrecken und Angst; über die Großthat deines Arms wurden sie starr wie Stein. So zog nun ein dein Volk, o Jahwe! So zog nun ein das Volk, das du dir zum Eigentum erwählt hast.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'Du brachtest sie hin und pflanztest sie an auf dem Berge, deinem Besitztum, der Stätte, die du dir bereitet hast, Jahwe! um daselbst zu wohnen, dem Heiligtum, o Herr, das deine Hände bereitet haben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'Jahwe ist König auf immer und ewig!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'Denn als die Rosse des Pharao samt seinen Wagen und Reitern in das Meer gerieten, da ließ Jahwe die Wogen des Meeres über sie zusammenschlagen, während die Israeliten im Trockenen durch das Meer hindurch gezogen waren.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'Da nahm die Prophetin Mirjam, Aarons Schwester, die Pauke zur Hand, und alle Weiber zogen hinter ihr drein mit Pauken und im Reigen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'Mirjam aber sang ihnen vor: Singt Jahwe ein Lied, denn hoch erhaben ist er; Rosse und Reiter hat er ins Meer gestürzt!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, 'Hierauf ließ Mose die Israeliten vom Schilfmeer aufbrechen; da zogen sie weiter nach der Wüste Sur und wanderten drei Tage in der Wüste, ohne Wasser zu finden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'So gelangten sie nach Mara; aber sie konnten das Wasser wegen seiner Bitterkeit nicht trinken. Denn es war bitter; daher hieß der Platz Mara.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, 'Da murrten die Leute gegen Mose und fragten: Was sollen wir trinken?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'Er aber rief Jahwe um Hilfe an. Da wies ihm Jahwe eine gewisse Art Holz; das warf er ins Wasser, da wurde es trinkbar. Dort gab er ihm Gesetz und Recht und dort ließ er ihm die Wahl,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, 'indem er sprach: Wenn du den Worten Jahwes, deines Gottes, treulich gehorchst und thust, was vor seinen Augen recht ist, und seinen Befehlen Folge leistest und alle seine Satzungen beobachtest, so werde ich keines der Leiden, von denen ich die Ägypter befallen ließ, dich befallen lassen, sondern ich, Jahwe, werde dein Arzt sein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'Hierauf gelangten sie nach Elim; dort fanden sich zwölf Quellen mit Wasser nebst siebzig Palmbäumen, und sie lagerten sich daselbst am Wasser.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, 'Sodann brachen sie von Elim auf, und es gelangte die ganze Gemeinde der Israeliten in die Wüste Sin, die zwischen Elim und dem Sinai liegt, am fünfzehnten Tage des zweiten Monats nach ihrem Auszug aus Ägypten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'Da murrte die ganze Gemeinde der Israeliten gegen Mose und Aaron in der Wüste.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, 'Und die Israeliten sprachen zu ihnen: O wären wir doch lieber durch die Hand Jahwes in Ägypten gestorben, wo wir bei unseren Fleischtöpfen saßen und uns am Brot satt essen konnten; statt dessen habt ihr uns in diese Wüste geführt, um diese ganze Gemeinde dem Hungertode preiszugeben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'Da sprach Jahwe zu Mose: Wohlan! ich will euch Brot vom Himmel fallen lassen wie Regen; so sollen dann die Leute hingehen und jeden Tag ihren täglichen Bedarf einsammeln. Damit will ich sie prüfen, ob sie nach meinen Lehren wandeln wollen oder nicht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'Wenn sie dann aber am sechsten Tage zubereiten, was sie heimbringen, so wird es doppelt so viel sein, als was sie sonst alltäglich einsammeln.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'Da sprachen Mose und Aaron zu allen Israeliten: Am Abend werdet ihr einsehen, daß Jahwe euch aus Ägypten weggeführt hat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'Morgen früh aber werdet ihr Jahwes Majestät zu sehen bekommen; denn er hat euer Murren wider Jahwe gehört. Was sind aber wir, daß ihr wider uns murrt?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'Da sprach Mose: Dadurch, daß euch Jahwe abends Fleisch zu essen geben wird und reichliches Brot am Morgen; dadurch, daß Jahwe euer Murren erhört, das ihr gegen ihn richtet - denn was sind wir? Euer Murren richtet sich nicht gegen uns, sondern gegen Jahwe!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'Hierauf sprach Mose zu Aaron: Befiehl der ganzen Gemeinde der Israeliten: Tretet heran vor Jahwe; denn er hat euer Murren vernommen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'Als nun Aaron der ganzen Gemeinde der Israeliten dies befohlen hatte, schauten sie gegen die Wüste hin; da erschien plötzlich Jahwes Herrlichkeit in der Wolke.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'Und Jahwe sprach folgendermaßen zu Mose:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, 'Ich habe das Murren der Israeliten vernommen; sprich zu ihnen also: Heute abend werdet ihr Fleisch zu essen bekommen und morgen früh sollt ihr euch an Brot satt essen, und ihr sollt erkennen, daß ich Jahwe, euer Gott, bin!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, 'Als es nun Abend wurde, zog ein Wachtelschwarm heran und fiel überall im Lager nieder. Am folgenden Morgen aber legte sich ein starker Tau rings um das Lager.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'Und als der Tauniederschlag verschwand, da lag auf dem Boden der Wüste etwas Feines, Körniges, so fein, wie kleine Reiskörner, auf dem Boden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'Als dies die Israeliten sahen, fragten sie einander: Was ist das? denn sie wußten nicht, was es war. Und Mose sprach zu ihnen: Das ist das Brot, das euch Jahwe als Nahrungsmittel schenkt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'Folgendes hat Jahwe geboten: Sammelt davon ein, jeder nach seinem Bedürfnis und zwar einen Gomer auf den Kopf; je nach der Seelenzahl in eines jeglichen Zelt sollt ihr euch nehmen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'Da thaten die Israeliten so und sammelten ein, der eine viel, der andere weniger.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'Als sie es aber mit dem Gomer maßen, hatte der, der viel genommen, nicht zu viel, und der, der weniger genommen, nicht zu wenig gesammelt, sondern jeder hatte nach seinem Bedürfnis gesammelt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'Hierauf befahl ihnen Mose: Niemand soll etwas davon für den folgenden Tag aufheben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'Aber sie gehorchten Mose nicht, und einige hoben etwas davon für den folgenden Tag auf. Da wurde es voll Würmer und verdarb; Mose aber wurde zornig auf sie.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'Und sie sammelten es jeden Morgen früh ein, jeder nach seinem Bedürfnis. Wenn aber die Sonne heiß schien, zerschmolz es.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'Am sechsten Tag aber hatten sie doppelt so viel Speise gesammelt, je zwei Gomer auf die Person. Da gingen alle Vorstände der Gemeinde hin, um es Mose zu berichten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'Er jedoch sprach zu ihnen: Das geschieht, weil Jahwe gebietet: Morgen soll Ruhetag, ein Jahwe geweihter Sabbat sein. Was ihr backen wollt, das backt, und was ihr kochen wollt, das kocht; alles aber, was übrig bleibt, thut auf die Seite, um es für morgen aufzubewahren.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'Da hoben sie es nach Moses Gebot bis zum folgenden Tag auf; und es verdarb nicht und bekam auch keine Würmer.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'Hierauf befahl Mose: Nährt euch heute davon! denn heute ist Sabbat Jahwes; heute werde ihr draußen nichts finden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'Sechs Tage hindurch sollt ihr davon einsammeln; aber am siebenten Tag, am Sabbat, wird es keines geben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'Am siebenten Tage jedoch gingen etliche Leute hinaus, um einzusammeln; aber sie fanden nichts.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'Da sprach Jahwe zu Mose: Wie lange wollt ihr euch weigern, meine Befehle und Lehren zu beobachten?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'Seht doch! Jahwe giebt euch den Sabbat, daher spendet er euch am sechsten Tage Nahrung auf zwei Tage, bleibt ruhig zu Hause; niemand soll am siebenten Tage seine Behausung verlassen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'So feierte das Volk am siebenten Tage.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'Die Israeliten aber nannten es Man. Es war weiß wie Korianderkörner und hatte einen Geschmack wie Kuchen mit Honig.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'Hierauf sprach Mose: Folgendes befiehlt Jahwe: Ein ganzer Gomer davon soll aufbewahrt werden von Geschlecht zu Geschlecht, damit sie die Speise sehen, womit ich euch in der Wüste genährt habe, als ich euch aus Ägypten wegführte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'Da sprach Mose zu Aaron: Nimm einen Krug, thue einen ganzen Gomer voll Manna hinein und stelle ihn hin vor Jahwe, daß er aufbewahrt werde von Geschlecht zu Geschlecht,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'wie Jahwe Mose geboten hatte. Und Aaron stellte es nieder vor der Lade mit dem Gesetz zur Aufbewahrung.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'Die Israeliten aber aßen Manna vierzig Jahre hindurch, bis sie in bewohntes Land gelangten; Manna aßen sie, bis sie an die Grenze des Landes Kanaan gelangten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'Ein Gomer aber ist der zehnte Teil eines Epha.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'Hierauf zog die ganze Gemeinde der Israeliten aus der Wüste Sin stationenweise weiter gemäß dem Befehle Jahwes; dann lagerten sie sich in Raphidim. Es gab aber kein Wasser für das Volk zum Trinken.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'Da haderte das Volk mit Mose und verlangte: Schaffe uns Wasser zum Trinken! Mose aber erwiderte ihnen: Warum hadert ihr mit mir? Was versucht ihr Jahwe?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'Und das Volk litt daselbst Durst, daher murrte das Volk wider Mose, indem sie sprachen: Wozu hast du uns denn aus Ägypten fortgeführt? Etwa um uns, unsere Kinder und unser Vieh vor Durst umkommen zu lassen?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, 'Da rief Mose Jahwe um Hilfe an, indem er sprach: Was soll ich mit diesen Leuten anfangen? Nur wenig fehlt, so werden sie mich steinigen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'Jahwe aber erwiderte Mose: Gehe vor dem Volke voraus und nimm einige von den Vornehmen der Israeliten mit; auch deinen Stab, womit du in den Nil geschlagen hast, nimm zur Hand und geh!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'Dann will ich dort vor deinen Augen auf den Felsen am Horeb treten. Schlage dann auf den Felsen, so soll Wasser aus ihm hervorsprudeln, so daß die Leute zu trinken haben. Da that Mose so im Beisein der Vornehmen der Israeliten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'Und er benannte die Stätte Massa und Meriba, weil die Israeliten gehadert und Jahwe versucht hatten, indem sie fragten: Ist Jahwe unter uns oder nicht?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, 'Hierauf rückten die Amalekiter heran, um die Israeliten in Raphidim zu bekämpfen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'Da befahl Mose Josua: Wähle uns Männer aus und zieh morgen aus, um den Amalekitern eine Schlacht zu liefern; ich aber werde auf dem Gipfel des Hügels stehen mit dem Stabe Gottes in der Hand.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'Und Josua that, wie Mose ihm geboten hatte, und zog aus, den Amalekitern eine Schlacht zu liefern; Mose, Aaron und Hur aber stiegen auf den Gipfel des Hügels.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'Wenn nun Mose seine Arme erhob, so hatten die Israeliten die Oberhand; wenn er jedoch seine Arme sinken ließ, so hatten die Amalekiter die Oberhand.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'Als jedoch die Arme Moses ermüdeten, nahmen sie einen Stein und legten ihm den unter; da setzte er sich darauf. Aaron aber und Hur stützten seine Arme, der eine auf dieser, der andere auf jener Seite; da blieben seine Arme beständig ausgereckt bis zum Sonnenuntergang.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'Also brachte Josua den Amalekitern und ihrem Kriegsvolk eine blutige Niederlage bei.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'Hierauf befahl Jahwe Mose: Schreibe dies zum Andenken in ein Buch und schärfe es Josua ein: ich will die Amalekiter bis auf den Namen gänzlich von der Erde verschwinden lassen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, 'Da errichtete Mose einen Altar und benannte ihn: Jahwe ist mein Banner!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, 'Denn er sprach: Hand an das Banner Jah\'s!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, 'Als aber Jethro, der Priester der Midianiter, der Schwiegervater Moses, die Kunde von alledem vernahm, was Gott an Mose und an seinem Volke Israel gethan hatte, daß Jahwe Israel aus Ägypten weggeführt hatte,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'nahm Jethro, der Schwiegervater Moses, Zipora, das Weib Moses, - er hatte sie zurückgesandt -');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'und ihre beiden Söhne - der eine hieß Gersom, weil er gesagt hatte: ein Fremdling bin ich geworden in einem fremden Lande;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'der andere hieß Elieser, denn: der Gott meines Vaters half mir und errettete mich vor dem Schwerte des Pharao. -');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'Da kam Jethro, der Schwiegervater Moses, mit seinen Söhnen und seinem Weibe zu Mose in die Wüste, woselbst er lagerte am Berge Gottes.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'Und er ließ Mose sagen: Ich, dein Schwiegervater Jethro, komme zu dir, nebst deinem Weib und ihren beiden Söhnen, die sie bei sich hat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'Da machte sich Mose auf den Weg, seinem Schwiegervater entgegenzugehen, verneigte sich und küßte ihn; dann fragten sie einander nach ihrem Wohlbefinden und begaben sich zum Zelte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'Mose aber erzählte seinem Schwiegervater alles, was Jahwe dem Pharao und den Ägyptern zu Gunsten der Israeliten angethan hatte, von allen Mühsalen, die ihnen unterwegs zugestoßen waren, und wie Jahwe sie errettet hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'Und Jethro freute sich über alle die Wohlthaten, die Jahwe den Israeliten erwiesen hatte, daß er sie aus der Gewalt der Ägypter befreit hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'Und Jethro sprach: Gepriesen sei Jahwe, daß er euch aus der Gewalt des Pharao und der Ägypter befreit hat, daß er das Volk aus der Gewalt der Ägypter befreit hat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, 'Nun erkenne ich, daß Jahwe mächtiger ist als alle Götter!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'Hierauf ließ Jethro, der Schwiegervater Moses, Schlachtvieh zu einem Brandopfer und zu einer Opfermahlzeit zu Ehren Gottes herbeischaffen, und es kamen Aaron und alle Vornehmen der Israeliten herbei, um mit dem Schwiegervater Moses ein Mahl vor Gott zu halten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, 'Des anderen Tages aber setzte sich Mose hin, um dem Volke Recht zu sprechen; da traten Leute vor Mose hin vom Morgen bis zum Abend.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'Als nun der Schwiegervater Moses sah, wie er für die Leute zu thun hatte, sagte er: Was machst du dir mit den Leuten zu thun? Warum sitzest du allein zu Gericht, während alle Leute dich überlaufen vom Morgen bis zum Abend?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'Mose erwiderte seinem Schwiegervater: Ja, die Leute kommen zu mir, um Gott zu befragen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, 'Wenn sie eine Rechtssache haben, kommen sie zu mir, damit ich entscheide, wer von beiden Recht hat, und verkündige die Rechtssprüche und Entscheide Gottes.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'Da sprach der Schwiegervater Moses zu ihm: Daran thust du nicht gut.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, 'Du wirst dich, sowie die Leute, die bei dir sind, aufreiben; denn dieses Geschäft ist zu schwer für dich, du kannst es nicht allein besorgen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'Ich will dir jetzt einen guten Rat geben; folge mir, so wird Gott dir beistehen: bleibe du selbst für das Volk Sachwalter bei Gott und bringe du selbst die Rechtssachen vor Gott.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'Und belehre sie über die Rechtssatzungen und Entscheide und weise ihnen den Weg, den sie wandeln sollen, und was sie thun sollen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'Wähle dir aber aus dem ganzen Volke tüchtige, gottesfürchtige, vertrauenswürdige und uneigennützige Männer und bestelle sie zu Vorgesetzten über je tausend, je hundert, je fünfzig und je zehn,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'damit sie den Leuten jederzeit Recht sprechen. Dann soll jede wichtige Sache vor dich gebracht werden, jede minder wichtige aber sollen sie selbst entscheiden; so wirst du dich entlasten und sie werden dich unterstützen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'Wenn du dies so anordnest, und Gott es dir befiehlt, so wirst du es aushalten können, und alle diese Leute werden befriedigt zu ihrer Behausung zurückkehren.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'Da folgte Mose den Worten seines Schwiegervaters und führte alles aus, was er geraten hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'Und Mose wählte aus der Gesamtheit der Israeliten tüchtige Männer aus und bestellte sie zu Häuptern über das Volk, zu Vorgesetzten über je tausend, je hundert, je fünfzig und je zehn.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'Und sie sprachen den Leuten jederzeit Recht; wichtige Sachen brachte man vor Mose, alle minder wichtigen Sachen aber entschieden sie selbst.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'Hierauf gab Mose seinem Schwiegervater das Geleite; der aber zog in seine Heimat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'Im dritten Monat nach dem Auszug der Israeliten aus Ägypten, an eben dem Tage kamen sie in die Wüste Sinai.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'Und sie brachen auf von Raphidim und gelangten in die Wüste Sinai; da lagerten sie sich in der Wüste. Und die Israeliten lagerten sich daselbst dem Berge gegenüber.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'Als nun Mose zu Gott hinaufgestiegen war, rief ihm Jahwe vom Berge herab zu und sprach: So sollst du sprechen zum Hause Jakobs und ankündigen den Söhnen Israels:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, 'Ihr habt gesehen, was ich an den Ägyptern verrichtet, wie ich euch auf Adlersflügeln getragen und euch hierher zu mir gebracht habe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'Wenn ihr nun auf mich hören und die von mir festgesetzten Ordnungen beobachten wollt, so sollt ihr unter allen Völkern mein besonderes Eigentum sein; denn mir gehört die ganze Erde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'Und ihr sollt mir werden ein Königreich von Priestern und ein heiliges Volk! - das sind die Worte, die du den Israeliten ausrichten sollst.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'Da ging Mose hin, die Vornehmsten des Volkes zusammen zu rufen, und richtete ihnen alle jene Worte aus, die ihm Jahwe aufgetragen hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'Das ganze Volk aber sprach einstimmig: Alles, was Jahwe befiehlt, wollen wir thun! Da überbrachte Mose die Rede des Volks an Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'Hierauf sprach Jahwe zu Mose: Ich werde alsbald zu dir kommen in dichtem Gewölk, damit das Volk es höre, wenn ich mit dir rede, sowie auf ewige Zeiten an dich glaube. Mose aber berichtete Jahwe die Rede des Volks.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, 'Da sprach Jahwe zu Mose: Geh zu dem Volk und befiehl, daß sie heute und morgen sich rein halten und ihre Kleider waschen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'Und übermorgen sollen sie bereit sein; denn übermorgen wird Jahwe vor den Augen des ganzen Volks auf den Berg Sinai hinabfahren.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'Dem Volk aber sollst du ringsum eine Grenze ziehen, indem du gebietest: Hütet euch davor, den Berg hinanzusteigen oder seinem Fuße zu nahe zu kommen; wer irgend dem Berge zu nahe kommt, der soll getötet werden!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'Keines Hand darf ihn berühren; denn ein solcher soll gesteinigt oder erschossen werden, sowohl Mensch als Vieh, und das Leben lassen müssen. Wenn das Widderhorn geblasen wird, sollen sie den Berg hinansteigen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'Da stieg Mose vom Berge zum Volke hinab und befahl dem Volke, sich rein zu halten und die Kleider zu waschen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, 'Und er sprach zu dem Volke: Seid übermorgen bereit; keiner darf sich einem Weibe nahen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'Am dritten Tag aber, als es Morgen wurde, brachen Donner und Blitze los, indem eine schwere Wolke über dem Berge gelagert war, und es erscholl starkes Geschmetter von Trompeten: Da kam ein Schrecken über alles Volk, das im Lager war.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'Mose aber führte das Volk aus dem Lager heraus, Gott entgegen, und sie stellten sich am Fuße des Berges auf.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'Der Berg Sinai jedoch war ganz in Rauch eingehüllt, weil Jahwe im Feuer auf ihn herabgefahren war, und Rauch stieg von ihm auf wie von einem Schmelzofen, und alles Volk erbebte heftig.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'Und das Schmettern der Trompeten wurde immer stärker: Mose redete und Gott antwortete ihm laut.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'Da fuhr Jahwe auf den Berg Sinai, auf den Gipfel des Berges, hinab. Und Jahwe berief Mose auf den Gipfel des Berges; da stieg Mose hinauf.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'Da sprach Jahwe zu Mose: Steige hinab und schärfe dem Volke ein, daß sie sich ja nicht unterfangen sollen, zu Jahwe vorzudringen, um ihn zu sehen; sonst würde eine große Zahl von ihnen umkommen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'Auch die Priester, die Jahwe nahe treten, sollen sich der Reinigung unterziehen, daß nicht etwa Jahwe gegen sie losbreche.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'Mose aber entgegnete Jahwe: Das Volk kann unmöglich auf den Berg Sinai hinaufsteigen; denn du selbst hast uns ja eingeschärft: Grenze den Berg ein und erkläre ihn für unnahbar!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'Da sprach Jahwe zu ihm: Steige nur hinab und komme dann in Begleitung Aarons wieder herauf; die Priester aber und das Volk sollen sich nicht vorwagen, um zu Jahwe emporzusteigen, daß er nicht gegen sie losbreche.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'Da stieg Mose zum Volke hinab und sagte es ihnen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, 'Nun redete Gott alle diese Worte und sprach:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, 'Ich bin Jahwe, dein Gott, der dich aus Ägypten, aus dem Lande, wo ihr Sklaven wart, weggeführt hat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, 'Du sollst keinen anderen Gott haben neben mir.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'Du sollst dir keinen Götzen verfertigen, noch irgend ein Abbild von etwas, was droben im Himmel oder unten auf der Erde oder im Wasser unter der Erde ist.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'Du sollst dich vor solchen nicht niederwerfen, noch sie verehren; denn ich Jahwe, dein Gott, bin ein eifersüchtiger Gott, der die Verschuldung der Väter ahndet an den Kindern, den Enkeln und Urenkeln derer, die mich hassen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'aber Gnade erweist solchen, die mich lieben und meine Befehle beobachten, auf Tausende hinaus.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, 'Du sollst den Namen Jahwes, deines Gottes, nicht freventlich aussprechen; denn Jahwe läßt den nicht ungestraft, der seinen Namen freventlich ausspricht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, 'Denke daran, den Sabbattag heilig zu halten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'Sechs Tage hindurch sollst du arbeiten und alle deine Geschäfte verrichten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'Aber der siebente Tag ist ein Jahwe, deinem Gotte, geweihter Sabbat; da sollst du gar kein Geschäft verrichten, weder du selbst, noch dein Sohn oder deine Tochter, dein Sklave noch deine Sklavin, noch dein Hausvieh, noch der Fremde, der sich in deinen Ortschaften aufhält.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'Denn im Verlaufe von sechs Tagen hat Jahwe den Himmel und die Erde, das Meer und alles, was in ihnen ist, gemacht; hierauf ruhte er am siebenten Tage. Daher hat Jahwe den Sabbattag gesegnet und für heilig erklärt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, 'Sei ehrerbietig gegen deinen Vater und deine Mutter, damit du lange lebest auf dem Boden, den dir Jahwe, dein Gott, zu eigen geben wird.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, 'Du sollst nicht morden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, 'Du sollst nicht ehebrechen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, 'Du sollst nicht stehlen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, 'Du sollst gegen deinen Nächsten nicht als falscher Zeuge aussagen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, 'Du sollst nicht Verlangen tragen nach deines Nächsten Hause. Du sollst nicht Verlangen tragen nach deines Nächsten Weibe, noch nach seinem Sklaven, seiner Sklavin, seinem Ochsen, seinem Esel, noch nach irgend etwas, was deinem Nächsten gehört.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, 'Als aber das ganze Volk die Donnerschläge und die Blitze, das Trompetengeschmetter und den rauchenden Berg wahrnahm, da fürchtete sich das Volk und zitterte und blieb in der Ferne stehen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'Und sie sprachen zu Mose: Sprich du mit uns; wir wollen es gern anhören! Gott selbst aber soll lieber nicht mit uns reden, sonst müssen wir sterben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'Mose erwiderte dem Volke: habt keine Angst; denn um euch zu prüfen ist Gott gekommen, und damit Furcht vor ihm euch innewohne, daß ihr nicht sündigt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, 'Da blieb das Volk in der Ferne stehen, während Mose an das dunkle Gewölk herantrat, in welchem sich Gott befand.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, 'Jahwe aber sprach zu Mose: So sollst du zu den Israeliten sprechen: Ihr habt gesehen, daß ich vom Himmel her mit euch geredet habe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'Verfertigt euch neben mir keine silbernen Götzen; auch goldene Götzen sollt ihr euch nicht verfertigen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, 'Einen Opferaltar aus Erde sollst du mir errichten und darauf deine Brandopfer und Heilsopfer, deine Schafe und Rinder opfern; an jeder Stätte, die ich dazu bestimmen werde, daß man mich daselbst verehre, werde ich zu dir kommen und dich segnen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'Wenn du mir aber einen Altar aus Steinen errichtest, so darfst du ihn nicht aus behauenen Steinen aufbauen, denn wenn du sie mit eisernen Werkzeugen bearbeitest, entweihst du sie.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'Auch darfst du nicht auf Stufen zu meinem Altar heransteigen, daß nicht etwa deine Schamteile vor ihm entblößt werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, 'Folgendes sind die Rechtssatzungen, die du ihnen vorlegen sollst:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, 'Wenn du einen Sklaven hebräischen Stammes kaufst, so soll er sechs Jahre lang Sklavendienste verrichten; im siebenten Jahr aber soll er unentgeltlich freigelassen werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, 'Wenn er allein eingetreten ist, so soll er auch allein entlassen werden; wenn er ein Weib gehabt hat, so soll auch sein Weib mit ihm zugleich entlassen werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'Wenn sein Herr ihm ein Weib gegeben und sie ihm Knaben oder Mädchen geboren hat, so soll das Weib nebst ihren Kindern ihrem Herrn gehören, und er soll allein entlassen werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'Wenn jedoch der Sklave erklären sollte: Ich habe meinen Herrn, mein Weib und meine Kinder lieb und mag nicht frei werden,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'so soll ihn sein Herr vor Gott führen und ihn an die Thüre oder den Thürpfosten stellen, und sein Herr soll ihm das Ohr mit einem Pfriemen durchbohren; so soll er dann für immer sein Sklave sein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'Wenn jemand seine Tochter als Sklavin verkauft, so darf sie nicht entlassen werden, wie die Sklaven.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'Wenn sie ihrem Herrn, der sie für sich bestimmt hat, mißfällt, so soll er sie loskaufen lassen; aber an volksfremde Leute darf er sie nicht verkaufen, wenn er ihr sein Wort nicht hält.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'Wenn er sie für seinen Sohn bestimmt, so soll er sie wie seine eigene Tochter behandeln.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'Wenn er sich eine andere nimmt, darf er jener nichts von dem abbrechen, was sie an Fleischnahrung, Kleidung und Beiwohnung zu beanspruchen hat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'Wenn er ihr diese drei Dinge nicht leistet, so soll sie umsonst, ohne Entgelt, frei werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, 'Wer einen anderen schlägt, so daß er stirbt, der soll mit dem Tode bestraft werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'Wenn er es aber nicht vorsätzlich gethan, sondern Gott es durch ihn so gefügt hat, so will ich dir eine Stätte bestimmen, wohin er flüchten kann.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'Wenn aber einer gegen den anderen eine offenbare Frevelthat begeht, indem er ihn auf hinterlistige Weise totschlägt, so sollst du ihn sogar von meinem Altare wegholen, damit er hingerichtet werde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'Wer seinen Vater oder seine Mutter schlägt, soll mit dem Tode bestraft werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, 'Wer einen Israeliten raubt, mag er ihn nun verkaufen, oder mag er noch bei ihm vorgefunden werden -, der soll mit dem Tode bestraft werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'Wer eine Verwünschung über seinen Vater oder seine Mutter ausspricht, soll mit dem Tode bestraft werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, 'Wenn ein paar Männer einen Streit haben, und einer den andern mit einem Stein oder mit einem Karst schlägt, so daß er zwar nicht stirbt, aber bettlägerig wird,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, 'so soll, wenn der Geschlagene wieder aufkommt und auf seinen Stock gestützt im Freien herumgehen kann, der Thäter frei ausgehen; bloß für die Zeit, wo er unthätig bleiben mußte, soll er ihn entschädigen und für seine Heilung Sorge tragen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'Wenn jemand seinen Sklaven oder seine Sklavin mit dem Stocke schlägt, so daß er ihm unter der Hand stirbt, so soll er bestraft werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'Wenn er dagegen noch einen oder zwei Tage leben bleibt, so soll er nicht bestraft werden; denn er ist ja sein um Geld erkauftes Eigentum.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'Wenn aber Leute einen Raufhandel haben und dabei ein schwangeres Weib stoßen, so daß eine Fehlgeburt erfolgt, ohne daß weiterer Schaden geschieht, so soll der Thäter eine Buße entrichten, wie sie ihm der Ehemann des Weibes auferlegt, und er soll sie bezahlen nach dem Ausspruch von Schiedsrichtern.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'Geschieht aber ein Schaden, so soll einer lassen Leben um Leben,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'Auge um Auge, Zahn um Zahn, Hand um Hand, Fuß um Fuß,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, 'Brandwunde um Brandwunde, Stichwunde um Stichwunde, Hiebwunde um Hiebwunde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'Wenn jemand seinem Sklaven oder seiner Sklavin ins Auge schlägt so daß dasselbe unbrauchbar wird, so soll er ihn zur Entschädigung für das Auge freilassen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'Und wenn er seinem Sklaven oder seiner Sklavin einen Zahn ausschlägt, so soll er ihn zur Entschädigung für den Zahn freilassen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, 'Wenn ein Rind einen Mann oder eine Frau totstößt, so soll das Rind gesteinigt und darf sein Fleisch nicht gegessen werden; der Besitzer des Rindes aber soll frei ausgehen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'Wenn aber das Rind schon längst stößig gewesen ist, und man dies seinem Besitzer vorgehalten, und er es trotzdem nicht sorgfältig gehütet hat, so soll das Rind, wenn es einen Mann oder eine Frau totstößt, gesteinigt, aber auch sein Besitzer mit dem Tode bestraft werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'Wenn ihm ein Lösegeld auferlegt wird, soll er als Lösegeld für sein Leben so viel bezahlen, als ihm auferlegt wird.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'Wenn ein Knabe oder ein Mädchen gestoßen wird, so soll nach demselben Rechte mit ihm verfahren werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'Wenn das Rind einen Sklaven oder eine Sklavin stößt, so sollen dem Eigentümer derselben dreißig Sekel Silber bezahlt, das Rind aber gesteinigt werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, 'Wenn jemand eine Cisterne offen läßt oder wenn jemand eine Cisterne gräbt, ohne sie zuzudecken, und ein Rind oder ein Esel hineinfällt,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'so soll der Besitzer der Cisterne den Besitzer desselben mit Geld entschädigen; das tote Tier aber soll ihm selbst gehören.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, 'Wenn jemandes Rind das Rind eines andern totstößt, so sollen sie das lebende Rind verkaufen und den Erlös dafür unter sich teilen; auch das tote sollen sie unter sich teilen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'Wenn es aber bekannt war, daß das Rind schon längst stößig war, und sein Besitzer es nicht sorgfältig gehütet hat, soll er als Ersatz für jenes Rind ein Rind hergeben, das tote aber soll ihm zufallen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 37, 'Wenn jemand ein Rind oder ein Schaf stiehlt und es schlachtet oder verkauft, soll er fünf Stück Rinder für ein Rind und vier Stück Schafe für ein Schaf als Buße entrichten;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, 'Wenn der Dieb beim nächtlichen Einbruch betroffen und dabei tot geschlagen wird, so erwächst für den Totschläger keine Blutschuld.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'Wenn ihm aber die Sonne bereits geschienen hat, so erwächst für ihn Blutschuld, er muß Ersatz leisten, und wenn er nicht hat, soll er als Entgelt für seinen Diebstahl als Sklave verkauft werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'Wenn das gestohlene, sei es nun ein Rind oder ein Esel oder ein Schaf, lebendig bei ihm vorgefunden wird, so soll er je noch ein zweites Tier als Buße entrichten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, 'Wenn jemand seinen Acker oder Weinberg beweiden, sein Vieh aber frei laufen läßt, und dasselbe auf einem fremden Acker etwas frißt, so soll er von dem seinigen entsprechend dem Ertrage desselben Ersatz leisten; wenn es aber den ganzen Acker abweidet, soll er das Beste von dem Ertrage seines Ackers oder Weinbergs als Ersatz entrichten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'Wenn Feuer auskommt und das Gestrüpp ergreift, hernach aber ein Getreidehaufen oder das in Halmen stehende Korn oder überhaupt Ackerfrüchte verbrennen, so muß der, welcher den Brand verursacht hat, vollen Ersatz leisten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, 'Wenn einer dem andern Geld oder Kostbarkeiten zum Aufbewahren übergeben hat, und dies aus dem Hause des Betreffenden gestohlen wird, so muß der Dieb, wenn er ausfindig gemacht wird, das Doppelte als Ersatz entrichten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, 'Wenn jedoch der Dieb nicht ausfindig gemacht wird, so soll der Besitzer des Hauses vor Gott hintreten, damit entschieden werde, daß er sich am Eigentume des anderen nicht vergriffen habe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, 'Bei irgend einem Eigentumsverbrechen, mag es sich nun um ein Rind handeln oder um einen Esel, ein Schaf, ein Obergewand oder überhaupt etwas abhanden Gekommenes, von dem einer behauptet: das ist es! soll die Angelegenheit beider vor Gott gebracht werden, und wenn ihn Gott für schuldig erklärt, soll er dem anderen als Ersatz das Doppelte entrichten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, 'Wenn einer dem anderen einen Esel oder ein Rind oder ein Schaf, überhaupt irgend ein Stück Vieh zum Hüten übergiebt, und dieses umkommt oder Schaden nimmt oder weggeschleppt wird, ohne daß es jemand sieht,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, 'so soll ein Eid bei Jahwe den Handel entscheiden, ob er sich etwa an dem Eigentume des anderen vergriffen hat; wenn der Besitzer diesen annimmt, braucht jener keinen Ersatz zu leisten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'Wenn es ihm gestohlen worden ist, so soll er es seinem Besitzer ersetzen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'Wenn es von einem wilden Tiere zerrissen worden ist, und er es zum Beweise beibringen kann, braucht er für das Zerrissene keinen Ersatz zu leisten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 'Wenn einer von dem anderen ein Stück Vieh entleiht, und dasselbe Schaden nimmt oder umkommt, ohne daß sein Besitzer zugegen gewesen ist, so muß es jener ersetzen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, 'Wenn aber der Besitzer zugegen gewesen ist, braucht der andere keinen Ersatz zu leisten. Ist er aber ein Löhner, so kommt es auf seinen Lohn.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, 'Wenn jemand eine Jungfrau, die noch unverlobt ist, verführt und ihr beiwohnt, so soll er für sie das Kaufgeld entrichten und sie sich zum Weibe nehmen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, 'Wenn sich jedoch ihr Vater weigern sollte, sie ihm zur Frau zu geben, so soll er so viel Silber darwägen, als das Kaufgeld für Jungfrauen beträgt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'Eine Zauberin sollst du nicht am Leben lassen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, 'Jeder, der mit einem Tiere Unzucht treibt, soll mit dem Tode bestraft werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, 'Wenn jemand den Götzen opfert, anstatt Jahwe allein, soll er dem Banne verfallen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'Einen Fremdling sollst du nicht drücken noch gewaltthätig behandeln; denn ihr seid auch Fremdlinge gewesen in Ägypten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, 'Eine Witwe oder Waise sollt ihr nimmermehr bedrücken.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'Denn wenn du sie bedrückst, und sie dann um Hilfe zu mir schreit, so werde ich ihren Hilferuf sicher erhören');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'und werde in Zorn geraten und euch durch das Schwert umbringen, so daß eure eigenen Weiber Witwen und eure Kinder Waisen werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'Wenn du jemand aus meinem Volk, einem Armen, der bei dir wohnt, Geld leihst, so behandle ihn nicht wie ein Wucherer; ihr sollt ihm keine Zinsen auferlegen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, 'Wenn du einem das Obergewand als Pfand wegnimmst, so sollst du es ihm bis Sonnenuntergang zurückgeben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'Denn sein Mantel ist ja seine einzige Körperdecke; womit könnte er sich sonst auf seinem Lager zudecken? Wenn er mich aber um Hilfe anruft, so will ich ihn erhören; denn ich bin barmherzig.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'Gott sollst du nicht lästern und einen Vorgesetzten deines Volkes nicht verwünschen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, 'Deinen Überfluß und das Beste deines Kelterertrags sollst du nicht vorenthalten. Den Erstgeborenen deiner Söhne sollst du mir geben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, 'Ebenso sollst du es halten mit deinem Rind und deinem Schaf: sieben Tage hindurch soll es bei seiner Mutter bleiben; am achten Tage sollst du es mir darbringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'Und ihr sollt mir reine Leute sein. Fleisch aber, das im Freien von wilden Tieren zerrissen worden ist, dürft ihr nicht genießen, sondern sollt es den Hunden vorwerfen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, 'Du sollst kein falsches Gerücht aussprengen. Biete dem, der eine ungerechte Sache hat, nicht die Hand, für ihn Zeugnis abzulgen und so das Recht zu verdrehen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, 'Du sollst nicht dem großen Haufen folgen, um Böses zu thun. Bei einer Rechtssache sollst du nicht, der Mehrheit dich anschließend, Aussagen machen und so das Recht beugen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'Du sollst nicht die Partei des Angesehenen ergreifen, wenn er eine Rechtssache hat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, 'Wenn du einen deinem Feinde gehörenden Ochsen oder Esel findest, der sich verirrt hat, so sollst du ihm denselben zurückbringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'Wenn du siehst, daß der Esel deines Feindes unter seiner Last zusammengebrochen ist, so gehe nicht etwa an ihm vorüber, sondern hilf ihm, den Esel zu befreien.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'Du sollst das Recht des Armen, der unter euch ist, nicht beugen, wenn er eine Streitsache hat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'halte dich fern von einer Sache, bei der Lüge im Spiel ist, und hilf nicht einen Unschuldigen oder der eine gerechte Sache hat, verurteilen; denn ich spreche keinen frei, der schuldig ist.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, 'Und Geschenke nimm nicht an; denn Geschenke machen Sehende blind und verkehren die gerechte Sache.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, 'Einen Fremdling sollst du nicht hart behandeln; ihr wißt ja, wie es dem Fremden zu Mute ist, weil ihr selbst Fremdlinge gewesen seid in Ägypten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, 'Sechs Jahre hindurch sollst du dein Land bebauen und seinen Ertrag einheimsen;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'im siebenten Jahre aber sollst du es brach liegen lassen und frei geben, so daß die Bedürftigen deines Volks ihre Nahrung holen können, und was sie übrig lassen, mögen die wilden Tiere fressen; ebenso sollst du verfahren mit deinem Weinberg und deinem Ölgarten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, 'Sechs Tage hindurch magst du deine Arbeit verrichten; am siebenten Tag aber sollst du feiern, damit dein Rind und dein Esel ruhe, und der Sohn deiner Sklavin, sowie der Fremdling einmal aufatme.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'Und in Bezug auf alles, was ich euch befohlen habe, nehmt euch wohl in acht! Den Namen anderer Götter erwähnet nicht; er soll dir nicht über die Lippen kommen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, 'Dreimal im Jahre sollst du mir eine Festfeier abhalten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, 'Das Fest der ungesäuerten Brote sollst du halten: sieben Tage lang sollst du ungesäuerte Brote essen, wie ich es dir befohlen habe, zur Zeit des Monats Abib; denn in ihm bist du aus Ägypten ausgezogen. Vor mir soll man nicht mit leeren Händen erscheinen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'Und das Fest der Kornernte, der Erstlinge deines Landbaus, den du betreibst, und das Fest der Herbstlese um die Wende des Jahres, wenn du die Bodenerzeugnisse einheimsest.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, 'Dreimal im Jahre soll alles, was männlich ist, vor dem Herrn, Jahwe, erscheinen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, 'Du sollst mir nicht zu gesäuerten Broten das Blut meines Opfers darbringen, und das Fett meines Festopfers soll nicht bis zum folgenden Tag aufbewahrt werrden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, 'Das Vorzüglichste, die Erstlinge deines Ackerbodens, sollst du zum Hause Jahwes, deines Gottes, bringen. Du sollst ein Böckchen nicht in der Milch seiner Mutter kochen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, 'Ich aber will einen Engel vor dir einhergehen lassen um dich unterwegs in meine Hut zu nehmen und dich an die Stätte zu bringen, die ich festgesetzt habe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'Nimm dich vor ihm in acht und gehorche ihm; sei nicht widerspenstig gegen ihn. Denn er wird euch eure Übertretung nicht verzeihen, denn er ist eine Offenbarung meines Wesens!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'Wenn du aber seinen Worten gehorchen und alles thun willst, was ich befehle, so will ich befeinden, die dir feind sind, und bedrängen, die dich bedrängen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'Ja mein Engel soll vor dir einherziehen und dich zu den Amoritern, Hethitern, Pheresitern, Kanaanitern, Hevitern und Jebusitern führen, damit ich sie ausrotte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'Bete ihre Götter nicht an und diene ihnen nicht und ahme ihr Thun nicht nach, sondern zerstöre sie von Grund aus und zerschmettere ihre Malsteine.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'Verehrt Jahwe, euren Gott, so wird er dir reichlich Speise und Trank gewähren, und Krankheiten will ich von dir fernhalten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, 'Nichts Kinderloses noch Unfruchtbares wird es in deinem Lande geben, und ich werde dich am Leben erhalten bis ins volle Alter.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, 'Einen Gottes-Schrecken werde ich vor dir hersenden und alle die Völker, unter welche du kommen wirst, in Verwirrung bringen und will machen, daß alle deine Feinde vor dir die Flucht ergreifen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'Und ich werde Hornissen vor dir hersenden, damit sie die Heviter, die Kanaaniter und die Hethiter vor dir her vertreiben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, 'Ich will sie aber nicht im Verlauf eines Jahres vor dir vertreiben, sonst würde das Land zur Wüste werden, und die wilden Tiere würden zu deinem Schaden überhandnehmen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, 'Ganz allmählich will ich sie vor dir vertreiben, bis ihr zahlreich genug sein werdet, um euch in den Besitz des Landes zu setzen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, 'Und ich will dein Gebiet reichen lassen vom Schilfmeer bis zum Meer der Philister und von der Wüste bis zum Euphrat-Strom; ja ich werde die Landesbewohner in eure Gewalt gegeben, und du sollst sie vor dir austreiben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'Du darfst weder mit ihnen noch mit ihren Göttern ein Abkommen schließen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'Sie sollen nicht wohnen bleiben in deinem Lande, daß sie dich nicht zur Versündigung an mir verleiten; denn wenn du ihre Götter verehrst, so wird dir das zum Fallstrick werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, 'Und zu Mose sprach er: Steige zu Jahwe hinauf, du und Aaron, Nadab und Abihu, sowie siebzig von den Vornehmen der Israeliten, und bringt ihm, ferne stehend, eure Verehrung dar.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'Mose aber soll allein näher zu Jahwe herantreten, während sie nicht herantreten dürfen, und das Volk soll nicht mit ihm hinaufsteigen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'Da ging Mose hin und trug dem Volk alle Gebote und alle Rechtssatzungen Jahwes vor; da antwortete das ganze Volk einmütig: Alle die Gebote, die Jahwe gegeben hat, wollen wir halten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'Da schrieb Mose die Gebote Jahwes auf. Am anderen Morgen früh aber errichtete er einen Altar am Fuß des Berges, sowie zwölf Malsteine nach der Zahl der zwölf Stämme Israels.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'Dann gab er den jungen Männern unter den Israeliten den Auftrag, Jahwe Brandopfer darzubringen und als Heilsopfer junge Stiere zu schlachten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'Sodann nahm Mose die Hälfte des Blutes und goß es in die Opferbecken; die andere Hälfte des Blutes aber sprengte er auf den Altar.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'Dann nahm er das Buch mit dem Bundesgesetz und las es dem Volke laut vor. Sie aber sprachen: Alles, was Jahwe befohlen hat, wollen wir halten und befolgen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'Hierauf nahm Mose das Blut und besprengte damit das Volk, indem er sprach: Das ist das Blut des Bundes, den Jahwe mit euch geschlossen hat auf Grund aller jener Gebote.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, 'Da stiegen Mose und Aaron, Nadab und Abihu, sowie siebzig von den Vornehmen der Israeliten hinauf');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'und sie erblickten den Gott Israels; zu seinen Füßen war ein Boden wie aus Sapphirstein und glänzend hell wie der Himmel selbst.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'Wider die Auserwählten der Israeliten aber reckte er seine Hand nicht aus; sie schauten Gott und aßen und tranken.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'Da befahl Jahwe Mose: Steige zu mir auf den Berg herauf und verweile daselbst; so will ich dir die Steintafeln mit dem Gesetz und den Geboten geben, die ich aufgeschrieben habe, um sie zu unterweisen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'Und Mose machte sich mit seinem Diener Josua auf; Mose aber stieg auf den Berg Gottes.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'Jenen Vornehmen aber befahl er: Wartet hier auf uns, bis wir wieder zu euch kommen; Aaron und Hur sind ja bei euch. Wer eine Rechtssache hat, mag vor sie hintreten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'Als nun Mose auf den Berg gestiegen war, hüllte die Wolke den Berg ein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'Und die Herrlichkeit Jahwes thronte auf dem Berge Sinai. Die Wolke aber hüllte ihn sechs Tage lang ein; am siebenten Tage rief er Mose aus der Wolke zu.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'Die Herrlichkeit Jahwes aber auf dem Gipfel des Berges stellte sich den Augen der Israeliten dar wie ein verzehrendes Feuer.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'Da begab sich Mose in die Wolke hinein und stieg auf den Berg. Hierauf blieb Mose vierzig Tage und vierzig Nächte auf dem Berge.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'Und Jahwe redete zu Mose:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, 'Gebiete den Israeliten, daß sie eine Beisteuer für mich erheben; von einem jeden, den sein Herz dazu treibt, sollt ihr die Beisteuer für mich erheben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'In den folgenden Dingen soll die Beisteuer bestehen, die ihr von ihnen erheben sollt: in Gold, Silber und Kupfer;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'in blauem Purpur, rotem Purpur, Karmesin, Byssus und Ziegenhaar;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, 'in rotgefärbten Widderfellen und Seekuhfellen, in Akazienholz,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, 'in Öl für den Leuchter, Spezereien für das Salböl und das wohlriechende Räucherwerk,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'in Schohamsteinen und in Edelsteinen zum Besetzen des Schulterkleids und des Brustschilds.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'Und sie sollen mir ein Heiligtum errichten, daß ich mitten unter ihnen wohne.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'Genau nach dem Modell der Wohnung und aller ihrer Geräte, das ich dir zeige, sollt ihr es errichten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, 'Und zwar sollen sie eine Lade von Akazienholz anfertigen, zwei und eine halbe Elle lang, anderthalbe Elle breit und anderthalbe Elle hoch;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'die sollst du mit gediegenem Gold überziehen - inwendig und auswendig mußt du sie überziehen - und sollst einen ringsumlaufenden goldenen Kranz an ihr anbringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'Weiter sollst du für sie vier goldene Ringe gießen und diese an ihren vier Füßen befestigen, und zwar zwei Ringe auf ihrer einen Seite und zwei Ringe auf ihrer anderen Seite.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'Sodann sollst du Stangen von Akazienholz anfertigen und sie mit Gold überziehen;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'diese Stangen sollst du durch die Ringe ziehen, die an den Seiten der Lade sind, damit man mittels ihrer die Lade tragen kann.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'In den Ringen an der Lade sollen die Stangen bleiben; sie dürfen nicht aus ihnen entfernt werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'In die Lade aber sollst du das Gesetz legen, das ich dir übergeben werde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, 'Sodann sollst du eine Deckplatte aus gediegenem Gold anfertigen, zwei und eine halbe Elle lang und anderthalbe Elle breit.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'Und du sollst zwei goldene Kerube anfertigen - in getriebener Arbeit sollst du sie anfertigen - an den beiden Enden der Deckplatte,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'und bringe den einen Kerub an dem einen Ende an und den anderen Kerub an dem anderen Ende. An der Deckplatte sollst du die Kerube anbringen, an ihren beiden Enden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'Es sollen aber die Kerube ihre Flügel nach oben ausgebreitet halten, indem sie mit ihren Flügeln die Deckplatte überdecken, während ihre Gesichter einander zugekehrt sind; gegen die Deckplatte hin sollen die Gesichter der Kerube gerichtet sein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'Sodann sollst du die Deckplatte oben auf die Lade legen; in die Lade aber sollst du das Gesetz legen, das ich dir übergeben werde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'Und dort werde ich mich dir offenbaren und mit dir reden von der Deckplatte aus, von dem Ort zwischen den beiden Keruben, die sich auf der Gesetzeslade befinden, so oft ich dir Befehle an die Israeliten zu übertragen habe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, 'Sodann sollst du einen Tisch aus Akazienholz anfertigen, zwei Ellen lang, eine Elle breit und anderthalbe Elle hoch.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'Den sollst du mit gediegenem Gold überziehen und einen ringsumlaufenden goldenen Kranz an ihm anbringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'Sodann sollst du eine in Handbreite ringsumlaufende Leiste an ihm anbringen und an dieser Leiste wiederum einen ringsumlaufenden goldenen Kranz.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'Weiter sollst du vier goldene Ringe für ihn anfertigen und diese Ringe an den vier Ecken seiner vier Füße befestigen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'Dicht an der Leiste sollen sich die Ringe befinden, zur Aufnahme von Stangen, damit man den Tisch tragen kann.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'Die Stangen aber sollst du aus Akazienholz anfertigen und sie mit Gold überziehen; mit ihnen soll dann der Tisch getragen werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, 'Und du sollst die zu ihm gehörenden Schüsseln und Schalen, sowie die Kannen und Becher, mit denen das Trankopfer gespendet wird, anfertigen; aus gediegenem Golde sollst du sie anfertigen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'Auf den Tisch aber sollst du beständig Schaubrote vor mich legen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, 'Ferner sollst du einen Leuchter von gediegenem Gold anfertigen; in getriebener Arbeit soll dieser Leuchter, sein Fußgestell und sein Schaft angefertigt werden, und an ihm sollen sich Blumenkelche - Knollen mit Blüten - befinden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'Von seinen Seiten aber sollen sechs Röhren ausgehen, je drei auf jeder Seite des Leuchters.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, 'An jeder Röhre sollen sich drei mandelblütenförmige Blumenkelche - je ein Knollen mit Blüte - befinden; so an allen sechs Röhren, die von dem Leuchter ausgehen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'Am Leuchter selbst aber sollen sich vier Blumenkelche befinden, mandelblütenförmige Knollen mit Blüten,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'und zwar jedesmal ein Knollen unter jedem der drei Röhrenpaare an ihm, - der sechs Röhren, die von dem Leuchter ausgehen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'Ihre Knollen und Röhren sollen aus einem Stück mit ihm sein; alles getriebene Arbeit aus einem Stück, von gediegenem Golde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, 'Du sollst auch sieben Lampen für ihn anfertigen, und man soll ihm die Lampen aufsetzen, damit sie den Platz vor ihm beleuchten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'Die zu ihm gehörenden Lichtscheren und Pfannen sollen aus gediegenem Golde sein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'Ein Talent gediegenen Goldes soll man auf ihn und alle die erwähnten Geräte verwenden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, 'Und sieh zu, daß du sie genau nach dem Modell anfertigst, das dir auf dem Berge gezeigt wurde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, 'Die Wohnung aber sollst du anfertigen aus zehn Teppichen aus gezwirntem Byssus, blauem und rotem Purpur und Karmesin; mit Keruben, wie sie der Kunstwirker macht, sollst du sie anfertigen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'Jeder Teppich soll 28 Ellen lang und vier Ellen breit sein; alle Teppiche sollen einerlei Maß haben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'Je fünf Teppiche sollen aneinander gefügt sein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'Sodann sollst du am Saume des äußersten Teppichs der einen Fläche Schleifen von blauem Purpur anbringen und ebenso am Saume des äußersten Teppichs der andern Fläche.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'Fünfzig Schleifen sollst du an dem einen Teppich anbringen und fünfzig Schleifen sollst du am Rande des Teppichs anbringen, der zu der anderen Fläche gehört, so daß die Schleifen einander gegenüberstehen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'Sodann sollst du fünfzig goldene Haken anfertigen und die Teppiche mittels der Haken zusammenfügen, so daß die Wohnung ein Ganzes wird.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'Weiter sollst du Teppiche aus Ziegenhaar fertigen, zum Zeltdach über der Wohnung; elf Teppiche sollst du dazu anfertigen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'Jeder Teppich soll dreißig Ellen lang und vier Ellen breit sein; 8 alle elf Teppiche sollen einerlei Maß haben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'Fünf von diesen Teppichen sollst du für sich zu einem Ganzen verbinden und ebenso die sechs andern für sich; und zwar sollst du den sechsten Teppich auf der Vorderseite des Zeltes doppelt legen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'Sodann sollst du am Saume des äußersten Teppichs der einen Fläche fünfzig Schleifen anbringen und ebenso fünfzig Schleifen am Saume des äußersten Teppichs der andern Fläche.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'Und du sollst fünfzig kupferne Haken anfertigen und die Haken durch die Schleifen ziehen und so das Zeltdach zusammenfügen, so daß es ein Ganzes wird.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'Und was das Überhängen des an den Zeltteppichen Überschüssigen betrifft, so soll die Hälfte des überschüssigen Teppichs auf der Rückseite der Wohnung herabhängen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'Und von dem, was an der Länge der übrigen Zeltteppiche überschüssig ist, soll auf beiden Seiten jedesmal eine Elle über die Langseiten der Wohnung überhängen und diese so bedecken.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, 'Sodann sollst du eine Überdecke für das Zeltdach anfertigen aus rotgefärbten Widderfellen und eine Überdecke von Seekuhfellen oben darüber.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, 'Ferner sollst du die Bretter zur Wohnung anfertigen, aufrechtstehende, von Akazienholz.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'Jedes Brett soll zehn Ellen lang und anderthalbe Elle breit sein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'Jedes Brett soll zwei Zapfen haben, die untereinander verbunden sind; in dieser Weise sollst du alle Bretter der Wohnung anfertigen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'Und zwar sollst du an Brettern für die Wohnung anfertigen: zwanzig Bretter für die nach Süden gewendete Seite;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, 'und sollst vierzig silberne Füße unter den zwanzig Brettern anbringen, je zwei Füße unter jedem Brette für die beiden Zapfen desselben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'Ebenso für die andere Seite der Wohnung, in der Richtung nach Norden, zwanzig Bretter');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'mit ihren vierzig silbernen Füßen, je zwei Füßen unter jedem Brette.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'Für die nach Westen gerichtete Seite der Wohnung aber sollst du sechs Bretter anfertigen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'Und zwei Bretter sollst du anfertigen für die Winkel der Wohnung auf der Hinterseite. Und sie sollen doppelt sein im unteren Teil und ebenso sollen sie doppelt sein am oberen Ende für den einen Ring.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'So sollen beide beschaffen sein; die beiden Winkel sollen sie bilden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'Somit sollen es acht Bretter sein mit ihren silbernen Füßen, - sechszehn Füßen, je zwei Füßen unter jedem Brette.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, 'Weiter sollst du fünf Riegel aus Akazienholz anfertigen für die Bretter der einen Seite der Wohnung,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'fünf Riegel für die Bretter der anderen Seite der Wohnung und fünf Riegel für die Bretter der nach Westen gerichteten Hinterseite der Wohnung.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'Und der mittelste Riegel soll in der Mitte der Bretter quer durchlaufen von einem Ende bis zum andern.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'Die Bretter aber sollst du mit Gold überziehen; auch die Ringe an ihnen, die zur Aufnahme der Riegel bestimmt sind, sollst du aus Gold anfertigen und auch die Riegel mit Gold überziehen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, 'So sollst du die Wohnung aufrichten nach Gebühr, wie es dir auf dem Berge gezeigt wurde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, 'Ferner sollst du einen Vorhang anfertigen aus blauem und rotem Purpur, Karmesin und gezwirntem Byssus; in Kunstwirker-Arbeit soll man ihn herstellen mit Keruben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'Befestige ihn an vier mit Gold überzogenen Säulen von Akazienholz, die goldene Nägel haben und auf vier silbernen Füßen stehen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'Es soll aber der Vorhang seine Stelle haben unter den Haken; und hinein hinter den Vorhang sollst du die Lade mit dem Gesetze bringen. So soll euch der Vorhang als eine Scheidewand dienen zwischen dem Heiligen und dem Allerheiligsten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'Und du sollst die Deckplatte auf die Gesetzeslade thun, im Allerheiligsten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'Den Tisch aber sollst du außerhalb des Vorhangs aufstellen und den Leuchter gegenüber dem Tisch auf der Südseite der Wohnung, während du den Tisch auf die Nordseite stellst.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, 'Ferner sollst du einen Vorhang anfertigen für die Thüröffnung des Zeltes aus blauem und rotem Purpur, Karmesin und gezwirntem Byssus, in Buntwirker-Arbeit.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'Und für diesen Vorhang sollst du fünf Säulen aus Akazienholz anfertigen und sie mit Gold überziehen; auch die zugehörigen Nägel sollen von Gold sein. Und du sollst fünf kupferne Füße für sie gießen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, 'Den Altar sollst du aus Akazienholz anfertigen, fünf Ellen lang und fünf Ellen breit - viereckig soll der Altar sein - und drei Ellen hoch.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'Und die zugehörigen Hörner sollst du an seinen vier Ecken anbringen, so daß die Hörner ein Ganzes mit ihm bilden, und sollst ihn mit Kupfer überziehen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'Und die zugehörigen Töpfe, die man braucht, um ihn vom Fett zu säubern, wie die zugehörigen Schaufeln, Becken, Gabeln und Pfannen, alle zu ihm gehörenden Geräte, sollst du aus Kupfer anfertigen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'Ferner sollst du ein Gitterwerk für ihn anfertigen, ein Netzwerk aus Kupfer, und sollst an dem Netze vier kupferne Ringe anbringen, an den vier Ecken des Altars,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'und sollst es unterhalb des den Altar umlaufenden Simses befestigen, so daß das Netz bis zur Mitte des Altars reicht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'Ferner sollst du Stangen für den Altar anfertigen, Stangen aus Akazienholz, und sie mit Kupfer überziehen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'Diese seine Stangen sollen durch die Ringe gezogen werden, so daß sich die Stangen auf den beiden Seiten des Altars befinden, wenn man ihn trägt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'Aus Brettern, so daß er inwendig hohl ist, sollst du ihn herstellen; wie man es dir auf dem Berge gezeigt hat, so sollen sie es machen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, 'Und den Vorhof der Wohnung sollst du so herstellen: für die nach Süden gewendete Seite Vorhof-Umhänge aus gezwirntem Byssus, hundert Ellen lang, für die eine Seite;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'dazu zwanzig Säulen nebst ihren zwanzig kupfernen Füßen - die Nägel der Säulen und die zugehörigen Ringe sollen von Silber sein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'Ebenso Umhänge für die nördliche Langseite, hundert Ellen; dazu zwanzig Säulen nebst ihren zwanzig kupfernen Füßen, die Nägel der Säulen und die zugehörigen Ringe von Silber.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'Die westliche Breitseite des Vorhofs aber soll Umhänge von fünfzig Ellen haben, dazu zehn Säulen nebst ihren zehn Füßen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'Und die nach Osten gewendete Breitseite des Vorhofs soll fünfzig Ellen betragen;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, 'und zwar sollen fünfzehn Ellen Umhänge, dazu drei Säulen nebst ihren drei Füßen, auf die eine Seite kommen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'und ebenso auf die andere Seite fünfzehn Ellen Umhänge, dazu drei Säulen nebst ihren drei Füßen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'Das Thor des Vorhofs aber soll einen Vorhang haben, zwanzig Ellen breit, von blauem und rotem Purpur, Karmesin und gezwirntem Byssus in Buntwirker-Arbeit; dazu vier Säulen nebst ihren vier Füßen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'Alle Säulen des Vorhofs ringsum sollen mit silbernen Ringen versehen sein; auch die Nägel an ihnen sollen von Silber sein, ihre Füße aber von Kupfer.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'Die Länge des Vorhofs soll hundert Ellen betragen, die Breite fünfzig Ellen und die Höhe fünf Ellen aus gezwirntem Byssus, mit kupfernen Füßen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'Und alle Geräte der Wohnung, deren man bedarf bei dem gesamten heiligen Dienst an ihr, und alle ihre Pflöcke und alle Pflöcke des Vorhofs sollen aus Kupfer sein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, 'Du aber gebiete den Israeliten, daß sie dir lauteres Öl aus zerstoßenen Oliven für den Leuchter herbeibringen, damit man beständig Lampen aufstecken kann.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'Im Offenbarungszelt, außerhalb des Vorhangs, welcher sich vor dem Gesetze befindet, soll ihn Aaron mit seinen Söhnen herrichten, daß er vom Abend bis zum Morgen vor Jahwe brenne. Solches ist den Israeliten als eine für alle Zeiten und alle Geschlechter geltende Verpflichtung auferlegt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, 'Du aber laß aus der Gesamtheit der Israeliten deinen Bruder Aaron nebst seinen Söhnen zu dir herantreten, damit er mir Priesterdienst thue, Aaron, Nadab und Abihu, Eleasar und Ithamar, die Söhne Aarons.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'Und du sollst für deinen Bruder Aaron heilige Kleider anfertigen, zur Ehre und herrlichen Zier.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'Und rede mit allen Kunstverständigen, die ich mit künstlerischem Geist erfüllt habe, daß sie die Kleider Aarons anfertigen sollen, damit man ihn weihen, und er mir Priesterdienst thun kann.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'Dies aber sind die Kleider, die sie anfertigen sollen: Tasche, Schulterkleid, Obergewand, Leibrock aus gewürfeltem Zeug, Kopfbund und Gürtel.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'Und sie sollen deinem Bruder Aaron und seinen Söhnen heilige Kleider anfertigen, damit er mir Priesterdienst thue. Und zwar sollen sie dazu das Gold, den blauen und roten Purpur, den Karmesin und den Byssus verwenden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, 'Sie sollen aber das Schulterkleid anfertigen aus Gold, blauem und rotem Purpur, Karmesin und gezwirntem Byssus, in Kunstwirker-Arbeit.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'Zwei mit ihm verbundene Schulterstücke soll es haben; an seinen beiden Enden soll es mit ihnen verbunden werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'Und die Binde, die sich behufs seiner Anlegung an ihm befindet, soll von gleicher Arbeit sein und ein Ganzes mit ihm bilden, aus Gold, blauem und rotem Purpur, Karmesin und gezwirntem Byssus.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, 'Hierauf sollst du die beiden Schohamsteine nehmen und in dieselben die Namen der Israels-Söhne eingraben,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'sechs ihrer Namen auf den einen Stein und die sechs übrigen Namen auf den anderen Stein, nach der Reihenfolge ihrer Geburt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'Mittels Steinschneider-Arbeit - Siegelstecherkunst - sollst du die beiden Steine gravieren, nach Maßgabe der Namen der Israels-Söhne, und sollst sie mit einem Flechtwerk von Golddraht einfassen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'Diese beiden Steine sollst du auf den Schulterstücken des Schulterkleids befestigen, als Steine des gnädigen Gedenkens an die Israeliten; so soll Aaron ihre Namen auf seinen beiden Schultern vor Jahwe tragen, daß ihrer gnädig gedacht werde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'Ferner sollst du Goldgeflechte anfertigen');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'und zwei Kettchen von gediegenem Gold; in Gestalt von gedrehten Schnuren sollst du sie herstellen und sollst diese aus Schnuren gefertigten Kettchen an den Geflechten befestigen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, 'Weiter sollst du eine Orakel-Tasche anfertigen, in Kunstwirker-Arbeit. So wie das Schulterkleid gearbeitet ist, sollst du sie anfertigen; aus Gold, blauem und rotem Purpur, Karmesin und gezwirntem Byssus sollst du sie anfertigen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, 'Viereckig soll sie sein, doppelt gelegt, je eine Spanne lang und breit.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, 'Und du sollst sie besetzen mit einem Besatze von Edelsteinen in vier Reihen: ein Carneol, ein Topas und ein Smaragd sollen der Reihe nach die erste Reihe bilden;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, 'die zweite Reihe ein Karfunkel, ein Sapphir und ein Jaspis;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'die dritte Reihe ein Hyacinth, ein Achat und ein Amethyst;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, 'die vierte Reihe ein Chrysolith, ein Schoham und ein Onyx; umgeben von Goldgeflecht sollen sie den Besatz bilden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'Und der Steine sollen entsprechend den Namen der Israels-Söhne zwölf sein, entsprechend ihren Namen; in einem jeden soll der Name eines der zwölf Stämme mittels Siegelstecherarbeit eingegraben sein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, 'Sodann sollst du an der Tasche die schnurenartig gedrehten Kettchen von gediegenem Gold anbringen');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'und sollst an der Tasche zwei goldene Ringe anbringen, indem du die beiden Ringe an den beiden Enden der Tasche befestigst.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'Hierauf sollst du die beiden goldenen Schnuren an den beiden Ringen an den Enden der Tasche befestigen;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'die beiden Enden der beiden Schnuren aber sollst du an den beiden Geflechten befestigen und diese dann an den Schulterstücken des Schulterkleids auf dessen Vorderseite befestigen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'Ferner sollst du zwei goldene Ringe anfertigen und sie an den beiden Enden der Tasche befestigen, an ihrem inneren, dem Schulterkleide zugewendeten Rand.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'Weiter sollst du zwei goldene Ringe anfertigen und sie an den beiden Schulterstücken des Schulterkleids ganz unten an seiner Vorderseite befestigen, da, wo es mit den Schulterstücken zusammenhängt, oberhalb der Binde des Schulterkleids.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'Und man soll die Tasche mit ihren Ringen mittels Schnuren von blauem Purpur an die Ringe des Schulterkleids anketten, so daß sie über der Binde des Schulterkleids liegt; so wird die Tasche unbeweglich auf dem Schulterkleid aufliegen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'Und Aaron soll die Namen der Israels-Söhne an der Orakel-Tasche auf seiner Brust tragen, wenn er hineingeht ins Heiligtum, im Angesicht Jahwes, damit er ihrer allezeit gnädig gedenke.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, 'In die Orakel-Tasche aber sollst du die Urim und die Tummim thun, damit sie auf der Brust Aarons liegen, wenn er hineingeht vor Jahwe, und so soll Aaron das Orakel für die Israeliten beständig vor Jahwe auf seiner Brust tragen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, 'Und das Obergewand zum Schulterkleide sollst du ganz und gar aus blauem Purpur anfertigen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, 'so, daß sich eine Öffnung für den Kopf in ihm befindet. Diese seine Öffnung soll rings von einem angewebten Saume eingefaßt sein; eine Öffnung, wie die eines Panzerhemdes, soll es haben, damit es nicht zerreißt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'An seinem Saume aber sollst du Granatäpfel aus blauem und rotem Purpur und Karmesin anbringen - an seinem Saume ringsum - und inmitten derselben goldene Glöckchen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'so, daß immer ein goldenes Glöckchen und ein Granatapfel ringsum am Saume des Obergewands miteinander abwechseln.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'Und Aaron soll es tragen, um den heiligen Dienst zu verrichten, und man soll es klingen hören, wenn er hineingeht ins Heiligtum vor Jahwe und wenn er herauskommt, damit er nicht sterbe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, 'Ferner sollst du ein Stirnblatt von gediegenem Gold anfertigen und darauf in Siegelstecher-Arbeit eingraben: “Geheiligt dem Jahwe”,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'und sollst es an einer Schnur von blauem Purpur befestigen, damit es sich am Kopfbund befinde; an der Vorderseite des Kopfbundes soll es sich befinden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'Es soll aber auf der Stirn Aarons liegen, damit Aaron so die Verfehlungen in betreff der heiligen Dinge - aller der geweihten Gaben, welche die Israeliten darbringen werden - auf sich nehme. Beständig soll es auf seiner Stirn liegen, damit es sie wohlgefällig mache vor Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, 'Den Leibrock aber sollst du aus Byssus würfelförmig gemustert weben und sollst einen Kopfbund aus Byssus anfertigen, sowie einen Gürtel in Buntwirker-Arbeit.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, 'Und für die Söhne Aarons sollst du Leibröcke anfertigen und Gürtel für sie anfertigen und hohe Mützen für sie anfertigen, zur Ehre und zur herrlichen Zier.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'Und du sollst Aaron und seine Söhne damit bekleiden und sollst sie salben und ihnen die Hand füllen und sie weihen, damit sie mir Priesterdienst thun.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'Und fertige ihnen linnene Beinkleider zur Bedeckung der Schamteile; von den Hüften bis zu den Schenkeln sollen sie reichen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'Und Aaron und seine Söhne sollen sie tragen, wenn sie in das Offenbarungszelt hineingehen und wenn sie an den Altar herantreten, um den Dienst im Heiligtum zu verrichten, damit sie nicht Schuld auf sich laden und sterben müssen. Solches gelte ihm und seinen Nachkommen als eine immerwährende Verpflichtung.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, 'Folgendermaßen sollst du mit ihnen verfahren, um sie zu weihen, damit sie mir Priesterdienst thun. Nimm einen jungen Stier und zwei fehllose Widder,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'ungesäuertes Brot und ungesäuerte, mit Öl gemengte Kuchen, sowie ungesäuerte, mit Öl bestrichene Fladen; aus Weizen-Feinmehl sollst du sie herstellen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'Hierauf sollst du sie in einen Korb thun und sie in dem Korbe darbringen, dazu den Farren und die beiden Widder.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, 'Aaron aber und seine Söhne laß an den Eingang zum Offenbarungszelt herantreten und wasche sie mit Wasser.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'Sodann nimm die Kleider, bekleide Aaron mit dem Leibrock, dem Obergewand zum Schulterkleid, dem Schulterkleid und der Tasche und binde ihm die Binde des Schulterkleids um;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'setze ihm den Kopfbund auf das Haupt und befestige das heilige Diadem am Kopfbund.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'Sodann nimm das Salböl, gieße es ihm aufs Haupt und salbe ihn so.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'Seine Söhne aber laß herzutreten, bekleide sie mit Leibröcken,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'umgürte sie mit einem Gürtel und setze ihnen Mützen auf, damit ihnen das Priesteramt zustehe kraft einer für alle Zeiten geltenden Ordnung. Sodann sollst du Aaron und seinen Söhnen die Hand füllen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, 'Und zwar sollst du den Farren herzubringen vor das Offenbarungszelt, damit Aaron und seine Söhne auf den Kopf des Farren die Hand aufstemmen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'Sodann schlachte den Farren vor Jahwe, am Eingang zum Offenbarungszelte,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'nimm etwas von dem Blute des Farren und streiche es mit dem Finger an die Hörner des Altars; das ganze übrige Blut aber gieße am Altar auf den Boden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'Sodann nimm alles Fett, welches die Eingeweide bedeckt, und das Anhängsel an der Leber, dazu die beiden Nieren samt dem Fett an ihnen und laß es auf dem Altar in Rauch aufgehn.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'Das Fleisch des Farren aber, sein Fell und seinen Mist sollst du außerhalb des Lagers verbrennen - ein Sündopfer ist es.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, 'Sodann bringe den einen Widder, damit Aaron und seine Söhne auf den Kopf des Widders die Hand aufstemmen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'Sodann schlachte den Widder, nimm sein Blut und sprenge es ringsum an den Altar.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'Den Widder selbst aber zerlege in seine Teile, wasche seine Eingeweide und seine Beine und lege sie zu seinen übrigen Stücken und zu seinem Kopfe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'Sodann laß den ganzen Widder auf dem Altar in Rauch aufgehn - ein Brandopfer für Jahwe ist es, ein lieblicher Geruch, ein Jahwe dargebrachtes Feueropfer.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, 'Sodann bringe den anderen Widder, damit Aaron und seine Söhne auf den Kopf des Widders die Hand aufstemmen;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'alsdann schlachte den Widder, nimm etwas von seinem Blut und streiche es an das rechte Ohrläppchen Aarons und an das rechte Ohrläppchen seiner Söhne, an ihren rechten Daumen und an ihre rechte große Zehe; das übrige Blut sprenge ringsum an den Altar.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'Sodann nimm etwas von dem Blute, das auf dem Altar ist, sowie von dem Salböl und sprenge es auf Aaron und seine Kleider, sowie auf seine Söhne und ihre Kleider, damit er und seine Kleider, sowie seine Söhne und ihre Kleider geheiligt seien.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, 'Sodann nimm von dem Widder das Fett, den Fettschwanz samt dem Fett, welches die Eingeweide bedeckt, das Anhängsel an der Leber und die beiden Nieren samt dem Fett an ihnen, dazu die rechte Keule - denn ein Einsetzungs-Widder ist es -,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, 'ferner einen Laib Brot, einen mit Öl angemachten Brotkuchen und einen Fladen aus dem Korbe mit dem Ungesäuerten, der vor Jahwe steht,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, 'und gieb dies alles Aaron und seinen Söhnen in die Hände und webe es als Webe vor Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'Sodann nimm es ihnen aus den Händen und laß es auf dem Altar über dem Brandopfer in Rauch aufgehn zum lieblichen Geruch vor Jahwe: ein Jahwe dargebrachtes Feueropfer ist es.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, 'Sodann nimm die Brust von dem Einsetzungs-Widder Aarons und webe sie als Webe vor Jahwe; dann soll sie dir als Anteil zufallen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, 'So sollst du die Webebrust, welche gewebt, und die Hebekeule, welche als Hebe weggenommen wurde von dem Einsetzungs-Widder Aarons und seiner Söhne, für etwas Geweihtes erklären;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'sie sollen Aaron und seinen Söhnen zufallen kraft einer den Israeliten für alle Zeit auferlegten Verpflichtung. Denn ein Hebeopfer ist es, und als Hebeopfer soll es von den Israeliten abgegeben werden von ihren Heilsopfern, als ihr Hebeopfer an Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'Die heiligen Kleider Aarons aber sollen nachmals auf seine Söhne übergehen, damit man sie darin salbe und ihnen die Hand fülle.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'Sieben Tage hindurch soll sie derjenige seiner Söhne anziehen, welcher an seiner Statt Priester wird, der in das Offenbarungszelt hineingehen wird, um den Dienst im Heiligtume zu verrichten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, 'Den Einsetzungs-Widder aber sollst du nehmen und sein Fleisch an heiliger Stätte kochen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'Und Aaron und seine Söhne sollen das Fleisch des Widders samt dem Brote, welches im Korbe ist, am Eingange zum Offenbarungszelte verzehren.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, 'Das, womit Sühne vollzogen wurde, als man ihnen die Hand füllte und sie weihte, sollen sie verzehren; ein Fremder aber darf nicht davon essen, denn es ist heilig.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'Und wenn von dem Fleische des Einsetzungsopfers oder von dem Brote etwas übrig bleibt bis zum Morgen, so sollst du das Übriggebliebene mit Feuer verbrennen: es darf nicht gegessen werden, denn es ist heilig.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, 'So sollst du mit Aaron und seinen Söhnen verfahren, ganz wie ich dir befohlen habe: sieben Tage hindurch sollst du ihnen die Hand füllen');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, 'und sollst für jeden Tag einen Sündopfer-Farren herrichten zum Vollzuge der Sühne und sollst den Altar entsündigen, indem du die Sühnehandlungen an ihm vollziehst, und sollst ihn salben, um ihn zu weihen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'Sieben Tage lang sollst du die Sühnehandlungen an dem Altar vollziehen, um ihn zu weihen; so wird der Altar hochheilig werden: jeder, der den Altar berührt, ist dem Heiligtume verfallen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, 'Folgendes aber sollst du auf dem Altar herrichten: Tag für Tag zwei einjährige Lämmer als regelmäßiges Brandopfer.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'Das eine Lamm sollst du am Morgen herrichten und das andere Lamm sollst du gegen Abend herrichten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'Und ein Zehntel Feinmehl, das mit einem Viertel Hin Öl aus zerstoßenen Oliven gemengt ist, sowie ein Trankopfer, bestehend in einem Viertel Hin Wein, soll zu dem einen Lamme kommen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'Das andere Lamm aber sollst du gegen Abend herrichten - in betreff des Speisopfers und Trankopfers sollst du dabei verfahren, wie am Morgen - zu einem lieblichen Geruch, als eine Jahwe dargebrachte Feuerspeise,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, 'als euer regelmäßiges Brandopfer von Geschlecht zu Geschlecht, am Eingange zum Offenbarungszelte vor Jahwe, woselbst ich mich dir offenbaren werde, indem ich daselbst mit dir rede.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, 'Und ich werde mich daselbst den Israeliten offenbaren, und es soll geheiligt werden durch meine Herrlichkeit.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'So will ich das Offenbarungszelt und den Altar weihen; auch Aaron und seine Söhne will ich weihen, damit sie mir Priesterdienst thun.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'Und ich will unter den Israeliten wohnen und ihr Gott sein;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'so sollen sie dann erkennen, daß ich, Jahwe, ihr Gott bin, der sie weggeführt hat aus Ägypten, um unter ihnen zu wohnen - ich, Jahwe, ihr Gott!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, 'Weiter sollst du einen Altar zum Verbrennen des Räucherwerks anfertigen; aus Akazienholz sollst du ihn anfertigen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'eine Elle lang und eine Elle breit; viereckig soll er sein und zwei Ellen hoch. Seine Hörner sollen ein Ganzes mit ihm bilden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'Den sollst du mit gediegenem Gold überziehen, seine Platte und seine Wände ringsum, sowie seine Hörner, und sollst einen ringsumlaufenden goldenen Kranz an ihm anbringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'Unterhalb dieses Kranzes sollst du an seinen beiden Ecken je zwei goldene Ringe anbringen; auf seinen beiden Seiten sollst du sie anbringen, daß sie zur Aufnahme der Stangen dienen, damit man ihn mittels derselben tragen kann.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'Die Stangen aber sollst du aus Akazienholz fertigen und mit Gold überziehen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'Und du sollst ihn vor den Vorhang setzen, der sich vor der Lade mit dem Gesetze befindet - vor der Deckplatte, die sich über dem Gesetze befindet, woselbst ich mich dir offenbaren werde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'Und Aaron soll darauf wohlriechendes Räucherwerk verbrennen. Alle Morgen, wenn er die Lampen zurecht macht, soll er es verbrennen;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'auch, wenn er gegen Abend die Lampen aufsteckt, soll es Aaron verbrennen, als regelmäßiges Rauchopfer eurerseits vor Jahwe von Geschlecht zu Geschlecht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'Fremdes Räucherwerk, Brandopfer oder Speisopfer dürft ihr nicht auf ihm darbringen; auch Trankopfer dürft ihr nicht auf ihn ausgießen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'Und Aaron soll einmal im Jahre an seinen Hörnern die Sühne vollziehen; vermittelst des Blutes des Entsündigungs-Sündopfers soll er einmal im Jahre von Geschlecht zu Geschlecht die Sühne an ihm vollziehen - hochheilig ist er dem Jahwe!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'Und Jahwe redete mit Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, 'Wenn du die Gesamtzahl der Israeliten, soweit sie gemustert werden, aufnimmst, sollen sie Mann für Mann Jahwe ein Lösegeld zur Deckung ihres Lebens geben, wenn man sie mustert, damit nicht eine Plage über sie komme, wenn man sie mustert.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'Und zwar soll jeder, der der Musterung unterliegt, einen halben Sekel heiliges Gewicht, den Sekel zu zwanzig Gera gerechnet, entrichten, einen halben Sekel als Hebeopfer für Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'Jeder, der der Musterung unterliegt, von zwanzig Jahren an und darüber, soll das Hebeopfer für Jahwe entrichten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'Die Reichen sollen nicht mehr, und die Armen nicht weniger geben, als einen halben Sekel, bei der Entrichtung des Hebeopfers für Jahwe, zur Deckung ihres Lebens.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'Und du sollst das Sühngeld von den Israeliten erheben und auf den Dienst am Offenbarungszelte verwenden, damit es den Israeliten ein gnädiges Gedenken bei Jahwe und Deckung ihres Lebens erwirke.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'Und Jahwe redete mit Mose also: Fertige ein kupfernes Becken mit einem kupfernen Gestell zum Waschen an,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, 'stelle es auf zwischen dem Offenbarungszelt und dem Altar und thue Wasser hinein,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'damit sich Aaron und seine Söhne ihre Hände und Füße darin waschen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'Wenn sie hineingehen ins Offenbarungszelt, sollen sie sich abwaschen, damit sie nicht sterben, und ebenso, wenn sie herzutreten zum Altar, um den heiligen Dienst zu verrichten, indem sie Feueropfer für Jahwe in Rauch aufgehen lassen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'Da sollen sie dann ihre Hände und Füße waschen, damit sie nicht sterben, und dies soll ihnen als eine für alle Zeiten geltende Verpflichtung obliegen - für ihn und seine Nachkommen von Geschlecht zu Geschlecht!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'Und Jahwe redete mit Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, 'Du aber verschaffe dir wohlriechende Stoffe von der besten Sorte, nämlich 500 Sekel vorzüglichsten Balsam, halb so viel wohlriechenden Zimt, also 250 Sekel, ferner 250 Sekel wohlriechenden Kalmus');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'und 500 Sekel Cassia, nach heiligem Gewicht, dazu ein Hin Olivenöl,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'und stelle daraus ein heiliges Salböl her, eine würzige Salbe, wie sie der Salbenmischer herstellt, - ein heiliges Salböl soll es sein!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'Und du sollst damit salben das Offenbarungszelt und die Lade mit dem Gesetze,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'den Tisch mit allen seinen Geräten, den Leuchter mit seinen Geräten und den Räucheraltar,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'ferner den Brandopferaltar mit allen seinen Geräten und das Becken samt seinem Gestelle.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'Und du sollst sie weihen, damit sie hochheilig seien; jeder, der sie berührt, ist dem Heiligtum verfallen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'Auch Aaron und seine Söhne sollst du salben und sie so weihen, damit sie mir Priesterdienst thun.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, 'Den Israeliten aber gebiete folgendes: Als ein mir geheiligtes Salböl soll euch dieses gelten von Geschlecht zu Geschlecht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'Auf keines Menschen Leib darf es gegossen werden, noch dürft ihr welches im gleichen Mischungsverhältnis für euch bereiten: heilig ist es, als heilig soll es euch gelten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'Wenn jemand solches mischt oder etwas davon an einen Fremden bringt, so soll er hinweggetilgt werden aus seinen Volksgenossen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'Und Jahwe gebot Mose: Verschaffe dir Spezereien: Stakte, Räucherklaue und Galbanum - Spezereien und reinen Weihrauch, alles zu gleichen Teilen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'und bereite daraus Räucherwerk, eine würzige Mischung, wie sie der Salbenmischer bereitet, mit etwas Salz versetzt, rein, zu heiligem Gebrauche bestimmt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'Und du sollst etwas davon zu feinem Pulver zerreiben und sollst davon in die Nähe des Gesetzes ins Offenbarungszelt bringen, woselbst ich mich dir offenbaren werde; als hochheilig soll es euch gelten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, 'Für euch aber dürft ihr kein Räucherwerk bereiten nach dem Mischungsverhältnis, wie es bei dem stattfindet, welches du bereiten sollst; als etwas Jahwe Geheiligtes soll es dir gelten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'Sollte jemand seinesgleichen bereiten, um sich an seinem Geruche zu ergötzen, so soll er hinweggetilgt werden aus seinen Volksgenossen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'Und Jahwe redete mit Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, 'Merke auf! Ich habe Bezaleel, den Sohn Uris, des Sohnes Hurs, vom Stamme Juda, namentlich berufen und ihn erfüllt mit göttlichem Geiste,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'mit Kunstsinn, Einsicht, Wissen und allerlei Fertigkeiten,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'um Kunstwerke zu ersinnen und in Gold, Silber, Kupfer,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'mittels Verarbeitung von Edelsteinen zum Besetzen und mittels Bearbeitung von Holz auszuführen und so in allen Gattungen zu arbeiten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'Zugleich aber habe ich ihm Oholiab, den Sohn Ahisamachs, vom Stamme Dan beigegeben und habe allen Kunstverständigen künstlerischen Sinn verliehen, damit sie alles, was ich dir befohlen habe, anfertigen:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'das Offenbarungszelt, die Lade für das Gesetz, die Deckplatte darauf und alle zum Zelte gehörenden Geräte;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'ferner den Tisch mit seinen Geräten, den Leuchter aus gediegenem Golde mit allen seinen Geräten und den Räucheraltar,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'den Brandopferaltar mit allen seinen Geräten und das Becken mit seinem Gestelle,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'die prachtvoll gewirkten Kleider und die übrigen heiligen Kleider Aarons, des Priesters, sowie die Kleider seiner Söhne zum priesterlichen Dienste,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'das Salböl und das wohlriechende Räucherwerk zum heiligen Gebrauche. Ganz wie ich es dir befohlen habe, sollen sie es anfertigen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'Und Jahwe gebot Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, 'Du aber befiehl den Israeliten Folgendes: Beobachtet nur ja meine Ruhetage! Denn er ist ein Zeichen zwischen mir und euch von Geschlecht zu Geschlecht, damit man erkenne, daß ich, Jahwe, es bin, der euch heiligt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'Darum sollt ihr den Ruhetag beobachten, denn er muß euch heilig sein; wer immer ihn entweiht, soll mit dem Tode bestraft werden. Denn wenn irgend jemand eine Arbeit an ihm verrichtet, ein solcher soll hinweggetilgt werden mitten aus seinen Volksgenossen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'Sechs Tage hindurch darf Arbeit verrichtet werden, aber der siebente Tag ist ein Jahwe geheiligter Tag unbedingter Ruhe; jeder, der am Sabbattage eine Arbeit verrichtet, soll mit dem Tode bestraft werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'So sollen also die Israeliten den Sabbat beobachten, indem sie den Sabbat feiern von Geschlecht zu Geschlecht, kraft einer für alle Zeiten geltenden Verpflichtung.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'Für alle Zeiten sei er ein Zeichen zwischen mir und den Israeliten. In sechs Tagen hat Jahwe den Himmel und die Erde gemacht; am siebenten Tag aber ruhte er und atmete auf.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'Als er nun das Gespräch mit Mose auf dem Berge Sinai beendet hatte, übergab er ihm die beiden Gesetztafeln, steinerne Tafeln, vom Finger Gottes beschrieben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, 'Als aber das Volk sah, daß sich die Rückkunft Moses vom Berge verzögerte, scharte sich das Volk um Aaron und forderte ihn auf: Wohlan, schaffe uns einen Gott, der vor uns einherziehe; denn wir wissen nicht, was jenem Manne Mose, der uns aus Ägypten weggeführt hat, zugestoßen ist.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'Da sprach Aaron zu ihnen: Reißt die goldenen Ringe ab, die eure Weiber, Söhne und Töchter an den Ohren tragen, und bringt sie mir her.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'Da rissen sich alle Leute die goldenen Ringe ab, die sie an den Ohren trugen, und brachten sie Aaron.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'Der nahm das Gold von ihnen in Empfang, bearbeitete es mit dem Meißel und machte daraus ein gegossenes Kalb. Da riefen sie: Das ist dein Gott, o Israel, der dich aus Ägypten weggeführt hat!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'Als dies Aaron sah, errichtete er vor ihm einen Altar; und Aaron ließ ausrufen: Morgen wird Jahwe ein Fest gefeiert!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'Des anderen Tages früh opferten sie Brandopfer und brachten Heilsopfer dar, und das Volk setzte sich hin, um zu essen und zu trinken; dann standen sie auf, um sich zu belustigen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, 'Da befahl Jahwe Mose: Auf! steige hinab, denn dein Volk, das du aus Ägypten weggeführt hast, handelt verderbt!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'Gar schnell sind sie von dem Wege abgewichen, den ich ihnen vorgeschrieben habe; sie haben sich ein gegossenes Kalb gemacht und es angebetet, haben ihm Opfer dargebracht und gerufen: Das ist dein Gott, o Israel, der dich aus Ägypten weggeführt hat!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'Und Jahwe sprach zu Mose: Ich sehe nun wohl, daß dieses Volk ein halsstarriges Volk ist.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'So laß mich nun, daß mein Zorn gegen sie entbrenne, und ich sie vernichte; dann will ich dich zum Stammvater eines großen Volkes machen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'Mose aber suchte Jahwe, seinen Gott, zu begütigen, indem er sprach: O Jahwe! Warum bist du so sehr zornig über dein Volk, das du doch mit großer Kraft und starker Hand aus Ägypten weggeführt hast?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, 'Es sollen doch nicht etwa die Ägypter sagen: In schlimmer Absicht hat er sie weggeführt, um sie in den Bergen umzubringen und sie vom Erdboden zu vertilgen? Laß ab von deinem heftigen Zorn und laß dich das Unheil gereuen, das du deinem Volke zugedacht hast.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'Gedenke deiner Diener Abraham, Isaak und Israel, denen du bei dir selbst zugeschworen und verheißen hast: Ich will eure Nachkommen so zahlreich werden lassen, wie die Sterne am Himmel, und dieses ganze Land, von dem ich gesprochen habe, will ich euren Nachkommen verleihen, damit sie es auf ewige Zeiten besitzen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'Da ließ sich Jahwe das Unheil gereuen, das er seinem Volke angedroht hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'Mose aber machte sich auf den Rückweg und stieg vom Berge hinab, mit den beiden Gesetztafeln in der Hand, - Tafeln, die auf beiden Seiten beschrieben waren; vorn und hinten waren sie beschrieben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'Es waren aber die Tafeln von Gott angefertigt und die Schrift Gottesschrift, eingegraben auf die Tafeln.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'Als nun Josua das laute Gelärm des Volkes vernahm, sagte er zu Mose: Es ist Kriegslärm im Lager!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'Der aber erwiderte: Das ist kein Geschrei, wie es Sieger, und kein Geschrei, wie es Unterliegende anheben; Gesangestöne höre ich!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, 'Als er nun in die Nähe des Lagers kam und das Kalb, sowie die Reihen der Tanzenden erblickte, da entbrannte der Zorn Moses, so daß er die Tafeln wegwarf und sie am Fuße des Berges zerschmetterte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'Dann nahm er das Kalb, das sie gemacht hatten, verbrannte es und zermalmte es zu feinem Staube; den streute er auf Wasser und gab es den Israeliten zu trinken.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, 'Und zu Aaron sprach Mose: Was haben dir diese Leute gethan, daß du eine so schwere Versündigung über sie gebracht hast?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, 'Aaron erwiderte: O Herr! zürne nicht; du weißt es ja selbst, daß das Volk zum Bösen geneigt ist.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'Sie baten mich: Mache uns einen Gott, der vor uns einherziehe; denn wir wissen nicht, was jenem Manne Mose, der uns aus Ägypten hierher geführt hat, zugestoßen ist.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'Da gebot ich ihnen: Wer Gold trägt, der reiße es sich ab! Da gaben sie es mir, und ich warf es ins Feuer; da wurde dieses Kalb daraus!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, 'Als nun Mose sah, daß das Volk aus Rand und Band gekommen war - denn Aaron hatte ihm die Zügel schießen lassen, zur Schadenfreude seiner Feinde -,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'da trat Mose an das Thor des Lagers und rief: Her zu mir, wer Jahwe angehört! Da sammelten sich um ihn alle Leviten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'Er aber sprach zu ihnen: So spricht Jahwe, der Gott Israels: Gürtet ein jeder sein Schwert um, geht im Lager hin und her, von einem Thore zum andern und schlagt tot, wer es sei, Brüder, Freunde und Verwandte!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'Die Leviten aber thaten nach dem Befehle Moses, und so fielen an jenem Tage vom Volk ungefähr dreitausend Mann.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, 'Da sprach Mose: Füllt euch heute die Hand für Jahwe - denn ein jeder war wider seinen Sohn und seinen Bruder -, damit fortan Segen auf euch ruhe!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, 'Des andern Tags aber sprach Mose zu dem Volke: Ihr habt euch sehr schwer versündigt! Ich will daher zu Jahwe hinaufsteigen; vielleicht kann ich euch Verzeihung auswirken für eure Sünde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'Da ging Mose wieder zu Jahwe und sprach: Ach! dieses Volk hat sich sehr schwer versündigt und sich einen Gott aus Gold verfertigt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'Und nun vergieb ihnen doch ihre Sünde! Wo nicht, so streiche mich doch lieber aus dem Buche, das du führst!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'Jahwe aber entgegnete Mose: Wer irgend sich gegen mich verfehlt, den streiche ich aus meinem Buche.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'Aber gehe jetzt nur hin und führe das Volk dorthin, wohin ich dir geboten habe; mein Engel soll vor dir hergehen. Aber wenn die Zeit der Ahndung für mich da ist, will ich ihre Versündigung ahnden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'Und Jahwe verhängte Unheil über das Volk, weil sie das Kalb verfertigt hatten, welches Aaron verfertigt hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'Hierauf sprach Jahwe zu Mose: Wohlan! ziehe nun mit dem Volke, daß du aus Ägypten hierher gebracht hast, von hier hinweg in das Land, das ich Abraham, Isaak und Jakob zugeschworen habe, indem ich verhieß: Euren Nachkommen will ich es verleihen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, 'Ich will aber einen Engel vor euch einherziehen lassen, um die Kanaaniter, Amoriter, Hethiter, Pheresiter, Heviter und Jebusiter vor euch zu vertreiben, -');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, 'in ein Land, das von Milch und Honig überfließt. Denn ich will nicht in eurer Mitte einherziehen, weil ihr ein halsstarriges Volk seid; sonst würde ich euch unterwegs den Garaus machen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'Als aber das Volk diese schlimmen Worte vernahm, da wurden sie sehr betrübt, und niemand legte seinen Schmuck an.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'Da sprach Jahwe zu Mose: Sprich zu den Israeliten: Ihr seid ein halsstarriges Volk! Wenn ich auch nur einen Augenblick in eurer Mitte einherzöge, würde ich euch den Garaus machen. So legt nun euren Schmuck ab; dann will ich zusehen, was ich für euch thun kann.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'Da entledigten sich die Israeliten ihres Schmuckes vom Berge Horeb ab.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'Mose aber nahm jedesmal das Zelt und schlug es außerhalb des Lagers, etwas entfernt vom Lager, auf und nannte es Offenbarungszelt. Wer irgend Jahwe befragen wollte, der begab sich zu dem Offenbarungszelte hinaus vor das Lager.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'So oft sich nun Mose zu dem Zelte hinaus begab, erhoben sich alle Leute und traten ein jeder unter die Thüre seines Zeltes und blickten Mose nach, bis er zum Zelte gelangt war.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'So oft aber Mose zum Zelte kam, senkte sich die Wolkensäule herab und nahm ihren Platz an der Thüre des Zeltes, und dann redete er mit Mose.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'Und alle Leute sahen die Wolkensäule an der Thüre des Zeltes stehen; dann erhoben sich alle Leute und warfen sich ein jeder unter der Thüre seines Zeltes zu Boden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'Jahwe aber redete jedesmal persönlich mit Mose, wie jemand mit seinem Freunde redet; hierauf kehrte er ins Lager zurück, während sein Gehilfe Josua, der Sohn Nuns, als Diener beständig im Innern des Zeltes verweilte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, 'Hierauf sprach Mose zu Jahwe: Du befiehlst mir freilich: Führe dieses Volk hinweg! hast mir aber nicht kund gethan, wen du mir als Begleiter mitsenden willst. Und du hast ja doch gesagt: Ich kenne dich mit Namen; auch hast du Gnade bei mir gefunden!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'Wenn ich nun also Gnade bei dir gefunden habe, so weihe mich ein in deine Pläne und laß mich dich erkennen, damit ich Gnade vor dir finde, und bedenke doch, daß diese Leute dein Volk sind!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, 'Da sprach er: Soll ich in Person mitgehen und dich bis zum Bestimmungsorte bringen?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, 'Er antwortete: Wenn du nicht in Person mitgehst, so führe uns lieber nicht von hier hinweg!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, 'Woran sonst soll erkannt werden, daß ich und dein Volk Gnade vor dir gefunden haben, außer indem du mit uns ziehst, und ich und dein Volk dadurch ausgezeichnet werden vor allen Völkern auf Erden?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'Da sprach Jahwe zu Mose: Auch das, was du da erbeten hast, will ich thun; denn du hast Gnade vor mir gefunden und ich kenne dich mit Namen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'Da bat er: Laß mich deine Herrlichkeit schauen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'Er erwiderte: Ich will alle meine Schöne an dir vorüberziehen lassen und den Namen Jahwe vor dir ausrufen und will gnädig sein, wem ich will, und mich erbarmen, wessen ich will.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'Hierauf sprach er: Du kannst mein Antlitz nicht schauen; denn kein Mensch bleibt am Leben, wenn er mich sieht!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'Sodann sprach Jahwe: Es ist eine Stätte in meiner Nähe, da magst du hintreten auf den Felsen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'Wenn dann meine Herrlichkeit vorüberzieht, so will ich dich in eine Höhlung des Felsens stellen und meine Hand über dich decken, bis ich vorüber bin.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'Wenn ich dann meine Hand entferne, so wirst du meine Rückseite sehen; aber mein Antlitz darf niemand schauen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'Da befahl Jahwe Mose: haue dir zwei Steintafeln zurecht, wie die früheren waren; dann will ich auf die Tafeln die Gebote schreiben, die auf den früheren Tafeln standen, welche du zerbrochen hast.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'Und sei bereit, morgen in aller Frühe auf den Berg Sinai hinaufzusteigen; dann erwarte mich dort auf der Spitze des Berges.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'Es darf aber niemand mit dir hinaufsteigen. Ja es darf sich niemand im Bereiche des ganzen Berges blicken lassen; selbst Schafe und Rinder dürfen nirgends in der Nähe dieses Berges weiden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'Da hieb er zwei Steintafeln aus wie die früheren. Und Mose brach des anderen Tages früh auf und stieg auf den Berg Sinai, wie ihm Jahwe befohlen hatte, und nahm zwei Steintafeln mit sich.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'Da fuhr Jahwe in einer Wolke hernieder; er aber stellte sich dort neben ihn und rief den Namen Jahwes an.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'Da zog Jahwe an ihm vorüber, indem er rief: Jahwe, Jahwe ist ein barmherziger und gnädiger Gott, langsam zum Zorn und reich an Huld und Treue,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'der Huld bewahrt Tausenden, der Missethat, Übertretung und Sünde vergiebt, aber nicht ganz ungestraft läßt, sondern Väterschuld ahndet an den Kindern und an den Enkeln, am dritten und vierten Gliede.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'Da neigte sich Mose eilends bis auf den Boden, warf sich nieder');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, 'und sprach: O Herr, wenn ich irgend Gnade vor dir gefunden habe, so wolle doch mitten unter uns einherziehen! Das Volk ist ja halsstarrig; aber verzeihe uns unsere Missethaten und Sünden und mache uns zu deinem Eigentum!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, 'Er antwortete: Wohlan, ich verordne feierlich im Beisein deines ganzen Volkes: Ich will Wunder thun, wie sie nicht verrichtet worden sind auf der ganzen Erde und unter allen Völkern, und das ganze Volk, inmitten dessen du dich befindest, soll das Thun Jahwes gewahren; denn staunenswert ist, was ich an dir thun werde!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, 'Beobachte, was ich dir heute gebiete. Ich will vor dir vertreiben die Amoriter, die Kanaaniter, die Hethiter, die Pheresiter, die Heviter und die Jebusiter.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'Hüte dich davor, mit den Bewohnern des Landes, in welches du kommen wirst, ein Abkommen zu treffen; sie könnten euch sonst, wenn sie mitten unter euch wohnen, zum Fallstricke werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'Vielmehr sollt ihr ihre Altäre zerstören, ihre Malsteine zertrümmern und ihre heiligen Bäume umhauen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'Aber du sollst dich vor keinem anderen Gotte niederwerfen. Denn Jahwe heißt eifersüchtig; ein eifersüchtiger Gott ist er.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'Wenn du ein Abkommen mit den Bewohnern des Landes triffst, und sie mit ihren Göttern Abgötterei treiben und ihren Göttern Opfer bringen und dich dazu einladen, so lauft ihr Gefahr, von ihrer Opfergabe zu essen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'Auch würdet ihr ihre Töchter für eure Söhne freien; wenn dann ihre Töchter ihren Göttern dienend Abgötterei trieben, so würden sie auch deine Söhne zu der gleichen Abgötterei verführen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, 'Du sollst dir nicht ein gegossenes Gottesbild machen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, 'Das Fest der ungesäuerten Brote sollst du halten; sieben Tage hindurch sollst du ungesäuerte Brote essen, wie ich dir befohlen habe, zur Zeit des Monats Abib; denn im Monat Abib bist du aus Ägypten weggezoggen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, 'Alle Erstgeburt gehört mir; ebenso all\' dein Vieh, soweit es männlich ist, - der erste Wurf von Rindern und Schafen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'Den ersten Wurf eines Esels aber sollst du mit einem Schaf auslösen und wenn du ihn nicht auslösen willst, so mußt du ihm das Genick brechen. Alle Erstgeburt unter deinen Söhnen sollst du auslösen; und vor mir soll man nicht mit leeren Händen erscheinen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, 'Sechs Tage hindurch magst du arbeiten, aber am siebenten Tage sollst du ruhen; selbst während der Zeit des Pflügens und Erntens sollst du ruhen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, 'Und das Wochenfest sollst du halten, das Fest der Erstlinge der Weizenernte und das Fest des Einherbstens bei der Wende des Jahres.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, 'Dreimal im Jahre soll alles, was männlich unter euch ist, vor dem Herrn, Jahwe, dem Gott Israels erscheinen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'Denn ich will dir zuliebe Völker ihres Besitzes berauben und deinem Gebiete eine weite Ausdehnung geben; aber niemand soll sich gelüsten lassen nach deinem Lande, während du hinziehst, um vor Jahwe, deinem Gotte, zu erscheinen, dreimal im Jahre.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, 'Du sollst das Blut meiner Opfer nicht zu gesäuertem Brote schlachten, und das Opferfleich des Passahfestes soll nicht bis zum andern Morgen aufbehalten werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, 'Die Erstlinge von den ersten Früchten deines Bodens sollst du zum Hause Jahwes, deines Gottes, bringen. Du sollst ein Böckchen nicht in der Milch seiner Mutter kochen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'Und Jahwe befahl Mose: Schreibe dir diese Gebote auf; denn auf Grund dieser Gebote schließe ich mit dir und mit Israel einen Bund.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, 'Er verweilte aber dort bei Jahwe vierzig Tage und vierzig Nächte, ohne Speise und Trank zu sich zu nehmen. Da schrieb er die Bundesgebote, die zehn Gebote, auf die Tafeln.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'Als aber Mose vom Berge Sinai herabstieg mit den beiden Gesetztafeln in der Hand, - als er vom Berge herabstieg, wußte Mose nicht, daß die Haut seines Antlitzes glänzend geworden war infolge seiner Unterredung mit ihm.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'Als nun Aaron und alle Israeliten an Mose wahrnahmen, daß die Haut seines Antlitzes glänzte, fürchteten sie sich, ihm nahe zu kommen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'Mose aber rief ihnen zu; da wandten sie sich ihm wieder zu, sowohl Aaron, als alle Fürsten in der Gemeinde. Und Mose redete mit ihnen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'Darnach traten alle übrigen Israeliten heran. Da trug er ihnen alle Gebote vor, welche ihm Jahwe auf dem Berge Sinai anbefohlen hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'Als aber Mose seine Unterredung mit ihnen beendigt hatte, legte er eine Hülle auf sein Antlitz.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'Jedesmal wenn Mose vor Jahwe trat, um mit ihm zu reden, entfernte er die Hülle, bis er wieder herauskam. Und jedesmal wenn er herauskam, richtete er den Israeliten aus, was ihm aufgetragen worden war.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'Da sahen dann jedesmal die Israeliten, daß die Haut des Antlitzes Moses glänzte. Dann legte Mose die Hülle wieder auf sein Antlitz, bis er hineinging, mit ihm zu reden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'Hierauf versammelte Mose die ganze Gemeinde der Israeliten und sprach zu ihnen: Dies ist\'s, was Jahwe zu thun befohlen hat:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, 'Sechs Tage hindurch darf Arbeit verrichtet werden, den siebenten Tag aber sollt ihr heilig halten als einen Jahwe geweihten Tag unbedingter Ruhe. Jeder, der eine Arbeit an ihm verrichtet, soll getötet werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'Am Sabbattage dürft ihr kein Feuer anzünden in allen euren Wohnungen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'Da gebot Mose der ganzen Gemeinde der Israeliten also: Dies ist\'s, was Jahwe befohlen hat:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, 'Liefert von eurem Besitz eine Beisteuer für Jahwe! Jeder, den sein Herz dazu treibt, möge sie bringen, die Beisteuer für Jahwe: Gold, Silber, Kupfer,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'blauen und roten Purpur, Karmesin, Byssus und Ziegenhaar,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, 'rotgefärbte Widderfelle, Seekuhfelle und Akazienholz,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, 'Öl für den Leuchter, sowie Spezereien zum Salböl und zum wohlriechenden Räucherwerk,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'Schohamsteine und Edelsteine zum Besetzen des Schulterkleids und der Tasche.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, 'Und alle, die kunstverständig sind unter euch, mögen kommen und alles das verfertigen, was Jahwe gefordert hat:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'die Wohnung mit ihren Zeltwänden und ihrer Decke, ihren Haken, Brettern, Riegeln, Säulen und Füßen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'die Lade mit ihren Stangen, die Deckplatte und den verhüllenden Vorhang;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'den Tisch mit seinen Stangen und allen seinen Geräten und den Schaubroten,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'den Leuchter mit seinen Geräten und seinen Lampen und das Öl für den Leuchter,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'den Räucheraltar mit seinen Stangen, das Salböl, das wohlriechende Räucherwerk und den Thürvorhang für die Thüre der Wohnung,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'den Brandopferaltar mit seinem kupfernen Gitterwerk, seinen Stangen und allen seinen Geräten, das Becken mit seinem Gestelle,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'die Umhänge des Vorhofs, seine Säulen samt ihren Füßen, sowie den Vorhang für das Thor des Vorhofs,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'die Pflöcke zur Befestigung der Wohnung und die Pflöcke zur Befestigung des Vorhofs samt den zugehörigen Stricken,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, 'die prachtvoll gewirkten Kleider für den Dienst im Heiligtume, die heiligen Kleider für Aaron, den Priester, und die Kleider seiner Söhne zum priesterlichen Dienst.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, 'Hierauf ging die ganze Gemeinde der Israeliten von Mose hinweg.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, 'Sodann aber kam ein jeder, den sein Herz dazu trieb, und jeder, der dazu willig war, und brachte die Beisteuer für Jahwe zur Anfertigung des Offenbarungszeltes und für den gesamten Dienst in ihm und zu den heiligen Kleidern.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, 'Und zwar brachten sowohl Männer als Frauen: alle, die ihr Herz dazu trieb, brachten Spangen, Ohrringe, Fingerringe und Geschmeide, allerlei goldene Schmucksachen; dazu alle die, welche Jahwe eine Gabe an Gold zu weihen beschlossen hatten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, 'Und alle die, welche blauen und roten Purpur, Karmesin, Byssus und Ziegenhaar, rotgefärbte Widderfelle und Seekuhfelle besaßen, die brachten sie herbei.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, 'Alle die, welche eine Beisteuer an Silber und Kupfer liefern wollten, brachten die Beisteuer für Jahwe herbei; und alle die, welche Akazienholz besaßen, wie es allenthalben bei der Anfertigung zu verwenden war, die brachten es.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'Und alle kunstverständigen Frauen spannen eigenhändig und brachten das Gespinst: blauen und roten Purpur, Karmesin und Byssus.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, 'Und alle Frauen, die sich vermöge ihrer Kunstfertigkeit dazu getrieben fühlten, spannen Ziegenhaar.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, 'Die Fürsten aber brachten die Schohamsteine und die Edelsteine zum Besetzen des Schulterkleids und der Tasche,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, 'dazu die Spezereien und das Öl für den Leuchter und zum Salböl und zum wohlriechenden Räucherwerk.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, 'Alle Männer und Frauen, die sich angetrieben fühlten, für alle die Arbeiten, deren Anfertigung Jahwe durch Mose befohlen hatte, Gaben zu bringen, - als freiwillige Spende an Jahwe brachten die Israeliten ihre Gaben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, 'Mose aber sprach zu den Israeliten: Merket auf! Jahwe hat Bezaleel, den Sohn Uris, des Sohnes Hurs, vom Stamme Juda, namentlich berufen');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, 'und ihn erfüllt mit göttlichem Geiste, mit Kunstsinn, Einsicht, Wissen und allerlei Kunstfertigkeiten,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, 'um Kunstwerke zu ersinnen und in Gold, Silber und Kupfer,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, 'sowie mittels Bearbeitung von Edelsteinen zum Besetzen und mittels Bearbeitung von Holz auszuführen und so in allen Gattungen von Kunstwerken zu arbeiten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, 'Aber auch die Gabe der Unterweisung hat er ihm verliehen, ihm und Oholiab, dem Sohne Ahisamachs vom Stamme Dan.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, 'Er hat sie erfüllt mit Kunstsinn, allerlei Arbeiten auszuführen, wie sie der Schmied und der Zimmermann, der Kunstweber, der Buntwirker in blauem und rotem Purpur, Karmesin und Byssus, sowie der Weber fertigt, indem sie alle Arbeiten ausführen und Kunstwerke ersinnen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, 'So sollen nun Bezaleel, Oholiab und alle Kunstverständigen, denen Jahwe Kunstsinn und Einsicht verliehen hat, so daß sie sich auf die Ausführung verstehen, alle zur Anfertigung des Heiligtums nötigen Arbeiten ausführen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'Hierauf berief Mose Bezaleel, Oholiab und alle Kunstverständigen, denen Jahwe Kunstsinn verliehen hatte, alle, die sich angetrieben fühlten, ans Werk zu gehen, um es auszuführen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'Und sie empfingen von Mose die gesamte Beisteuer, welche die Israeliten zur Ausführung der Arbeiten behufs Anfertigung des Heiligtums gebracht hatten. Diese brachten ihm aber nach wir vor an jedem Morgen freiwillige Gaben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'Da verließen alle Künstler, welche mit allen den Arbeiten für das Heiligtum beschäftigt waren, Mann für Mann die Arbeit, mit der sie gerade beschäftigt waren,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'und sprachen zu Mose: Das Volk bringt viel mehr, als zur Anfertigung der Arbeiten, deren Ausführung Jahwe befohlen hat, erforderlich ist!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'Da ließ Mose im Lager den Befehl verbreiten: Niemand, es sei Mann oder Weib, soll fortan noch etwas anfertigen als Beisteuer für das Heiligtum! So wurde dem Volke gewehrt, Gaben zu bringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'Denn es war genug, ja übergenug Stoff für sie da, um alle Arbeiten auszuführen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, 'So verfertigten denn alle Kunstverständigen unter den bei dem Werke Beschäftigten die Wohnung aus zehn Teppichen. Aus gezwirntem Byssus, blauem und rotem Purpur und Karmesin, mit Keruben, wie sie der Kunstwirker macht, verfertigte er sie,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'jeden Teppich 28 Ellen lang und 4 Ellen breit; alle Teppiche hatten einerlei Maß.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, 'Je fünf Teppiche fügte er aneinander;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, 'hierauf brachte er am Saume des äußersten Teppichs der einen Fläche Schleifen von blauem Purpur an, und ebenso am Saume des äußersten Teppichs der anderen Fläche.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, 'Fünfzig Schleifen brachte er an dem einen Teppich an und fünfzig Schleifen brachte er am Rande des Teppichs an, der zu der anderen Fläche gehörte, so, daß die Schleifen einander gegenüber standen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, 'Sodann fertigte er fünfzig goldene Haken an und fügte die Teppiche mittels der Haken zusammen, so daß die Wohnung ein Ganzes wurde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, 'Weiter fertigte er Teppiche aus Ziegenhaar, zum Zeltdach über der Wohnung. Elf Teppiche fertigte er dazu an,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'jeden Teppich dreißig Ellen lang und vier Ellen breit; alle elf Teppiche hatten einerlei Maß.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'Fünf von diesen Teppichen verband er zu einem Ganzen für sich und ebenso die sechs anderen für sich.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'Sodann brachte er am Saume des äußersten Teppichs der einen Fläche fünfzig Schleifen an und ebenso fünfzig Schleifen am Saume des äußersten Teppichs der anderen Fläche.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, 'Hierauf fertigte er fünfzig kupferne Haken an, um das Zeltdach zusammenzufügen, so daß es ein Ganzes wurde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, 'Sodann fertigte er aus rotgefärbten Widderfellen eine Überdecke für das Zeltdach an und oben darüber eine Überdecke von Seekuhfellen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, 'Sodann fertigte er die Bretter zur Wohnung an, aufrechtstehende, von Akazienholz,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, 'jedes Brett zehn Ellen lang und anderthalbe Elle breit,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, 'jedes Brett mit zwei untereinander verbundenen Zapfen; in dieser Weise fertigte er alle Bretter der Wohnung an.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, 'Und zwar fertigte er an Brettern für die Wohnung an: zwanzig Bretter für die nach Süden gewendete Seite -');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'unter den zwanzig Brettern aber brachte er vierzig silberne Füße an, je zwei Füße unter jedem Brette für die beiden Zapfen desselben -,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, 'ebenso für die andere Seite der Wohnung, in der Richtung nach Norden, zwanzig Bretter');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, 'mit ihren vierzig silbernen Füßen, je zwei Füßen unter jedem Brette.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, 'Für die nach Westen gerichtete Seite der Wohnung aber fertigte er sechs Bretter an.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, 'Und zwei Bretter fertigte er für die Winkel der Wohnung auf der Hinterseite.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'Und sie waren doppelt im unteren Teil und ebenso waren sie doppelt am oberen Ende für den einen Ring. So verfuhr er mit beiden in den beiden Winkeln;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'somit waren es acht Bretter mit ihren silbernen Füßen - sechzehn Füßen, je zwei Füßen unter jedem Brette.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, 'Weiter fertigte er fünf Riegel aus Akazienholz an für die Bretter der einen Seite der Wohnung,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, 'fünf Riegel für die Bretter der anderen Seite der Wohnung und fünf Riegel für die Bretter der nach Westen gerichteten Hinterseite der Wohnung.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, 'Den mittelsten Riegel aber ließ er in der Mitte der Bretter quer durchlaufen von einem Ende bis zum anderen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, 'Die Bretter aber überzog er mit Gold; auch die Ringe an ihnen, die zur Aufnahme der Riegel bestimmt waren, fertigte er aus Gold an und überzog auch die Riegel mit Gold.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, 'Sodann fertigte er den Vorhang aus blauem und rotem Purpur, Karmesin und gezwirntem Byssus; in Kunstwirker-Arbeit fertigte der ihn, mit Keruben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'Und er fertigte für ihn vier Säulen von Akazienholz und überzog sie mit Gold; auch ihre Nägel waren aus Gold. Und er goß für sie vier silberne Füße.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, 'Sodann fertigte er einen Vorhang an für die Thüröffnung des Zeltes aus blauem und rotem Purpur, Karmesin und gezwirntem Byssus, in Buntwirkerarbeit,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, 'nebst den dazu gehörenden fünf Säulen und den Nägeln an denselben; ihre Köpfe und die Ringe an ihnen überzog er mit Gold. Ihre fünf Füße aber fertigte er aus Kupfer.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'Weiter fertigte Bezaleel die Lade aus Akazienholz an, zwei und eine halbe Elle lang, anderthalbe Elle breit und anderthalbe Elle hoch.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, 'Und er überzog sie inwendig und auswendig mit gediegenem Gold und brachte einen ringsumlaufenden goldenen Kranz an ihr an.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, 'Sodann goß er für sie vier goldene Ringe für ihre vier Füße, und zwar zwei Ringe auf ihrer einen Seite und zwei Ringe auf ihrer anderen Seite.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, 'Sodann fertigte er Stangen aus Akazienholz und überzog sie mit Gold;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'diese Stangen zog er durch die Ringe an den Seiten der Lade, so daß man die Lade tragen konnte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, 'Sodann fertigte er eine Deckplatte aus gediegenem Gold an, zwei und eine halbe Elle lang und anderthalbe Elle breit.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, 'Auch fertigte er zwei Kerube aus Gold an; in getriebener Arbeit verfertigte er sie an den beiden Enden der Deckplatte,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, 'den einen Kerub an dem einen Ende und den anderen Kerub an dem anderen Ende. An der Deckplatte brachte er die Kerube an, an ihren beiden Enden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'Es hielten aber die Kerube ihre Flügel nach oben ausgebreitet, indem sie mit ihren Flügeln die Deckplatte überdeckten, während ihre Gesichter einander zugekehrt waren; gegen die Deckplatte hin waren die Gesichter der Kerube gerichtet.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, 'Sodann fertigte er den Tisch aus Akazienholz an, zwei Ellen lang, eine Elle breit und anderthalbe Elle hoch.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, 'Und er überzog ihn mit gediegenem Gold und brachte einen ringsumlaufenden goldenen Kranz an ihm an.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, 'Sodann brachte er eine in Handbreite ringsumlaufende Leiste an ihm an und an dieser Leiste wiederum einen ringsumlaufenden goldenen Kranz.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, 'Ferner goß er für ihn vier goldene Ringe und befestigte diese Ringe an den vier Ecken seiner vier Füße.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, 'Dicht an der Leiste befanden sich die Ringe zur Aufnahme der Stangen, damit man den Tisch tragen könne.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, 'Die Stangen aber fertigte er aus Akazienholz an und überzog sie mit Gold, damit man den Tisch tragen könne.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, 'Sodann fertigte er die Geräte an, die sich auf dem Tische befinden sollten, die zu ihm gehörenden Schüsseln und Schalen, Becher und Kannen, mit denen das Trankopfer gespendet wird, alles aus gediegenem Golde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, 'Weiter fertigte er den Leuchter an aus gediegenem Golde. In getriebener Arbeit fertigte er den Leuchter an - sein Fußgestell und seinen Schaft; die dazu gehörenden Blumenkelche - Knollen mit Blüten - befanden sich an ihm.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, 'Von seinen Seiten aber gingen sechs Röhren aus, je drei auf jeder Seite des Leuchters.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, 'An jeder Röhre befanden sich drei mandelblütenförmige Blumenkelche - je ein Knollen mit Blüte; so an allen sechs Röhren, die von dem Leuchter ausgingen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, 'Am Leuchter aber befanden sich vier Blumenkelche, mandelblütenförmig mit den zugehörigen Knollen und Blüten,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, 'und zwar jedesmal ein Knollen unter jedem der drei Röhrenpaare an ihm, - der sechs Röhren, die von ihm ausgingen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'Ihre Knollen und Röhren waren aus einem Stücke mit ihm, alles getriebene Arbeit aus einem Stücke, von gediegenem Golde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, 'Sodann fertigte er die sieben Lampen an, die zu ihm gehörten, nebst den zu ihm gehörenden Lichtscheren und Pfannen, aus gediegenem Golde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, 'Ein Talent gediegenen Goldes verwendete er auf ihn und die zu ihm gehörenden Geräte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, 'Sodann fertigte er den Räucheraltar aus Akazienholz an, eine Elle lang und eine Elle breit, viereckig und zwei Ellen hoch; seine Hörner bildeten ein Ganzes mit ihm.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'Und er überzog ihn mit gediegenem Golde, seine Platte und seine Wände ringsum, sowie seine Hörner, und brachte einen ringsumlaufenden goldenen Kranz an ihm an.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, 'Unterhalb dieses Kranzes aber brachte er an seinen beiden Ecken auf seinen beiden Seiten je zwei goldene Ringe an zur Aufnahme der Stangen, damit man ihn mittels derselben tragen könne.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, 'Die Stangen aber fertigte er aus Akazienholz an und überzog sie mit Gold.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, 'Sodann fertigte er das heilige Salböl und das reine, wohlriechende Räucherwerk an, wie es der Salbenmischer herstellt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, 'Sodann fertigte er den Brandopferaltar aus Akazienholz an, fünf Ellen lang und fünf Ellen breit, viereckig und drei Ellen hoch.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, 'Seine Hörner aber brachte er an seinen vier Ecken an, so, daß seine Hörner ein Ganzes mit ihm bildeten, und überzog ihn mit Kupfer.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, 'Sodann fertigte er alle zum Altar gehörenden Geräte an, die Töpfe, Schaufeln, Becken, Gabeln und Pfannen; alle zu ihm gehörenden Geräte fertigte er aus Kupfer an.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, 'Ferner fertigte er für den Altar ein Gitterwerk an, ein Netzwerk aus Kupfer, unterhalb des um den Altar laufenden Simses bis zu seiner halben Höhe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'Sodann goß er vier Ringe für die vier Ecken des kupfernen Gitterwerks zur Aufnahme der Stangen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, 'Die Stangen aber fertigte er aus Akazienholz an und überzog sie mit Kupfer;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, 'sodann zog er die Stangen durch die Ringe an den Seiten des Altars, damit man ihn vermittelst derselben tragen könne. Aus Brettern, so daß er inwendig hohl war, fertigte er ihn an.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, 'Sodann fertigte er das Becken aus Kupfer an und sein Gestelle aus Kupfer - aus den Spiegeln der dienstthuenden Weiber, die am Eingange des Offenbarungszeltes Dienst thaten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, 'Sodann stellte er den Vorhof her: für die nach Süden gewendete Seite Vorhofumhänge aus gezwirntem Byssus, hundert Ellen lang,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'dazu zwanzig Säulen nebst ihren zwanzig kupfernen Füßen; die Nägel der Säulen und die zugehörigen Ringe waren aus Silber.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, 'Für die Westseite aber Umhänge in der Länge von fünfzig Ellen, dazu zehn Säulen nebst ihren zehn Füßen; die Nägel der Säulen und die zugehörigen Ringe waren aus Silber.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, 'Für die nach Osten gewendete Seite fünfzig Ellen;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, 'Umhänge in der Länge von fünfzehn Ellen für die eine Seite, dazu drei Säulen nebst ihren drei Füßen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, 'und ebenso für die andere Seite Umhänge in der Länge von fünfzehn Ellen, dazu drei Säulen nebst ihren drei Füßen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'und ebenso für die andere Seite Umhänge in der Länge von fünfzehn Ellen, dazu drei Säulen nebst ihren drei Füßen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, 'Alle Vorhofumhänge ringsum waren aus gezwirntem Byssus,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, 'die Füße der Säulen aus Kupfer, ihre Nägel aus Silber und der Überzug ihrer Köpfe aus Silber; es waren aber alle Säulen des Vorhofs mit silbernen Ringen versehen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, 'Der Vorhang aber des Vorhofsthores war Buntwirker-Arbeit aus blauem und rotem Purpur, Karmesin und gezwirntem Byssus, zwanzig Ellen lang und fünf Ellen hoch, entsprechend den Umhängen des Vorhofs.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'Die zugehörigen vier Säulen aber nebst ihren vier Füßen waren aus Kupfer, die Nägel daran aus Silber und ebenso der Überzug ihrer Köpfe und die Ringe an ihnen aus Silber.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'Alle Pflöcke aber der Wohnung und des Vorhofs ringsum waren aus Kupfer.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, 'Folgendes ist die Berechnung der Kosten der Wohnung, der Wohnung des Gesetzes, welche auf Befehl Moses vorgenommen wurde mittels Dienstleistung der Leviten unter der Leitung Ithamars, des Sohnes Aarons, des Priesters.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'Bezaleel aber, der Sohn Uris, des Sohnes Hurs aus dem Stamme Juda, fertigte alles an, was Jahwe Mose befohlen hatte,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'und mit ihm Oholiab, der Sohn Ahisamachs vom Stamme Dan, als Schmied und Zimmermann, sowie als Kunstwirker und als Buntwirker in rotem und blauem Purpur, Karmesin und Byssus.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, 'Anlangend das gesamte Gold, das bei der Anfertigung verarbeitet wurde, bei allen Arbeiten zur Anfertigung des Heiligtums, so betrug das als Weihegabe gespendete Gold 29 Talente und 730 Sekel heiliges Gewicht;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, 'das infolge der Musterung der Gemeinde eingehende Silber 100 Talente und 1775 Sekel heiliges Gewicht,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, 'je ein Halbsekel, die Hälfte eines Sekels heiliges Gewicht, von jedem Kopfe, von allen, die der Musterung unterlagen, von zwanzig Jahren an und darüber, 603550 Mann.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, 'Die hundert Talente Silber wurden verwendet zum Gießen der Füße des Heiligtums und der Füße des Vorhangs, hundert Talente zu hundert Füßen, zu jedem Fuß ein Talent.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, 'Aus den 1775 Sekeln aber fertigte er Nägel für die Säulen an, überzog ihre Köpfe und versah sie mit Ringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, 'Das als Weihegabe gespendete Kupfer betrug siebzig Talente und 2400 Sekel.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, 'Daraus fertigte er die Füße der Thüre des Offenbarungszeltes an, den kupfernen Altar samt dem kupfernen Gitterwerk an ihm und allen Altargeräten,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, 'dazu die Füße des Vorhofs ringsum und die Füße des Vorhofthores, sowie alle Pflöcke der Wohnung und alle Pflöcke des Vorhofs ringsum.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, 'Aus dem blauen und roten Purpur aber und aus dem Karmesin fertigten sie prachtvoll gewirkte Kleider zum Dienst im Heiligtum; und sie fertigten die heiligen Kleider Aarons, wie Jahwe Mose befohlen hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, 'Und zwar verfertigte er das Schulterkleid aus Gold, blauem und rotem Purpur, Karmesin und gezwirntem Byssus.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, 'Und sie schlugen die Goldplatten breit, so daß er sie in Fäden zerschneiden konnte, um diese mittels Kunstwirker-Arbeit in den blauen Purpur, in den roten Purpur, in den Karmesin und in den Byssus einzuarbeiten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, 'An ihm brachen sie mit ihm verbundene Schulterstücke an; an seinen beiden Enden wurde es mit ihnen verbunden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'Die Binde aber, die sich behufs seiner Anlegung an ihm befand, bildete ein Ganzes mit ihm von gleicher Arbeit aus Gold, blauem und rotem Purpur, Karmesin und gezwirntem Byssus, wie Jahwe Mose befohlen hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, 'Sodann richteten sie die Schohamsteine zu, daß sie mit einem Flechtwerke von Golddraht eingefaßt und mittels Siegelstecherkunst graviert waren nach Maßgabe der Namen der Israels-Söhne.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'Und er befestigte sie an den Schulterstücken des Schulterkleids als Steine des gnädigen Gedenkens an die Israeliten, wie Jahwe Mose befohlen hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'Sodann verfertigte er die Tasche in Kunstwirker-Arbeit, so wie das Schulterkleid gearbeitet war, aus Gold, blauem und rotem Purpur, Karmesin und gezwirntem Byssus.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, 'Viereckig war sie; doppelt gelegt fertigten sie die Tasche, je eine Handbreite lang und breit, doppelt gelegt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'Und sie besetzten sie mit vier Reihen von Edelsteinen: ein Carneol, ein Topas und ein Smaragd bildeten der Reihe nach die erste Reihe;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, 'die zweite Reihe ein Karfunkel, ein Sapphir und ein Jaspis;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, 'die dritte Reihe ein Hyacinth, ein Achat und ein Amethyst,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, 'die vierte Reihe ein Chrysolith, ein Schoham und ein Onyx; umgeben von Goldgeflecht bildeten sie den Besatz.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'Es waren aber der Steine entsprechend den Namen der Israels-Söhne ihrer Zwölf, entsprechend ihren Namen, mittels Siegelstecherkunst mit dem Namen je eines der zwölf Stämme versehen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, 'Sodann brachten sie an der Tasche die schnurenartig gedrehten Kettchen aus gediegenem Gold an.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, 'Weiter verfertigten sie zwei goldene Geflechte und zwei goldene Ringe und befestigten die beiden Ringe an den beiden Enden der Tasche.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'Sodann befestigten sie die beiden goldenen Schnuren an den beiden Ringen an den Enden der Tasche.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, 'Die beiden Enden aber der beiden Schnuren befestigten sie an den beiden Geflechten und diese befestigten sie an den beiden Schulterstücken des Schulterkleids auf dessen Vorderseite.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, 'Sodann fertigten sie zwei goldene Ringe an und befestigten sie an den beiden Enden der Tasche, an ihrem inneren, dem Schulterkleide zugewendeten Saume.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'Sodann fertigten sie zwei goldene Ringe an und befestigten sie an den beiden Schulterstücken des Schulterkleids ganz unten an seiner Vorderseite, da, wo es mit den Schulterstücken zusammenhängt, oberhalb der Binde des Schulterkleids.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, 'Dann ketteten sie die Tasche mit ihren Ringen mittels Schnuren von blauem Purpur an die Ringe des Schulterkleids an, so daß sie sich oberhalb der Binde des Schulterkleids befand und unbeweglich auf dem Schulterkleid auflag, wie Jahwe Mose befohlen hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, 'Sodann verfertigte er das Obergewand zum Schulterkleid in Weberarbeit, ganz und gar aus blauem Purpur.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, 'Und die Halsöffnung in dem Obergewande glich der Halsöffnung eines Panzerhemdes, mit einem Saume rings um die Öffnung, damit es nicht zerreiße.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, 'Sodann brachten sie am Saume des Obergewands Granatäpfel aus blauem und rotem Purpur, Karmesin und gezwirntem Byssus an,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, 'fertigten Glöckchen aus gediegenem Gold an und setzten diese Glöckchen zwischen die Granatäpfel hinein, ringsum am Saume des Obergewands zwischen die Granatäpfel hinein,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, 'so daß immer ein Glöckchen und ein Granatapfel ringsum am Saume des Obergewands miteinander abwechselten, behufs der Verrichtung des Dienstes, wie Jahwe Mose befohlen hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, 'Sodann verfertigten sie die Leibröcke aus Byssus für Aaron und seine Söhne in Weberarbeit,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, 'dazu den Kopfbund aus Byssus und die turbanartigen Mützen aus Byssus und die linnenen Beinkleider aus gezwirntem Byssus,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, 'ferner den Gürtel aus gezwirntem Byssus, blauem und rotem Purpur und Karmesin in Buntwirker-Arbeit, wie Jahwe Mose befohlen hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, 'Sodann fertigten sie das Stirnblatt, das heilige Diadem, aus gediegenem Gold und gruben darein mit Siegelstecher-Schrift: “Geheiligt dem Jahwe”.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, 'Und sie befestigten daran eine Schnur von blauem Purpur, um es oben am Kopfbund anzubringen, wie Jahwe Mose befohlen hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, 'So wurden sämtliche Arbeiten für die Offenbarungszelt-Wohnung vollendet und die Israeliten thaten ganz, wie Jahwe Mose befohlen hatte - so thaten sie.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, 'Und sie brachten die Wohnung zu Mose, das Zelt mit allen seinen Geräten, seinen Haken, Brettern, Riegeln, Säulen und Füßen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, 'dazu die Überdecke aus rotgefärbten Widderfellen, die Überdecke aus Seekuhfellen und den verhüllenden Vorhang,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, 'die Gesetzeslade mit ihren Stangen und der Deckplatte,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, 'den Tisch mit allen seinen Geräten und den Schaubroten,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, 'den Leuchter aus gediegenem Golde mit seinen in geordneter Reihe aufgesetzten Lampen und allen seinen Geräten, sowie das Öl für den Leuchter,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, 'den goldenen Altar, das Salböl, das wohlriechende Räucherwerk und den Vorhang für die Thüre des Zeltes,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, 'den kupfernen Altar und das kupferne Gitterwerk an ihm, seine Stangen und alle seine Geräte, das Becken samt seinem Gestelle,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, 'die Umhänge des Vorhofs, seine Säulen und Füße, sowie den Vorhang für das Thor des Vorhofs, seine Seile und Pflöcke, sowie alle Geräte zum Dienst in der Offenbarungszelt-Wohnung,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, 'die prachtvoll gewirkten Kleider zum Dient im Heiligtum, die heiligen Kleider Aarons, des Priesters, sowie die Kleider seiner Söhne zum priesterlichen Dienste.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, 'Ganz, wie Jahwe Mose befohlen hatte, so führten die Israeliten die gesamte Arbeit aus.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'Als aber Mose wahrnahm, daß sie nunmehr die ganze Arbeit ausgeführt hatten - wie Jahwe befohlen hatte, so hatten sie gethan -, da segnete sie Mose.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, 'Und Jahwe gebot Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, 'Am zweiten Tage des zweiten Monats sollst du die Offenbarungszelt-Wohnung aufrichten,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'die Gesetzeslade hineinsetzen und die Lade mit dem Vorhang verhüllen;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'sodann sollst du den Tisch hineinbringen und die Schichten darauf zurechtlegen, sollst den Leuchter hineinbringen und ihm seine Lampen aufsetzen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'Den goldenen Räucheraltar aber sollst du vor die Gesetzeslade stellen und den Thürvorhang der Wohnung aufhängen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'Sodann sollst du den Brandopferalter vor der Thüre der Offenbarungszelt-Wohnung aufstellen');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, 'und sollst das Becken zwischen dem Offenbarungszelt und dem Altar aufstellen und Wasser hinein thun.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'Weiter sollst du ringsum den Vorhof aufrichten und den Vorhang zum Thore des Vorhofs aufhängen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'Sodann sollst du das Salböl nehmen und die Wohnung samt allem, was sich in ihr befindet, salben und sie so weihen samt allen ihren Geräten, damit sie heilig sei.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'Ebenso sollst du den Brandopferaltar samt allen seinen Geräten salben und so den Altar weihen, damit der Altar hochheilig sei.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'Ebenso sollst du das Becken mit seinem Gestelle salben und es so weihen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'Sodann sollst du Aaron und seine Söhne herantreten lassen an die Thüre des Offenbarungszeltes und sie mit Wasser waschen');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'und sollst Aaron mit den heiligen Kleidern bekleiden, ihn salben und ihn so weihen, daß er mir Priesterdienst thue.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'Seine Söhne aber sollst du herantreten lassen und mit Leibröcken bekleiden;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'sodann sollst du sie salben, wie du ihren Vater gesalbt hast, damit sie mir Priesterdienst thun, und kraft ihrer Salbung sollen sie für alle Zeiten Priesterrecht besitzen von Geschlecht zu Geschlecht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'Und Mose that ganz, wie ihm Jahwe befohlen hatte; so that er.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'Am zweiten Tage des zweiten Monats im zweiten Jahre wurde die Wohnung aufgerichtet.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'Da richtete Mose die Wohnung auf: er stellte ihre Füße hin, setzte die Bretter darauf, fügte die Riegel ein und richtete die Säulen auf.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'Er spannte das Zeltdach über der Wohnung aus und legte oben darauf die Überdecke über das Zeltdach, wie Jahwe Mose befohlen hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'Sodann nahm er das Gesetz und legte es in die Lade, steckte die Stangen an die Lade und legte die Deckplatte oben auf die Lade.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'Hierauf brachte er die Lade hinein in die Wohnung, hängte den verhüllenden Vorhang auf und verhüllte so die Gesetzeslade, wie Jahwe Mose befohlen hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'Sodann stellte er den Tisch in das Offenbarungszelt, auf die nach Norden gewendete Seite der Wohnung außerhalb des Vorhangs,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'und legte darauf die Schichten der Brote zurecht vor Jahwe, wie Jahwe Mose befohlen hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'Sodann stellte er den Leuchter ins Offenbarungszelt gegenüber dem Tisch, auf die nach Süden gewendete Seite der Wohnung,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'und setzte die Lampen auf vor Jahwe, wie Jahwe Mose befohlen hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'Sodann stellte er den goldenen Altar ins Offenbarungszelt vor den Vorhang');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'und zündete darauf wohlriechendes Räucherwerk an, wie Jahwe Mose befohlen hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'Er hängte den Thürvorhang der Wohnung auf,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'stellte den Brandopferaltar an den Eingang der Offenbarungszelt-Wohnung und opferte darauf das Brandopfer und das Speisopfer, wie Jahwe Mose befohlen hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'Er stellte das Becken zwischen das Offenbarungszelt und den Altar und that Wasser hinein zum Waschen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'und Mose, Aaron und dessen Söhne wuschen sich jedesmal ihre Hände und Füße darin;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'so oft sie ins Offenbarungszelt hineingingen oder an den Altar herantraten, wuschen sie sich, wie Jahwe Mose befohlen hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'Sodann richtete er den Vorhof auf rings um die Wohnung und den Altar und hängte den Vorhang des Vorhofthores auf. Als aber Mose mit der Aufrichtung zu Ende gekommen war,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, 'bedeckte die Wolke das Offenbarungszelt, und die Herrlichkeit Jahwes erfüllte die Wohnung.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'Und Mose war nicht imstande, in das Offenbarungszelt hineinzugehen, weil die Wolke darauf lagerte und die Herrlichkeit Jahwes die Wohnung erfüllte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, 'Und wenn sich die Wolke von der Wohnung hinweg erhob, brachen die Israeliten jedesmal auf während ihres ganzen Zugs.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, 'Erhob sich aber die Wolke nicht, so brachen sie nicht auf, bis sie sich erhob.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, 'Denn tagsüber war die Wolke Jahwes über der Wohnung; des Nachts aber war sie feurig vor den Augen des ganzen Hauses Israel während ihres ganzen Zugs.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'Da berief Jahwe Mose und redete zu ihm vom Offenbarungszelte aus wie folgt:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, 'Rede mit den Israeliten und befiehl ihnen: Wenn jemand unter euch Jahwe eine Opfergabe bringen will, so soll die Opfergabe, die ihr bringt, vom Vieh - von den Rindern oder dem Kleinvieh - genommen sein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, 'Soll seine Opfergabe in einem Rinder-Brandopfer bestehen, so muß es ein männliches fehlloses Tier sein, welches er darbringt. Dieses bringe er hin vor die Thüre des Offenbarungszeltes, damit es ihn wohlgefällig mache vor Jahwe;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, 'sodann stemme er die Hand auf den Kopf des Brandopfers, so wird es ihn wohlgefällig machen und ihm Sühne schaffen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, 'Sodann soll er das junge Rind vor Jahwe schlachten; die Söhne Aarons aber, die Priester, sollen das Blut darbringen. Und zwar sollen sie das Blut ringsum an den Altar sprengen, der vor der Thüre des Offenbarungszeltes steht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, 'Sodann soll er das Brandopfer abhäuten und in seine Teile zerlegen;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, 'die Söhne Aarons aber, die Priester, sollen Feuer auf den Altar thun und Holzscheite über dem Feuer aufschichten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, 'Alsdann sollen die Söhne Aarons, die Priester, die Stücke, den Kopf und das Fett auf den Holzscheiten, die über dem Feuer auf dem Altar sind, zurecht legen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'Die Eingeweide aber und die Beine soll man mit Wasser waschen, und der Priester soll alles zusammen auf dem Altar in Rauch aufgehn lassen als Brandopfer, als ein Jahwe dargebrachtes Feueropfer lieblichen Geruchs.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, 'Ist aber die Opfergabe, die er als Brandopfer bringen will, dem Kleinvieh - den Lämmern oder den Ziegen - entnommen, so muß es ein männliches, fehlloses Tier sein, welches er darbringt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, 'Dieses schlachte er vor Jahwe auf der Nordseite des Altars; die Söhne Aarons aber, die Priester, sollen das Blut ringsum an den Altar sprengen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, 'Sodann soll er es in seine Teile zerlegen, und der Priester dieselben samt dem Kopf und dem Fett auf den Holzscheiten, die über dem Feuer auf dem Altar sind, zurecht legen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'Die Eingeweide aber und die Beine soll man mit Wasser waschen, und der Priester soll alles zusammen darbringen und auf dem Altar in Rauch aufgehn lassen; ein Brandopfer ist es, ein Jahwe dargebrachtes Feueropfer lieblichen Geruchs.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, 'Soll aber die Opfergabe, die er Jahwe bringen will, in einem Geflügel-Brandopfer bestehen, so müssen es Turteltauben oder junge Tauben sein, die er als Opfergabe darbringt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, 'Der Priester aber soll es an den Altar bringen, ihm den Kopf einknicken und es auf dem Altar in Rauch aufgehn lassen; das Blut aber ist auszupressen an die Wand des Altars.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'Und den Kropf samt den Federn soll er wegnehmen und östlich vom Altar auf den Aschenhaufen werfen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'Alsdann soll er ihm die Flügel einreißen, jedoch ohne sie abzutrennen. Der Priester aber soll es auf dem Altar in Rauch aufgehn lassen, auf den Holzscheiten, die über dem Feuer sind; ein Brandopfer ist es, ein Jahwe dargebrachtes Feueropfer lieblichen Geruchs.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, 'Will jemand Jahwe eine Speisopfergabe darbringen, so muß seine Opfergabe in Feinmehl bestehen; dieses übergieße er mit Öl und thue Weihrauch darauf.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'Alsdann bringe er es den Söhnen Aarons, den Priestern; der Priester aber nehme davon eine reichliche Hand voll, von dem Mehl und dem Öl, aus dem es besteht, samt dem ganzen Weihrauch, und lasse diesen Duftteil von ihm auf dem Altar in Rauch aufgehn als ein Jahwe dargebrachtes Feueropfer lieblichen Geruchs.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, 'Alles Übrige aber von dem Speisopfer soll Aaron und seinen Söhnen gehören, als hochheiliger Bestandteil der Feueropfer Jahwes.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, 'Willst du aber im Ofen Gebackenes als Speisopfergabe darbringen, so seien es ungesäuerte Kuchen von Feinmehl, die mit Öl angemacht sind, und ungesäuerte mit Öl bestrichene Fladen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, 'Soll aber deine Opfergabe in einem Speisopfer auf der Platte bestehen, so muß es aus ungesäuertem, mit Öl angemachtem Feinmehl bereitet sein;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, 'brich es in einzelne Bissen und übergieße es mit Öl - ein Speisopfer ist es.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, 'Soll aber deine Opfergabe in einem Pfannen-Speisopfer bestehen, so soll es aus Feinmehl mit Öl bereitet werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, 'Sodann sollst du das Speisopfer, das daraus bereitet ist, Jahwe hinbringen; und zwar soll man es dem Priester übergeben, damit er es an den Altar bringe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'Es soll aber der Priester von dem Speisopfer den erforderlichen Duftteil hinwegnehmen und auf dem Altar in Rauch aufgehn lassen als ein Jahwe dargebrachtes Feueropfer lieblichen Geruchs.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, 'Alles Übrige aber von dem Speisopfer soll Aaron und seinen Söhnen gehören, als hochheiliger Bestandteil der Feueropfer Jahwes.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, 'Kein Speisopfer, das ihr Jahwe darbringen wollt, darf aus gesäuertem bereitet werden; denn ihr dürft keinerlei Sauerteig oder Honig in Rauch aufgehn lassen als Feueropfer für Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, 'Als Erstlings-Opfergabe mögt ihr sie Jahwe darbringen; auf den Altar aber dürfen sie nicht kommen zum lieblichen Geruch.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, 'Alle deine Speisopfergaben aber mußt du salzen; nie darfst du das Salz des Bundes, den dein Gott angeordnet hat, bei deinem Speisopfer fehlen lassen: zu allen deinen Opfergaben mußt du Salz darbringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, 'Willst du aber Jahwe ein Speisopfer von Erstlingsfrüchten darbringen, so mußt du am Feuer geröstete Ähren oder zerriebene Körner von der frischen Frucht als dein Frühfrucht-Speisopfer darbringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, 'Du mußt aber Öl darauf thun und Weihrauch darauf legen - ein Speisopfer ist es.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, 'Sodann soll der Priester einen Duftteil von ihm - von den zerriebenen Körnern und dem Öl, woraus es besteht, - samt dem ganzen dazu gehörenden Weihrauch als Feueropfer für Jahwe in Rauch aufgehn lassen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, 'Ist aber seine Opfergabe ein Heilsopfer, und er will sie von den Rindern darbringen, so muß es ein fehlloses männliches oder weibliches Tier sein, welches er vor Jahwe bringt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'Sodann stemme er die Hand auf den Kopf seines Opfers und schlachte es vor der Thüre des OffenbarungszeItes; die Söhne Aarons aber, die Priester, sollen das Blut ringsum an den Altar sprengen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, 'Hierauf soll er von dem Heilsopfer Jahwe ein Feueropfer darbringen, nämlich das Fett, das die Eingeweide bedeckt, und alles Fett an den Eingeweiden,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'dazu die beiden Nieren samt dem Fett an ihnen, an den Lendenmuskeln, und das Anhängsel an der Leber; bei den Nieren soll er es wegnehmen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, 'Die Söhne Aarons aber sollen es auf dem Altar über dem Brandopfer, das auf den Holzscheiten über dem Feuer liegt, in Rauch aufgehn lassen als ein Jahwe dargebrachtes Feueropfer lieblichen Geruchs.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, 'Ist aber die Opfergabe, die er zu einem Heilsopfer für Jahwe bestimmt hat, dem Kleinvieh entnommen, so soll es ein fehlloses männliches oder weibliches Tier sein, welches er darbringt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, 'Will er ein Lamm als Opfergabe darbringen, so bringe er sie vor Jahwe,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'stemme seine Hand auf den Kopf seine Opfers und schlachte es sodann vor dem Offenbarungszelte; die Söhne Aarons aber sollen das Blut ringsum an den Altar sprengen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, 'Hierauf soll er von dem Heilsopfer Jahwe ein Feueropfer darbringen, und zwar das Fett desselben: den ganzen Fettschwanz - dicht am Schwanzbein soll er ihn wegnehmen -, dazu das Fett, das die Eingeweide bedeckt, samt allem Fett an den Eingeweiden,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'die beiden Nieren samt dem Fett an ihnen, an den Lendenmuskeln, und das Anhängsel an der Leber; bei den Nieren soll er es wegnehmen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, 'Und der Priester soll es auf dem AItar in Rauch aufgehn lassen als Feueropferspeise für Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, 'Besteht aber sein Opfer in einer Ziege, so bringe er es vor Jahwe,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, 'stemme die Hand auf seinen Kopf und schlachte es sodann vor dem Offenbarungszelte; die Söhne Aarons aber sollen das Blut ringsum an den Altar sprengen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, 'Hierauf bringe er seine Opfergabe davon dar, als Feueropfer für Jahwe, nämlich das Fett, das die Eingeweide bedeckt, und alles Fett an den Eingeweiden,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'die beiden Nieren samt dem Fett an ihnen, an den Lendenmuskeln, und das Anhängsel an der Leber; bei den Nieren soll er es wegnehmen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, 'Und der Priester soll es auf dem Altar in Rauch aufgehn lassen als eine Jahwe dargebrachte Feueropferspeise lieblichen Geruchs. Alles Fett gehört Jahwe zu!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, 'Das ist eine für alle Zeiten geltende Satzung, die ihr beobachten sollt von Geschlecht zu Geschlecht in allen euren Wohnsitzen: unter keinen Umständen dürft ihr Fett oder Blut genießen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, 'Und Jahwe sprach zu Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, 'Rede mit den Israeliten und befiehl ihnen: Wenn sich jemand unvorsätzlich gegen irgend eines der Verbote Jahwes vergeht, so daß er irgend etwas Verbotenes thut:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, 'Wenn sich der gesalbte Priester vergeht, und so Schuld auf das Volk kommt, so soll er für das Vergehen, dessen er sich schuldig gemacht hat, Jahwe einen fehllosen jungen Stier als Sündopfer darbringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, 'Und zwar soll er den Farren an die Thüre des Offenbarungszeltes vor Jahwe bringen, die Hand auf den Kopf des Farren aufstemmen und sodann den Farren vor Jahwe schlachten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'Hierauf nehme der gesalbte Priester einen Teil des Blutes des Farren und bringe es hinein ins Offenbarungszelt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, 'Und der Priester soll seinen Finger in das Blut tauchen und siebenmal etwas von dem Blute vor Jahwe - vor den Vorhang im Heiligtum - hinsprengen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, 'Sodann soll der Priester etwas von dem Blute an die Hörner des Altars mit dem wohlriechenden Räucherwerk streichen, der vor Jahwe im Offenbarungszelte steht; das ganze übrige Blut des Farren aber soll er am Brandopferaltar, der vor der Thüre des Offenbarungszeltes steht, auf den Boden gießen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'Sodann aber soll er von dem Sündopfer-Farren das ganze Fett abheben - das Fett, welches die Eingeweide bedeckt, und alles Fett an den Eingeweiden,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'die beiden Nieren samt dem Fett an ihnen, an den Lendenmuskeln, sowie das Anhängsel an der Leber; an den Nieren soll er es wegnehmen -');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, 'so, wie es vom Heilsopfer-Stier abgehoben wird. Und der Priester soll es auf dem Brandopferaltar in Rauch aufgehn lassen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'Was aber das Fell des Farren betrifft, sowie sein gesamtes Fleisch nebst seinem Kopf und seinen Beinen, seine Eingeweide und seinen Mist,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, 'so soll man den ganzen Farren hinaus vor das Lager schaffen an eine reine Stätte - an den Ort, wo man die Asche hinschüttet, - und ihn auf Holzscheiten verbrennen; an dem Orte, wo man die Asche hinschüttet, soll er verbrannt werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, 'Wenn sich aber die ganze Gemeinde Israel unvorsätzlich vergeht, ohne daß sich das Volk dessen bewußt wird, und sie irgend eines der Verbote Jahwes übertreten und so in Schuld geraten,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'so soll das Volk, wenn das Vergehen kund geworden ist, dessen sie sich schuldig gemacht haben, einen jungen Stier als Sündopfer darbringen. Und zwar sollen sie ihn vor das Offenbarungszelt bringen;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, 'die Vornehmsten der Gemeinde sollen vor Jahwe die Hand auf den Kopf des Farren stemmen, und dann soll man den Farren vor Jahwe schlachten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, 'Hierauf soll der gesalbte Priester einen Teil des Blutes des Farren hinein ins Offenbarungszelt bringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, 'Und der Priester soll seinen Finger in das Blut tauchen und siebenmal etwas von dem Blute vor Jahwe - vor den Vorhang - hinsprengen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, 'Auch soll er etwas von dem Blut an die Hörner des Altars streichen, der vor Jahwe im Offenbarungszelte steht; das ganze übrige Blut aber soll er am Brandopferaltar, der vor der Thüre des Offenbarungszeltes steht, an den Boden gießen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'Das gesamte Fett aber soll er von ihm abheben und auf dem Altar in Rauch aufgehn lassen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'Und mit dem Farren soll er verfahren, wie er mit dem eigenen Sündopfer-Farren verfuhr - so soll er auch mit ihm verfahren. Wenn ihnen so der Priester Sühne geschafft haben wird, wird ihnen vergeben werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'Den Farren aber soll man hinaus vor das Lager schaffen und ihn verbrennen, wie man den ersterwähnten Stier verbrannt hat. Dies ist das Gemeinde-Sündopfer.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, 'Wenn sich ein Fürst vergeht und unvorsätzlich irgend eines der Verbote Jahwes, seines Gottes, übertritt und so in Schuld gerät,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, 'und das Vergehen, dessen er sich schuldig gemacht hat, ihm kundgegeben worden ist, so soll er einen fehllosen Ziegenbock als Opfergabe bringen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'die Hand auf den Kopf des Bockes stemmen und ihn schlachten, da, wo man die Brandopfer vor Jahwe zu schlachten pflegt; ein Sündopfer ist es.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, 'Sodann soll der Priester etwas von dem Blute des Sündopfers mit dem Finger nehmen und an die Hörner des Brandopferaltars streichen; sein übriges Blut aber soll er am Brandopferaltar auf den Boden gießen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, 'Das gesamte Fett aber soll er auf dem Altar in Rauch aufgehn lassen, wie das Fett des Heilsopfers. Wenn ihm so der Priester Sühne wegen seines Vergehens geschafft haben wird, wird ihm vergeben werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, 'Wenn aber einer aus dem gemeinen Volke sich unvorsätzlich vergeht, indem er irgend eines der Verbote Jahwes übertritt und so in Schuld gerät,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, 'und ihm das Vergehen, dessen er sich schuldig gemacht hat, kundgegeben worden ist, so soll er für das Vergehen, dessen er sich schuldig gemacht hat, ein fehlloses Ziegenweibchen als Opfergabe bringen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, 'die Hand auf den Kopf des Sündopfers stemmen und sodann das Sündopfer schlachten, da, wo man die Brandopfer zu schlachten pflegt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, 'Hierauf soll der Priester etwas von dem Blute mit dem Finger nehmen und an die Hörner des Brandopferaltars streichen; das ganze übrige Blut aber soll er am Altar auf den Boden gießen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, 'Das gesamte Fett aber soll er hinwegnehmen, wie das Fett vom Heilsopfer weggenommen wurde, und der Priester soll es auf dem Altar in Rauch aufgehn lassen zum lieblichen Geruch für Jahwe. Wenn ihm so der Priester Sühne geschafft haben wird, wird ihm vergeben werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, 'Falls aber die Opfergabe, die er als Sündopfer bringt, in einem Schaflamm besteht, so muß es ein weibliches fehlloses Tier sein, das er bringt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'Sodann soll er die Hand auf den Kopf des Sündopfers stemmen und es schlachten als Sündopfer, da, wo man die Brandopfer zu schlachten pflegt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'Hierauf soll der Priester etwas von dem Blute des Sündopfers mit dem Finger nehmen und an die Hörner des Brandopferaltars streichen; das ganze übrige Blut aber soll er am Altar auf den Boden gießen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, 'Das gesamte Fett aber soll er wegnehmen, wie das Fett des Schaflamms beim Heilsopfer weggenommen zu werden pflegt, und der Priester soll es auf dem Altar über den Feueropfern Jahwes in Rauch aufgehn lassen. Wenn ihm so der Priester Sühne geschafft haben wird wegen des Vergehens, dessen er sich schuldig gemacht hatte, wird ihm vergeben werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, 'Wenn sich jemand vergeht, indem er eine laut ausgesprochene Verwünschung anhört und könnte Zeuge sein, mag er nun den Thäter gesehen oder sonst in Erfahrung gebracht haben, hat aber keine Anzeige gemacht und so Schuld auf sich geladen, -');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, 'oder wenn jemand irgend etwas Unreines berührt, sei es nun das Aas eines unreinen wilden Tiers oder das Aas eines unreinen Haustiers; oder das Aas eines unreinen Gewürms, ohne daß er sich dessen bewußt wird, es aber nachher inne wird und in Schuld gerät, -');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, 'oder wenn er mit der Unreinigkeit an einem Menschen in Berührung kommt, mit irgend welcher Unreinigkeit, infolge derer einer unrein sein kann, ohne daß er sich dessen bewußt wird, es aber nachher inne wird und in Schuld gerät, -');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, 'oder wenn jemand Ieichtfertigerweise schwört, daß er irgend etwas thun wolle, worauf man etwa leichtfertigerweise einen Schwur setzt, ohne daß er sich dessen bewußt wird, es aber nachher inne wird und durch irgend etwas Derartiges in Schuld gerät,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, 'so soll er, wenn er durch irgend etwas Derartiges in Schuld gerät, bekennen, wessen er sich schuldig gemacht hat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'Sodann soll er Jahwe als Buße für das Vergehen, dessen er sich schuldig gemacht hat, ein Stück Kleinvieh, und zwar ein Weibchen, es sei ein Schaf oder eine Ziege, zum Sündopfer bringen, und der Priester soll ihm wegen seines Vergehens Sühne schaffen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, 'Wenn er aber zur Beschaffung eines Schafs zu arm ist, so soll er Jahwe als Buße für sein Vergehen zwei Turteltauben oder zwei junge Tauben bringen, die eine als Sündopfer, die andere als Brandopfer.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, 'Und zwar soll er sie zum Priester bringen; dieser soll die zum Sündopfer bestimmte zuerst darbringen. Er soll ihr dicht vor dem Genick den Kopf einknicken, ohne ihn abzutrennen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, 'Sodann soll er etwas von dem Blute des Sündopfers an die Wand des Altars sprengen. Der Rest des Blutes aber soll auf den Grund des Altars ausgedrückt werden; ein Sündopfer ist es.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'Die andere aber soll er zum Brandopfer herrichten, so, wie es sich gebührt. Wenn ihm so der Priester Sühne geschafft haben wird wegen des Vergehens, dessen er sich schuldig gemacht hat, wird ihm vergeben werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'Wenn er aber zur Beschaffung zweier Turteltauben oder zweier junger Tauben zu arm ist, so soll er als Opfergabe für sein Vergehen ein Zehntel Epha Feinmehl zum Sündopfer bringen, doch ohne Öl darauf zu schütten oder Weihrauch darauf zu thun, denn es ist ein Sündopfer.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, 'Und er soll es zum Priester bringen. Der Priester aber soll eine reichliche Hand voll davon nehmen, als Duftteil von ihm, und soll es auf dem Altar über den Feueropfern Jahwes in Rauch aufgehn lassen; ein Sündopfer ist es.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, 'Wenn ihm so der Priester Sühne geschafft haben wird wegen des Vergehens, dessen er sich bei irgend einem jener Anlässe schuldig gemacht hat, wird ihm vergeben werden. Es soll aber wie das Speisopfer dem Priester gehören.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, 'Und Jahwe redete mit Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, 'Wenn jemand etwas veruntreut und sich unvorsätzlich an dem vergreift, was Jahwe geheiligt ist, so soll er Jahwe als Buße einen fehllosen Widder aus seiner Klienvieh-Herde, der nach deiner Schätzung einen Wert von mindestens zwei Sekeln heiligen Gewichts hat, zum Schuldopfer bringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, 'Und was er sich von dem Geheiligten widerrechtlich angeeignet hat, soll er zurückerstatten und noch ein Fünftel des Betrags darauflegen. Er soll es dem Priester übergeben, und der Priester soll ihm durch den Schuldopfer-Widder Sühne schaffen; so wird ihm vergeben werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, 'Und wenn sich jemand vergeht und unbewußt irgend eines der Verbote Jahwes übertritt und so in Schuld gerät und Verschuldung auf sich geladen hat,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, 'so soll er einen fehllosen Widder aus seiner Kleinvieh-Herde nach deiner Schätzung als Schuldopfer zum Priester bringen, und der Priester soll ihm Sühne schaffen wegen des Vergehens, das er unbewußt begangen hat; so wird ihm vergeben werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, 'Ein Schuldopfer ist es; hat er sich doch gegen Jahwe verschuldet.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 20, 'Und Jahwe redete mit Mose aIso:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 21, 'Wenn sich jemand vergeht und sich einer Veruntreuung gegen Jahwe schuldig macht, indem er seinem Nächsten etwas Anvertrautes oder Hinterlegtes oder Geraubtes ableugnet oder seinen Nächsten übervorteilt');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 22, 'oder Verlorenes, das er gefunden hat, ableugnet oder indem er einen falschen Eid schwört wegen irgend einer Handlung, durch die sich einer vergehen kann, -');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 23, 'wenn er sich so vergeht und in Schuld gerät, so soll er dasjenige, was er geraubt oder erpreßt hat, oder was ihm anvertraut worden war, oder das Verlorene, das er gefunden,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 24, 'oder dasjenige, um dessentwillen er betrüglich geschworen hat - was es auch sein mag - zurückerstatten; und zwar soll er es nach seinem vollen Wert ersetzen und noch ein Fünftel des Betrags darauflegen. Dem soll er es geben, dem es zukommt, an dem Tage, wo er seine Buße entrichtet.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 25, 'Als Buße aber soll er für Jahwe einen fehllosen Widder aus seiner Kleinvieh-Herde nach deiner Schätzung als Schuldopfer zum Priester bringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 26, 'Und der Priester soll ihm Sühne schaffen vor Jahwe; so wird ihm vergeben werden - jedwede Handlung, durch die sich einer verschulden kann.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, 'Und Jahwe redete mit Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, 'Gieb Aaron und seinen Söhnen folgende Weisung: Dies sind die Bestimmungen in betreff des Brandopfers. Dieses - das Brandopfer - soll auf dem Altar da, wo es angezündet wurde, die ganze Nacht hindurch verbleiben bis zum Morgen; das Altarfeuer soll damit brennend erhalten werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, 'Und der Priester ziehe sein linnenes Gewand an, bedecke seine Scham mit linnenen Beinkleidern, nehme die Asche weg, in welche das Brandopfer vom Feuer auf dem Altar verwandelt ist, und schütte sie neben den Altar.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, 'Hierauf ziehe er seine Kleider aus, lege andere Kleider an und schaffe die Asche hinaus vor das Lager an einen reinen Ort.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, 'Das Feuer auf dem Altar aber soll damit brennend erhalten werden und nie erlöschen. Alle Morgen soll der Priester Holzscheite darauf anzünden, das Brandopfer darauf schichten und die Fettstücke der Heilsopfer über demselben in Rauch aufgehn lassen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, 'Immerfort soll Feuer auf dem Altar brennen und nie erlöschen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, 'Und dies sind die Bestimmungen in betreff des Speisopfers. Die Söhne Aarons sollen es vor Jahwe, heran an den Altar, bringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, 'Sodann soll er eine Hand voll davon nehmen - von dem Feinmehl und dem Öl, aus welchem das Speisopfer besteht, - dazu den ganzen Weihrauch, der auf dem Speisopfer liegt, und es auf dem Altar in Rauch aufgehn lassen als ein Feueropfer lieblichen Geruchs, als den Duftteil von ihm für Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, 'Und was übrig ist von ihm, das sollen Aaron und seine Söhne essen. Ungesäuert soll es gegessen werden an heiliger Stätte; im Vorhof des Offenbarungszeltes sollen sie es essen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, 'Es darf nicht mit Sauerteig gebacken werden. Ich verleihe es ihnen als ihren Anteil an meinen Feueropfern; hochheilig ist es, wie das Sündopfer und das Schuldopfer.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, 'Alles, was männlich ist unter den Kindern Aarons, darf es essen, kraft eines für alle Zeiten geltenden Rechtes, das euch gegenüber den Feueropfern Jahwes zusteht von GeschIecht zu Geschlecht. Jeder der sie berührt, ist dem Heiligtume verfallen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, 'Und Jahwe redete mit Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, 'Dies sei die Opfergabe Aarons und seiner Söhne, die sie Jahwe darzubringen haben an dem Tag, an welchem er gesalbt wird: Ein Zehntel Epha Feinmehl als regelmäßiges Speisopfer - die eine Hälfte davon am Morgen, die andere Hälfte am Abend.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, 'Auf einer Platte soll es mit Öl bereitet werden; eingerührt sollst du es bringen. Zu einem Speisopfer in Bissen sollst du es zerbrechen und es darbringen zum lieblichen Geruch für Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, 'Der Priester, der aus der Reihe seiner Söhne an seiner Statt gesalbt ist, soll es verrichten, kraft einer für alle Zeiten geltenden Satzung Jahwes; als Ganzopfer soll es verbrannt werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, 'Alle Priester-Speisopfer sollen Ganzopfer sein; sie dürfen nicht gegessen werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, 'Und Jahwe redete mit Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, 'Sprich zu Aaron und zu seinen Söhnen und gebiete ihnen: Dies sind die Bestimmungen in betreff des Sündopfers: Da, wo das Brandopfer zu schIachten ist vor Jahwe, soll auch das Sündopfer geschlachtet werden; hochheiIig ist es.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, 'Der Priester, der das Sündopfer darbringt, soll es verzehren; an heiliger Stätte muß es gegessen werden, im Vorhofe des Offenbarungszeltes.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, 'Jeder, der das Fleisch von ihm berührt ist dem Heiligtume verfallen; und wenn etwas von seinem Blut ans Kleid spritzt, so mußt du das von ihm bespritzte an heiliger Stätte waschen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, 'Irdenes Gefäß, in dem es gekocht wurde, muß zerbrochen werden; wurde es aber in einem kupfernen Gefäße gekocht, so muß dieses gescheuert und gehörig ausgespült werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, 'Alles, was männlich ist unter den Priestern, darf es essen; hochheilig ist es.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, 'Alle die Sündopfer aber, von denen ein Teil des Blutes ins Offenbarungszelt gebracht worden ist, um die Sühnegebräuche im Heiligtume zu vollziehen, dürfen nicht gegessen werden, sondern sind zu verbrennen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, 'Und dies sind die Bestimmungen in betreff des Schuldopfers; hochheilig ist es.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, 'Da, wo man das Brandopfer schlachtet, soll man auch das Schuldopfer schlachten, und das Blut desselben soll man ringsum an den Altar sprengen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'Das gesamte Fett aber soll man von ihm darbringen: Den Fettschwanz und das Fett, welches die Eingeweide bedeckt,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, 'die beiden Nieren samt dem Fett an ihnen, an den Lendenmuskeln, sowie das Anhängsel an der Leber; bei den Nieren soll er es wegnehmen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, 'Und der Priester soll es auf dem Altar in Rauch aufgehn lassen als ein Jahwe dargebrachtes Feueropfer; ein Schuldopfer ist es.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, 'Alles, was männlich ist unter den Priestern, soll es essen; an heiliger Stätte muß es gegessen werden - hochheilig ist es.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, 'Wie vom Sündopfer, so gilt ganz gleich auch vom Schuldopfer: Dem Priester, der die Sühnegebräuche damit vollzieht, dem soll es gehören!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, 'Und dem Priester, der das Brandopfer jemandes darbringt, demselben soll das Fell des Brandopfers, welches er dargebracht hat, gehören.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, 'Ebenso sollen alle Speisopfer, die im Ofen gebacken, sowie alle, die in der Pfanne und auf der Platte bereitet sind, dem Priester gehören, der sie darbringt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, 'Alle Speisopfer, die mit Öl angemachten, wie die trockenen, sollen allen Söhnen Aarons gehören, einem wie dem anderen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, 'Und dies sind die Bestimmungen in betreff der Heilsopfer, die man Jahwe darbringt:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, 'Wenn es einer als Danksagung darbringt, so soll er zu dem Dankopfer ungesäuerte, mit ÖI angemachte Kuchen und ungesäuerte Fladen, die mit Öl bestrichen sind, und eingerührtes Feinmehl - mit Öl angemachte Kuchen darbringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'Nebst Kuchen von gesäuertem Brote soll er seine Opfergabe darbringen, außer dem Opfertier, in welchem sein Heils-Dankopfer besteht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, 'Und zwar soll er davon je ein Stück von jeder Art Opfergabe als Hebeopfer für Jahwe darbringen; dem Priester, der das Blut des Heilsopfers sprengt, soll es gehören.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, 'Das Fleisch des Heils-Dankopfers aber muß an demselben Tage gegessen werden, an welchem das Opfer gebracht wird; man darf nichts davon übrig lassen bis zum Morgen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'Beruht aber das Opfer, das er darbringt, auf einem Gelübde oder ist es eine freiwillige Leistung, so soll es an demselben Tage gegessen werden, an welchem das Opfer dargebracht wird; doch mag, was davon übrig geblieben ist, am folgenden Tage gegessen werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, 'Was aber am dritten Tage vom Opferfleisch übrig ist, muß verbrannt werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, 'Sollte aber auch am dritten Tage noch von dem Heilsopfer-Fleische gegessen werden, so wird dies den, der es dargebracht hat, nicht wohlgefällig machen; es wird ihm nicht angerechnet werden, sondern als Verdorbenes gelten, und derjenige, der davon ißt, wird Verschuldung auf sich laden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'Auch solches Fleisch, welches mit irgend etwas Unreinem in Berührung gekommen ist, darf nicht gegessen werden, sondern ist zu verbrennen. Was aber das Fleisch überhaupt anlangt, so darf jeder, der rein ist, Fleisch essen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, 'Derjenige aber, der Fleisch von dem Jahwe dargebrachten Heilsopfer ißt, während er mit Unreinigkeit behaftet ist, ein solcher soll hinweggetilgt werden aus seinen Volksgenossen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'Und wenn jemand mit irgend etwas Unreinem in Berührung gekommen ist, sei es nun mit der Unreinigkeit an einem Menschen oder mit einem unreinen Vieh oder irgend einem unreinen Greuel, und ißt von dem Fleische des Jahwe dargebrachten Heilsopfers, ein solcher soll hinweggetilgt werden aus seinen Volksgenossen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, 'Und Jahwe redete mit Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, 'Sprich zu den Israeliten und gebiete ihnen: Ihr dürft keinerlei Fett von Rindern, Schafen oder Ziegen essen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, 'Das Fett von gefallenen und das Fett von zerrissenen Tieren kann zu allerlei Zwecken verwendet werden, aber essen dürft ihr es nicht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, 'Denn jeder, der Fett von Tierarten genießt, wie man sie Jahwe als Feueropfer darbringt, - hinwegzutilgen ist ein solcher, der es genießt, aus seinen Volksgenossen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'Ebenso dürft ihr auch kein Blut genießen in allen euren Wohnsitzen, weder von Vögeln noch von vierfüßigen Tieren.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, 'Jeder, der irgend Blut äße, der soll hinweggetilgt werden aus seinen Volksgenossen!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, 'Und Jahwe redete mit Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, 'Sprich zu den Israeliten und gebiete ihnen: Wer Jahwe sein Heilsopfer darbringt, der bringe Jahwe von seinem Heilsopfer den Opferanteil, den er ihm schuldet.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'Er selbst bringe die Stücke, die Jahwe als Feueropfer gehören: Das Fett nebst der Brust soll er herzubringen; die Brust, damit sie als Webe vor Jahwe gewebt werde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, 'Und der Priester soll das Fett auf dem Altar in Rauch aufgehn lassen, die Brust aber soll Aaron und seinen Söhnen gehören.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, 'Auch die rechte Keule sollt ihr von euren Heilsopfern dem Priester als Hebe geben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'Derjenige von den Söhnen Aarons, der das Blut und das Fett des Heilsopfers darbringt, dem soll die rechte Keule als Anteil zufallen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, 'Denn die Webe-Brust und die Hebe-Keule nehme ich von den Heilsopfern der Israeliten in Anspruch und gebe sie Aaron, dem Priester, und seinen Söhnen als eine Gebühr, die allezeit von den Israeliten zu entrichten ist.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, 'Dies ist der Anteil Aarons und seiner Söhne an den Feueropfern Jahwes, an dem Tag, an welchem er sie herzutreten ließ, Jahwe Priesterdienst zu thun,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'den ihnen Jahwe an dem Tag, an welchem er sie salbte, als eine Gabe seitens der Israeliten überwies, als eine Gebühr, die diesen alle Zeit obliegen sollte von Geschlecht zu Geschlecht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, 'Dies sind die Bestimmungen in betreff des Brandopfers, des Speisopfers, des Sündopfers, des Schuldopfers, des Einsetzungs-Opfers und des Heilsopfers,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'welche Jahwe Mose anbefahl auf dem Berge Sinai, als er die Israeliten anwies, Jahwe ihre Opfergaben darzubringen, in der Steppe am Sinai.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, 'Und Jahwe redete mit Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, 'Nimm Aaron samt seinen Söhnen, dazu die Kleider, das Salböl, den Sündopfer-Farren, die beiden Widder, sowie den Korb mit dem Ungesäuerten,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'und versammle die ganze Gemeinde vor der Thüre des Offenbarungszeltes.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'Da tat Mose, wie ihm Jahwe befohlen hatte, und die Gemeinde versammelte sich vor der Thüre des Offenbarungszeltes.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'Da sprach Mose zu der Gemeinde: Dies ist\'s, was Jahwe zu thun befohlen hat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, 'Hierauf ließ Mose Aaron und seine Söhne antreten und wusch sie mit Wasser.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'Sodann legte er ihm den Leibrock an, umgürtete ihn mit dem Gürtel, bekleidete ihn mit dem Obergewand und legte ihm das Schulterkleid an; sodann band er ihm die Binde des Schulterkleids um und befestigte es so an ihm.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'Hierauf legte er ihm die Tasche an und that in die Tasche die Urim und die Tummim.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'Sodann setzte er ihm den Kopfbund aufs Haupt; auf der Vorderseite des Kopfbunds aber befestigte er das goldene Stirnblatt, das heilige Diadem, wie Jahwe Mose befohlen hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'Sodann nahm Mose das Salböl, salbte die Wohnung und alles, was sich in ihr befand, und weihte es so.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, 'Auch sprengte er davon auf den Altar, siebenmal, und salbte den Altar samt allen seinen Geräten, sowie das Becken samt seinem Gestelle, um sie so zu weihen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'Sodann goß Mose einen Teil des Salböls auf das Haupt Aarons und salbte ihn, um ihn so zu weihen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'Hierauf ließ Mose die Söhne Aarons herantreten, bekleidete sie mit Leibröcken, umgürtete sie mit einem Gürtel und setzte ihnen Mützen auf, wie Jahwe Mose befohlen hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'Sodann brachte er den Sündopfer-Farren herzu, und Aaron und seine Söhne stemmten die Hand auf den Kopf des Sündopfer-Farren.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, 'Dann schlachtete ihn Mose, nahm das Blut, strich es mit dem Finger ringsum an die Hörner des Altars und entsündigte so den Altar; das übrige Blut aber goß er am Altar auf den Boden. So weihte er den Altar, indem er die Sühnehandlungen an ihm vollzog.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'Sodann nahm er das ganze Fett, welches die Eingeweide bedeckte, das Anhängsel an der Leber und die beiden Nieren samt dem Fett daran, und Mose ließ es auf dem Altar in Rauch aufgehn.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, 'Den Farren aber samt seinem Fell, seinem Fleisch und seinem Mist verbrannte er außerhalb des Lagers, wie Jahwe Mose befohlen hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'Sodann lief er den Widder zum Brandopfer herzubringen, und Aaron und seine Söhne stemmten die Hand auf den Kopf des Widders.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, 'Dann schlachtete ihn Mose und sprengte das Blut ringsum an den Altar.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, 'Den Widder aber zerlegte er in seine Teile; sodann ließ Mose den Kopf, die Stücke und das Fett in Rauch aufgehn.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'Die Eingeweide aber und die Beine wusch er mit Wasser; sodann ließ Mose den ganzen Widder auf dem Altar in Rauch aufgehn als ein Brandopfer lieblichen Geruchs, als eine Jahwe dargebrachte Feuerspeise, wie Jahwe Mose befohlen hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'Hierauf ließ er den anderen Widder, den Einsetzungswidder, herzubringen, und Aaron und seine Söhne stemmten die Hand auf den Kopf des Widders.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, 'Dann schlachtete ihn Mose, nahm etwas von dem Blut und strich es an das rechte Ohrläppchen Aarons, sowie an seinen rechten Daumen und seine rechte große Zehe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'Sodann ließ Mose die Söhne Aarons herantreten und strich etwas von dem Blut an ihr rechtes Ohrläppchen, sowie an ihren rechten Daumen und ihre rechte große Zehe; das übrige Blut aber sprengte Mose ringsum an den Altar.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, 'Sodann nahm er das Fett, den Fettschwanz samt all\' dem Fett an den Eingeweiden, das Anhängsel an der Leber und die beiden Nieren samt ihrem Fette, sowie die rechte Keule.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'Dazu nahm er aus dem Korbe mit dem Ungesäuerten, der vor Jahwe stand, einen ungesäuerten Kuchen, einen mit Öl angemachten Brotkuchen und einen Fladen und legte sie zu den Fettstücken und zu der rechten Keule.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, 'Dann gab er alles miteinander Aaron und seinen Söhnen in die Hände und webte es als Webe vor Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, 'Hierauf nahm es ihnen Mose aus den Händen und lies es auf dem Altar über dem Brandopfer in Rauch aufgehn als ein Einsetzungs- Opfer lieblichen Geruchs, als ein Jahwe dargebrachtes Feueropfer.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, 'Sodann nahm Mose die Brust von dem Einsetzungs-Widder und webte sie als Webe vor Jahwe; sie fiel Mose als Anteil zu, wie Jahwe Mose befohlen hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, 'Sodann nahm Mose einen Teil des Salböls und des Blutes, das sich auf dem Altar befand, und sprengte es auf Aaron und seine Kleider, sowie auf seine Söhne und ihre Kleider, und weihte so Aaron und seine Kleider, sowie seine Söhne und ihre Kleider.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, 'Hierauf gebot Mose Aaron und seinen Söhnen: kocht das Fleisch vor der Thüre des Offenbarungszeltes und verzehrt es daselbst samt dem Brote, welches sich in dem zum Einsetzungs-Opfer gehörenden Korbe befindet, wie ich angewiesen wurde durch den Befehl: Aaron und seine Söhne sollen es verzehren!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'Was von dem Fleisch und dem Brot übrig bleibt, müßt ihr verbrennen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, 'Uns sieben Tage lang dürft ihr nicht von der Thüre des Offenbarungszeltes hinweggehen, bis zu dem Tage, wo die zu eurer Einsetzung bestimmte Zeit um ist; denn sieben Tage hindurch soll er euch die Hand füllen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, 'Wie er heute gethan hat, so hat Jahwe weiter zu tun geboten, um euch Sühne zu schaffen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, 'Sieben Tage hindurch müßt ihr Tag und Nacht vor der Thüre des Offenbarungszeltes bleiben und die Anordnungen Jahwes befolgen; sonst müßtet ihr sterben - so ist mir\'s geboten!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'Aaron aber und seine Söhne thaten alles, was Jahwe durch Mose befohlen hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, 'Am achten Tag aber berief Mose Aaron und seine Söhne und die Vornehmsten des Volks');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, 'und gebot Aaron: Hole dir ein junges Rind zum Sündopfer und einen Widder zum Brandopfer, beide fehllos, und bringe sie dar vor Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, 'Den Israeliten aber gebiete folgendes: Holt einen Ziegenbock zum Sündopfer, sowie ein Kalb und ein Schaf, beide einjährig und fehllos, zum Brandopfer,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, 'ferner einen Stier und einen Widder zum Heilsopfer, um sie vor Jahwe zu schlachten, dazu ein mit Öl angemachtes Speisopfer; denn heute wird euch Jahwe erscheinen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, 'Da brachten sie, was Mose verlangt hatte, hin vor das Offenbarungszelt, und die ganze Gemeinde nahte herzu und trat vor Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, 'Und Mose sprach: Dies ist\'s, was euch Jahwe zu thun befohlen hat, damit euch die Herrlichkeit Jahwes erscheine.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'Sodann gebot Mose Aaron: Tritt heran an den Altar und besorge dein Sündopfer und dein Brandopfer, damit du für dich und das Volk Sühne schaffst; sodann besorge die Opfergabe des Volks, damit du für sie Sühne schaffst, wie Jahwe befohlen hat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, 'Da trat Aaron an den Altar heran und schlachtete das Kalb, das zum Sündopfer für ihn selbst bestimmt war.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'Die Söhne Aarons aber reichten ihm das Blut; da tauchte er seinen Finger in das Blut und strich es an die Hörner des Altars. Das übrige Blut goß er am Altar auf den Boden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'Das Fett des Sündopfers aber samt den Nieren und dem Anhängsel an der Leber ließ er auf dem Altar in Rauch aufgehn, wie Jahwe Mose befohlen hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'Das Fleisch und das Fell verbrannte er außerhalb des Lagers.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'Sodann schlachtete er das Brandopfer; die Söhne Aarons überreichten ihm das Blut, und er sprengte es ringsum an den Altar.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, 'Das Brandopfer aber reichten sie ihm in Stücke zerlegt samt dem Kopf, und er ließ es auf dem Altar in Rauch aufgehn.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'Die Eingeweide und die Beine wusch er mit Wasser und ließ sie auf dem Altar über dem Brandopfer in Rauch aufgehn.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, 'Sodann brachte er die Opfergabe des Volkes dar: Er nahm den Bock, der zum Sündopfer für das Volk bestimmt war, schlachtete ihn und brachte ihn als Sündopfer, wie zuvor.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'Hierauf brachte er das Brandopfer dar und besorgte es, wie es sich gebührt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'Sodann brachte er das Speisopfer dar, nahm eine Hand voll davon und ließ sie auf dem Altar in Rauch aufgehn, außer dem Morgen-Brandopfer.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'Hierauf schlachtete er das Rind und den Widder als Heilsopfer für das Volk; die Söhne Aarons reichten ihm das Blut, und er sprengte es ringsum an den Altar.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, 'Was aber die Fettstücke des Rindes anlangt, sowie den Fettschwanz des Widders samt dem die Eingeweide bedeckenden Fett, den Nieren und dem Anhängsel an der Leber,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, 'so legten sie diese Fettstücke auf die Bruststücke, und er ließ die Fettstücke auf dem Altar in Rauch aufgehn.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'Die Bruststücke aber und die rechte Keule webte Aaron als Webe vor Jahwe, wie Mose befohlen hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, 'Sodann erhob Aaron seine Hände nach dem Volke zu und segnete sie; und nachdem er so das Sündopfer, das Brandopfer und das Heilsopfer befolgt hatte, stieg er herab.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, 'Hierauf gingen Mose und Aaron hinein ins Offenbarungszelt; und als sie wieder herauskamen, segneten sie das Volk. Da erschien die Herrlichkeit Jahwes dem ganzen Volk,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, 'und es ging Feuer aus von Jahwe und verzehrte das Brandopfer und die Fettstücke auf dem Altar. Als alles Volk dies wahrnahm, da jubelten sie und fielen auf ihr Antlitz.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, 'Nadab aber und Abihu, die Söhne Aarons, nahmen ihre Kohlenpfannen, thaten Feuer hinein und legten Räucherwerk darauf und brachten so ein ungehöriges Feueropfer, das er ihnen nicht geboten hatte, vor Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, 'Da ging Feuer aus von Jahwe und verzehrte sie, so daß sie dort vor Jahwe starben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'Da sprach Mose zu Aaron: Hier erfüllt sich, was Jahwe angekündigt hat, indem er sprach: An denen, die mir nahe stehen, will ich meine Heiligkeit erweisen. Und vor allem Volke will ich mich verherrlichen. Aaron aber verhielt sich schweigend.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'Da rief Mose Misael und Elzaphan, sie Söhne Usiels, des Oheims Aarons, herbei und gebot ihnen: Tretet herzu und tragt eure Verwandten von dem Platze vor dem Heiligtum hinweg hinaus vor das Lager!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'Da traten sie herzu und trugen sie in ihren Leibröcken hinaus vor das Lager, wie Mose geboten hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, 'Aaron aber und seinen Söhnen Eleasar und Ithamar gebot Mose: Ihr dürft eure Häupter nicht entblößen und eure Kleider nicht zerreißen; sonst müßtet ihr sterben, und er würde heftig auf die ganze Gemeinde zürnen! Eure Brüder aber, das ganze Haus Israel, mögen den Brand beweinen, den Jahwe angerichtet hat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, 'Auch dürft ihr nicht zur Thüre des Offenbarungszeltes hinausgehen, damit ihr nicht sterbt; denn das Salböl Jahwes ist auf euch! Sie aber thaten nach Moses Geheiß.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, 'Und Jahwe redete mit Aaron also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, 'Wein und berauschendes Getränk dürft ihr - du und deine Söhne - nicht trinken, wenn ihr ins Offenbarungszelt hineingeht, sonst müßt ihr sterben. Das ist eine für alle Zeiten geltende Satzung, die ihr beobachten sollt von Geschlecht zu Geschlecht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, 'Und ihr sollt unterscheiden zwischen dem, was heilig, und dem, was nicht heilig ist, zwischen dem, was unrein, und dem, was rein ist,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, 'und sollt die Israeliten alle die Satzungen lehren, die ihnen Jahwe durch Mose verkündigt hat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, 'Und Mose gebot Aaron, sowie Eleasar und Ithamar, die ihm von seinen Söhnen noch geblieben waren: Nehmt das Speisopfer, das von den Jahwe dargebrachten Feueropfern noch übrig ist, und eßt es ungesäuert neben dem Altar, denn es ist hochheilig.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, 'Darum sollt ihr es an heiliger Stätte essen, denn es ist die Gebühr, die dir und deinen Söhnen von den Feueropfern zufällt - so ist mir\'s geboten!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'Die Webebrust aber und die Hebekeule sollst du neben deinen Söhnen und Töchtern an reiner Stätte essen, denn sie sind verliehen als die Gebühr, die dir und deinen Kindern von den Heilsopfern der Israeliten zufällt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, 'Die Hebekeule und die Webebrust soll man neben den zu Feueropfern bestimmten Fettstücken bringen, damit sie als Webe vor Jahwe gewebt werden; dann sollen sie dir und deinen Kindern als eine für alle Zeiten feststehende Gebühr zufallen, wie Jahwe befohlen hat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, 'Als sich nun Mose angelegentlich nach dem Sündopfer-Bock erkundigte, befand sich, daß er verbrannt war. Da zürnte er heftig auf Eleasar und Ithamar, die Söhne Aarons, die diesem noch geblieben waren, und fragte:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, 'Warum habt ihr denn das Sündopfer nicht gegessen an heiliger Stätte? Denn es ist hochheilig, und er hat es euch verliehen, um die Verschuldung der Gemeinde hinwegzuschaffen und ihnen Sühne vor Jahwe zu erwirken.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, 'Ist ja doch sein Blut nicht ins Innere des Heiligtums gebracht worden; somit mußtet ihr es essen im heiligen Bezirke, wie ich befohlen hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'Da antwortete Aaron Mose: Bedenke, sie haben heute ihr Sündopfer und ihr Brandopfer vor Jahwe dargebracht, und mich betraf dennoch solches; wenn ich nun heute Sündopferfleisch genießen wollte, würde das wohl Jahwe gefallen?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'Als Mose das hörte, ließ er sich\'s gefallen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, 'Und Jahwe redete mit Mose und Aaron und gebot ihnen folgendes:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, 'Sprecht zu den Israeliten also: Dies sind die Tiere, die ihr essen dürft von allen Vierfüßlern auf Erden:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, 'alle Vierfüßler, die gespaltene Klauen haben - und zwar völlig durchgespaltene Klauen - und wiederkäuen, die dürft ihr essen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, 'Dagegen dürft ihr von den Tieren, welche wiederkäuen und welche gespaltene Klauen haben, die nachfolgenden nicht essen: Das Kamel, denn es ist zwar Wiederkäuer, hat aber keine durchgespaltenen Klauen - als unrein hat es euch zu gelten;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, 'den Klippdachs, denn er ist zwar Wiederkäuer, hat aber keine durchgespaltenen Klauen - als unrein hat er euch zu gelten;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, 'den Hasen, denn er ist zwar Wiederkäuer, hat aber keine durchgespaltenen Klauen - als unrein hat er euch zu gelten;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, 'das Schwein, denn es hat zwar völlig durchgespaltene Klauen, ist aber kein Wiederkäuer - als unrein hat es euch zu gelten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, 'Ihr dürft weder ihr Fleisch genießen, noch dürft ihr ihr Aas berühren - als unrein haben Sie euch zu gelten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, 'Folgende dürft ihr essen von allen, die im Wasser leben: Alle Wassertiere sowohl im Meer, als in den Bächen, welche Flossen und Schuppen haben, die dürft ihr essen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, 'Alles aber, sowohl im Meer, als in den Bächen, was keine Flossen und Schuppen hat, unter allem, was im Wasser wimmelt, und unter allen Lebewesen, die sich im Wasser befinden, soll euch ein Greuel sein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, 'Ein Greuel sollen sie euch sein: ihr Fleisch dürft ihr nicht genießen und ihr Aas müßt ihr verabscheuen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, 'Alle Wassertiere, die keine Flossen und Schuppen haben, sollen euch ein Greuel sein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, 'Von den Vögeln aber sollt ihr folgende verabscheuen - sie dürfen nicht gegessen werden, sondern sind zu verabscheuen -: den Adler, den Bartgeier, den Geier,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, 'die Weihe und das Geschlecht der Falken,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, 'das ganze Geschlecht der Raben,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, 'den Strauß, die Schwalbe, die Möve und das Geschlecht der Habichte;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, 'das Käuzchen, den Sturzpelikan, den Uhu,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, 'die Eule, den Pelikan, den Erdgeier,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, 'den Storch, das Geschlecht der Regenpfeifer, den Wiedehopf und die Fledermaus.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, 'Alle geflügelten kleinen Tiere, die auf vieren gehen, sollen euch ein Greuel sein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, 'Von allen geflügelten kleinen Tieren, die auf vieren gehen, dürft ihr nur diejenigen essen, welche oberhalb ihrer Füße zwei Hinterschenkel haben, um damit auf der Erde zu hüpfen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, 'Von diesen dürft ihr die folgenden essen: Die verschiedenen Arten der Zugheuschrecken, die verschiedenen Arten der Solamheuschrecken, die verschiedenen Arten der Chargolheuschrecken und die verschiedenen Arten der Chagabheuschrecken.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, 'Alle übrigen geflügelten kleinen Tiere aber, die vier Füße haben, sollen euch ein Greuel sein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, 'Durch diese Tiere verunreinigt ihr euch; jeder, der ihr Aas anrührt, wird unrein bis zum Abend.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, 'Und jeder, der eines ihrer Äser trägt, muß seine Kleider waschen und wird unrein bis zum Abend -');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, 'durch jedes Tier, welches gespaltene, aber doch nicht völlig durchgespaltene Klauen hat und nicht wiederkäut. Als unrein sollen sie euch gelten; jeder, der sie berührt, wird unrein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, 'Auch alle die, welche auf Tatzen gehen, unter allen den Tieren, die auf Vieren gehen, sollen euch als unrein gelten; jeder, der ihr Aas berührt, wird unrein bis zum Abend.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'Und wer ihr Aas trägt, muß seine Kleider waschen und wird unrein bis zum Abend - als unrein sollen sie euch gelten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, 'Diese aber sind es, die euch als unrein gelten sollen unter den kleinen Tieren, die sich auf der Erde tummeln: Das Wiesel, die Maus, die verschiedenen Arten der Eidechse,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, 'die Anaka, der Koach, die Letaa, der Chomet und die Tinschemeth.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, 'Das sind die, welche euch als unrein gelten sollen unter allen kleinen Tieren; jeder, der sie berührt, wenn sie tot sind, wird unrein bis zum Abend.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, 'Und alles, worauf eines von ihnen im Tode fällt, wird unrein: So jedes hölzerne Gefäß oder Gewand oder Fell oder Sacktuch - alle Gefäße, die zum Gebrauche dienen. Sie sind ins Wasser zu stecken und bleiben unrein bis zum Abend; dann sind sie wieder rein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'Wenn aber eines von ihnen in irgend ein irdenes Gefäß hineinfällt, so wird alles, was darin ist, unrein, und ihr müßt es zerbrechen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'Jede Art Speise, die gegessen zu werden pflegt, an die Wasser kommt, wird unrein; ebenso wird jedes Getränk, das getrunken zu werden pflegt, in jederlei Gefäß unrein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, 'Und alles, worauf eines ihrer Äser fällt, wird unrein: ein Backtopf oder Kochherd muß eingerissen werden. Unrein sind sie und sollen euch als unrein gelten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, 'Nur Quellen und Brunnen, also Wasserbehälter, bleiben rein; wer aber ihr Aas berührt, wird unrein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, 'Und wenn eines ihrer Äser auf irgend welche Sämereien fällt, die ausgesäet werden, so bleiben diese rein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, 'Wird aber Wasser an die Sämereien gebracht, und es fällt dann eines ihrer Äser darauf, so haben sie euch als unrein zu gelten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, 'Und wenn eines von den Tieren stirbt, die euch zur Speise dienen, so wird derjenige, der sein Aas berührt, unrein bis zum Abend.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'Und wer etwas von seinem Aase genießt, muß seine Kleider waschen und bleibt unrein bis zum Abend; und wer sein Aas trägt, muß seine Kleider waschen und bleibt unrein bis zum Abend.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, 'Alle kleinen Tiere, die sich auf der Erde tummeln, sind als ein Greuel zu betrachten und dürfen nicht gegessen werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, 'Alle, die auf dem Bauche kriechen, und alle, die auf vieren gehen, sowie alle die, welche noch mehr Füße haben, von allen den kleinen Tieren, die sich auf der Erde tummeln, die dürft ihr nicht essen, denn sie sind als ein Greuel zu betrachten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, 'Macht euch nicht selbst abscheulich durch irgend welche kriechenden Tiere und verunreinigt euch nicht durch sie, so daß ihr unrein durch sie werdet.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, 'Denn ich bin Jahwe, euer Gott; so erweist euch denn heilig und seid heilig, denn ich bin heilig! Und verunreinigt euch nicht selbst durch irgend welche kleinen Tiere, von denen es auf Erden wimmelt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, 'Denn ich bin Jahwe, der euch aus Ägypten hinweggeführt hat, um euer Gott zu sein; darum sollt ihr heilig sein, denn ich bin heilig.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, 'Das sind die Bestimmungen in betreff der Vierfüßler und der Vögel und aller der Lebewesen, die sich im Wasser tummeln, und aller der Wesen, die sich auf der Erde regen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, 'damit man unterscheide zwischen dem, was unrein, und dem, was rein ist, sowie zwischen den eßbaren Tieren und den Tieren, welche nicht gegessen werden dürfen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, 'Und Jahwe redete mit Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, 'Sprich zu den Israeliten und gebiete ihnen: Wenn ein Weib niederkommt und einen Knaben gebiert, so bleibt sie sieben Tage unrein; ebenso lange, als ihre Unreinigkeit infolge des Monatsflusses währt, ist sie unrein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'Am achten Tag aber ist seine Vorhaut zu beschneiden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'Sodann muß sie 33 Tage lang im Reinigungsblute bleiben; sie darf nichts Heiliges berühren und nicht ins Heiligtum kommen, bis die Zeit ihrer Reinigung um ist.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, 'Gebiert sie aber ein Mädchen, so bleibt sie auf zwei Wochen unrein, wie bei ihrer monatlichen Unreinigkeit, und 66 Tage muß sie im Reinigungsblute bleiben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, 'Wenn aber die Zeit ihrer Reinigung um ist - mag es sich nun um einen Sohn oder eine Tochter handeln -, so soll sie ein einjähriges Lamm zum Brandopfer und eine junge Taube oder eine Turteltaube zum Sündopfer an die Thüre des Offenbarungszeltes zum Priester bringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, 'Der soll sie vor Jahwe darbringen und ihr Sühne verschaffen, so wird sie rein werden von ihrem Blutflusse. Das sind die Bestimmungen in betreff der Kindbetterinnen, mag es sich nun um einen Knaben oder um ein Mädchen handeln.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'Wenn sie aber zur Beschaffung eines Schafes zu arm ist, so nehme sie zwei Turteltauben oder zwei junge Tauben, eine zum Brandopfer und eine zum Sündopfer, und der Priester schaffe ihr Sühne, so wird sie rein werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, 'Und Jahwe redete mit Mose und Aaron also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, 'Wenn sich auf der Haut jemandes ein Grind oder Ausschlag oder heller Fleck zeigt, und sich so eine aussätzige Stelle bildet, so ist er zu Aaron, dem Priester, oder zu einem seiner Söhne, der Priester, zu bringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'Wenn nun der Priester die betroffene Stelle auf der Haut besieht und findet, daß die Haare an der betroffenen Stelle weiß geworden sind, und daß die betroffene Stelle tiefer liegend erscheint, als die Haut, so ist es wirklicher Aussatz; sobald das der Priester sieht, muß er ihn für unrein erklären.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'Findet sich aber ein weißer Fleck an seiner Haut, der nicht tiefer liegend erscheint, als die Haut, und auf dem die Haare nicht weiß geworden sind, so soll der Priester den damit behafteten sieben Tage absperren.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, 'Wenn ihn dann der Priester am siebenten Tage besieht und findet, daß sich die betroffene Stelle in ihrem Aussehen gleich geblieben ist, indem das Übel nicht weiter auf der Haut um sich gegriffen hat, so soll ihn der Priester abermals sieben Tage absperren.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, 'Wenn ihn dann der Priester am siebenten Tag abermals besieht und findet, daß die betroffene Stelle blässer geworden ist, und das Übel auf der Haut nicht weiter um sich gegriffen hat, so soll ihn der Priester für rein erklären - es ist ein Ausschlag; er aber soll seine Kleider waschen, so wird er rein sein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, 'Wenn aber der Ausschlag nach der Zeit, wo er sich dem Priester gezeigt hat, um rein zu werden, immer weiter auf der Haut um sich greift, und er sich dem Priester abermals zeigt,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, 'und der Priester wahrnimmt, daß der Ausschlag auf der Haut um sich gegriffen hat, so soll ihn der Priester für unrein erklären: es ist Aussatz.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, 'Wenn sich eine aussätzige Stelle an einem Menschen zeigt, so soll man ihn zum Priester bringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, 'Und wenn der Priester wahrnimmt, daß sich ein weißer Grind auf der Haut befindet, an welchem die Haare weiß geworden sind, und daß wildes Fleisch in dem Grinde wuchert,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, 'so erweist sich das Übel an seiner Haut als ein veralteter Aussatz, und der Priester erkläre ihn für unrein, ohne ihn erst abzusperren, denn er ist unrein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, 'Wenn aber der Aussatz durchweg auf der Haut ausbricht, so daß der Aussatz die ganze Haut des betroffenen vom Kopfe bis zu den Füßen bedeckt, wohin auch nur der Priester blicken mag,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, 'und der Priester wahrnimmt, daß der Aussatz den ganzen Leib bedeckt, so erkläre er den betroffenen für rein: er ist ganz und gar rein geworden und ist somit rein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, 'Sobald sich aber wildes Fleisch an ihm zeigt, wird er unrein,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, 'und wenn der Priester das wilde Fleisch erblickt, so erkläre er ihn für unrein; denn das wilde Fleisch ist unrein: es ist Aussatz.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, 'Wenn jedoch das wilde Fleisch wieder verschwindet, und er wird weiß, so soll er sich zum Priester begeben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, 'Wenn ihn dann der Priester besieht und findet, daß die betroffene Stelle weiß geworden ist, so erkläre der Priester den betroffenen für rein; denn er ist rein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, 'Wenn sich an der Haut jemandes ein Geschwür bildet und wieder heilt,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'dann aber an der Stelle des Geschwürs ein weißer Grind entsteht oder ein weiß-rötlicher Fleck, so zeige er sich dem Priester.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, 'Wenn dann der Priester wahrnimmt, daß er niedriger aussieht, als die Haut, und daß die Haare daran weiß geworden sind, so erkläre ihn der Priester für unrein; es ist wirklicher Aussatz, der in dem Geschwür ausgebrochen ist.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, 'Wenn aber der Priester bei der Besichtigung des Flecks findet, daß sich keine weißen Haare an ihm befinden, daß er nicht niedriger ist, als die Haut, und daß er blässer geworden ist, so soll ihn der Priester sieben Tage lang absperren.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, 'Wenn dann der Fleck immer weiter auf der Haut um sich greift, so erkläre ihn der Priester für unrein; die Stelle ist vom Aussatze betroffen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, 'Blieb aber der helle Fleck auf dieselbe Stelle beschränkt, ohne weiter um sich zu greifen, so ist es die Narbe des Geschwürs, und der Priester erkläre ihn für rein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, 'Oder wenn sich an der Haut jemandes eine Brandwunde befindet, und das in der Brandwunde wachsende Fleisch sich als ein weiß-rötlicher oder weißer Fleck erzeigt,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, 'und der Priester bei dessen Besichtigung findet, daß die Haare an dem hellen Flecke weiß geworden sind, und daß er tiefer liegend erscheint, als die Haut, so ist es der Aussatz, der in der Brandwunde ausgebrochen ist, und der Priester erkläre ihn für unrein; es ist wirklicher Aussatz.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, 'Wenn aber der Priester bei seiner Besichtigung findet, daß sich an dem hellen Flecke keine weißen Haare befinden, daß er nicht niedriger ist, als die Haut, und daß er blässer geworden ist, so sperre ihn der Priester sieben Tage lang ab.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, 'Wenn ihn dann der Priester am siebenten Tage besieht, so muß ihn der Priester, wenn der Fleck immer weiter auf der Haut um sich greift, für unrein erklären - es ist wirklicher Aussatz.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'Blieb aber der helle Fleck auf dieselbe Stelle beschränkt, ohne weiter auf der Haut um sich zu greifen, und ist er blässer geworden, so ist es der Grind der Brandwunde, und der Priester mag ihn für rein erklären, denn es ist nur die Narbe der Brandwunde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, 'Wenn bei einem Mann oder Weib am Kopf oder am Bart ein Mal entsteht,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, 'und der Priester das Mal besieht und findet, daß es tiefer liegend erscheint, als die Haut, und daß sich dünne, goldgelbe Haare daran befinden, so erkläre ihn der Priester für unrein; es ist der bösartige Grind - der Aussatz des Kopfes oder des Bartes.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, 'Wenn aber der Priester bei der Besichtigung der von dem bösen Grind betroffenen Stelle findet, daß sie zwar nicht tiefer liegend erscheint, als die Haut, daß sich aber keine schwarzen Haare an ihr befinden, so soll der Priester den vom bösen Grinde betroffenen sieben Tage lang absperren.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, 'Wenn nun der Priester die betroffene Stelle am siebenten Tage besieht und findet, daß der böse Grind nicht weiter um sich gegriffen hat, daß keine goldgelben Haare an ihm entstanden sind, und daß der böse Grind nicht tiefer liegend erscheint, als die Haut,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'so soll er sich bescheren - nur den bösen Grind soll er nicht bescheren -; dann soll der Priester den mit dem bösen Grinde behafteten abermals sieben Tage absperren.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, 'Wenn nun der Priester den bösen Grind am siebenten Tage besieht und findet, daß der böse Grind nicht weiter auf der Haut um sich gegriffen hat und daß er nicht tiefer liegend erscheint, als die Haut, so soll ihn der Priester für rein erklären; und er wasche seine Kleider, so wird er rein sein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, 'Wenn jedoch der böse Grind, nachdem der betreffende für rein erklärt war, immer weiter auf der Haut um sich greift,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, 'und der Priester besieht ihn und findet, daß der böse Grind weiter auf der Haut um sich gegriffen hat, so braucht der Priester nicht erst nach dem goldgelben Haar zu suchen - er ist unrein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, 'Wenn sich aber der böse Grind in seinem Aussehen gleich geblieben ist, und schwarze Haare auf ihm gewachsen sind, so ist der böse Grind geheilt: er ist rein, und der Priester soll ihn für rein erklären.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, 'Wenn sich bei einem Mann oder Weib auf der Haut helle Flecken, weiße helle Flecken zeigen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, 'und der Priester findet bei der Besichtigung auf ihrer Haut verblaßte helle weiße Flecken, so ist es der gutartige Ausschlag, der auf der Haut ausgebrochen ist: ein solcher ist rein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, 'Wenn jemandes Haupt kahl wird, so ist er ein Hinter-Glatzkopf: ein solcher ist rein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, 'Und wenn sein Haupt auf der Vorderseite kahl wird, so ist er ein Vorder-Glatzkopf: ein solcher ist rein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, 'Wenn sich aber an der Hinterglatze oder an der Vorderglatze ein weiß-rötlicher Ausschlag zeigt, so ist es Aussatz, der an seiner Hinter- oder Vorderglatze ausbricht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, 'Wenn ihn nun der Priester besieht und findet einen weiß-rötlichen Grind auf seiner Hinter- oder Vorderglatze, der aussieht, wie Aussatz auf der bloßen Haut -');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, 'ein solcher ist aussätzig. Er ist unrein; der Priester soll ihn ohne weiteres für unrein erklären: er hat das Übel auf seinem Haupte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, 'Es soll aber der Aussätzige, der das Übel an sich hat, in zerrissenen Kleidern einhergehen, sein Haupthaar fliegen lassen, den Bart verhüllen und “unrein! unrein!” rufen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'Die ganze Zeit, in der er das Übel an sich hat, bleibt er unrein. Unrein ist er; abgesondert muß er wohnen: außerhalb des Lagers soll er sich aufhalten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, 'Wenn sich aber an einem Kleid eine aussätzige Stelle zeigt - sei es nun an einem wollenen oder linnenen Kleid -,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, 'oder an einem linnenen oder wollenen Gewebe oder Gewirke oder an Leder oder an irgend etwas aus Leder Gefertigtem,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, 'und es ist die betroffene Stelle an dem Kleid oder dem Leder oder dem Gewebe oder dem Gewirke oder an irgend welchem ledernen Gegenstande grünlich oder rötlich, so liegt ein Fall von Aussatz vor, und man zeige es dem Priester.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, 'Und wenn der Priester die betroffene Stelle besichtigt hat, so schließe er das vom Ausschlage betroffene sieben Tage ein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, 'Wenn er dann am siebenten Tage wahrnimmt, daß der Ausschlag auf dem Kleid oder dem Gewebe oder dem Gewirke oder dem Leder - an irgend etwas, wozu das Leder verarbeitet zu werden pflegt, - weiter um sich gegriffen hat, so ist der Ausschlag ein bösartiger Aussatz. Derartiges ist unrein,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, 'und man soll das Kleid oder das in Wolle oder Linnen Gewebte oder Gewirkte oder jederlei ledernen Gegenstand, an dem sich der Ausschlag zeigt, verbrennen; denn es ist ein bösartiger Aussatz, verbrannt muß es werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, 'Wenn es aber der Priester besieht und findet, daß der Ausschlag auf dem Kleid oder dem Gewebe ober dem Gewirke über irgend welchem ledernen Gegenstande nicht um sich gegriffen hat,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, 'so gebiete der Priester, daß man das, woran sich der Ausschlag findet, wasche, und schließe es dann abermals sieben Tage ein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, 'Wenn es dann der Priester, nachdem die betroffene Stelle ausgewaschen worden war, besichtigt und findet, daß sich das Aussehen der betroffenen Stelle nicht verändert hat, wenn auch der Ausschlag nicht weiter um sich gegriffen hat, so ist es unrein; man muß es verbrennen - es ist eine Einfressung, sei es nun an seiner Hinter- oder an seiner Vorderseite.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, 'Wenn aber der Priester bei der Besichtigung findet, daß die betroffene Stelle, nachdem man sie ausgewaschen hat, verblaßt ist, so soll man sie aus dem Kleid oder Leder oder Gewebe oder Gewirke herausreißen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, 'Und wenn sich an dem Kleid oder Gewebe oder Gewirke oder an irgend welchem ledernen Gegenstand abermals Aussatz zeigt, so ist es ein frisch ausbrechender; man muß das, was mit dem Ausschlage behaftet ist, verbrennen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'Die Kleider aber oder Gewebe oder Gewirke oder ledernen Gegenstände jeder Art, von denen der Ausschlag, nachdem man sie gewaschen hat, verschwunden ist, müssen nochmals gewaschen werden, so werden sie rein sein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, 'Das sind die Bestimmungen über den Aussatz an einem wollenen oder linnenen Kleid oder Gewebe oder Gewirke oder an irgend einem ledernen Gegenstande, wiefern sie für rein oder unrein zu erklären sind.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, 'Und Jahwe redete mit Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, 'Dies sind die Bestimmungen in betreff des Aussätzigen zur Zeit seiner Reinigung: Er soll zum Priester gebracht werden;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, 'und zwar muß der Priester zu ihm hinaus vor das Lager gehen. Wenn nun der Priester bei der Besichtigung findet, daß die vom Aussatze betroffene Stelle am Aussätzigen heil geworden ist,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, 'so soll der Priester Befehl geben, daß man für den, der sich reinigen läßt, zwei lebendige reine Vögel, Cedernholz, Karmesin und Ysop bringe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, 'Sodann soll der Priester Befehl geben, daß man den einen Vogel schlachte, in ein irdenes Gefäß über lebendigem Wasser.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, 'Den lebendigen Vogel aber, das Cedernholz, den Karmesin und Ysop soll er nehmen und es samt dem lebendigen Vogel in das Blut des über dem lebendigen Wasser geschlachteten Vogels eintauchen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, 'Sodann soll er den, der sich vom Aussatze reinigen läßt, siebenmaI besprengen und ihn so reinigen; den lebendigen Vogel aber lasse er ins freie Feld fliegen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, 'Und der, welcher sich reinigen läßt, muß seine Kleider waschen, alle seine Haare abscheren und sich baden, so wird er rein werden. Darnach darf er hineingehen ins Lager, muß aber noch sieben Tage außerhalb seines Zeltes bleiben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, 'Am siebenten Tag aber soll er alle seine Haare abscheren - Haupt, Bart und Augenbrauen, kurz alle seine Haare soll er abscheren; sodann soll er seine Kleider waschen und seinen Leib baden, so wird er rein werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, 'Am achten Tag aber soll er zwei fehllose Lämmer nehmen und ein einjähriges, fehlloses weibliches Lamm, nebst drei Zehntel Feinmehl, das mit Öl angemacht ist, zum Speisopfer und einem Log Öl.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, 'Und der Priester, der die Reinigung vollzieht, soll den Mann, der sich reinigen läßt, und diese Dinge Jahwe darstellen an der Thüre des Offenbarungszeltes.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, 'Sodann soll der Priester das eine Lamm nehmen und es zum Schuldopfer darbringen mit dem Log Öl und soll beides als Webe vor Jahwe weben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'Und zwar soll man das Lamm da schlachten, wo man die Sündopfer und die Brandopfer zu schlachten pflegt, an heiliger Stätte; denn wie das Sündopfer, so gehört auch das Schuldopfer dem Priester: hochheilig ist es.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, 'Sodann nehme der Priester etwas von dem Blute des Schuldopfers und der Priester streiche es dem, der sich reinigen läßt, an den rechten Ohrknorpel, den Daumen der rechten Hand und die große Zehe des rechten Fußes.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, 'Alsdann nehme der Priester etwas von dem Log Öl und gieße es auf seine - des Priesters - linke Hand.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, 'Sodann tauche der Priester seinen rechten Finger in das Öl, das in seiner linken Hand ist, und sprenge von dem Öl mit seinem Finger siebenmal vor Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'Von dem übrigen Öl aber, das in seiner Hand ist, streiche der Priester dem, der sich reinigen läßt, etwas an den rechten Ohrknorpel, an den Daumen der rechten Hand und die große Zehe des rechten Fußes, oben auf das Blut des Schuldopfers.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, 'Und was noch übrig ist von dem Öl in der Hand des Priesters, das thue er auf das Haupt dessen, der sich reinigen läßt, damit ihm so der Priester Sühne schaffe vor Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, 'Sodann soll der Priester das Sündopfer herrichten, um dem, der sich reinigen läßt, Sühne zu schaffen wegen seiner Unreinigkeit; darnach soll er das Brandopfer schlachten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, 'Und der Priester soll das Brandopfer samt dem Speisopfer auf dem Altar darbringen; und wenn ihm so der Priester Sühne geschafft hat, wird er rein werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, 'Wenn er aber arm ist und nicht so viel zu leisten vermag, so nehme er ein Lamm als Schuldopfer, damit es gewebt und ihm Sühne geschafft werde, dazu ein Zehntel Feinmehl, mit Öl angemacht, zum Speisopfer und ein Log Öl,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, 'ferner zwei Turteltauben oder zwei junge Tauben - was er zu leisten vermag -, damit die eine als Sündopfer, die andere als Brandopfer diene.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, 'Und zwar soll er sie am achten Tage, nachdem er rein geworden, zum Priester bringen, an die Thüre des Offenbarungszeltes vor Jahwe;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'und der Priester nehme das Schuldopferlamm nebst dem Log Öl und der Priester webe beides als Webe vor Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, 'Sodann schlachte man das Schuldopferlamm, und der Priester nehme etwas von dem Blute des Schuldopfers und streiche es dem, der sich reinigen läßt, an den rechten Ohrknorpel, den Daumen der rechten Hand und die große Zehe des rechten Fußes.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'Von dem Öl aber gieße der Priester etwas in seine - des Priesters - linke Hand');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, 'und es sprenge der Priester von dem Öl, das in seiner linken Hand ist, mit seinem rechten Finger siebenmal vor Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, 'Sodann streiche der Priester etwas von dem Öl, das in seiner Hand ist, dem, der sich reinigen läßt, an den rechten Ohrknorpel, den Daumen der rechten Hand und die große Zehe des rechten Fußes, auf die mit dem Blute des Schuldopfers bestrichene Stelle.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'Und was noch übrig ist von dem Öl in der Hand des Priesters, das thue er auf das Haupt dessen, der sich reinigen läßt, damit er ihm Sühne schaffe vor Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'Sodann soll er die eine von den Turteltauben oder von den jungen Tauben, die er zu leisten vermochte, herrichten,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, '- die eine als Sündopfer, die andere als Brandopfer, samt dem Speisopfer, und so soll der Priester dem, der sich reinigen läßt, Sühne schaffen vor Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, 'Das sind die Bestimmungen in betreff dessen, der mit Aussatz behaftet ist, bei seiner Reinigung aber nicht so viel zu leisten vermag.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, 'Und Jahwe redete mit Mose und Aaron also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, 'Wenn ihr ins Land Kanaan kommt, das ich euch zu eigen geben will, und ich lasse in dem Lande, das ihr zu eigen habt, an irgend einem Hause eine aussätzige Stelle entstehen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'so soll der, dem das Haus gehört, hingehen und es dem Priester melden und sprechen: An meinem Hause zeigt sich etwas wie Aussatz!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, 'So soll dann der Priester Befehl geben, das Haus auszuräumen, bevor der Priester hineingeht, um die betreffende Stelle zu besichtigen, damit nicht etwa alles, was sich im Hause befindet, für unrein erklärt werden muß. Alsdann soll der Priester hineingehen, um das Haus zu besehen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'Wenn er nun bei der Besichtigung der aussätzigen Stellen wahrnimmt, daß sich dieselben an den Wänden des Hauses befinden in Gestalt grünlicher oder rötlicher Grübchen, die tiefer zu liegen scheinen, als die Wandfläche,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, 'so soll der Priester aus dem Hause heraus an die Thüre des Hauses gehen und das Haus auf sieben Tage verschließen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, 'Wenn dann der Priester am siebenten Tage wiederkehrt und bei der Besichtigung findet, daß der Aussatz an den Wänden des Hauses weiter um sich gegriffen hat,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, 'so soll der Priester Befehl geben, daß man die Steine, an denen sich der Aussatz zeigt, herausreißt und draußen vor der Stadt an einen unreinen Ort wirft.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'Das Haus selbst aber soll man inwendig ringsum abkratzen und den abgekratzten Lehm draußen vor der Stadt an einen unreinen Ort schütten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, 'Sodann soll man andere Steine nehmen und an Stelle jener Steine einsetzen; ebenso soll man anderen Lehm nehmen und das Haus bewerfen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, 'Wenn dann der Aussatz abermals am Hause hervorbricht, nachdem man die Steine herausgerissen, das Haus abgekratzt und neu beworfen hat,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, 'so soll der Priester hineingehen, und wenn er bei der Besichtigung findet, daß der Aussatz weiter um sich gegriffen hat am Hause, so ist es ein bösartiger Aussatz an dem Hause: dasselbe ist unrein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, 'Und man soll das Haus abbrechen, die zu ihm gehörenden Steine, Balken und den gesamten Lehmbewurf am Hause, und soll es hinausschaffen an einen unreinen Ort draußen vor der Stadt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'Und wer das Haus betritt, so lange es verschlossen ist, der soll für unrein gelten bis zum Abend.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'Und wer in dem Hause geschlafen hat, der muß seine Kleider waschen; und wer in dem Hause gegessen hat, der muß seine Kleider waschen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, 'Wenn aber der Priester hineinkommen und bei der Besichtigung finden sollte, daß der Aussatz nicht weiter am Hause um sich gegriffen hat, nachdem das Haus neu beworfen war, so soll der Priester das Haus für rein erklären, denn der Schaden ist geheilt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, 'So soll er dann, um das Haus zu entsündigen, zwei Vögel, Cedernholz, Karmesin und Ysop nehmen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'Den einen Vogel schlachte er in ein irdenes Gefäß über lebendigem Wasser;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, 'das Cedernholz aber, den Ysop, den Karmesin und den lebendigen Vogel soll er nehmen und in das Blut des geschlachteten Vogels und in das lebendige Wasser tauchen und das Haus siebenmal besprengen');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, 'und soll so das Haus mit dem Blute des Vogels und mit dem lebendigen Wasser, sowie mit dem lebendigen Vogel, dem Cedernholz, dem Ysop und dem Karmesin entsündigen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'Den lebendigen Vogel aber lasse er hinaus vor der Stadt ins freie Feld fliegen und schaffe so dem Hause Sühne: so wird es rein werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, 'Das sind die Bestimmungen in betreff der verschiedenen Arten des Aussatzes und in betreff des Grindes,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'sowie des Aussatzes an Kleidern und Häusern,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'der Hautmale, des Schorfs und der weißen Flecken,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, 'um darüber zu belehren, wenn etwas unrein oder rein ist. Das sind die Bestimmungen in betreff des Aussatzes.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, 'Und Jahwe redete mit Mose und Aaron also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, 'Redet mit den Israeliten und sprecht zu ihnen: wenn irgend jemand an seiner Scham einen Fluß hat, so ist solches ein unreiner Fluß.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'Und zwar verhält es sich so mit seiner Unreinigkeit infolge seines Flusses: Mag nun der Fluß aus seiner Scham im Gange sein oder seine Scham verstopft sein, so daß nichts ausfließt - es liegt Unreinigkeit bei ihm vor.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, 'Alles Lager, auf dem der Flüssige liegt, wird unrein, und alles Geräte, auf dem er sitzt, wird unrein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'Wer sein Lager berührt, muß seine Kleider waschen und sich baden und bleibt unrein bis zum Abend.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, 'Und wer sich auf das Geräte setzt, auf dem der Flüssige saß, muß seine Kleider waschen und sich baden und bleibt unrein bis zum Abend.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, 'Und wer den Leib des Flüssigen berührt, muß seine Kleider waschen und sich baden und bleibt unrein bis zum Abend.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'Und wenn der Flüssige seinen Speichel auf einen Reinen wirft, so muß dieser seine Kleider waschen und sich baden und bleibt unrein bis zum Abend.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, 'Und jeder Sattel, auf dem der Flüssige reitet, wird unrein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'Und wer irgend etwas von dem berührt, was sich unter ihm befindet, der wird unrein bis zum Abend. Und wer es fortträgt, muß seine Kleider waschen und sich baden und bleibt unrein bis zum Abend.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, 'Und jeder, den der Flüssige berührt, ohne zuvor seine Hände mit Wasser abgespült zu haben, der muß seine Kleider waschen und sich baden und bleibt unrein bis zum Abend.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, 'Irdene Gefäße, die der Flüssige berührt, müssen zerbrochen, alle hölzernen Gefäße aber mit Wasser abgespült werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, 'Wenn aber der Flüssige rein wird von seinem Flusse, so soll er von da ab, wo er rein wurde, sieben Tage zählen; alsdann soll er seine Kleider waschen und seinen Leib in lebendigem Wasser baden - so wird er rein werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, 'Am achten Tag aber nehme er zwei Turteltauben oder zwei junge Tauben, gehe hin vor Jahwe an die Thüre des Offenbarungszeltes und übergebe sie dem Priester.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, 'Der Priester aber soll sie herrichten, die eine als Sündopfer und die andere als Brandopfer; und so soll ihm der Priester Sühne schaffen vor Jahwe wegen seines Flusses.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, 'Wenn jemandem der Same entgeht, so muß er seinen Leib baden und bleibt unrein bis zum Abend.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, 'Und alles Kleid und alles Leder, an das solcher Same kommt, muß gewaschen werden und bleibt unrein bis zum Abend.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, 'Und wenn einer bei einem Weibe liegt und Samenerguß erfolgt, so müssen sie sich baden und bleiben unrein bis zum Abend.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, 'Wenn ein Weib flüssig wird, indem sie ihres Leibes Blutfluß hat, so haftet an ihr die Unreinigkeit sieben Tage lang, und jeder, der Sie berührt, wird unrein bis zum Abend.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'Und alles, worauf sie liegt während ihrer Unreinigkeit, wird unrein; und alles, worauf sie sitzt, wird unrein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'Und jeder, der ihr Lager berührt, muß seine Kleider waschen und sich baden und bleibt unrein bis zum Abend.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, 'Und jeder, der irgend ein Geräte berührt, auf dem Sie saß, muß seine Kleider waschen und sich baden und bleibt unrein bis zum Abend.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, 'Und wenn er etwas berührt, was sich auf dem Lager oder auf dem Geräte befindet, auf dem sie sitzt, so wird er unrein bis, zum Abend.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, 'Und wenn einer bei ihr liegen sollte und von ihrer Unreinigkeit an ihn kommt, so bleibt er sieben Tage lang unrein, und alles Lager, auf dem er liegt, wird unrein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, 'Wenn aber ein Weib lange Zeit hindurch den Blutfluß hat, außer der Zeit ihrer gewöhnlichen Unreinigkeit, oder wenn Sie blutflüssig bleibt über die Zeit ihrer gewöhnlichen Unreinigkeit hinaus, so gilt von ihr die ganze Zeit hindurch, die sie an dem unreinen Flusse leidet, dasselbe, wie zur Zeit ihrer gewöhnlichen Unreinigkeit: Sie ist unrein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, 'Alles Lager, auf dem sie liegt, so lange Sie an dem Flusse leidet, hat ihr zu gelten, wie das Lager zur Zeit ihrer gewöhnlichen Unreinigkeit, und alles Geräte, auf dem sie sitzt, wird unrein, wie es unrein wird bei ihrer gewöhnlichen Unreinigkeit.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, 'Wer diese Dinge berührt, wird unrein; er muß seine Kleider waschen und sich baden und bleibt unrein bis zum Abend.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, 'Wenn sie aber rein geworden ist von ihrem Fluß, so soll sie noch sieben Tage zählen: darnach soll sie als rein gelten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, 'Und am achten Tage soll sie zwei Turteltauben oder zwei junge Tauben nehmen und dieselben zum Priester bringen an die Thüre des Offenbarungszeltes.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, 'Und der Priester soll die eine als Sündopfer, die andere als Brandopfer herrichten, und so soll ihr der Priester vor Jahwe Sühne schaffen wegen ihres unreinen Flusses.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, 'So sollst du die Israeliten verwarnen in betreff ihrer Unreinigkeit, damit Sie nicht sterben infolge ihrer Unreinigkeit, indem Sie meine Wohnung verunreinigen, die unter ihnen ist.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, 'Das sind die Bestimmungen in betreff des Flüssigen und dessen, dem der Same entgeht, so daß er dadurch unrein wird;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'und in betreff derjenigen, die an ihrer gewöhnlichen Unreinigkeit leidet, und dessen, der einen Fluß hat, es sei ein Mann oder ein Weib, sowie dessen, der bei einer Unreinen liegt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, 'Und Jahwe redete mit Mose nach dem Tode der beiden Söhne Aarons, als sie vor Jahwe getreten waren und sterben mußten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, 'Und Jahwe sprach zu Mose: Sage deinem Bruder Aaron, daß er nicht zu jeder beliebigen Zeit hineingehen darf in das Heiligtum innerhalb des Vorhangs, vor die Deckplatte hin, die sich über der Lade befindet - sonst muß er sterben! Denn in der Wolke erscheine ich über der Deckplatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'Nur unter der Bedingung darf Aaron in das Heiligtum hineingehen, daß er einen jungen Stier als Sündopfer und einen Widder als Brandopfer darbringt;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, 'einen heiligen linnenen Leibrock muß er anhaben, linnene Beinkleider müssen seine Scham bedecken, mit einem linnenen Gürtel muß er sich gürten und einen linnenen Kopfbund umbinden. Heilige Kleider sind es - er soll sie anlegen, nachdem er seinen Leib gebadet hat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'Von der Gemeinde der Israeliten aber soll er zwei Ziegenböcke zum Sündopfer und einen Widder zum Brandopfer nehmen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, 'Sodann soll Aaron seinen eigenen Sündopfer-Farren herzubringen und sich und seinem Hause Sühne schaffen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, 'Dann soll er die beiden Böcke nehmen und Sie Jahwe darstellen an der Thüre des OffenbarungszeItes.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'Und Aaron soll über die beiden Böcke das Los werfen: ein Los für Jahwe und ein Los für Asasel.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, 'Sodann soll Aaron den Bock, der durch das Los für Jahwe bestimmt worden ist, herzubringen und ihn als Sündopfer herrichten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, 'Der Bock aber, der durch das Los für Asasel bestimmt ward, ist Jahwe lebendig darzustellen, damit man die Sühnegebräuche über ihm vollziehe und ihn dem Asasel in die Wüste schicke.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, 'So soll also Aaron seinen eigenen Sündopfer-Farren herzubringen und sich und seinem Hause Sühne schaffen und soll seinen Sündopfer-Farren schlachten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, 'Sodann aber soll er eine Pfanne voll glühender Kohlen von dem Altar, der vor Jahwe steht, hinwegnehmen und feingestoßenes wohlriechendes Räucherwerk, so viel er mit seinen beiden Händen zu fassen vermag, und soll es hinein hinter den Vorhang bringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'Sodann soll er das Räucherwerk vor Jahwe auf das Feuer thun, damit die Wolke von dem Räucherwerk die Deckplatte, die sich über dem Gesetze befindet, verhülle, und er nicht sterben müsse.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, 'Sodann nehme er etwas von dem Blute des Farren und sprenge es mit seinem Finger oben auf die Vorderseite der Deckplatte; vor die Deckplatte hin aber sprenge er mit seinem Finger siebenmal von dem Blute.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, 'Sodann schlachte er den Sündopferbock des Volks und bringe sein Blut hinein hinter den Vorhang und verfahre mit seinem Blute so, wie er mit dem Blute des Farren verfuhr, und sprenge es auf die Deckplatte und vor die Deckplatte hin');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'und entsündige so das Heiligtum von wegen der Unreinigkeiten der Israeliten und der Übertretungen, die sie irgend begangen haben, und ebenso verfahre er mit dem Offenbarungszelte, das bei ihnen weilt inmitten ihrer Unreinigkeiten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, 'Es darf aber gar niemand im Offenbarungszelte zugegen sein, wenn er hineingeht, um die Sühnegebräuche im Heiligtum zu vollziehen, bis er wieder hinausgeht, und so soll er sich und seinem Hause und der ganzen Gemeinde Israel Sühne schaffen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, 'Sodann soll er hinausgehen an den Altar, der vor Jahwe steht, und ihn entsündigen; und zwar soll er etwas von dem Blute des Farren und dem Blute des Bockes nehmen und ringsum an die Hörner des Altars streichen');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'und soll mit seinem Finger siebenmal etwas von dem Blut auf ihn sprengen und ihn so reinigen und weihen von wegen der Unreinigkeit der Israeliten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, 'Wenn er so die Entsündigung des Heiligtums und des Offenbarungszeltes und des Altars vollendet hat, so bringe er den lebendigen Bock herzu.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, 'Und Aaron soll seine beiden Hände auf den Kopf des lebendigen Bockes aufstemmen und über ihm alle Verschuldungen der Israeliten bekennen und alle Übertretungen, die Sie irgend begangen haben, und soll sie auf den Kopf des Bockes legen und diesen durch einen bereitgehaltenen Mann in die Wüste entsenden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, 'So soll der Bock alle ihre Verschuldungen auf sich hinwegtragen in eine abgelegene Gegend, und man soll den Bock erst in der Wüste loslassen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, 'Und Aaron soll hineingehen ins Offenbarungszelt und die linnenen Kleider ausziehen, die er angelegt hatte, als er in das Heiligtum hineinging, und sie dort niederlegen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, 'Sodann soll er seinen Leib an heiliger Stätte baden und seine Kleider anziehen; dann soll er herauskommen und sein und des Volkes Brandopfer herrichten, um sich und dem Volke Sühne zu schaffen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'Das Fett des Sündopfers aber soll er auf dem Altar in Rauch aufgehen lassen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'Und der, welcher den Bock zu Asasel hinausgeschafft hat, muß seine Kleider waschen und seinen Leib baden; darnach darf er ins Lager kommen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, 'Den Sündopfer-Farren aber und den Sündopferbock, deren Blut hineingebracht wurde, um im Heiligtume die Sühnegebräuche zu vollziehen, soll man hinaus vor das Lager schaffen und ihr Fleisch und ihren Mist verbrennen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, 'Und der, welcher sie verbrannt hat, muß seine Kleider waschen und seinen Leib baden; darnach darf er ins Lager kommen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, 'Und es soll euch als eine Satzung für alle Zeiten gelten: Im siebenten Monat, am zehnten des Monats, müßt ihr euch kasteien und dürft ihr gar kein Geschäft verrichten, der Landeseingeborne, wie der Fremde, der sich unter euch aufhält.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, 'Denn an diesem Tage wird man euch Sühne schaffen, um euch zu reinigen; von allen euren Sünden sollt ihr rein werden vor Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, 'Ein Tag unbedingter Ruhe soll es für euch sein, und ihr sollt euch kasteien kraft einer für alle Zeiten geltenden Satzung.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, 'Es soll aber die Entsündigung vollziehen der Priester, den man salben und dem man die Hand füllen wird, daß er Priesterdienst thue an Stelle seines Vaters. Und er soll die linnenen Kleider, die heiligen Kleider, anlegen');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, 'und das Allerheiligste entsündigen; und das Offenbarungszelt und den Altar soll er entsündigen und den Priestern und allen Gliedern der Gemeinde soll er Sühne schaffen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, 'Und das soll euch als eine Satzung für alle Zeiten gelten, daß man den Israeliten einmal im Jahre Sühne schaffen soll von wegen aller ihrer Sünden. Und er that, wie Jahwe Mose befohlen hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, 'Und Jahwe redete mit Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, 'Rede mit Aaron und mit seinen Söhnen und allen Israeliten und sprich zu ihnen: Dies ist\'s, was Jahwe geboten hat:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, 'Jedermann aus dem Hause Israel, der ein Rind oder ein Lamm oder eine Ziege schlachtet im Lager oder der sie schlachtet außerhalb des Lagers');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, 'und sie nicht hinbringt zur Thüre des Offenbarungszeltes, um sie Jahwe als Opfergabe darzubringen vor der Wohnung Jahwes, einem solchen soll es als Blutschuld angerechnet werden: Blut hat er vergossen, und ein solcher soll hinweggetilgt werden mitten aus seinen Volksgenossen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, 'damit die Israeliten ihre SchIachtopfer, die sie auf freiem Felde zu opfern pflegen, herbringen, und zwar sollen sie sie für Jahwe an die Thüre des Offenbarungszeltes zum Priester bringen und sollen sie als Heilsopfer für Jahwe schlachten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, 'Und der Priester soll das Blut an den Altar Jahwes sprengen vor der Thüre des Offenbarungszeltes und soll das Fett in Rauch aufgehen lassen zum lieblichen Geruch für Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, 'Und sie sollen ihre Schlachtopfer hinfort nicht mehr den Bocksgestalten opfern, mit denen sie Abgötterei treiben. Solches soll ihnen als eine Satzung für alle Zeiten gelten, die zu beobachten ist von Geschlecht zu Geschlecht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, 'Und du sollst zu ihnen sprechen: Jedermann vom Hause Israel und von den Fremden, die sich unter ihnen aufhalten, der ein Brandopfer oder SchIachtopfer bringt');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, 'und es nicht hinbringt an die Thüre des Offenbarungszeltes, um es für Jahwe herzurichten, ein solcher soll hinweggetilgt werden aus seinen Volksgenossen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, 'Und jedermann vom Hause Israel und von den Fremden, die sich unter ihnen aufhalten, der irgend Blut genießt, - gegen einen solchen, der Blut genießt, will ich mein Antlitz richten und ihn hinwegtilgen mitten aus seinen Volksgenossen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, 'Denn das Leben des Leibes ist im Blute, und ich habe es euch verliehen für den Altar, daß man euch Sühne damit schaffe; denn das Blut bewirkt Sühne mittels des in ihm enthaltenen Lebens.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, 'Darum habe ich den Israeliten geboten: Niemand von euch darf Blut genießen! Auch der Fremde, der sich unter euch aufhält, darf kein Blut genießen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, 'Und jedermann von den Israeliten und von den Fremden, die sich unter ihnen aufhalten, der ein Stück Wild oder Geflügel erjagt; das gegessen werden darf, der soll sein Blut auslaufen lassen und dann mit Erde bedecken.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, 'Denn das Leben eines jeden Leibes besteht in seinem das Leben enthaltenden Blute. Daher gebot ich den Israeliten: Von keinem Leibe dürft ihr das Blut genießen: Denn das Leben eines jeden Leibes besteht in seinem Blute - jeder, der es genießt, soll hinweggetilgt werden!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, 'Und jeder, der Aas oder von wilden Tieren Zerrissenes genießt, es sei ein Landeseingeborner oder ein Fremder, der muß seine Kleider waschen und sich baden und bleibt unrein bis zum Abend; dann wird er rein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'Wenn er sie aber nicht wäscht und seinen Leib nicht badet, so lädt er Verschuldung auf sich.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'Und Jahwe redete mit Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, 'Rede mit den Israeliten und sprich zu ihnen: Ich bin Jahwe, euer Gott.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'Ihr dürft nicht thun, wie man im Lande Ägypten thut, in welchem ihr gewohnt habt, und ihr dürft nicht thun, wie man im Lande Kanaan thut, wohin ich euch bringen will; nach ihren Satzungen dürft ihr nicht wandeln.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, 'Nach meinen Rechten sollt ihr thun und meine Satzungen sollt ihr beobachten und nach ihnen wandeln; ich bin Jahwe, euer Gott.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'Darum sollt ihr meine Satzungen und meine Rechte beobachten: derjenige, der nach ihnen thut, wird durch sie leben; ich bin Jahwe!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, 'Keiner von euch darf seinen nächsten Blutsverwandten nahen, ihre Scham zu entblößen; ich bin Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, 'Die Scham deines Vaters und die Scham deiner Mutter darfst du nicht entblößen; es ist deine Mutter, du darfst ihre Scham nicht entblößen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, 'Die Scham des Weibes deines Vaters darfst du nicht entblößen, es ist deines Vaters Scham.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, 'Die Scham deiner Schwester, der Tochter deines Vaters oder der Tochter deiner Mutter, mag sie nun im Hause oder mag sie draußen geboren sein - du darfst ihre Scham nicht entblößen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, 'Die Scham der Tochter deines Sohns oder der Tochter deiner Tochter - du darfst ihre Scham nicht entblößen, denn es ist deine Scham.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, 'Die Scham der Tochter des Weibes deines Vaters, die dein Vater erzeugt hat - du darfst ihre Scham nicht entblößen; sie ist deine Schwester.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, 'Die Scham der Schwester deines Vaters darfst du nicht entblößen, sie ist deines Vaters nächste Blutsverwandte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'Die Scham der Schwester deiner Mutter darfst du nicht entblößen, denn sie ist deiner Mutter nächste Blutsverwandte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, 'Die Scham des Bruders deines Vaters darfst du nicht entblößen, darfst seinem Weibe nicht nahen; sie ist deine Muhme.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, 'Die Scham deiner Schwiegertochter darfst du nicht entblößen; sie ist das Weib deines Sohns, du darfst ihre Scham nicht entblößen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, 'Die Scham des Weibes deines Bruders darfst du nicht entblößen, es ist deines Bruders Scham.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, 'Die Scham eines Weibes und ihrer Tochter darfst du nicht entblößen. Die Tochter ihres Sohns und die Tochter ihrer Tochter darfst du nicht nehmen, ihre Scham zu entblößen; sie sind nächste Blutsverwandte - solches ist grobe Unzucht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, 'Auch darfst du nicht ein Weib zu ihrer Schwester hinzunehmen und so Feindschaft erregen, indem du ihre Scham entblößest neben ihr, bei ihren Lebzeiten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, 'Du darfst einem Weibe nicht nahen, ihre Scham zu entblößen, während der Zeit ihrer Unreinigkeit.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, 'Mit dem Weibe deines Nächsten darfst du dich nicht fleischlich vermischen und dich dadurch verunreinigen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, 'Du darfst nicht eines von deinen Kindern hergeben, um es dem Melech zu weihen, daß du nicht entheiligest den Namen deines Gottes; ich bin Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, 'Du darfst nicht bei einem Manne liegen, wie man beim Weibe liegt; solches ist eine Greueltat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, 'Mit keinem Tiere darfst du dich fleischlich vermischen und dich dadurch verunreinigen, und ein Weib soll sich nicht vor ein Tier hinstellen, daß es sich mit ihr begatte; solches ist eine schwere Schandthat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, 'Ihr dürft euch nicht durch irgend etwas derartiges verunreinigen; denn durch alles das haben sich die Heiden verunreinigt, die ich vor euch vertreibe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'Da wurde das Land unrein, und ich suchte seine Verschuldung an ihm heim, so daß das Land seine Bewohner ausspie.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'So beobachtet denn ihr meine Satzungen und meine Rechte und verübt nicht irgend eine dieser Greuelthaten, weder der Landeseingeborne, noch der Fremde, der sich unter euch aufhält.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, 'Denn alle diese Greuelthaten haben die Bewohner des Landes verübt, die vor euch waren, und das Land wurde unrein;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, 'daß nicht etwa das Land euch ausspeie, wenn ihr es verunreinigt, wie es das Volk ausgespieen hat, das vor euch war.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'Denn wer irgend eine dieser Greuelthaten verüben wird: solche, die sie verüben, sollen hinweggetilgt werden mitten aus ihren Volksgenossen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'So befolgt denn meine Anordnungen, daß ihr nicht thut nach den greulichen Sitten, die vor euch geübt wurden, und euch dadurch verunreinigt; ich bin Jahwe, euer Gott!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'Und Jahwe redete mit Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, 'Rede mit der ganzen Gemeinde der Israeliten und sprich zu ihnen: Ihr sollt heilig sein, denn ich bin heilig, Jahwe, euer Gott.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, 'Ihr sollt ein jeglicher seine Mutter und seinen Vater fürchten und meine Ruhetage sollt ihr beobachten; ich bin Jahwe, euer Gott.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'Ihr sollt euch nicht den Götzen zuwenden und dürft euch keine gegossenen Götter machen; ich bin Jahwe, euer Gott.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'Und wenn ihr Jahwe ein Heilsopfer schlachtet, sollt ihr es opfern, daß es euch wohlgefällig mache.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'An dem Tag, an welchem ihr es opfert, und Tags darauf muß es gegessen werden; was aber bis zum dritten Tag übrig geblieben ist, muß verbrannt werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'Sollte aber dennoch am dritten Tage davon gegessen werden, so würde es als Verdorbenes gelten und nicht wohlgefällig aufgenommen werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, 'Wer es genießt, lädt Verschuldung auf sich; denn er hat das Jahwe Geheiligte entweiht und ein solcher soll hinweggetilgt werden aus seinen Volksgenossen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, 'Wenn ihr euer Land aberntet, so sollst du dein Feld nicht bis auf den äußersten Rand abernten und nicht Nachlese halten nach deiner Ernte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'Auch deinen Weinberg sollst du nicht nachlesen und die umhergestreuten Beeren in deinem Weinberge nicht auflesen: den Armen und den Fremden sollst du sie überlassen; ich bin Jahwe, euer Gott.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, 'Ihr sollt nicht stehlen, nichts ableugnen und nicht einer den andern betrügen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, 'Ihr sollt bei meinem Namen nicht falsch schwören, daß du so den Namen deines Gottes entweihest; ich bin Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, 'Du sollst deinen Nächsten nicht übervorteilen und nicht berauben; der Lohn des Lohnarbeiters soll von dir nicht zurückbehalten werden bis zum andern Morgen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, 'Du sollst einem Tauben nicht fluchen und einem Blinden nicht ein Hindernis in den Weg legen, sondern sollst dich vor deinem Gotte fürchten; ich bin Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, 'Ihr sollt nicht Unrecht verüben beim Rechtsprechen - du sollst weder für einen Geringen Partei ergreifen, noch auf einen Vornehmen Rücksicht nehmen, sondern du sollst deinen Nächsten recht richten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, 'Du sollst nicht als Verleumder unter deinen Volksgenossen umgehen, noch auf dem Tode deines Nächsten bestehen; ich bin Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'Du sollst gegen deinen Bruder nicht Haß im Herzen tragen, sondern sollst deinen Nächsten freimütig zur Rede stellen, daß du nicht etwa seinetwegen Sünde auf dich ladest.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'Du sollst nicht rachgierig noch nachträgerisch sein gegenüber deinen Volksgenossen, sondern sollst deinen Nächsten lieben, wie dich selbst; ich bin Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, 'Meine Satzungen sollt ihr beobachten: du darfst nicht zweierlei Arten deines Viehs sich begatten lassen, noch dein Feld mit zweierlei Arten von Samen besäen, noch darf dir ein Kleid, das aus zweierlei Fäden zusammengewirkt ist, auf den Leib kommen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, 'Wenn sich einer mit einem Weibe fleischlich vermischt, das als Sklavin unter der Gewalt eines anderen Mannes steht, ohne daß Sie losgekauft oder freigelassen war, so soll eine Strafe verhängt werden; doch sollen sie nicht mit dem Tode bestraft werden, denn sie war nicht freigelassen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'Er soll aber Jahwe als seine Buße einen Widder zum Schuldopfer an die Thüre des Offenbarungszeltes bringen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, 'und der Priester soll ihm mit dem Schuldopfer-Widder vor Jahwe Sühne schaffen wegen der Sünde, die er begangen hat; so wird ihm dann die Sünde, die er begangen hat, vergeben werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, 'Wenn ihr in das Land kommt und allerlei Fruchtbäume pflanzt, so sollt ihr deren Vorhaut - ihre ersten Früchte - ungestört wachsen lassen. Drei Jahre sollen sie euch als unbeschnitten gelten, und darf nicht von ihnen gegessen werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, 'Im vierten Jahre sollen alle ihre Früchte Jahwe zu einer Dankfeier geweiht sein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, 'Im fünften Jahr aber dürft ihr ihre Früchte essen, daß euch um so reichIicherer Ertrag von ihnen zu teil werde; ich bin Jahwe, euer Gott.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, 'Ihr dürft nichts samt dem Blut essen. Ihr dürft nicht wahrsagen, noch Zauberei treiben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, 'Ihr dürft den Rand eures Kopfes nicht kreisförmig abscheren, noch sollst du den Rand deines Bartes verstümmeln.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, 'Ihr dürft euch nicht wegen eines Toten Einschnitte an eurem Leibe machen, noch dürft ihr euch Schriftzeichen einätzen; ich bin Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, 'Du sollst deine Tochter nicht entweihen, indem du sie zum Huren anhältst, daß nicht das Land hurerisch und voll grober Unzucht werde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, 'Meine Ruhetage sollt ihr beobachten und euch vor meinem Heiligtume scheuen; ich bin Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, 'Wendet euch nicht an die Totenbeschwörer- und an die Wahrsagegeister. Befragt sie nicht, daß ihr euch durch sie verunreinigt; ich bin Jahwe, euer Gott.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, 'Vor einem grauen Haupte sollst du aufstehen und die Person eines Greisen ehren und sollst dich fürchten vor deinem Gott; ich bin Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, 'Und wenn sich ein Fremder bei dir aufhält in eurem Lande, so sollt ihr ihn nicht bedrücken.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, 'Wie ein Landeseingeborner aus eurer Mitte soll euch der Fremde gelten, der sich bei euch aufhält, und du sollst ihn lieben, wie dich selbst. Denn ihr seid auch Fremdlinge gewesen in Ägypten; ich bin Jahwe, euer Gott.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, 'Ihr sollt nicht Unrecht verüben beim Rechtsprechen, noch in betreff des Längenmaßes, des Gewichts und des Hohlmaßes.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, 'Richtige Wage, richtige Gewichtsteine, richtiges Epha und richtiges Hin sollt ihr führen; ich bin Jahwe, euer Gott, der euch aus Ägypten weggeführt hat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, 'So sollt ihr denn alle meine Satzungen und alle meine Rechte beobachten und nach ihnen thun; ich bin Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'Und Jahwe redete mit Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, 'Und zu den Israeliten sollst du sprechen: Jedermann von den Israeliten und von den Fremden, die sich in Israel aufhalten, der eines von seinen Kindern dem Melech hingiebt, soll mit dem Tode bestraft werden; die Landesbewohner sollen ihn steinigen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, 'Und ich selbst will gegen einen solchen mein Antlitz richten und ihn hinwegtilgen mitten aus seinem Volke, darum daß er eines von seinen Kindern dem Melech hingegeben hat, um mein Heiligtum zu verunreinigen und meinen heiligen Namen zu entweihen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'Und wenn etwa die Landesbewohner einem solchen durch die Finger sehen wollten, wenn er eines von seinen Kindern dem Melech hingiebt, daß Sie ihn nicht töten wollen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, 'so will doch ich mein Antlitz wider einen solchen richten und wider sein Geschlecht und will ihn und alle, die es ihm in der Abgötterei nachthun, indem sie mit dem Melech Abgötterei treiben, mitten aus ihrem Volk hinwegtilgen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, 'Derjenige aber, der sich an die Totenbeschwörer- und die Wahrsagegeister wendet und so Abgötterei mit ihnen treibt, wider einen solchen will ich mein Antlitz richten und ihn mitten aus seinem Volk hinwegtilgen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, 'Und ihr sollt euch heilig erweisen und sollt heilig sein, denn ich bin Jahwe, euer Gott.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, 'Darum sollt ihr meine Satzungen beobachten und nach ihnen thun; ich bin Jahwe der euch heiligt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, 'Denn jedermann, der seinem Vater und seiner Mutter flucht, soll mit dem Tode bestraft werden; seinem Vater und seiner Mutter hat er geflucht - Blutschuld haftet auf ihm.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, 'Und wenn jemand Ehebruch treibt mit einem Eheweibe, wenn jemand Ehebruch treibt mit dem Weibe seines Nächsten, soll sowohl der Ehebrecher als die Ehebrecherin mit dem Tode bestraft werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'Und wenn jemand bei dem Weibe seines Vaters liegt, so hat er die Scham seines Vaters entblößt; sie sollen beide mit dem Tode bestraft werden, Blutschuld haftet auf ihnen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, 'Und wenn jemand bei seiner Schwiegertochter liegt, so sollen beide mit dem Tode bestraft werden; sie haben eine schwere Schandthat verübt, Blutschuld haftet auf ihnen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, 'Und wenn jemand bei einem Manne liegt, wie man beim Weibe liegt, so haben beide eine Greuelthat verübt; mit dem Tode sollen sie bestraft werden, Blutschuld haftet auf ihnen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, 'Und wenn jemand ein Weib nimmt und dazu ihre Mutter, so ist dies grobe Unzucht; man soll ihn und sie beide verbrennen, daß nicht Unzucht unter euch im Schwange gehe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, 'Und wenn sich jemand mit einem Tiere fleischlich vermischt, so soll er mit dem Tode bestraft werden, und auch das Tier sollt ihr töten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, 'Und wenn sich ein Weib irgend einem Tiere naht, daß es sich mit ihr begatte, so sollst du das Weib samt dem Tiere töten; mit dem Tode sollen sie bestraft werden, Blutschuld haftet auf ihnen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, 'Und wenn einer seine Schwester, die Tochter seines Vaters oder die Tochter seiner Mutter, nimmt, so daß er ihre Scham sieht, und sie seine Scham sieht, so ist dies Blutschande, und sie sollen hinweggetilgt werden vor den Augen ihrer Volksgenossen; die Scham seiner Schwester hat er entblößt und Verschuldung auf sich geladen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, 'Und wenn jemand bei einem Weibe liegt zur Zeit ihrer monatlichen Krankheit und ihre Scham entblößt, ihren Brunnen aufgedeckt hat, und sie so den Brunnen ihres Bluts entblößt hat, so sollen beide mitten aus ihrem Volk hinweggetilgt werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, 'Die Scham der Schwester deiner Mutter und der Schwester deines Vaters darfst du nicht entblößen; denn wer es thut, der hat seine nächste Blutsverwandte aufgedeckt und sie haben Verschuldung auf sich geladen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, 'Und wenn jemand bei dem Weibe des Bruders seines Vaters liegt, so hat er die Scham seines Oheims entblößt und sie haben Sünde auf sich geladen - ohne Kinder sollen sie sterben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, 'Und wenn jemand das Weib seines Bruders nimmt, so ist dies Blutschande; die Scham seines Bruders hat er entblößt - sie sollen ohne Kinder sein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, 'So beobachtet denn alle meine Satzungen und alle meine Rechte und thut darnach, daß euch das Land nicht ausspeie, in das ich euch bringen will, daß ihr darin wohnen sollt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, 'Ihr dürft nicht wandeln nach den Satzungen des Volks, welches ich vor euch ausstoße, weil sie alles das verübt haben, so daß es mich vor ihnen ekelte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, 'Darum sprach ich zu euch: Ihr sollt ihren Boden zu eigen bekommen, und ich will ihn euch zum Besitze geben - ein Land, das von Milch und Honig überfließt, ich, Jahwe, euer Gott, der euch ausgesondert hat von den Völkern.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, 'So macht denn einen Unterschied zwischen den reinen und den unreinen Vierfüßlern, sowie zwischen den unreinen und den reinen Vögeln, und macht euch nicht selbst abscheulich durch Vierfüßler oder Vögel oder irgend etwas, das sich auf Erden regt, was ich abgesondert habe, damit es euch als unrein gelte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, 'Und ihr sollt mir heilig sein, denn ich, Jahwe, bin heilig und habe euch abgesondert von den Völkern, daß ihr mir angehören sollt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, 'Und wenn sich in einem Mann oder Weib ein Totenbeschwörer- oder Wahrsagegeist befinden wird, so sollen sie mit dem Tode bestraft werden; man soll sie steinigen, Blutschuld lastet auf ihnen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, 'Und Jahwe sprach zu Mose: Sage den Priestern, den Söhnen Aarons, und sprich zu ihnen: ein Priester darf sich nicht an einer Leiche verunreinigen unter seinen Volksgenossen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, 'Nur an den Blutsverwandten, die ihm am nächsten stehen, an seiner Mutter und seinem Vater, seinem Sohne, seiner Tochter, seinem Bruder und');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'seiner Schwester, die Jungfrau ist und ihm so noch nahe steht, die noch keinem Manne zu teil geworden ist - an der darf er sich verunreinigen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, 'Er darf sich nicht verunreinigen unter seinen Volksgenossen, daß er sich dadurch entweihe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, 'Sie dürfen sich auf ihrem Haupte keine Glatze scheren, dürfen den Rand ihres Bartes nicht abscheren und sich an ihrem Leibe keine Einschnitte machen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'Sie sollen ihrem Gotte heilig sein und den Namen ihres Gottes nicht entweihen; denn Sie bringen die Feueropfer Jahwes, die Speise ihres Gottes, dar, darum sollen sie heilig sein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, 'Eine Hure oder eine Geschwächte dürfen sie nicht zum Weibe nehmen; auch eine von ihrem Manne verstoßene Frau dürfen Sie nicht nehmen, denn der Priester ist seinem Gotte heilig.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, 'Darum sollst du ihn heilig halten, denn er bringt die Speise deines Gottes dar; als heilig soll er dir gelten, denn ich bin heilig, Jahwe, der euch heiligt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, 'Und wenn sich die Tochter eines Priesters entweiht durch Hurerei, so entweiht sie damit ihren Vater; man soll sie verbrennen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, 'Der aber Hoherpriester ist unter seinen Brüdern, auf dessen Haupt das Salböl gegossen ward, dem man die Hand gefüllt und die heiligen Kleider angelegt hat, der darf sein Haupthaar nicht wild fliegen lassen und seine Kleider nicht zerreißen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, 'Er darf zu gar keiner Leiche hineingehen; sogar an seinem Vater und an seiner Mutter darf er sich nicht verunreinigen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'Das Heiligtum darf er nicht verlassen, damit er nicht etwa das Heiligtum seines Gottes entweihe, denn die Weihe des Salböls seines Gottes ruht auf ihm; ich bin Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, 'Eine reine Jungfrau muß er zum Weibe nehmen;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, 'eine Witwe oder Verstoßene oder Geschwächte oder Hure - diese darf er nicht nehmen; nur eine Jungfrau aus seinen Volksgenossen darf er zum Weibe nehmen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'daß er nicht seinen Stamm unter seinen Volksgenossen entweihe, denn ich bin Jahwe, der ihn heiligt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, 'Und Jahwe redete mit Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, 'Rede mit Aaron also: wenn jemand von deinen Nachkommen, jetzt und in allen künftigen Zeiten, ein Leibesgebrechen hat, so darf er nicht herzutreten, um die Speise seines Gottes darzubringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, 'Denn wer irgend ein Leibesgebrechen hat, darf nicht herzutreten, er sei nun blind oder lahm oder im Gesicht verstümmelt oder mit einem zu langen Gliede behaftet');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, 'oder habe ein gebrochenes Bein oder einen gebrochenen Arm');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, 'oder sei bucklig oder unnatürlich abgemagert oder habe weiße Flecken im Auge oder leide an Krätze oder Flechten oder an einem Hodenbruch.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, 'Keiner von den Nachkommen Aarons, des Priesters, der ein Leibesgebrechen hat, darf herzunahen, um die Feueropfer Jahwes darzubringen; hat er ein Leibesgebrechen, so darf er nicht herzunahen, die Speise seines Gottes darzubringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, 'Von der Speise seines Gottes, sowohl den hochheiligen, als den heiligen Gaben, darf er essen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, 'Nur darf er nicht hineingehn zum inneren Vorhang und zum Altar nicht nahen, weil er ein Leibesgebrechen hat, damit er meine Heiligtümer nicht entweihe; denn ich bin Jahwe, der sie heiligt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'Und Mose redete solches zu Aaron und zu seinen Söhnen und zu allen Israeliten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'Und Jahwe redete mit Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, 'Sage Aaron und seinen Söhnen, daß sie sich vorsichtig verhalten sollen gegenüber den heiligen Gaben der Israeliten, die sie mir weihen, damit sie nicht meinen heiligen Namen entweihen; ich bin Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, 'Sprich zu ihnen: Wenn irgend jemand von allen euren Nachkommen, jetzt und in künftigen Zeiten, den heiligen Gaben, welche die Israeliten Jahwe weihen werden, sich nähert, während ihm Unreinigkeit anhaftet, ein solcher soll hinweggetilgt werden aus meinem Angesicht; ich bin Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'Wer irgend von den Nachkommen Aarons aussätzig ist oder einen Fluß hat, darf von den heiligen Gaben nicht mit essen, bis er wieder rein ist. Wer irgend einen durch eine Leiche Verunreinigten berührt hat oder wem der Same entgangen ist,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'oder wer irgend ein Gewürm berührt hat, durch das er unrein geworden ist, oder einen Menschen, durch den er unrein geworden ist zufolge irgend welcher Unreinigkeit, die ihm anhaftet, -');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, 'wer solches berührt hat, ein solcher bleibt unrein bis zum Abend und darf nicht von den heiligen Gaben essen, wenn er nicht zuvor seinen Leib gebadet hat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, 'Sobald die Sonne untergegangen ist, ist er wieder rein; alsdann mag er von den heiligen Gaben essen, denn das ist seine Speise.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, 'Aas und von wilden Tieren Zerrissenes darf er nicht essen, daß er sich dadurch verunreinigt; ich bin Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, 'So sollen sie denn meine Anordnungen befolgen, daß sie nicht wegen des Geheiligten Sünde auf sich laden und deshalb sterben, weil sie es entweihen; ich bin Jahwe, der sie heiligt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, 'Kein Fremder aber darf Geheiligtes essen; der Beisaß oder Tagelöhner eines Priesters darf nicht Geheiligtes essen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, 'Wenn aber ein Priester einen Sklaven für Geld erwirbt, so darf dieser mit davon essen; ebenso der in seinem Hause geborene - sie dürfen mit von seiner Speise essen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, 'Eine Priesterstochter, die einem Fremden zu teil geworden ist, darf von der Hebe, die von den heiligen Gaben entrichtet wird, nicht mit essen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, 'Eine Priesterstochter aber, welche Witwe oder von ihrem Manne verstoßen und kinderlos ist und wieder zu ihrer Familie zurückkehrt, wie in ihrer Jugend, die darf von der Speise ihres Vaters essen; dagegen darf durchaus kein Fremder mit davon essen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, 'Und wenn jemand aus Versehen Geheiligtes ißt, so soll er ein Fünftel des Betrags darauf legen und es dem Priester geben samt dem Geheiligten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'Und die Priester sollen die heiligen Gaben der Israeliten nicht entweihen - was sie als Hebe für Jahwe hinwegnehmen -,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'damit Sie ihnen nicht Schuld aufladen durch ihre Verschuldung, wenn Sie ihre heiligen Gaben verzehren; denn ich bin Jahwe, der Sie heiligt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, 'Und Jahwe redete mit Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, 'Rede mit Aaron und mit seinen Söhnen und allen Israeliten und sprich zu ihnen: Wenn irgend jemand vom Hause Israel oder von den Fremden in Israel seine Opfergabe darbringt - irgend welche gelobte oder freiwillige Gaben, die sie Jahwe als Brandopfer darbringen wollen -,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, 'sollt ihr sie so darbringen, daß sie euch wohlgefällig mache: ein fehlloses, männliches Tier von den Rindern, den Lämmern oder den Ziegen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, 'Was irgend einen Makel an sich hat, dürft ihr nicht darbringen; denn es würde euch nicht wohlgefällig machen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, 'Und wenn jemand Jahwe von den Rindern oder Schafen ein Heilsopfer darbringen will, sei es nun zur Abtragung eines Gelübdes oder als freiwillige Gabe, so muß es fehllos sein, damit es ihn wohlgefällig mache; es darf gar keinen Makel an sich haben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, 'Was blind ist oder ein gebrochenes Glied oder eine Wunde hat oder mit Geschwüren oder Krätze oder Flechten behaftet ist - solche dürft ihr Jahwe nicht darbringen und kein derartiges Jahwe als Feueropfer auf den Altar legen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, 'Ein Rind aber oder ein Schaf mit zu langen oder zu kurzen Gliedern darfst du als freiwillige Gabe herrichten; dagegen als Gelübdeopfer würde es euch nicht wohlgefällig machen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, 'Auch ein solches, dem die Hoden zerquetscht oder zerschlagen oder abgerissen oder ausgeschnitten sind, dürft ihr Jahwe nicht darbringen. Ihr dürft weder irgend welche derart Verstümmelte in eurem Lande machen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, 'noch von einem Ausländer erwerben und als Speise eures Gottes darbringen; denn es haftet ihnen ein Schaden an - ein Makel haftet an ihnen -, darum werden sie euch nicht wohlgefällig machen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, 'Und Jahwe redete mit Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, 'wenn ein Rind oder ein Lamm oder ein Zicklein geboren wird, so soll es sieben Tage von seiner Mutter gesäugt werden; aber vom achten Tage ab und weiterhin wird es wohlgefällig aufgenommen werden, wenn es Jahwe als Feueropfer dargebracht wird.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, 'Ein Rind oder Schaf dürft ihr nicht zusammen mit seinem Jungen an einem und demselben Tage schlachten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, 'Und wenn ihr Jahwe ein Dankopfer opfern wollt, sollt ihr es so opfern, daß es euch wohlgefällig mache.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, 'An ebendemselben Tage muß es verzehrt werden: ihr dürft nichts davon übrig lassen bis zum nächsten Morgen; ich bin Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, 'So beobachtet denn meine Gebote und thut darnach - ich bin Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, 'Und entweiht nicht meinen heiligen Namen, damit ich geheiligt werde inmitten der Israeliten; ich bin Jahwe, der euch heiligt,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, 'der euch weggeführt hat aus Ägypten, um euer Gott zu sein - ich, Jahwe!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, 'Und Jahwe redete mit Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, 'Rede mit den Israeliten und sprich zu ihnen: Die Festzeiten Jahwes, die ihr auszurufen habt als Festversammlungen am Heiligtume - folgende sind meine Festzeiten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, 'Sechs Tage hindurch darf Arbeit verrichtet werden, aber der siebente Tag ist ein Tag unbedingter Ruhe, mit Festversammlung am Heiligtum; da dürft ihr keinerlei Arbeit verrichten in allen euren Wohnsitzen - es ist ein Ruhetag für Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, 'Dies sind die Festzeiten Jahwes, mit Festversammlungen am Heiligtume, die ihr auszurufen habt, ein jedes zu seiner Zeit.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, 'Im ersten Monat, am vierzehnten des Monats gegen Abend findet Passahfeier für Jahwe statt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, 'Am fünfzehnten Tage aber desselben Monats ist Jahwe das Fest der ungesäuerten Brote zu feiern; sieben Tage lang müßt ihr ungesäuerte Brote essen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'Am ersten Tage habt ihr Festversammlung am Heiligtume zu halten; da dürft ihr keinerlei Werktagsarbeit verrichten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, 'Und sieben Tage hindurch habt ihr Jahwe ein Feueropfer darzubringen; am siebenten Tage findet Festversammlung am Heiligtume statt, da dürft ihr keinerlei Werktagsarbeit verrichten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'Und Jahwe redete mit Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, 'Rede mit den Israeliten und sprich zu ihnen: Wenn ihr in das Land kommt, das ich euch verleihen werde, und die Ernte in ihm abhaltet, so sollt ihr die Erstlingsgarbe von eurer Ernte zum Priester bringen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, 'und er soll die Garbe vor Jahwe weben, daß Sie euch wohlgefällig mache; am Tage nach dem Sabbat soll sie der Priester weben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'Und ihr sollt an dem Tage, an welchem ihr die Garbe webt, ein fehlIoses, einjähriges Lamm zum Brandopfer für Jahwe herrichten,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'dazu als Speisopfer zwei Zehntel Feinmehl, angemacht mit Öl, als ein Feueropfer lieblichen Geruchs für Jahwe, und als Trankopfer dazu ein Viertel Hin Wein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, 'Brot aber und geröstete oder zerstoßene Körner dürft ihr bis zu eben diesem Tage nicht essen, bis ihr die Opfergabe für euren Gott dargebracht habt. Das ist eine für alle Zeiten geltende Satzung, die ihr beobachten sollt von Geschlecht zu Geschlecht in allen euren Wohnsitzen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, 'Sodann sollt ihr vom Tage nach dem Sabbat ab - von dem Tage ab, wo ihr die Webegarbe darbrachtet, - sieben volle Wochen zählen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'bis zum Tage nach dem siebenten Sabbat sollt ihr zählen, fünfzig Tage; alsdann sollt ihr Jahwe ein Speisopfer vom neuen Getreide darbringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'Aus euren Wohnsitzen sollt ihr zwei Webe-Brote bringen; aus zwei Zehnteln Feinmehl sollen sie bestehen und mit Sauerteig gebacken sein, als Erstlingsopfer für Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, 'Und zu dem Brote sollt ihr darbringen sieben fehllose einjährige Lämmer, einen jungen Stier und zwei Widder - die sollen Jahwe als Brandopfer gebracht werden, nebst dem zugehörigen Speisopfer und den zugehörigen Trankopfern, als ein Feueropfer lieblichen Geruchs für Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, 'Ferner sollt ihr einen Ziegenbock herrichten zum Sündopfer und zwei einjährige Lämmer zum Heilsopfer.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, 'Und der Priester soll sie samt den Erstlingsbroten als Webeopfer vor Jahwe weben samt zwei Lämmern; sie sollen Jahwe geheiligt sein zum Besten des Priesters.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, 'Und ihr sollt an eben diesem Tag ausrufen - ihr sollt Festversammlung am Heiligtum abhalten; da dürft ihr keinerlei Werktagsarbeit verrichten. Das ist eine für alle Zeiten geltende Satzung, die ihr beobachten sollt in allen euren Wohnsitzen von Geschlecht zu Geschlecht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, 'Und wenn ihr euer Land aberntet, so sollst du dein Feld nicht bis auf den äußersten Rand abernten und sollst nicht Nachlese halten nach deiner Ernte: den Armen und den Fremden sollst du beides überlassen; ich bin Jahwe, euer Gott.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, 'Und Jahwe redete mit Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, 'Rede mit den Israeliten also: Im siebenten Monat soll euch der erste des Monats ein Ruhetag sein, mit mahnendem Lärmblasen und Festversammlung am Heiligtum.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, 'Ihr dürft da keinerlei Werktagsarbeit verrichten und habt Jahwe ein Feueropfer darzubringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, 'Und Jahwe redete mit Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, 'Dagegen der zehnte desselben siebenten Monats ist der Sühntag; da habt ihr Festversammlung am Heiligtume zu halten und euch zu kasteien und Jahwe ein Feueropfer darzubringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'Und an eben diesem Tage dürft ihr keinerlei Arbeit verrichten, denn der Sühntag ist es, daß man euch Sühne schaffe vor Jahwe, eurem Gott.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, 'Denn wer irgend an diesem Tage sich nicht kasteit, der soll hinweggetilgt werden aus seinen Volksgenossen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'Und wer immer an diesem Tag irgend welche Arbeit verrichtet, einen solchen will ich hinwegraffen mitten auf seinen Volksgenossen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, 'Ihr dürft da keinerlei Arbeit verrichten; das ist eine für alle Zeiten geltende Satzung, die ihr beobachten sollt von Geschlecht zu Geschlecht in allen euren Wohnsitzen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, 'Als ein Tag unbedingter Ruhe soll er euch gelten, und ihr sollt euch kasteien. Am Abend des neunten des Monats - vom Abend bis wieder zum Abend sollt ihr die geforderte Ruhezeit einhalten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, 'Und Jahwe redete mit Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, 'Rede mit den Israeliten also: Am fünfzehnten Tage desselben siebenten Monats soll man Jahwe sieben Tage lang das Hüttenfest feiern.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, 'Am ersten Tag ist Festversammlung am Heiligtume; da dürft ihr keinerlei Werktagsarbeit verrichten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, 'Sieben Tage hindurch habt ihr Jahwe ein Feueropfer darzubringen; am achten Tage habt ihr Festversammlung am Heiligtume zu halten und Jahwe ein Feueropfer darzubringen - Festversammlung ist es; da dürft ihr keinerlei Werktagsarbeit verrichten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, 'Das sind die Festzeiten Jahwes, in welchen ihr Festversammlungen am Heiligtum ausrufen sollt, daß man Jahwe Feueropfer darbringe - Brandopfer und Speisopfer, Schlachtopfer und Trankopfer, je nach der Erfordernis des betreffenden Tags,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'abgesehen von den Sabbaten Jahwes und abgesehen von euren Gaben, sowie von allen euren Gelübdeopfern und allen euren freiwilligen Spenden, die ihr Jahwe bringen wollt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, 'Jedoch am fünfzehnten Tage des siebenten Monats, wenn ihr den Ertrag des Landes einheimst, sollt ihr sieben Tage lang das Fest Jahwes feiern; der erste Tag ist ein Ruhetag und der achte Tag ist ein Ruhetag.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'Und ihr sollt euch am ersten Tage Früchte von prächtigen Bäumen, Palmenzweige und Äste von dichtbelaubten Bäumen, sowie von Bachweiden holen und sieben Tage lang vor Jahwe, eurem Gotte, fröhlich sein,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, 'und sollt es als ein Fest Jahwes feiern jedes Jahr sieben Tage lang; das ist eine für alle Zeiten geltende Satzung, die ihr beobachten sollt von Geschlecht zu Geschlecht: im siebenten Monat sollt ihr es feiern.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, 'Da sollt ihr sieben Tage lang in Hütten wohnen; alle Landeseingebornen in Israel sollen in Hütten wohnen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, 'damit eure künftigen Geschlechter erfahren, daß ich die Israeliten habe in Hütten wohnen lassen, als ich sie aus Ägypten hinwegführte, ich, Jahwe, euer Gott.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'Und Mose sagte den Israeliten die Festzeiten Jahwes.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, 'Und Jahwe redete mit Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, 'Gebiete den Israeliten, daß sie dir lauteres Öl aus zerstoßenen Oliven für den Leuchter herbeibringen, damit man beständig Lampen aufstecken kann.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'Außerhalb des Vorhangs vor dem Gesetz im Offenbarungszelte soll ihn Aaron herrichten, daß er beständig vor Jahwe brenne vom Abend bis zum Morgen. Das ist eine für alle Zeiten geltende Satzung, die ihr beobachten sollt von Geschlecht zu Geschlecht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, 'Auf dem Leuchter von gediegenem Golde soll er die Lampen herrichten, daß sie beständig vor Jahwe brennen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, 'Ferner sollst du Feinmehl nehmen und daraus zwölf Kuchen backen - zwei Zehntel sollen auf jeden Kuchen kommen -');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, 'und sollst sie in zwei Reihen, je sechs in einer Reihe, auf dem Tisch von gediegenem Golde vor Jahwe auflegen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, 'Jeder Schicht aber sollst du reinen Weihrauch beigeben; dieser soll dann als Duftteil von dem Brote dienen als ein Jahwe dargebrachtes Feueropfer.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, 'Jedesmal am Sabbattage soll er es beständig vor Jahwe aufschichten, kraft einer den Israeliten obliegenden, für alle Zeiten geltenden Verpflichtung.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'Und es soll Aaron und seinen Söhnen zufallen, daß sie es verzehren an heiliger Stätte; denn es gehört ihm als ein Hochheiliges unter den Feueropfern, kraft eines für alle Zeiten geltenden Rechts.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, 'Und der Sohn einer Israelitin - er stammte aber von einem ägyptischen Manne - ging aus mitten unter die Israeliten; da gerieten sie im Lager in Streit, der Sohn der Israelitin und ein israelitischer Mann.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, 'Da lästerte der Sohn der Israelitin den heiligen Namen und fluchte; da brachten sie ihn zu Mose (seine Mutter aber hieß Selomith, die Tochter Dibris, vom Stamme Dan).');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, 'Und sie legten ihn in Gewahrsam, bis ihnen Weisung zukäme auf Grund eines Ausspruchs Jahwes.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, 'Und Jahwe redete mit Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, 'Laß den Flucher hinaus vor das Lager führen, und alle, die es gehört haben, sollen ihm die Hände auf daß Haupt aufstemmen, und sodann soll ihn die ganze Gemeinde steinigen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, 'Zu den Israeliten aber sollst du also sprechen: Wer irgend seinem Gotte flucht, der lädt Sünde auf sich.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'Und wer den Namen Jahwes lästert, soll mit dem Tode bestraft werden; die ganze Gemeinde soll ihn unfehlbar steinigen. Es sei ein Fremder oder ein Landeseingeborner - wenn er den heiligen Namen lästert, soll er getötet werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, 'Wenn jemand irgend einen Menschen erschlägt, soll er mit dem Tode bestraft werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, 'Und wer ein Stück Vieh erschlägt, hat er es zu ersetzen - Leben um Leben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, 'Wenn jemand seinem Nächsten einen Leibesschaden zufügt, dem soll man thun, wie er gethan hat:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, 'Bruch um Bruch, Auge um Auge, Zahn um Zahn; derselbe Leibesschaden, den er einem andern zufügt, soll ihm zugefügt werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, 'Wer ein Stück Vieh erschlägt, hat es zu ersetzen; wer aber einen Menschen erschlägt, der soll getötet werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, 'Einerlei Recht soll unter euch gelten, für den Fremden, wie für den Landeseingebornen, denn ich bin Jahwe, euer Gott.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'Und Mose redete mit den Israeliten; da führten sie den Flucher hinaus vor das Lager und steinigten ihn. Und die Israeliten thaten, wie Jahwe Mose befohlen hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, 'Und Jahwe redete mit Mose auf dem Berge Sinai also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, 'Rede mit den Israeliten und sprich zu ihnen: Wenn ihr in das Land kommt, das ich euch verleihen werde, so soll das Land Jahwe eine Ruhezeit halten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, 'Sechs Jahre hindurch magst du dein Feld besäen und sechs Jahre hindurch deinen Weinberg beschneiden und den Ertrag des Landes einheimsen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, 'Aber das siebente Jahr soll für das Land eine Zeit unbedingter Ruhe sein, eine Ruhezeit für Jahwe. Da darfst du dein Feld nicht besäen, noch deinen Weinberg beschneiden;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, 'den Nachwuchs deiner vorigen Ernte darfst du nicht einernten und die Trauben deines unbeschnittenen Weinstocks nicht lesen - es soll ein Ruhejahr sein für das Land.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, 'Was das Land in der Ruhezeit freiwillig trägt, soll euch zur Nahrung dienen - dir, deinem Sklaven und deiner Sklavin, sowie deinem Lohnarbeiter und deinem Beisassen, die sich bei dir aufhalten;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'auch deinem Vieh und dem Wild in deinem Lande soll alles, was es trägt, zur Nahrung dienen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, 'Weiter sollst du sieben Ruhejahre zählen - siebenmal sieben Jahre - so daß die Zeit der sieben Ruhejahre neunundvierzig Jahren gleichkommt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, 'Dann aber sollst du im siebenten Monat, am zehnten des Monats die Lärmposaune erschallen Iassen; am Sühntage sollt ihr überall in eurem Lande die Posaune erschallen lassen');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'und sollt so das fünfzigste Jahr weihen und im Lande Freiheit ausrufen für alle seine Bewohner. Als ein Halljahr soll es euch gelten; da sollt ihr ein jeder wieder zu seinem Besitz und zu seinem Geschlechte kommen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'Als ein Halljahr soll es euch gelten, das fünfzigste Jahr; in ihm dürft ihr nicht säen und den Nachwuchs nicht einernten, noch von den unbeschnittenen Weinstöcken Trauben lesen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'Denn ein Halljahr ist es und soll euch als geheiligt gelten; vom Felde weg sollt ihr essen, was es trägt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'In solchem Halljahre sollt ihr ein jeder wieder zu seinem Besitze kommen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, 'Wenn du deinem Nächsten etwas verkaufst oder von deinem Nächsten kaufst, so sollt ihr nicht einer den andern übervorteilen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'Mit Rücksicht auf die Anzahl der Jahre seit dem letzten Halljahre sollst du deinem Nächsten abkaufen, und mit Rücksicht auf die Anzahl der Erntejahre soll er dir verkaufen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, 'Für eine größere Zahl von Jahren hast du einen entsprechend höheren Kaufpreis zu zahlen, wie für eine geringere Zahl von Jahren einen entsprechend geringeren; denn eine Anzahl von Ernten verkauft er dir.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, 'So übervorteilt nun keiner seinen Nächsten, sondern fürchte dich vor deinem Gotte, denn ich bin Jahwe, euer Gott.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, 'Darum sollt ihr nach meinen Satzungen thun und meine Rechte beobachten und nach ihnen thun, damit ihr sicher im Lande wohnt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, 'Da wird dann das Land seine Frucht hergeben, daß ihr euch satt essen könnt und sicher darin wohnt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, 'Und falls ihr sprächet: Was sollen wir essen im siebenten Jahre, wenn wir nicht säen und uns keine Früchte einsammeln dürfen?');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, 'So wisset: Ich werde im sechsten Jahre meinen Segen zu euren Gunsten aufbieten, daß es für alle drei Jahre den nötigen Ertrag abwerfen soll.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, 'Und wenn ihr im achten Jahre säet, werdet ihr noch immer von dem Ertrag altes Getreide essen; bis zum neunten Jahre - bis der Ertrag desselben zu Gebote steht - werdet ihr altes essen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, 'Grund und Boden darf nicht endgiltig verkauft werden, denn mein ist das Land; denn ihr seid nur Fremdlinge und Beisassen bei mir.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, 'Daher sollt ihr in dem Lande, das ihr zu eigen habt, überall eine Wiedereinlösung von Grund und Boden gestatten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, 'Wenn dein Bruder verarmt und etwas von seinem Besitztume verkauft, so soll sein nächster Verwandter als Löser für ihn eintreten und das, was sein Verwandter verkauft hat, wieder einlösen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, 'Und wenn jemand keinen Löser hat, aber so viel zu beschaffen vermag, als er zur Wiedereinlösung bedarf,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'so soll er die Jahre, die seit dem Verkaufe verflossen sind, in Anrechnung bringen; was darüber ist, soll er demjenigen, an den er verkauft hat, zurückerstatten, damit er wieder zu seinem Besitztum komme.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, 'Beschafft er aber nicht so viel, als er zur Rückerstattung bedarf, so bleibt das von ihm Verkaufte im Besitze des Käufers bis zum Halljahr; im Halljahr aber soll es unentgeltlich heimfallen, so daß er wieder zu seinem Besitztume kommt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, 'Und wenn jemand ein Wohnhaus in einer ummauerten Stadt verkauft, so soll er es wieder einlösen dürfen bis zum Abschlusse des Jahres, in welchem er es verkauft hat; für seine Wiedereinlösung ist damit eine Frist gesetzt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'Wenn es aber bis zum Ablauf eines vollen Jahres nicht eingelöst wird, so wird das Haus, das in einer ummauerten Stadt liegt, dem Käufer und seinen Nachkommen endgiltig als Besitz bestätigt und fällt im Halljahre nicht heim.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, 'Dagegen die Häuser in den Dörfern, welche nicht ringsum eine Mauer haben, sind als ein Teil des Ackerbesitzes zu betrachten; sie dürfen wieder eingelöst werden und fallen im Halljahre heim.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, 'Was aber die Häuser der Leviten betrifft - die Häuser in den Städten, die ihr Eigentum sind -, so steht den Leviten jederzeit die Wiedereinlösung zu.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, 'Und wenn jemand von den Leviten seinen Besitz nicht wieder einlöst, so fällt das von ihm - und zwar in der Stadt, wo er seinen Erbbesitz hat - verkaufte Haus im Halljahre heim; denn die Häuser in den Städten der Leviten sind ihr Erbbesitz inmitten der Israeliten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, 'Das zu ihren Städten gehörende Weideland aber darf nicht verkauft werden; denn es gehört ihnen für alle Zeiten als Erbbesitz.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, 'Und wenn dein Bruder verarmt, daß er sich neben dir nicht halten kann, so sollst du ihn aufrecht erhalten als Fremdling und Beisassen, daß er seinen Unterhalt neben dir habe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, 'Du darfst nicht Zins und Wucher von ihm nehmen, sondern sollst dich fürchten vor deinem Gotte, daß dein Bruder seinen Unterhalt neben dir habe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, 'Du darfst ihm dein Geld nicht um Zins geben, noch deine Nahrungsmittel um Wucher.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, 'Ich bin Jahwe, euer Gott, der euch aus Ägypten weggeführt hat, um euch das Land Kanaan zu verleihen, um euer Gott zu sein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, 'Und wenn dein Bruder neben dir verarmt und sich dir verkauft, so sollst du ihn nicht Sklavendienst thun lassen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, 'Gleich einem Lohnarbeiter, einem Beisassen, soll er bei dir sein; bis zum Halljahre soll er bei dir dienen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, 'Dann aber soll er samt seinen Kindern frei von dir ausgehen und zu seinem Geschlechte zurückkehren und wieder zu seinem väterlichen Besitztume kommen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, 'Denn meine Knechte sind sie, die ich aus Ägypten weggeführt habe; sie dürfen nicht verkauft werden, wie man Sklaven verkauft.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, 'Du sollst nicht mit Härte über ihn herrschen, sondern dich fürchten vor deinem Gotte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, 'Und wenn du Sklaven und Sklavinnen haben willst: Von den Völkern, die euch rings umgeben, - von denen mögt ihr Sklaven und Sklavinnen kaufen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'Auch von den Kindern der Beisassen, die sich bei euch aufhalten, mögt ihr welche kaufen, sowie aus ihrer Sippschaft, die sich bei euch befindet, die in eurem Lande geboren ist; sie sollen euer Besitztum sein,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, 'und ihr mögt sie auf eure Kinder nach euch vererben, daß sie ihr Eigentum seien, und mögt sie so dauernd zu Sklaven haben. Aber über eure Brüder, die Israeliten, - da darfst du nicht, einer über den andern, mit Härte herrschen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, 'Und wenn ein Fremdling oder Beisaß neben dir zu Besitz gelangt, dagegen dein Bruder neben ihm verarmt und sich einem Fremdling oder Beisassen oder einem Abkömmling von der Sippschaft eines Fremdlings neben dir verkauft,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, 'so soll er, nachdem er sich verkauft hat, wieder ausgelöst werden können. Einer seiner Brüder mag ihn auslösen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'oder sein Oheim oder der Sohn seines Oheims mag ihn auslösen, oder sonst einer von seinen nächsten Blutsverwandten aus seinem Geschlechte mag ihn auslösen; oder, wenn er selbst wieder zu Besitz gelangt, so mag er sich auslösen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, 'Und zwar soll er mit dem, der ihn gekauft hat, die Zeit berechnen von dem Jahr ab, wo er sich ihm verkaufte, bis zum Halljahr. Der Preis, um den er sich verkauft, soll der Anzahl der Jahre entsprechen; gleich einem Lohnarbeiter ist er eine bestimmte Zeit bei ihm.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, 'Wenn noch viele Jahre fehlen, so hat er zum Behufe seiner Auslösung einen dementsprechenden Betrag von der Kaufsumme zurückzuerstatten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, 'Wenn aber nur noch wenige Jahre bis zum Halljahre fehlen, so muß er sie ihm auch berechnen; nach seinen Dienstjahren richtet es sich, wie viel er zum Behufe seiner Auslösung zurückzuerstatten hat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, 'Gleich einem, der Jahr um Jahr für Lohn arbeitet, soll er bei ihm sein; du darfst nicht ruhig mit ansehen, daß er mit Härte über ihn herrscht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, 'Falls er aber nicht in dieser Weise ausgelöst wird, so soll er samt seinen Kindern im Halljahre frei ausgehen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, 'Denn die Israeliten gehören mir als Knechte zu; meine Knechte sind sie, der ich sie aus Ägypten weggeführt habe, ich, Jahwe, ihr Gott!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, 'Ihr dürft euch nicht Götzen anfertigen und euch nicht Schnitzbilder und Malsteine aufstellen, noch einen Stein mit Bildwerk in eurem Lande setzen, um euch davor niederzuwerfen, denn ich bin Jahwe, euer Gott.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, 'Meine Ruhetage sollt ihr beobachten und euch vor meinem Heiligtume scheuen; ich bin Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, 'Wenn ihr nach meinen Satzungen wandeln und meine Gebote beobachten und nach ihnen thun wollt,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, 'so will ich euch jedesmal zur rechten Zeit Regen senden, daß der Boden seinen Ertrag gebe, und die Bäume auf dem Feld ihre Früchte tragen;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, 'da soll sich bei euch die Dreschzeit bis zur Weinlese hinziehen und die Weinlese bis zur Saatzeit, daß ihr Brot in Fülle zu essen habt und sicher in eurem Lande wohnt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, 'Und ich will machen, daß Friede im Lande herrscht, das ihr euch niederlegen könnt, ohne daß euch jemand aufschreckt; die reißenden Tiere will ich wegschaffen aus dem Land, und kein Schwert soll in euer Land eindringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, 'Ihr werdet eure Feinde in die Flucht schlagen, daß sie auf der Flucht vor euch dem Schwerte verfallen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, 'Fünf von euch sollen hundert in die Flucht schlagen, und hundert von euch sollen zehntausend in die Flucht schlagen, so daß eure Feinde auf der Flucht vor euch dem Schwerte verfallen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, 'Und ich werde mich zu euch wenden und will verleihen, daß ihr euch mehrt und zahlreich werdet, und will meinen Bund mit euch in Kraft treten lassen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, 'Und ihr werdet abgelagertes altes Getreide zu essen haben und das alte hinausschaffen müssen, um das neue unterzubringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, 'Und ich werde meinen Wohnsitz unter euch aufschlagen und keinen Widerwillen gegen euch hegen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, 'sondern werde unter euch wandeln und will euer Gott sein, und ihr sollt mein Volk sein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, 'Ich bin Jahwe, euer Gott, der euch aus Ägypten weggeführt hat, damit ihr nicht länger ihre Sklaven wäret; ich zerbrach die Stangen eures Jochs und ließ euch aufrecht einhergehn.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, 'Wenn ihr mir aber nicht gehorcht und nicht durchaus nach diesen Geboten handelt,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'wenn ihr meine Satzungen verachtet und gegen meine Rechte Widerwillen hegt, so daß ihr nicht durchaus nach meinen Geboten handelt und so den Bund mit mir brecht,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, 'so will auch ich demgemäß mit euch verfahren und will Schreckliches über euch verhängen: Schwindsucht und Fieber, die die Augen erlöschen und das Leben schwinden machen. Da sollt ihr dann vergeblich euren Samen säen, denn eure Feinde werden es verzehren.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, 'Und ich werde mein Angesicht wider euch kehren, daß ihr geschlagen werdet und fliehen müßt vor euren Feinden; und eure Hasser werden euch unterjochen, und ihr werdet fliehen, auch wenn euch niemand verfolgt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, 'Und wenn ihr mir auch dann noch ungehorsam seid, so will ich euch noch siebenmal härter züchtigen um eurer Sünden willen');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, 'und will euren frechen Stolz brechen und will machen, daß der Himmel über euch wie Eisen und euer Boden wie Erz ist.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, 'Da werdet ihr euch dann nutzlos abquälen: der Boden wird euch keinen Ertrag geben, und die Bäume im Lande werden keine Früchte tragen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, 'Und wenn ihr mir zuwiderhandelt und mir nicht gehorchen wollt, so will ich euch weiter schlagen siebenmal, wie es eure Sünden verdienen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, 'Da werde ich die wilden Tiere gegen euch entsenden, daß Sie euch eurer Kinder berauben und euer Vieh würgen und eure Zahl mindern, so daß eure Straßen veröden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, 'Und wenn ihr euch dadurch nicht von mir warnen laßt, sondern mir zuwiderhandelt,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, 'so will auch ich euch zuwiderhandeln und will euch meinerseits schlagen siebenmal um eurer Sünden willen');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, 'und will ein Schwert über euch kommen lassen, das Rache nehmen soll für den Bundesbruch. Und wenn ihr euch dann in eure Städte zurückziehen werdet, so will ich die Pest unter euch senden, und ihr sollt in Feindeshand gegeben werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, 'Wenn ich euch die Stütze des Brotes zerbreche, so werden dann zehn Weiber in einem Backtopfe Brot für euch backen und euch das Brot abgewogen zurückbringen, und ihr werdet essen, aber nicht satt werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, 'Und wenn ihr mir trotzdem ungehorsam seid und mir zuwiderhandelt,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, 'so will dann auch ich im Grimm euch zuwiderhandeln und euch züchtigen siebenmal um eurer Sünden willen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, 'Und ihr sollt das Fleisch eurer Söhne verzehren und das Fleisch eurer Töchter sollt ihr verzehren.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, 'Und ich will eure Opferhöhen verwüsten und eure Sonnensäulen zerstören und will eure Leichen auf die Leichen eurer Götzen werfen und werde Abscheu vor euch empfinden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'Eure Städte will ich zu Trümmerhaufen machen und eure Heiligtümer verwüsten und will nicht riechen den lieblichen Geruch eurer Opfer.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, 'Ja, ich selbst will das Land verwüsten, daß sich eure Feinde, die sich darin niederlassen, darüber entsetzen sollen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, 'Euch aber will ich verstreuen unter den Völkern und will hinter euch her das Schwert zücken; und euer Land soll zur Wüste und eure Städte sollen zu Trümmerhaufen werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, 'Da wird dann das Land seine Ruhezeiten ersetzt bekommen die ganze Zeit hindurch, in der es wüste liegt, während ihr im Land eurer Feinde seid; da wird dann das Land Ruhe haben und seine Ruhezeiten abtragen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, 'Die ganze Zeit hindurch, in der es wüste liegt, wird es Ruhe haben - die Ruhe, die es nicht gehabt hat zu den Ruhezeiten, die euch geboten waren, als ihr noch darin wohntet.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, 'Und die von euch übrig sein werden, die will ich gänzlich verzagt machen in den Ländern ihrer Feinde, daß sie das Rauschen eines verwehten Blattes in die Flucht jagen soll, daß sie fliehen sollen, wie man vor dem Schwerte flieht, und hinstürzen, obschon sie niemand verfolgt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, 'Und sie sollen übereinander fallen, wie auf der Flucht vor dem Schwert, obschon sie niemand verfolgt; und ihr sollt nicht Stand halten können vor euren Feinden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'Und ihr sollt unter den Heiden zu Grunde gehen, und das Land eurer Feinde soll euch verzehren.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'Und die von euch übrig sein werden, sollen infolge ihrer Sündenschuld in den Ländern eurer Feinde dahinsiechen; überdies auch infolge der Verschuldungen ihrer Väter sollen sie dahinsiechen, wie diese.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, 'Wenn Sie dann ihre Sündenschuld und die Schuld ihrer Väter bekennen - die Untreue, die sie gegen mich begangen haben, und wie sie mir zuwidergehandelt haben,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, 'daher auch ich ihnen zuwiderhandelte und sie in das Land ihrer Feinde verbrachte, - ja, wenn sich dann ihr unbeschnittenes Herz beugt, und Sie alsdann ihre Sündenschuld büßen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, 'so will ich an meinen Bund mit Jakob gedenken und auch meines Bundes mit Isaak, sowie meines Bundes mit Abraham will ich gedenken und des Landes will ich gedenken.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, 'Es muß aber das Land von ihnen verlassen werden und seine Ruhezeiten ersetzt bekommen, während es wüste liegt nach ihrer Entfernung; sie selbst aber müssen ihre Sündenschuld büßen, dieweil Sie meine Rechte verworfen und gegen meine Satzungen Widerwillen gehegt haben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'Aber selbst dann, wenn sie im Land ihrer Feinde sind, verwerfe ich sie nicht und verabscheue ich sie nicht, daß ich sie ganz vertilgen und so meinen Bund mit ihnen brechen sollte, denn ich bin Jahwe, euer Gott.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, 'Und ich will zu ihrem Besten gedenken an den Bund mit den Vorfahren, die ich vor den Augen der Heiden aus Ägypten weggeführt habe, um ihr Gott zu sein - ich, Jahwe!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 46, 'Das sind die Satzungen und Rechte und Weisungen, die Jahwe auf dem Berge Sinai durch Mose gegeben hat, daß sie zwischen ihm und den Israeliten zu Recht bestehen sollten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, 'Und Jahwe redete mit Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, 'Rede mit den Israeliten und sprich zu ihnen: Wenn jemand Jahwe ein Gelübde abträgt, und zwar ein solches von Personen nach dem Schätzungswert,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'so soll der Schätzungswert eines Mannes von zwanzig bis zu sechzig Jahren fünfzig Silbersekel nach dem heiligen Gewichte betragen; ist es aber ein Weib, so soll der Schätzungswert dreißig Sekel betragen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, 'Ist es jemand von fünf bis zu zwanzig Jahren,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'so soll der Schätzungswert der männlichen Person zwanzig Sekel, der weiblichen zehn SekeI betragen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'Ist es jemand von einem Monat bis zu fünf Jahren, so soll der Schätzungswert des Knaben fünf Silbersekel, der Schätzungswert des Mädchens drei Silbersekel betragen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'Ist es jemand von sechzig Jahren und darüber, so soll der Schätzungswert des Mannes fünfzehn Sekel betragen, der des Weibes zehn Sekel.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'Und wenn der Betreffende zu arm ist, um den Schätzungswert zu entrichten, so stelle man ihn vor den Priester, und der Priester möge ihn abschätzen; mit Rücksicht darauf, wie viel der Gelobende zu leisten vermag, soll ihn der Priester abschätzen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, 'Und wenn es Vieh ist, von welchem man Jahwe Opfer bringen kann, so soll alles, was einer Jahwe davon giebt, als geheiligt gelten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, 'Er darf es nicht umwechseln, noch vertauschen - ein gutes für ein schlechtes oder ein schlechtes für ein gutes; und wenn er dennoch ein Stück Vieh mit einem anderen vertauschen sollte, so soll das eine wie das andere dem Heiligtume verfallen sein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'Ist es aber irgend welches unreines Vieh, von dem man Jahwe keine Opfer bringen kann, so soll man das Vieh dem Priester darstellen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, 'und der Priester soll es abschätzen, je nachdem es schön oder gering ist; bei dem Schätzungswerte, den der Priester festsetzt, soll es verbleiben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, 'Will er es aber einlösen, so hat er noch ein Fünftel von dem Schätzungswerte darauf zu legen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, 'Und wenn jemand Jahwe sein Haus als heilige Gabe weiht, so soll es der Priester abschätzen, je nachdem es schön oder gering ist; so, wie es der Priester abschätzt, soll es zu stehen kommen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'Falls aber der, der sein Haus geweiht hat, es wieder einlösen will, so hat er noch ein Fünftel der Schätzungssumme darauf zu legen; dann gehört es ihm.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, 'Wenn jemand etwas von seinem erblichen Grundbesitze Jahwe weiht, so richtet sich der Schätzungswert nach dem Maße der Aussaat; ein Feld von einem Gomer Gerste Aussaat ist auf fünfzig Silbersekel zu schätzen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'Weiht er sein Feld vom Halljahr ab, so soll es nach dem Schätzungswerte zu stehen kommen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'Weiht er aber sein Feld nach dem Halljahr, so muß ihm der Priester den Betrag berechnen mit Rücksicht auf die Zahl der Jahre, die noch bis zum Halljahre fehlen, und es ist dann von dem vollen Schätzungswert ein Abzug zu machen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'Will aber der, der das Feld geweiht hat, es doch wieder einlösen, so hat er ein Fünftel der Schätzungssumme darauf zu legen; dann verbleibt es ihm.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, 'Löst er das Feld nicht ein, verkauft aber trotzdem das Feld an einen anderen, so kann es nicht wiederum eingelöst werden,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'sondern das Feld hat, wenn es im Halljahre frei wird, als etwas Jahwe Geweihtes zu gelten, wie ein dem Banne verfallenes Feld; das Eigentumsrecht daran fällt dem Priester zu.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, 'Weiht er dagegen Jahwe ein von ihm erkauftes Feld, welches nicht zu seinem erblichen Grundbesitze gehört,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, 'so muß ihm der Priester ausrechnen, wie hoch sich der Schätzungswert für den Zeitraum bis zum Halljahre beläuft, und er soll diesen Schätzungswert am gleichen Tag als eine Jahwe geweihte Gabe entrichten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'Im Halljahr aber kommt das Feld wieder an den, von dem er es gekauft hatte, dem es als Erbbesitz gehörte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, 'Alle Schätzungen haben nach heiligem Gewichte zu geschehen; zwanzig Gera machen einen Sekel.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, 'Jedoch Erstgeburten unter dem Vieh, die als erstgeborne Jahwe verfallen, darf niemand weihen; es sei Rind oder Schaf - es gehört Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, 'Handelt es sich aber um unreines Vieh, so muß man es loskaufen nach dem Schätzungswert und ein Fünftel des Betrags darauf legen; falls es aber nicht eingelöst wird, ist es nach dem Schätzungswerte zu verkaufen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, 'Gebanntes jedoch, welches jemand Jahwe mittels des Bannes weiht von allem, was ihm gehört, es seien Menschen oder Vieh oder erblicher Grundbesitz, darf niemals verkauft oder eingelöst werden; alles Gebannte ist Jahwe hochheilig.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'Wenn irgend Menschen mit dem Banne belegt werden, so dürfen sie nicht losgekauft werden, sondern müssen getötet werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, 'Alle Zehnten vom Boden, von der Saatfrucht, wie von den Baumfrüchten, gehören Jahwe, sind Jahwe geheiligt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, 'Sollte aber jemand einen Teil seines Zehnten einlösen wollen, so hat er ein Fünftel des Betrags darauf zu legen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, 'Was aber den Zehnten von den Rindern und Schafen anlangt, so soll von allem, was unter dem Hirtenstab hindurchgeht, das je zehnte Stück Jahwe geheiligt sein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'Man soll nicht untersuchen, ob es gut oder schlecht sei, und darf es nicht mit einem anderen vertauschen. Sollte es einer aber doch vertauschen, so ist das eine wie das andere dem Heiligtume verfallen und darf nicht eingelöst werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, 'Das sind die Gebote, die Jahwe Mose auf dem Berge Sinai für die Israeliten auftrug.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'Und Jahwe redete mit Mose in der Steppe am Sinai, im Offenbarungszelt, am ersten Tage des zweiten Monats im zweiten Jahre nach ihrem Auszug aus Ägypten, und gebot:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, 'Nehmt die Gesamtzahl der ganzen Gemeinde der Israeliten auf, Geschlecht für Geschlecht, Familie für Familie samt den einzelnen Namen - alles, was männlich ist, Kopf für Kopf.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'Alles, was kriegstüchtig ist in Israel, von zwanzig Jahren an und darüber, sollt ihr mustern, Schar für Schar, du und Aaron.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'Und von jedem Stamme soll euch je einer, und zwar das Oberhaupt der zum Stamme gehörenden Familien, zugesellt sein.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, 'Dies sind die Namen der Männer, die euch zur Seite stehen sollen: von Ruben Elizur, der Sohn Sedeurs,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'von Simeon Selumiel, der Sohn Zuri-Sadais,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'von Juda Nahasson, der Sohn Amminadabs,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'von Issachar Nethaneel, der Sohn Zuars,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'von Sebulon Eliab, der Sohn Helons,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'von den Söhnen Josephs: von Ephraim Elisama, der Sohn Ammihuds, von Manasse Gamliel, der Sohn Pedazurs;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'von Benjamin Abidan, der Sohn Gideonis,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'von Dan Ahieser, der Sohn Ammi-Sadais,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'von Asser Pagiel, der Sohn Ochrans,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'von Gad Eliasaph, der Sohn Deguels,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'von Naphthali Ahira, der Sohn Enans.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, 'Das waren die aus der Gemeinde Berufenen, die Fürsten ihrer väterlichen Stämme, die Häupter der Tausendschaften Israels.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'Da ließen Mose und Aaron die genannten Männer, die ihnen namentlich bezeichnet worden waren, zu sich kommen');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, 'und versammelten die ganze Gemeinde am ersten Tage des zweiten Monats. Da ließen sie sich in die Geburts-Verzeichnisse eintragen nach ihren Geschlechtern, Familien und einzelnen Namen, von zwanzig Jahren an und darüber, Kopf für Kopf,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'wie Jahwe Mose befohlen hatte; so musterte er sie denn in der Steppe am Sinai.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, 'Es beliefen sich aber die Abkömmlinge der Söhne Rubens, des Erstgebornen Israels, nach ihren Geschlechtern, Familien und einzelnen Namen, Kopf für Kopf gerechnet - alles, was männlich war von zwanzig Jahren an und darüber, alles, was kriegstüchtig war,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'so viele ihrer vom Stamme Ruben gemustert wurden, auf 46500.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'Die Abkömmlinge der Söhne Simeons nach ihren Geschlechtern, Familien und einzelnen Namen, Kopf für Kopf gerechnet - alles, was männlich war von zwanzig Jahren an und darüber, alles, was kriegstüchtig war,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'so viele ihrer vom Stamme Simeon gemustert wurden, beliefen sich auf 59300.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'Die Abkömmlinge der Söhne Gads nach ihren Geschlechtern, Familien und einzelnen Namen, von zwanzig Jahren an und darüber, alles, was kriegstüchtig war,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'so viele ihrer vom Stamme Gad gemustert wurden, beliefen sich auf 45650.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'Die Abkömmlinge der Söhne Judas nach ihren Geschlechtern, Familien und einzelnen Namen, von zwanzig Jahren an und darüber, alles, was kriegstüchtig war,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'so viele ihrer vom Stamme Juda gemustert wurden, beliefen sich auf 74600.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'Die Abkömmlinge der Söhne Issachars nach ihren Geschlechtern, Familien und einzelnen Namen, von zwanzig Jahren an und darüber, alles, was kriegstüchtig war,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'so viele ihrer vom Stamme Issachar gemustert wurden, beliefen sich auf 54400.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'Die Abkömmlinge der Söhne Sebulons nach ihren Geschlechtern, Familien und einzelnen Namen, von zwanzig Jahren an und darüber, alles, was kriegstüchtig war,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'so viele ihrer vom Stamme Sebulon gemustert wurden, beliefen sich auf 57400.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'Was die Söhne Josephs anbelangt, so beliefen sich die Abkömmlinge der Söhne Ephraims nach ihren Geschlechtern, Familien und einzelnen Namen, von zwanzig Jahren an und darüber, alles, was kriegstüchtig war,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'so viele ihrer vom Stamme Ephraim gemustert wurden, auf 40500;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, 'die Abkömmlinge der Söhne Manasses nach ihren Geschlechtern, Familien und einzelnen Namen, von zwanzig Jahren an und darüber, alles, was kriegstüchtig war,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'so viele ihrer vom Stamme Manasse gemustert wurden, auf 32200.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'Die Abkömmlinge der Söhne Benjamins nach ihren Geschlechtern, Familien und einzelnen Namen, von zwanzig Jahren an und darüber, alles, was kriegstüchtig war,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'so viele ihrer vom Stamme Benjamin gemustert wurden, beliefen sich auf 35400.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'Die Abkömmlinge der Söhne Dans nach ihren Geschlechtern, Familien und einzelnen Namen, von zwanzig Jahren an und darüber, alles, was kriegstüchtig war,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'so viele ihrer vom Stamme Dan gemustert wurden, beliefen sich auf 62700.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'Die Abkömmlinge der Söhne Assers nach ihren Geschlechtern, Familien und einzelnen Namen, von zwanzig Jahren an und darüber, alles, was kriegstüchtig war,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'so viele ihrer vom Stamme Asser gemustert wurden, beliefen sich auf 41500.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'Die Abkömmlinge der Söhne Naphthalis nach ihren Geschlechtern, Familien und einzelnen Namen, von zwanzig Jahren an und darüber, alles, was kriegstüchtig war,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'so viele ihrer vom Stamme Naphthali gemustert wurden, beliefen sich auf 53.400.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, 'Das sind die Gemusterten, die Mose und Aaron und die Fürsten Israels musterten; derer waren zwölf, je einer für den zu ihm gehörenden Stamm.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, 'Und es beliefen sich alle, die von den Israeliten nach ihren Familien gemustert waren, von zwanzig Jahren an und darüber, alles, was kriegstüchtig war in Israel, -');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'es beliefen sich alle Gemusterten auf 603550.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, 'Die Leviten aber nach ihrem väterlichen Stamme wurden nicht mit unter ihnen gemustert.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, 'Und Jahwe redete mit Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, 'Jedoch den Stamm Levi darfst du nicht mit mustern und ihre Gesamtzahl nicht aufnehmen inmitten der übrigen Israeliten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'Stelle du die Leviten an bei der Wohnung des Gesetzes und allen ihren Geräten und allem, was zu ihr gehört; sie sollen die Wohnung und alle ihre Geräte tragen und sie sollen sie bedienen und sich rings um die Wohnung lagern.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, 'Wenn sich die Wohnung in Bewegung setzt, sollen die Leviten sie abbrechen, und wenn die Wohnung rastet, sollen die Leviten sie aufrichten; ein Fremder aber, der herantritt, soll getötet werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'Die übrigen Israeliten sollen sich nach ihren Heerscharen ein jeder in seinem Lager und bei seinem Paniere lagern;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, 'die Leviten aber sollen sich rings um die Wohnung des Gesetzes lagern, daß nicht etwa ein Zorn über die Gemeinde der Israeliten komme. So sollen denn die Leviten des Dienstes an der Wohnung des Gesetzes warten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, 'Und es thaten die Israeliten ganz, wie Jahwe Mose befohlen hatte, - also thaten sie.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, 'Und Jahwe redete mit Mose und Aaron also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, 'Die Israeliten haben sich zu Iagern, ein jeder bei seinem Panier, bei den Feldzeichen seines Stammes; gegenüber dem Offenbarungszelte sollen sie sich ringsum lagern.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, 'Und zwar sollen nach vorn, nach Osten zu, lagern: das Panier des Lagers Judas nach seinen Heerscharen, und als Anführer der Söhne Judas Nahasson, der Sohn Amminadabs,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, 'mit seinem Heer und mit ihren Gemusterten, 74600.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, 'Und neben ihm soll sich lagern der Stamm Issachar, und als Anführer der Söhne Issachars Nethaneel, der Sohn Zuars,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'mit seinem Heer und seinen Gemusterten, 54400;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, 'ferner der Stamm Sebulon, und als Anführer der Söhne Sebulons Eliab, der Sohn Helons,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'mit seinem Heer und seinen Gemusterten, 57400.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, 'Alle die Gemusterten im Lager Judas nach ihren Heerscharen zählen somit 186400; sie haben zuerst aufzubrechen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'Nach Süden zu soll sich lagern das Panier des Lagers Rubens nach seinen Heerscharen, und als Anführer der Söhne Rubens Elizur, der Sohn Sedeurs,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'mit seinem Heer und seinen Gemusterten, 46500.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, 'Und neben ihm soll sich lagern der Stamm Simeon, und als Anführer der Söhne Simeons Selumiel, der Sohn Zuri-Sadais,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'mit seinem Heer und mit ihren Gemusterten, 59300;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, 'ferner der Stamm Gad, und als Anführer der Söhne Gads Eliasaph, der Sohn Reguels,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'mit seinem Heer und mit ihren Gemusterten, 45650.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, 'Alle die Gemusterten im Lager Rubens nach ihren Heerscharen zählen somit 151450; diese haben an zweiter Stelle aufzubrechen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'Das Offenbarungszelt aber, das Lager der Leviten, soll aufbrechen inmitten der übrigen Lager; wie sie lagern, so haben Sie aufzubrechen, ein jeder auf seiner Seite, nach ihren Panieren.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'Das Panier des Lagers Ephraims nach seinen Heerscharen soll sich lagern nach Westen zu, und als Anführer der Söhne Ephraims Elisama, der Sohn Ammihuds,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'mit seinem Heer und mit ihren Gemusterten, 40500;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, 'und neben ihm der Stamm Manasse, und als Anführer der Söhne Manasses Gamliel, der Sohn Pedazurs,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'mit seinem Heer und mit ihren Gemusterten, 32200;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, 'ferner der Stamm Benjamin, und als Anführer der Söhne Benjamins Abidan, der Sohn Gideonis,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'mit seinem Heer und mit ihren Gemusterten, 35 400.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, 'Alle die Gemusterten im Lager Ephraims nach ihren Heerscharen zählen somit 108100. Diese haben an dritter Stelle aufzubrechen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'Das Panier des Lagers Dans nach seinen Heerscharen soll sich lagern nach Norden zu, und als Anführer der Söhne Dans Ahieser, der Sohn Ammi-Sadais,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'mit seinem Heer und mit ihren Gemusterten, 62700.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, 'Und neben ihm soll sich lagern der Stamm Asser, und als Anführer der Söhne Assers Pagiel, der Sohn Ochrans,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'mit seinem Heer und mit ihren Gemusterten, 41500.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, 'Ferner der Stamm Naphthali, und als Anführer der Söhne Naphthalis Ahira, der Sohn Enans,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'mit seinem Heer und mit ihren Gemusterten, 53400.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, 'Alle die Gemusterten im Lager Dans zählen somit 157600. Diese haben zuletzt aufzubrechen nach ihren Panieren.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'Das sind die Gemusterten der Israeliten nach ihren Stämmen, sämtliche Gemusterte der verschiedenen Lager nach ihren Heerscharen, 603550.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, 'Die Leviten aber wurden nicht mit gemustert unter den Israeliten, wie Jahwe Mose befohlen hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, 'Und die Israeliten thaten ganz, wie Jahwe Mose befohlen hatte, - also lagerten sie sich nach ihren Panieren und also brachen sie auf, ein jeder nach seinem Geschlechte bei seinem Stamm.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, 'Dies sind die Nachkommen Aarons und Moses, zu der Zeit, wo Jahwe mit Mose auf dem Berge Sinai redete.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'Dies sind die Namen der Söhne Aarons: Nadab, der Erstgeborne, und Abihu; Eleasar und Ithamar.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, 'Dies sind die Namen der Söhne Aarons, der gesalbten Priester, denen man die Hand gefüllt hatte, damit sie Priesterdienste thäten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'Es starben aber Nadab und Abihu vor Jahwe, als sie in der Steppe am Sinai ein ungehöriges Feueropfer vor Jahwe brachten; sie hatten aber keine Söhne. So pflegten nun Eleasar und Ithamar unter den Augen ihres Vaters Aaron des Priesteramts.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, 'Und Jahwe redete mit Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, 'Laß den Stamm Levi herzutreten und stelle ihn vor Aaron, den Priester, damit sie ihm dienen;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, 'und sie sollen besorgen, was es für ihn und für die ganze Gemeinde vor dem Offenbarungszelte zu besorgen giebt, und sollen so den Dienst an der Wohnung verrichten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'Und sie sollen die sämtlichen Geräte des Offenbarungszeltes besorgen, sowie alles, was es für die Israeliten zu besorgen giebt, und sollen so den Dienst an der Wohnung verrichten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, 'Und du sollst die Leviten Aaron und seinen Söhnen übergeben; ganz zu eigen seien sie ihm gegeben von Seiten der Iraeliten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, 'Aaron aber und seine Söhne sollst du bestellen, damit sie ihres Priesteramts warten; ein Fremder, der herantritt, soll getötet werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'Und Jahwe redete mit Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, 'Ich selbst habe die Leviten herausgenommen aus den Israeliten an Stelle aller Erstgebornen der Israeliten, derer, die zuerst den Mutterschoß durchbrochen haben, - damit die Leviten mir gehören sollen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, 'Denn mir gehören alle Erstgebornen; an dem Tag, an welchem ich alle Erstgeburten in Ägypten tötete, habe ich, Jahwe, mir alle Erstgeburten in Israel geweiht, es seien Menschen oder Vieh; mir sollen sie gehören.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, 'Und Jahwe redete mit Mose in der Steppe am Sinai also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, 'Mustere die Söhne Levis nach ihren Familien und Geschlechtern; alles, was männlich ist, von einem Monat an und darüber, sollst du von ihnen mustern.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, 'Da musterte sie Mose gemäß dem Befehle Jahwes, wie ihm geheißen war.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'Und dies sind die Söhne Levis nach ihren Namen: Gerson, Kahath und Merari.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'Und dies sind die Namen der Söhne Gersons nach ihren Geschlechtern: Libni und Simei.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'Und die Söhne Kahaths nach ihren Geschlechtern: Amram, Jizhar, Hebron und Usiel.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'Und die Söhne Meraris nach ihren Geschlechtern: Maheli und Musi. Das sind die GeschIechter der Leviten nach ihrer Abstammung.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'Von Gerson stammt das Geschlecht der Libniter und das Geschlecht der Simeiter. Das sind die Geschlechter der Gersoniter.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'Die Gesamtzahl der von ihnen Gemusterten - alles, was männlich war, von einem Monat an und darüber, - betrug 7500.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'Die Geschlechter der Gersoniter lagerten jedesmal hinter der Wohnung, nach Westen zu,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, 'und Oberhaupt der Söhne Gersons war Eliasaph, der Sohn Laels.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, 'Am Offenbarungszelt aber hatten die Söhne Gersons zu besorgen: die Wohnung und das Zeltdach; seine Überdecke und den Vorhang vor der Thüre des Offenbarungszeltes,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, 'die Umhänge des Vorhofs und den Vorhang vor der Thüre des Vorhofs, der die Wohnung und den Altar rings umgiebt, und die zugehörigen Seile - mit allem, was es dabei zu verrichten gab.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'Und von Kahath stammte das Geschlecht der Amramiter, das Geschlecht der Jezehariter, das Geschlecht der Hebroniter und das Geschlecht der Osieliter. Das sind die Geschlechter der Kahathiter;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, 'ihre Zahl - alles, was männlich war, von einem Monat an und darüber, - betrug 8600 solcher, die die Geschäfte am Heiligtume besorgten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'Die Geschlechter der Söhne Kahaths lagerten jedesmal an der Langseite der Wohnung nach Süden zu,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, 'und Oberhaupt der Geschlechter der Kahathiter war Elizaphan, der Sohn Usiels.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, 'Sie hatten aber zu besorgen: die Lade, den Tisch, den Leuchter, die Altäre, die heiligen Geräte, mit denen sie den Dienst verrichteten, und den Vorhang - mit allem, was es dabei zu verrichten gab.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, 'Und das Oberhaupt der Leviten-Oberhäupter war Eleasar, der Sohn Aarons, des Priesters, mit der Aufsicht über die, welche die Geschäfte am Heiligtume besorgten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, 'Von Merari stammte das Geschlecht der Maheliter und das Geschlecht der Musiter; das sind die Geschlechter Meraris.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'Die Gesamtzahl der von ihnen Gemusterten - alles, was männlich war, von einem Monat an und darüber, - betrug 6200.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'Und Oberhaupt über die Geschlechter Meraris war Zuriel, der Sohn Abihails; sie lagerten jedesmal an der Langseite der Wohnung, nach Norden zu.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'Es war aber den Söhnen Meraris übertragen die Sorge für die Bretter der Wohnung, ihre Riegel, Säulen und Füße, samt allen ihren Geräten und allem, was es dabei zu verrichten gab;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'ferner für die Säulen des Vorhofs ringsum mit ihren Füßen, Pflöcken und Seilen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, 'Vor der Wohnung aber nach vorn zu - vor dem Offenbarungszelte nach Osten zu - lagerten Mose und Aaron mit seinen Söhnen, die den Dienst am Heiligtume besorgten, alles, was für die Israeliten zu besorgen war; ein Fremder aber, der herantritt, soll getötet werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'Sämtliche von den Leviten Gemusterte, die Mose und Aaron gemäß dem Befehle Jahwes Geschlecht für Geschlecht gemustert hatten - alles, was männlich war, von einem Monat an und darüber, - beliefen sich auf 22000.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, 'Und Jahwe gebot Mose: Mustere alle männlichen Erstgebornen der Israeliten, von einem Monat an und darüber, und nimm die Zahl ihrer Namen auf.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, 'Du sollst aber die Leviten für mich, für Jahwe, nehmen an Stelle aller Erstgebornen unter den Israeliten und das Vieh der Leviten an Stelle aller Erstgeburten unter dem Vieh der Israeliten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'Und Mose musterte alle Erstgebornen unter den Israeliten, wie ihm Jahwe befohlen hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'Es betrug aber die Zahl der Namen aller männlichen Erstgebornen von einem Monat an und darüber, so viele ihrer gemustert wurden, 22273.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'Und Jahwe redete mit Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, 'Nimm die Leviten an Stelle aller Erstgebornen unter den Israeliten und das Vieh der Leviten an Stelle ihrer Viehs, daß die Leviten mir gehören; ich bin Jahwe.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'Und was die Auslösung der 273 israelitischen Erstgebornen betrifft, die überzählig sind über die Zahl der Leviten,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'so sollst du für jeden Kopf fünf Sekel erheben; nach heiligem Gewichte sollst du sie erheben, den Sekel zu zwanzig Gera gerechnet.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, 'Dieses Geld sollst du Aaron und seinen Söhnen übergeben als Auslösung derer, die unter ihnen überzählig sind.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, 'Da erhob Mose die Auslösungs-Summe von denen, welche überzählig waren über die durch die Leviten Ausgelösten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, 'Von den Erstgebornen der Israeliten erhob er die Summe, 1365 Sekel heiliges Gewicht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'Und Mose übergab die Auslösungs-Summe Aaron und seinen Söhnen gemäß dem Befehle Jahwes, wie Jahwe Mose befohlen hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, 'Und Jahwe redete mit Mose und Aaron also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, 'Nehmt unter den Söhnen Levis die Gesamtzahl der Söhne Kahaths auf, Geschlecht für Geschlecht, Familie für Familie,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, 'von dreißig Jahren an und darüber bis zu fünfzig Jahren, alle, die sich dem Dienst unterziehen und Geschäfte am Offenbarungszelte verrichten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'Dies ist die Verrichtung der Söhne Kahaths am Offenbarungszelte: die hochheiligen Dinge.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, 'Es sollen aber Aaron und seine Söhne, wenn sich das Lager in Bewegung setzt, hineingehen, den verdeckenden Vorhang herabnehmen und mit ihm die Gesetzeslade umhüllen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'Sodann sollen sie eine Decke von Seekuhfell darauf legen und oben darüber ein ganz aus blauem Purpur bestehendes Tuch breiten und die Stangen einstecken.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'Über den Schautisch aber sollen sie ein Tuch von blauem Purpur breiten und darauf die Schüsseln, Schalen und Becher, sowie die Kannen zum Trankopfer setzen; auch das ständig aufgelegte Brot soll darauf liegen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, 'Über alles dieses aber sollen sie ein Tuch von Karmesin breiten, dieses mit einer Decke von Seekuhfell überdecken und sodann die Stangen einstecken.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'Weiter sollen sie ein Tuch von blauem Purpur nehmen und damit den Leuchter überdecken samt seinen Lampen, seinen Lichtscheren und Pfannen und allen seinen Ölgefäßen, mit denen man ihn zu besorgen pflegt;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, 'sodann sollen sie ihn samt allen seinen Geräten in eine Hülle von Seekuhfell thun und auf die Trage legen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'Über den goldenen Altar aber sollen sie ein Tuch von blauem Purpur breiten, ihn mit einer Decke von Seekuhfell überdecken und die Stangen einstecken.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'Sodann sollen sie alle für den Dienst erforderlichen Geräte, mit denen man den Dienst im Heiligtume zu besorgen pflegt, nehmen und in ein Tuch von blauem Purpur thun; dann sollen sie sie mit einer Decke von Seekuhfell überdecken und auf die Trage legen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, 'Weiter sollen sie den Altar von der Asche reinigen und ein Tuch von rotem Purpur über ihn breiten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'Auf dieses sollen sie alle die Geräte legen, mit denen man den Dienst an ihm zu besorgen pflegt, die Pfannen, Gabeln, Schaufeln und Becken, kurz alle zum Altar gehörigen Geräte; darüber sollen sie eine Hülle von Seekuhfell breiten und die Stangen einstecken.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, 'Und wenn Aaron und seine Söhne mit der Einhüllung der heiligen Dinge und aller der heiligen Geräte zu Ende sind, wenn sich das Lager in Bewegung setzt, so sollen darnach die Söhne Kahaths kommen, um sie zu tragen; aber berühren dürfen sie die heiligen Dinge nicht, sonst müssen sie sterben. Das ist\'s, was die Söhne Kahaths vom Offenbarungszelte zu tragen haben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, 'Eleasar aber, dem Sohne Aarons, des Priesters, ist übertragen das Öl für den Leuchter, das wohlriechende Räucherwerk, das regelmäßige Speisopfer und das Salböl, sowie die Aufsicht über die ganze Wohnung und alles, was sich in ihr befindet an heiligen Gegenständen und den dazugehörigen Geräten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'Und Jahwe redete mit Mose und Aaron also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, 'Laßt es nicht geschehen, daß der Stamm der Geschlechter der Kahathiter mitten aus den Leviten weggetilgt werde.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, 'Vielmehr thut das für sie, damit sie am Leben bleiben und nicht sterben müssen, wenn sie sich den hochheiligen Dingen nähern: Aaron und seine Söhne sollen hineingehen und sie Mann für Mann anstellen bei dem, was sie zu verrichten und was sie zu tragen haben,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, 'daß sie nicht etwa hineingehen, um auch nur einen Augenblick die heiligen Dinge zu sehen, da sie sonst sterben müssen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'Und Jahwe redete mit Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, 'Nimm nun die Gesamtzahl auch der Söhne Gersons auf, Familie für Familie, Geschlecht für Geschlecht;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, 'von dreißig Jahren an und darüber bis zu fünfzig Jahren sollst du sie mustern, alle, die sich dem unterziehen, Dienst zu thun und Verrichtungen am Offenbarungszelte zu besorgen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'Dies ist die Verrichtung der Geschlechter der Gersoniter - was sie zu verrichten und zu tragen haben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, 'Sie haben zu tragen die Teppiche der Wohnung und das Offenbarungszelt, seine Decke und die Decke von Seekuhfell, die oben darüber liegt, sowie den Vorhang vor der Thüre des Offenbarungszeltes,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, 'ferner die Vorhänge des Vorhofs und den Vorhang vor der Thoröffnung des Vorhofs, der die Wohnung und den Altar rings umgiebt, samt seinen Seilen und allen Geräten, die es dabei zu besorgen giebt; und alles, was dabei zu thun ist, das sollen sie besorgen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'Nach dem Befehl Aarons und seiner Söhne sollen alle Verrichtungen der Gersoniter stattfinden, bezüglich alles dessen, was sie zu tragen, und alles dessen, was sie zu verrichten haben; und zwar sollt ihr ihnen alles, was sie zu tragen haben, namentlich anweisen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'Dies ist\'s, was die Geschlechter der Gersoniter am Offenbarungszelte zu verrichten haben, und zwar stehe ihr Dienst unter der Leitung Ithamars, des Sohnes Aarons, des Priesters.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, 'Auch die Söhne Meraris sollst du mustern, Geschlecht für Geschlecht, Familie für Familie;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, 'von dreißig Jahren an und darüber bis zu fünfzig Jahren sollst du sie mustern, alle, die sich dem Dienst unterziehen und die Verrichtungen für das Offenbarungszelt besorgen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, 'Und das ist\'s, was ihnen zu tragen obliegt, was sie alles vom Offenbarungszelte zu besorgen haben: die Bretter der Wohnung, ihre Riegel, Säulen und Füße;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, 'ferner die Säulen des Vorhofs ringsum mit ihren Füßen, Pflöcken und Seilen, mit allen ihren Geräten und allem, was es dabei zu besorgen giebt. Und zwar sollt ihr ihnen die Geräte, die zu tragen ihnen obliegt, namentlich anweisen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, 'Das ist die Verrichtung der Geschlechter der Söhne Meraris, alles, was sie vom Offenbarungszelt unter der Aufsicht Ithamars, des Sohnes Aarons, des Priesters, zu besorgen haben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, 'Und Mose, Aaron und die Fürsten der Gemeinde musterten die Kahathiter, Geschlecht für Geschlecht und Familie für Familie,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, 'von dreißig Jahren an und darüber bis zu fünfzig Jahren, alle, die sich dem Dienste - den Verrichtungen am Offenbarungszelt - unterzogen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'Es beliefen sich aber die Geschlecht für Geschlecht aus ihnen Gemusterten auf 2750.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, 'Das sind die aus den Geschlechtern der Kahathiter Gemusterten, alle, die am Offenbarungszelte Dienst thaten, welche Mose und Aaron musterten gemäß dem Befehle Jahwes durch Mose.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'Und was die betrifft, die aus den Söhnen Gersons Geschlecht für Geschlecht und Familie für Familie gemustert waren,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, 'von dreißig Jahren an und darüber bis zu fünfzig Jahren, alle, die sich dem Dienste - den Verrichtungen am Offenbarungszelt - unterzogen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'so beliefen sich die Geschlecht für Geschlecht, Familie für Familie aus ihnen Gemusterten auf 2630.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, 'Das sind die aus den Geschlechtern der Söhne Gersons Gemusterten, alle, die am Offenbarungszelt Dienst thaten, welche Mose und Aaron musterten gemäß dem Befehle Jahwes.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'Und was die betrifft, die aus den Geschlechtern der Söhne Meraris Geschlecht für Geschlecht, Familie für Familie gemustert waren,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, 'von dreißig Jahren an und darüber bis zu fünfzig Jahren, alle, die sich dem Dienste - den Verrichtungen am Offenbarungszelt - unterzogen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'so beliefen sich die Geschlecht für Geschlecht aus ihnen Gemusterten auf 3200.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, 'Das sind die aus den Geschlechtern der Söhne Meraris Gemusterten, die Mose und Aaron musterten gemäß dem Befehle Jahwes durch Mose.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'Was aber sämtliche Gemusterte betrifft, die Mose, Aaron und die Fürsten Israels Geschlecht für Geschlecht und Familie für Familie unter den Leviten musterten,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, 'von dreißig Jahren an und darüber bis zu fünfzig Jahren, alle die sich dem unterzogen, am OffenbarungszeIte dienstliche Verrichtungen, sowie den Dienst des Tragens zu besorgen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'so beliefen sich die aus ihnen Gemusterten auf 8580.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'Gemäß dem Befehle Jahwes stellte man sie unter der Aufsicht Moses Mann für Mann bei dem an, was sie zu besorgen und zu tragen hatten, wie Jahwe Mose befohlen hatte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, 'Und Jahwe redete mit Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, 'Befiehl den Israeliten, daß Sie alle mit dem Aussatz oder einem Flusse Behafteten, sowie alle, die sich an einer Leiche verunreinigt haben, aus dem Lager hinausschaffen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, 'Sowohl Männer, als Weiber sollt ihr hinausschaffen; hinaus vor das Lager sollt ihr sie schaffen, damit sie ihr Lager nicht verunreinigen, da doch ich unter ihnen wohne.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'Und die Israeliten thaten also und schafften sie hinaus vor das Lager; wie Jahwe Mose geboten hatte, also thaten die Israeliten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, 'Und Jahwe redete mit Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, 'Sage den Israeliten: Wenn ein Mann oder ein Weib irgend eine Sünde begehen, wie sie von den Menschen begangen wird, daß sie eine Veruntreuung gegen Jahwe verüben, und der Betreffende so in Schuld gerät,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'so sollen sie die Sünde, die sie begangen haben, bekennen und sollen das von ihnen Veruntreute nach seinem vollen Werte zurückerstatten und noch ein Fünftel des Betrags darauf legen, und sollen es dem geben, gegen den sie sich verschuldet haben.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, 'Wenn aber der Betreffende keinen nächsten Verwandten hinterlassen hat, dem man die Buße entrichten könnte, so fällt die Buße, die zu entrichten ist, Jahwe zu zum Besten der Priester, abgesehen von dem Sühnewidder, mit dem man ihm Sühne schafft.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, 'Und alle Hebe, von allen heiligen Gaben der Israeliten, die sie zum Priester bringen, soll diesem gehören.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, 'Ihm soll gehören, was irgend jemand heiligt; was jemand dem Priester giebt, soll diesem gehören.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, 'Und Jahwe redete mit Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, 'Sage den Israeliten und sprich zu ihnen: wenn irgend jemandes Weib sich vergeht und ihm untreu wird,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, 'so daß sich einer fleischlich mit ihr vermischt, ihr Mann aber nichts davon erfährt, und sie unentdeckt bleibt, obschon sie sich verunreinigt hat, auch kein Zeuge wider sie vorhanden ist, indem sie nicht auf der That ertappt ward,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, 'und es kommt über ihn ein Geist der Eifersucht, so daß er eifersüchtig wird auf sein Weib, indem sie sich verunreinigt hat - oder auch, es kommt über ihn ein Geist der Eifersucht, daß er eifersüchtig wird auf sein Weib, obschon sie sich nicht verunreinigt hat -,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, 'so soll dieser Mann sein Weib zum Priester bringen und das erforderliche Opfer, das um ihretwillen zu bringen ist, mit hinnehmen: ein Zehntel Epha Gerstenmehl; doch darf er nicht Öl darüber gießen, noch Weihrauch darauf thun. Denn es ist ein Eifersuchts-Speisopfer, ein Offenbarungs-Speisopfer, das Verschuldung offenbar macht.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, 'Hierauf soll sie der Priester herantreten lassen und sie vor Jahwe stellen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, 'Sodann nehme der Priester heiliges Wasser in ein irdenes Gefäß; ferner nehme der Priester etwas Erde, die sich am Boden der Wohnung befindet, und thue sie in das Wasser.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, 'Und der Priester stelle das Weib vor Jahwe, löse dem Weibe die Haare und gebe ihr das Offenbarungs-Speisopfer in die Hände - ein Eiferfuchts-Speisopfer ist es; aber das fluchbringende Wasser des bitteren Wehs behalte der Priester in der Hand.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, 'Sodann nehme der Priester die Beschwörung mit ihr vor und spreche zu dem Weibe: Wenn dir niemand beigewohnt hat und du dich nicht vergangen und verunreinigt und so die Pflicht gegen deinen Mann verletzt hast, so soll dir dieses fluchbringende Wasser des bitteren Wehs nicht schaden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, 'Wenn du dich aber vergangen und die Pflicht gegen deinen Mann verletzt und dich verunreinigt hast, und sich irgend jemand außer deinem Manne fleischlich mit dir vermischt hat -.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, 'So beschwöre nun der Priester das Weib mit feierlicher Verwünschung und der Priester spreche zu dem Weibe: Jahwe mache dich für deine Volksgenossen zu einem Beispiele feierlicher Verwünschung, indem Jahwe deine Hüfte schwinden, deinen Bauch aber anschwellen läßt;');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, 'und dieses fluchbringende Wasser soll eindringen in deine Eingeweide, daß der Bauch schwelle und die Hüfte schwinde! Das Weib aber spreche: So geschehe es! So geschehe es!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, 'Hierauf schreibe der Priester diese Verwünschungen auf ein Blatt, wische sie ab in das Wasser des bitteren Wehs hinein');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, 'und gebe dem Weibe das fluchbringende Wasser des bitteren Wehs zu trinken, damit das fluchbringende Wasser in sie eindringe zu bitterem Weh.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, 'Sodann nehme der Priester dem Weibe das Eifersuchts-Speisopfer aus der Hand, webe das Speisopfer vor Jahwe und bringe es hin zum Altar.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, 'Und zwar soll der Priester eine Hand voll von dem Speisopfer als den Duftteil, der von ihm zu entrichten ist, nehmen und auf dem Altar in Rauch aufgehn lassen, darnach gebe er dem Weibe das Wasser zu trinken.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'Und wenn er ihr das Wasser zu trinken gegeben hat, so wird, wenn sie sich verunreinigt hat und ihrem Mann untreu geworden ist, das fluchbringende Wasser in sie eindringen zu bitterem Weh: ihr Bauch wird anschwellen und ihre Hüfte schwinden, und so wird das Weib unter ihren Volksgenossen zu einem Beispiele für Verwünschungen werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, 'Hat sich aber das Weib nicht verunreinigt, sondern ist rein, so wird sie unversehrt bleiben und dann schwanger werden.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, 'Das sind die Bestimmungen in betreff der Eifersuchtsklagen: wenn ein Weib sich vergeht und die Pflicht gegen ihren Mann verletzt und sich verunreinigt,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'oder auch, wenn über einen Mann ein Geist der Eifersucht kommt und er eifersüchtig wird auf sein Weib, so stelle er das Weib vor Jahwe, und der Priester verfahre mit ihr ganz nach diesen Bestimmungen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, 'Der Mann wird frei bleiben von Verschuldung; ein solches Weib aber lädt Verschuldung auf sich.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, 'Und Jahwe redete mit Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, 'Rede mit den Israeliten und sprich zu ihnen: Wenn ein Mann oder ein Weib das Gelübde eines Gottgeweihten ablegen will, um sich so Jahwe zu weihen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, 'so muß er sich des Weins und berauschenden Getränks enthalten. Auch Essig von Wein oder berauschendem Getränke darf er nicht trinken; er darf keinerlei aus Trauben bereitete Flüssigkeit trinken, noch frische oder getrocknete Trauben essen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'So lange seine Weihezeit dauert, darf er gar nichts von dem essen, was aus dem Weinstock gewonnen wird, weder unreife Trauben, noch die Spitzen der Ranken.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'Die ganze Zeit, für die sein Weihe-Gelübde gilt, darf kein Schermesser über sein Haupt kommen. Bis die Zeit um ist, für die er sich Jahwe geweiht hat, soll er als ein Geheiligter gelten; er hat sein Haupthaar frei wachsen zu lassen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'Die ganze Zeit hindurch, während der er sich Jahwe geweiht hat, darf er zu keiner Leiche hineingehen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, 'Selbst wenn sein Vater oder seine Mutter, sein Bruder oder seine Schwester stirbt, darf er sich nicht an ihnen verunreinigen, denn die Weihe seines Gottes ist auf seinem Haupte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, 'Während der ganzen Zeit seiner Weihe ist er Jahwe geheiligt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, 'Falls aber jemand ganz plötzlich in seiner Gegenwart stirbt, und er so sein geweihtes Haupt verunreinigt, so hat er sein Haupt an dem Tag, an welchem er wieder rein wird, zu scheren: am siebenten Tag hat er es zu scheren.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, 'Am achten Tag aber bringe er zwei Turteltauben oder zwei junge Tauben hin zum Priester vor die Thüre des OffenbarungszeItes.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, 'Und der Priester richte die eine her zu einem Sündopfer, die andere zu einem Brandopfer und schaffe ihm Sühne dafür, daß er sich durch die Verunreinigung an der Leiche versündigt hat; sodann soll er am gleichen Tage sein Haupt aufs neue für geheiligt erklären,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, 'sich Jahwe für die früher von ihm gelobte Zeit weihen und ein einjähriges Lamm als Schuldopfer bringen; die erste Weihezeit aber wird hinfällig, weil seine Weihe verunreinigt ward.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, 'Und dies sind die Bestimmungen in betreff des Gottgeweihten: wenn die von ihm gelobte Weihezeit um ist, soll man ihn vor die Thüre des Offenbarungszeltes bringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, 'Als seine Opfergabe aber hat er Jahwe ein fehlloses, einjähriges Lamm zum Brandopfer und ein fehlloses, einjähriges weibliches Lamm zum Sündopfer, sowie einen fehllosen Widder zum Heilsopfer darzubringen,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'ferner einen Korb mit ungesäuerten Kuchen von Feinmehl, die mit Öl angemacht sind, und ungesäuerte mit Öl bestrichene Fladen, nebst dem zugehörigen Speisopfer und den zugehörigen Trankopfern.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, 'Und der Priester bringe sie vor Jahwe und richte das Sündopfer und das Brandopfer für ihn her.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'Den Widder aber richte er her als Heilsopfer für Jahwe, samt dem Korbe mit dem Ungesäuerten; auch das Speisopfer und das Trankopfer richte der Priester für ihn her.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'Sodann schere der Gottgeweihte vor der Thüre des Offenbarungszeltes sein geweihtes Haupt, nehme sein geweihtes Haupthaar und werfe es in das Feuer, das unter dem Heilsopfer brennt.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, 'Hierauf nehme der Priester den gekochten Bug von dem Widder nebst einem ungesäuerten Kuchen aus dem Korb und einem ungesäuerten Fladen und gebe es dem Gottgeweihten in die Hände, nachdem derselbe sein geweihtes Haar abgeschoren hat.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, 'Sodann webe es der Priester vor Jahwe als Webe, es ist eine dem Priester zufallende heilige Gabe, außer der Webebrust und der Webekeule. Darnach darf der Gottgeweihte Wein trinken.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, 'Das sind die Bestimmungen in betreff des Gottgeweihten, der ein Gelübde thut, - was er zufolge seiner Weihe Jahwe darzubringen hat, abgesehen von dem, was er außerdem noch zu leisten vermag. Wie das Gelübde fordert, das er abgelegt hat, soll er verfahren, nach den für seine Weihe geltenden Bestimmungen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'Und Jahwe redete mit Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, 'Rede mit Aaron und mit seinen Söhnen also: So sollt ihr die Israeliten segnen, indem ihr zu ihnen sprecht:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, 'Jahwe segne dich und behüte dich!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, 'Jahwe lasse sein Angesicht über dich leuchten und sei dir gnädig!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, 'Jahwe erhebe sein Angesicht auf dich und schaffe dir Friede!');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, 'So sollen sie meinen Namen auf die Israeliten legen, und ich will ihnen Segen zu teil werden lassen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'Als nun Mose die Wohnung fertig aufgerichtet und sie gesalbt und geweiht hatte samt allen ihren Geräten, dazu auch den Altar mit allen seinen Geräten gesalbt und geweiht hatte,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'da brachten die Fürsten IsraeIs, die Oberhäupter der einzelnen Stämme - das sind die Stammesfürsten, die Vorstände der Gemusterten - Opfer.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, 'Und zwar brachten sie vor Jahwe als ihre Gabe sechs überdeckte Wagen und zwölf Rinder, je einen Wagen von zwei Fürsten und je ein Rind von jedem; die brachten sie hin vor die Wohnung.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, 'Da sprach Jahwe zu Mose also:');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, 'Nimm sie von ihnen an, damit sie zur Besorgung der Verrichtungen für das Offenbarungszelt verwendet werden; und zwar sollst du sie den Leviten übergeben, mit Rücksicht darauf, was der Dienst eines jeden erfordert.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, 'Da nahm Mose die Wagen und die Rinder und übergab sie den Leviten.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, 'Zwei von den Wagen und vier Rinder übergab er den Söhnen Gersons, entsprechend dem, was ihr Dienst erforderte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'Vier von den Wagen und acht Rinder übergab er den Söhnen Meraris, entsprechend dem, was ihr Dienst unter der Leitung Ithamars, des Sohnes Aarons, des Priesters, erforderte.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, 'Den Söhnen Kahaths dagegen gab er nichts. Denn ihnen lag die Besorgung der heiligen Dinge ob; diese hatten sie auf der Schulter zu tragen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, 'Es brachten aber die Fürsten die Gaben zur Einweihung des Altars an dem Tage dar, an welchem er gesalbt ward; und die Fürsten brachten ihre Opfergabe hin vor den Altar.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'Da sprach Jahwe zu Mose: Laß Tag für Tag jedesmal einen der Fürsten seine Opfergabe zur Einweihung des Altars darbringen.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, 'Der, welcher seine Opfergabe am ersten Tage darbrachte, war Rahasson, der Sohn Amminadabs, vom Stamme Juda.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'Und seine Opfergabe war eine silberne Schüssel, hundertunddreißig Sekel schwer, ein silbernes Becken, siebzig Sekel schwer nach heiligem Gewichte, beide gefüllt mit Feinmehl, das mit Öl angemacht war, zum Speisopfer,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'eine Schale, zehn Goldsekel schwer, gefüllt mit Räucherwerk,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'ein junger Stier, ein Widder, ein einjähriges männliches Lamm zum Brandopfer,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, 'ein Ziegenbock zum Sündopfer,');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, 'und zum Heilsopfer zwei Rinder, fünf Widder, fünf Böcke und fünf einjährige männliche Lämmer. Das war die Gabe Rahassons, des Sohnes Amminadabs.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, 'Am zweiten Tage opferte Nethaneel, der Sohn Zuars, der Fürst von Issachar.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'Seine Opfergabe war eine silberne Schüssel, hundertunddreißig Sekel schwer, ein silbernes Becken, siebzig Sekel schwer nach heiligem Gewichte, beide gefüllt mit Feinmehl, das mit Öl angemacht war, zum Speisopfer,');
