INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 24, 'Am dritten Tage der Fürst der Söhne Sebulons, Eliab, der Sohn Helons.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 25, 'Seine Opfergabe war eine silberne Schüssel, hundertunddreißig Sekel schwer, ein silbernes Becken, siebzig Sekel schwer nach heiligem Gewichte, beide gefüllt mit Feinmehl, das mit Öl angemacht war, zum Speisopfer,');
