INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 54, 'Am achten Tage der Fürst der Söhne Manasses, Gamliel, der Sohn Pedazurs.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 55, 'Seine Opfergabe war eine silberne Schüssel, hundertunddreißig Sekel schwer, ein silbernes Becken, siebzig Sekel schwer nach heiligem Gewichte, beide gefüllt mit Feinmehl, das mit Öl angemacht war, zum Speisopfer,');
