INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 60, 'Am neunten Tage der Fürst der Söhne Benjamins, Abidan, der Sohn Gideonis.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 61, 'Seine Opfergabe war eine silberne Schüssel, hundertunddreißig Sekel schwer, ein silbernes Becken, siebzig Sekel schwer nach heiligem Gewichte, beide gefüllt mit Feinmehl, das mit Öl angemacht war, zum Speisopfer,');
