INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 72, 'Am elften Tage der Fürst der Söhne Assers, Pagiel, der Sohn Ochrans.');
INSERT INTO `GerTextbibel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 73, 'Seine Opfergabe war eine silberne Schüssel, hundertunddreißig Sekel schwer, ein silbernes Becken, siebzig Sekel schwer nach heiligem Gewichte, beide gefüllt mit Feinmehl, das mit Öl angemacht war, zum Speisopfer,');
